cat << 'EOF' > Cargo.toml
[workspace]
resolver = "3"
members = [
    "primitives",
    "work",
    "scivm",
    "scheduler",
    "ledger",
    "poc",
    "wire",
    "chain",
    "node",
]

# Consensus code: no `unsafe`, and every public item documented.
[workspace.lints.rust]
unsafe_code = "forbid"
missing_docs = "warn"

[workspace.dependencies]
primitives = { path = "primitives" }
work = { path = "work" }
scivm = { path = "scivm" }
scheduler = { path = "scheduler" }
ledger = { path = "ledger" }
wire = { path = "wire" }
chain = { path = "chain" }

# FIPS 202. Since sha3 0.12, RustCrypto ships SHAKE in the sibling `shake` crate
# (same repository, same `keccak` backend).
sha3 = { version = "0.12.0", default-features = false }
shake = { version = "0.1.0", default-features = false }
# FIPS 204 ML-DSA-87 (RustCrypto). Shares `shake` and `keccak` with the hashing above.
ml-dsa = { version = "0.1.1", default-features = false, features = ["alloc", "getrandom"] }
# FIPS 205 SLH-DSA-SHAKE-256s, the treasury co-signature (spec eq. 2.5). Only that
# parameter set is compiled.
fips205 = { version = "0.5.0", default-features = false, features = ["default-rng", "slh-dsa-shake-256s"] }

serde = { version = "1.0.228", features = ["derive"] }
# 3.0.0 is a compile_error! tombstone (RUSTSEC-2025-0141); 1.3.3 is declared complete.
bincode = "=1.3.3"
serde_json = "1"
tokio = { version = "1.53", features = [
    "rt-multi-thread",
    "macros",
    "net",
    "sync",
    "time",
    "signal",
    "fs",
] }
tokio-util = { version = "0.7.20", features = ["codec"] }
futures = "0.3.34"
bytes = "1"
axum = "0.8.9"
clap = { version = "4.6", features = ["derive"] }
tracing = "0.1.44"
tracing-subscriber = { version = "0.3.23", features = ["env-filter"] }

# One 512^3 tile at opt-level 0 is roughly 30x slower; tests mine and verify real tiles.
[profile.dev.package.work]
opt-level = 3
[profile.dev.package.primitives]
opt-level = 3
[profile.dev.package.scivm]
opt-level = 3
# Each tile check hashes about 1.5 MB with SHA3-512, so the Keccak crates need it too.
[profile.dev.package.keccak]
opt-level = 3
[profile.dev.package.sha3]
opt-level = 3
[profile.dev.package.shake]
opt-level = 3
# ML-DSA-87 signs and verifies every block, share and job.
[profile.dev.package.ml-dsa]
opt-level = 3
[profile.dev.package.module-lattice]
opt-level = 3
# SLH-DSA-SHAKE-256s signs treasury withdrawals in seconds even when optimized.
[profile.dev.package.fips205]
opt-level = 3
EOF

cat << 'EOF' > README.md
# Plauthium Public Testnet

Rust workspace for the Plauthium post-quantum layer-1. The six core crates are a frozen,
tested mathematical core that follows the *Plauthium Technical Specification*. Three
testnet crates wrap it into a multi-node P2P network, as specified in
[`../testnet_blueprint.md`](../testnet_blueprint.md). `unsafe` is forbidden everywhere,
and every public item is documented.

```sh
cargo test --workspace --release   # 134 tests, including the 3-node integration test (~2-3 min)
cargo run --release -p poc         # core: mock block transitions + ASCII summary
scripts/testnet.sh                 # join the public testnet, or run a local 3-node dev net
```

Run the tests in release mode. Every block involves at least one real 512×512 tile product.
The workspace needs Rust 1.89 or newer.

## Crates

| Crate        | Spec      | Contents |
|--------------|-----------|----------|
| `primitives` | §1.3–1.4, Table 3, §7.10 | `Atoms` (1 PLAU = 10^8 atoms), supply `M = 1.5·10^15`, `Mersenne61` field (`p = 2^61 − 1`), `DomainSeparatedHash` (SHA3-512) + `Shake256Xof` (SHAKE256), `BlockResourceVector` (5 components), PQ object sizes |
| `work`       | §3.1–3.2, §5.1–5.3 | 512×512 INT8 `WorkUnit` over `[-127, 127]`, INT32 `AccumulationTarget` with `\|z\| ≤ 8,258,048 < 2^23`, exact tile product, 16-field Fresh Work context, the three diagnostic generators on the modulo-3 schedule (`GeneratorProfile`), `verify_freivalds_rounds` (`r_F = 6`) |
| `scivm`      | §3.6      | `OzakiIIProfile` (pairwise-coprime moduli ≤ 255, `Q > 2·B_rec`), `split_residues`, centered CRT, exact residue dot product, zero consensus weight |
| `scheduler`  | §6.1–6.5  | `ShareID`, sequential D'Hondt (`w_s/(a_s+1)` by exact cross-multiplication, ties to least ShareID), owner capacity, persistent cohort counters |
| `ledger`     | Module 5, §7.1–7.8 | 10 disjoint transparent `StateCategory` balances, atomic zero-sum deltas, an all-unissued Genesis, primary issuance (`Emission`: linear `R_I → U_initial`, exact Q64 `R_M → P_pending`), the 720-block `InitialValve`, `FeeLot` with ceiling budgets, floor payouts and segregated dust |
| `poc`        | —         | Binary that runs Genesis → per-block issuance → Fresh Work under the three generators → D'Hondt → fee lock/maturation/payout → InitialValve |
| `wire`       | blueprint §3–§5 | The seven P2P messages (incl. `GossipShare` and `GossipWithdrawal`; the `Handshake` carries the genesis id and a node nonce), block/job/share/withdrawal types, `Digest`/`Target`, fixed-width ML-DSA-87 `PublicKey`/`Signature` and SLH-DSA-SHAKE-256s `SlhDsaPublicKey`/`SlhDsaSignature`, the bincode 1.3.3 codec (fixed-width little-endian, trailing bytes rejected), protocol constants |
| `chain`      | blueprint §6–§7 | Genesis validation, Stage A (signatures, then VerifyFW by recomputing the tile) and Stage B (context checks, including the scheduled generator id and the treasury policy), windowed retarget, `apply_body` (the state transition on `ledger::Ledger`, opening with primary issuance), D'Hondt leases, templates, `BlockTree` with heaviest-seal-weight fork choice, ML-DSA-87 owner keys and the dual-key treasury (`chain::keys`) |
| `node`       | blueprint §8–§10 | `plauthium-node`: ChainState / Mempool actors (jobs and pool withdrawals), multi-threaded ConsensusEngine, length-delimited TCP PeerManager with sync, append-only `blocks.log`, persistent miner key, share pool with `GossipShare` relay, Stage A limits per source, host-name bootnodes, offline treasury signing, axum JSON RPC and the embedded explorer |

## Running a node

`bash Plauthium_Testnet.sh` (the whole workspace in one script, generated by
`scripts/make_bundle.sh`) prints the testnet disclaimer, asks which of three to run,
writes the workspace, builds `plauthium-node` and starts it. `scripts/testnet.sh` does the
same from a checkout, and `--miner`, `--verifier` and `--local` choose without asking:

1. **`--miner`**: one node on Public Testnet that mines; with a seed node set, only
   once it is connected and caught up (`--mine-when-synced`).
2. **`--verifier`**: the same node without mining (`--no-mine`): it syncs, verifies and
   relays.
3. **`--local`**: a local dev net of three fully meshed mining nodes with a fresh genesis
   (`--seal-attempts 128 --target-block-secs 5 --blocks-per-epoch 12`) and explorers at
   <http://127.0.0.1:8081/>, <http://127.0.0.1:8082/> and <http://127.0.0.1:8083/>.
   Node `i` peers on `127.0.0.1:3034i` and keeps its data in `target/testnet/n<i>`; every
   run resets the chain data.

Every node creates its ML-DSA-87 miner key on its first run and loads it on every later
run; the launcher shows the key file and owner id before starting
(`plauthium-node key --data-dir DIR` does the same by hand). `--reset` wipes the chain
data but keeps the key. Ctrl-C stops the nodes gracefully.

Each explorer shows the 10 ledger categories with a live `Σ = M` check, the next primary
release, the InitialValve, the block feed (with each block's generator profile) and a
job-submission form. All of `M` starts unissued and the miner release waits in
`P_pending` until it is paid, so jobs become fundable once the first epoch's miner
release is paid into `U`, at height `2 · blocks_per_epoch` (24 here).

To submit a commercial job from the command line (default total charge is 1 PLAU; the
node signs it with its miner key):

```sh
curl -s localhost:8081/api/submit_job -H 'content-type: application/json' \
  -d "{\"payload\":{\"type\":\"exact_dot\",\"xs\":[$(seq -s, 1 512)],\"ys\":[$(seq -s, 512 -1 1)]}}"
```

Other endpoints: `GET /api/status`, `GET /api/blocks?limit=20&before=<height>` and
`POST /api/submit_withdrawal` (see [InitialProtocolPool](#initialprotocolpool-and-the-initialvalve)).
Run `plauthium-node --help`, `plauthium-node genesis --help`, `plauthium-node run --help`
and `plauthium-node treasury --help` for the CLI.

## Plauthium Public Testnet

All nodes built from this source share one genesis: `node/genesis.testnet.json`,
embedded in the binary, with `genesis_time_bucket` fixed at `1792540800`
(2026-10-21T00:00:00Z, the launch). Its genesis id is

```text
55a515d5a46782d1373d0ad31a546ce816147514248556e664c973584fbab9a3b44d20eca91d029c5c875ea88019acaef4fc78eaac7008e979762f644b2f481f
```

and `node/tests/public_testnet.rs` fails if it changes. Its treasury key ids are zero, so
no key can sign for the InitialProtocolPool: it accumulates its release and pays nothing
out until a genesis names a treasury. Retargeting never reads the
genesis time (its windows start at height `2 · window`), so a genesis in the past is
safe. The handshake carries the genesis id: a node on another genesis
(a local dev chain shares the `chain_id`) is not kept as a peer, and its dialer backs off
for 10 minutes.

The public node listens for peers on port 30333 (forward it to accept inbound peers) and
serves its explorer on `127.0.0.1:8080` only, since `/api/submit_job` pays with the miner
key. It dials the seed node named by `SEED_NODE_IP` (line 2 of `Plauthium_Testnet.sh`, or
the top of `scripts/testnet.sh`, or the environment) on port 30333. `--peer` takes
`IP:port` as well as `host:port`, re-resolved before every connection attempt. The
node's key is `~/.local/share/plauthium/miner_key.bin` and its chain data
`~/.local/share/plauthium/testnet-data` (under `$XDG_DATA_HOME` if set, or
`$PLAUTHIUM_HOME`), outside the workspace, so `cargo clean` or a fresh copy of the script
keeps the identity. A node locks its data directory, so a second node on it refuses to
start. `PLAUTHIUM_MINING_THREADS` (default 1) and `PLAUTHIUM_RESET=1` (wipe the chain data,
keep the key) are optional.

`--mine-when-synced` keeps a node that cannot reach the network from mining a private
fork it could never leave: it mines only while a peer is connected, once its tip has
reached the best height its peers report, or once its tip has not moved for a minute
while connected. A peer's claimed height drops to what it delivers when a sync request to
it goes unanswered, or its answer is empty, starts at another height or brings nothing
new; gossip raises it to at most one block past our tip. So a peer cannot hold the gate
closed by claiming a height it does not have. A node with peers configured warns every
minute while none is connected.

**Seed nodes.** The first seed node runs `--miner` with `SEED_NODE_IP` empty, so it mines
alone from genesis. Everyone else sets `SEED_NODE_IP` to a running seed node's public IP.
A seed node that is given its own address drops the connection to itself (the
`Handshake` nonce), even behind 1:1 NAT.

## Permissionless job and state limits

Each job may charge at most 100 PLAU (10,000,000,000 atoms), including its queue fee.
No job may charge more than the fixed total supply. Jobs expire at most 120 blocks
beyond their admission height; the mempool applies the same bound to the next block.
Every block may spend at most one sixteenth of the circulating balance `U` available
**after** primary issuance, epoch maintenance, settlement and pool withdrawals. Neither
`U_initial`, `P_pending` nor the unissued reserves count. The budget is fixed once and
shared by all jobs in the block; it is not recalculated for each job. There is no faucet
authority or privileged tester key.

Active and locked fee lots together may not exceed 16,384. Admission reserves two
lots per job. Epoch booking discards zero-principal lots after preserving the payout
and dust accounting. Mempool template windows rotate, including on a stationary tip,
so temporarily unfundable entries cannot hide the rest of the pool indefinitely.

## Network memory and deadlines

Outbound queues account for encoded bytes before allocating a frame: 32 MiB per
peer and 64 MiB across the node, including the frame currently being written.
Gossip shares immutable encoded buffers; sync encodes borrowed canonical blocks.
A stalled write is closed after five seconds. Inbound payload buffers share a
64 MiB budget. After the first byte of a frame, its remaining length prefix has
five seconds and its payload has fifteen seconds; trickled bytes do not extend
these deadlines. Idle established connections allocate no frame buffer.
A peer removed by a ban is cancelled even while waiting for an actor reply.
The registration mutex protects the final ban check and peer insertion together.

## Chain identity and data

The cryptographic domains carry clean `PLAU/...` labels with no version suffix
(`primitives::labels` for Fresh Work and transaction effects, `chain::core_adapter::LABELS`
for the rest; tests check they are distinct and unversioned). They fix the genesis,
block, job and withdrawal identifiers and every signing context, so start with a fresh
chain directory (`testnet-data`) rather than replaying a chain from an earlier bundle.
Existing miner seeds remain readable, including tagged seed containers, and keep their
public keys; their key ids follow the `PLAU/OWNER` domain. Cargo dependency pins, the
wire handshake discriminators (`WIRE_PROTOCOL_ID`, `CORE_PROTOCOL_ID`) and cryptographic
standard identifiers (FIPS 204/205 parameter sets) are technical metadata required to
build and interpret data.

## Ledger, issuance and the diagnostic generators

**Genesis.** All of `M = 15,000,000 PLAU` starts unissued: `R_I = 1,500,000 PLAU` (10%) and
`R_M = 13,500,000 PLAU` (90%). The other eight categories are zero and `R_a` holds no
Genesis fee lot (spec eq. 7.19a).

**Primary issuance.** `apply_body` opens every block `k = h − h_G ≥ 1`, before any other
transition, with `Ledger::begin_block` (eqs. 7.19b–7.19g), recorded as the block's first
`FeeTransition::PrimaryRelease`:

- *Initial release* `R_I → U_initial`: `i_k = ⌊I·k/N_I⌋ − ⌊I·(k−1)/N_I⌋` with
  `N_I = 1,051,200` blocks, so `R_I` is empty exactly at block `N_I`.
- *Miner release* `R_M → P_pending`: the state `S_k = ⌊a·S_{k−1}/Q⌋` with `Q = 2^64`,
  `a = 18,446,731,910,177,940,463 = ⌊Q·2^(−1/H_M)⌋` and `H_M = 1,051,200`, computed exactly
  in 128-bit arithmetic; `m_k = R_M(k−1) − R_M(k)`. Block 1 releases `i_1 = 142,694,063`
  and `m_1 = 890,171,600` atoms; after `H_M` blocks `R_M` is 25 atoms below `R/2`.

The miner release is booked to the epoch's shares by the same floor rule as the fee lots
(its remainder carries to the next epoch inside `P_pending`) and paid into `U` at the next
epoch boundary. `begin_block` admits only consecutive heights, so no block can skip or
repeat a release.

**Diagnostic generators.** Fresh Work at block `k` uses profile `j = (k − 1) mod 3`
(`(h − 1) mod 3` for `h_G = 0`) with generator id `3100 + j` in the context; there is no
fourth state and no fallback. Stage B rejects a block whose context names another id, and
an unknown id has no instance at all. `X` reads `SHAKE256(Enc(PLAU/FW/A, seed))` and `Y`
reads `SHAKE256(Enc(PLAU/FW/B, seed))`:

| `j` | Profile | Entries |
|-----|---------|---------|
| 0 | Outlier Fuzzing | small background (`byte & 15` → `0` twelve times, `±1`, `±2`), then a Fisher–Yates draw places exactly eight `−127` and eight `+127` in every row |
| 1 | Arithmetic Graph | `byte() & 127`, nonnegative |
| 2 | Correlated Accumulator Stress | a carrier stream `SHAKE256(Enc(PLAU/FW/CORRELATION/CARRIER, seed))` fixes the sign `σ_k` of inner dimension `k`; `A_ik = σ_k (127 − (byte() & 7))`, so every product term is positive and the 3-bit deficit defeats popcount shortcuts (`Z_ij ∈ [7,372,800, 8,258,048]`) |

## InitialProtocolPool and the InitialValve

`U_initial` pays out only through an `InitialPoolWithdrawal`: public outputs (recipient key
id and atoms, at most 16), a pool-funded fee into `R_l`, the expected `InitialNonce`, and
two signatures over `H(PLAU/SIG/WITHDRAWAL, genesis_id, tx_id)` by the genesis treasury
keys: ML-DSA-87 **and** SLH-DSA-SHAKE-256s (FIPS 205, the `fips205` crate, context
`PLAU/TX`). `InitialOK` (eq. 7.19j) also requires the nonce to match,
`U_initial ≥ v + f`, and the gross outflow of the rolling 720-block window plus `v + f`
to stay within `L_I = I/50 = 30,000 PLAU` (eqs. 7.19h–7.19i). At most two withdrawals
fit a block, in nonce order.

The node never holds treasury keys. Generate them offline, put their ids into a genesis,
and sign withdrawals offline:

```sh
plauthium-node treasury keygen --key-file treasury_key.bin    # prints both key ids
plauthium-node genesis --treasury-key-id <ID> --treasury-cosigner-key-id <ID> ...
plauthium-node treasury withdraw --key-file treasury_key.bin --genesis genesis.json \
  --nonce 0 --output <RECIPIENT_KEY_ID>:500000000 --fee 1000000 --out w.hex
curl -s localhost:8081/api/submit_withdrawal -H 'content-type: application/json' \
  -d "{\"withdrawal\":\"$(cat w.hex)\"}"
```

`chain/tests/vectors/slh_dsa_shake_256s.sig.hex` is a co-signature made by this code that a
separate FIPS 205 implementation, written from the standard, verified; that implementation
also derived the same public key from the same seeds. The mempool checks the policy before
the signatures and the ML-DSA-87 signature before the slower SLH-DSA one, pools nonces up to 16 ahead of the chain, and relays accepted
withdrawals as `GossipWithdrawal`. Templates include the run of consecutive nonces the
pool and the valve admit. `GET /api/status` reports `ledger.initial_pool` (next nonce,
rolling outflow, headroom) and `ledger.issuance`.

## Verification limits

Stage B (context checks) needs no work, so a peer could otherwise make a node recompute
tiles for free. Limits apply per **source**: an IP address, the /64 prefix for IPv6, or
the full address for loopback peers (local testnets). Bans and the inbound cap of 16
connections are per source too. A separate cap of 64 inbound connections includes
handshakes and loopback peers.

- **Stage A slots:** at most 2 blocks of a source in Stage A, 16 in total. A block that
  passes Stage B beyond that waits in a FIFO queue: at most 8 per source and 64 in total.
  A newly arrived block over these limits gets `Busy`: not remembered, nobody penalized,
  and net asks that peer again 2 s later. When the queue is full, the newest entry of the
  source holding the most (clearly more than the newcomer's) makes room. Parked children
  and deferred blocks obey the same limits. Ready children refused as busy stay in
  the bounded orphan pool and are retried on the maintenance tick.
- **Order:** signatures, then the header's tile, then the share tiles. A block's share
  tiles are only recomputed once its seal is known to be genuine work.
- **Cancellation:** when a block or share of a source fails verification, the chain actor
  bans the source on the spot: its other Stage A tasks are aborted (a tile already
  computing finishes, as it cannot be interrupted, and its result is discarded) and its
  queued, parked and deferred blocks, share checks and parked shares are dropped. Nothing
  new from it is admitted until the ban ends; net closes its connections and sends the
  same cancellation for bans of its own (protocol violations). Semaphore permits stay with
  the computation, so aborted work never lets more tiles run than `--verify-threads`.
- **Second senders:** each pending block remembers up to 3 other sources that delivered
  the same bytes. A block whose first sender is banned stays pending (a running Stage A
  goes on) for one of them, since honest peers relay a block only once.
- **Settled only:** net remembers a block or share as seen only once it is accepted or
  rejected, so copies of pending ones still reach the chain actor (a cheap duplicate
  check, which records the second sender).
- **Parked orphans** (parent not yet known; they cost nothing to make): at most 64 per
  source, a full sync batch, and 256 in total. A source over its share evicts its own
  oldest orphan; a full set evicts the oldest of the source holding the most.
- **Deferred blocks** (time bucket ahead of the local clock): at most 8 per source and 64
  in total, and none more than 75 s ahead. Orphans released by their parent count too.
- **Errors** of the verification machinery itself (a panicked or cancelled task) drop the
  block or share without penalizing anyone.
- **Jobs:** the mempool also refuses a copy of a job that is already on the canonical
  chain (until it expires), so replaying old jobs cannot fill it.

The RPC reports these counters under `verification` in `GET /api/status`.

## Owner identity

An owner is an ML-DSA-87 key pair (FIPS 204, RustCrypto `ml-dsa`), stored as its 32-byte
seed. Its **key id** is `H(PLAU/OWNER, public key)`.

- **On the wire:** `BlockHeader.miner_key`, `ShareProof.owner_key` and
  `JobTransaction.client_key` carry the 2,592-byte public key. Each object ends with a
  4,627-byte `signature` over a domain-separated digest of all its other fields:
  `PLAU/SIG/{HEADER,SHARE,JOB}`. The job digest also binds `genesis_id`, and
  every signature uses the FIPS 204 context string `PLAU/TX`.
- **Bound to the work:** context fields 11 and 12 are `H(PLAU/{MINER,PAYOUT},
  key id)`. Re-signing someone else's block or share under another key breaks Stage B.
- **Verified before the STF:** Stage A checks every signature before any tile is
  recomputed. `apply_body` only accepts a `VerifiedOwner`, which `chain::core_adapter` alone
  can create, after a successful verification.
- **Bridged to the frozen core:** the scheduler's `OwnerId(u64)` is the first 8 bytes of
  the key id. It only bounds owner capacity. Rewards (`OwnerReward`), leases and receipts
  carry the full 512-bit key id.
- **Stable job identity:** `tx_id` hashes the job without its signature, so re-signing never
  changes a job's identity.
- **Relay ids:** `block_id` and `tx_id` leave out signatures, so anyone can forge an invalid
  copy that shares an honest object's id. The node's relay and rejection caches therefore
  key on a hash of the full signed encoding (`chain::block_relay_id`, `chain::job_relay_id`),
  and a forged copy cannot shadow the genuine block or job. A block's relay id covers its
  body as well, so a genuine header carrying a forged body cannot shadow the block either.

`crypto_suite_id` is 1 (SHA3-512 + SHAKE256 + ML-DSA-87; SLH-DSA-SHAKE-256s co-signs
treasury withdrawals).

## Share gossip

The wire protocol carries `GossipShare(ShareProof)`. Every node keeps a share pool (`node::share_pool`)
of verified shares, its own and gossiped ones, one per `work_id`. Templates take up to
`max_shares_per_block` of them, whoever mined them, oldest height first, and emit them sorted by
`work_id`, so a share counts for rewards and leases even if its owner never seals a block.

A gossiped share enters the pool, and is relayed onward, only after every check passes,
cheapest first:

1. Dedupe: by relay id (`chain::share_relay_id`, the full signed encoding), by `work_id`
   against the pool (work-checked shares only), and by (owner key id, `work_id`) against
   shares still awaiting their work check. A slot is only taken once the owner signature
   verified, so a forged copy, or a claim to another owner's `work_id`, cannot shadow the
   genuine share, and re-signed copies (ML-DSA signing is randomized) cost nothing.
2. No-work checks (`BlockTree::check_gossip_share`): context constants, owner binding,
   height, anchor and target on the share's own branch, inclusion window, not yet
   registered.
3. Limits on shares awaiting their work check: 8 per source, 64 in total.
4. The ML-DSA-87 signature, checked on the spot.
5. Its tile, recomputed off the chain actor on a separate, smaller verification budget,
   so a block's Stage A never queues behind share gossip.

A share whose parent block is in Stage A waits for it (signature already checked, counted
in the limits), and is dropped if that block fails. Such a share, a stale one and one whose
parent is unknown are dropped without penalty and not remembered as seen, so a later relay
can still deliver them. Useless shares (ignored for any reason, including the limits above,
or duplicates under a new encoding) are budgeted at 256 a minute per peer; past that, the
peer's shares are dropped unread until the minute is up. The peer is throttled, not banned,
since an honest peer that is syncing sends many such shares. A peer that sends an invalid
share is banned, even if it disconnected first, and a ban closes every connection from its
source (see [Verification limits](#verification-limits)). A dialer backs off unless the
connection lasts a minute, so a peer that drops it at once is not redialed every second.

Templates include only fully verified shares, and `validate_genesis` requires every block
to fit a full set of `max_shares_per_block` shares, two withdrawals of the largest size
and 16 KiB of headroom. The pool is
pruned when shares leave the inclusion window or are registered on the canonical chain,
and the shares of abandoned blocks return to it on a reorg.

## Known gaps (blueprint §1.2)

**D'Hondt continuity.** Each registered share stores its cumulative
`allocated_slots`. Lease allocation restores those counters before every batch and
adds the newly assigned slots back to the block state. Counters survive idle blocks
and epoch boundaries until the share is pruned; a reorganization selects the counters
from the corresponding branch snapshot. The scheduler exposes `Cohort::with_counters`
to restore that state without changing its allocation rule.

Gaps 1 (placeholder hashing), 2 (self-declared integer owners, no signatures) and 4 (shares
not gossiped) are closed in this testnet. The numbering of the remaining gaps follows the blueprint.

- **Shared faucet.** The core ledger has no per-account balances (see the testnet note
  in `ledger/src/lib.rs`), so a job's signature authenticates its client, but its deposit
  is debited from the aggregate `U`, and the outputs of a pool withdrawal are credited
  to it (their recipients are recorded in the block).

3. **VerifyFW by recomputation.** Validators recompute every claimed tile instead of
   verifying a Circle STARK. There is no P-DAL (Reed–Solomon layer).
   The Technical Specification derives a 19.5 GiB peak prover-memory bound for its
   stated Circle STARK trace and buffer profile, and assumes a 2-second
   discovery-to-validation delay bound in its nominal security analysis. These are
   mathematical model bounds, conditional on the specified profile and assumptions,
   rather than measured performance. In this testnet, VerifyFW is done via
   recomputation. Empirical benchmarks for the STARK prover memory and the complete
   proving-to-validation delay are pending full integration.
5. **Commercial execution is replicated.** Every validator recomputes each job's result.
   The lessee is the executor by attribution only. Commercial weight stays 0
   (`scivm::CONSENSUS_WEIGHT`).
6. **No refunds or timeouts.** The core ledger has no `ESCROW_REFUND` or `LEASE_TIMEOUT`,
   so every admitted job settles deterministically after `settle_delay` blocks.
7. **Issuance and the valve count blocks.** `N_I`, `H_M` (1,051,200 blocks) and the
   720-block InitialValve window assume the specification's 120-second blocks; at the
   testnet's shorter `target_block_secs` they pass sooner in wall-clock time.
8. **Canonical history retention.** Canonical blocks remain in memory. Non-canonical
   branches beyond the reorganization horizon are removed from all tree indexes;
   exhausted fee lots and expired job replay identifiers are pruned.

## Core adapter (blueprint §13.2 A1)

The core math is unchanged. `primitives` provides SHA3-512/SHAKE256 behind its hashing
interface and exposes the digest bytes (the XOF type is now
`Shake256Xof`, formerly `MockXof`):

```rust
impl DomainSeparatedHash {
    /// The digest bytes by value; inverse of [`DomainSeparatedHash::from_bytes`].
    pub const fn to_bytes(&self) -> [u8; DIGEST_LEN] { self.0 }
}
```

`from_bytes` and `as_bytes` already existed. Every conversion between wire digests and core
hashes lives in `chain::core_adapter`, and so does the bridge from verified ML-DSA-87 keys
to the scheduler's `OwnerId`.

## PoC placeholders in the core

- **Hashing (real in this testnet):** `DomainSeparatedHash` is SHA3-512 and `Shake256Xof` is
  SHAKE256, both over the normative encoding: a domain label, an injective length-prefixed
  encoding, and 64-byte digests.
- **Signatures:** ML-DSA-87 lives in the `chain` crate in this testnet. The core crates take only the
  derived `OwnerId`.
- **Not implemented:** ML-KEM, the Circle STARK and P-DAL. SLH-DSA-SHAKE-256s is used only
  for the treasury co-signature.
- **Share weights:** `ShareWeight` is `u64`. The normative `w_s = ⌊2^640/Θ_S⌋` needs a bignum.
  With `u64` weights, every D'Hondt and payout cross-product is exact in `u128`.
- **Aggregate balances:** `U`, `B_bond` and `V_L2` hold totals only, with no per-UTXO
  ownership.
- **Deployment parameters:** epoch length, maturation delay `L`, `η` and fee tariffs are
  illustrative values in `LedgerParams::poc()`. The testnet takes them from its genesis file.

## Ledger category mapping

The 10 transparent categories are the ones of eqs. (7.9) and (7.15); there is no shielded
pool and no founder allocation. Escrows, locked fees, `MatureFeeLots`, booked rewards, the
emission counters and the InitialValve ring are sub-ledgers, not extra balances.

| Variant               | Symbol      | Holds |
|-----------------------|-------------|-------|
| `Circulating`         | `U`         | public outputs (aggregate) |
| `InitialProtocolPool` | `U_initial` | released initial allocation, paid out only through the InitialValve |
| `Escrow`              | `E_esc`     | per-job escrows |
| `Bonds`               | `B_bond`    | executor bonds |
| `L2Vaults`            | `V_L2`      | rollup settlement vaults |
| `EmissionReserve`     | `R_a`       | mature fee lots + segregated dust |
| `LockedBaseFees`      | `R_l`       | Base Fees, queue fees and withdrawal fees awaiting maturation |
| `PendingRewards`      | `P_pending` | booked, unpaid Fresh Work rewards + the miner release not yet booked |
| `UnissuedInitial`     | `R_I`       | unissued initial allocation (`I = M/10` at Genesis) |
| `UnissuedMiners`      | `R_M`       | unissued miner allocation (`M − I` at Genesis) |
EOF

