//! Consensus difficulty retargeting and seal/share weights (§6.4, §6.5).

use wire::{BlockHeader, DifficultyMode, Digest, GenesisConfig, MIN_TARGET, Target};

/// Read-only view of one branch's ancestor metadata, used by Stage B and retargeting.
pub trait ChainView {
    /// Returns the block identifier at height `h` (`genesis_id` at `h == 0`).
    fn block_id_at(&self, h: u64) -> Digest;
    /// Returns the `time_bucket` at height `h` (`genesis_time_bucket` at `h == 0`).
    fn time_bucket_at(&self, h: u64) -> u64;
    /// Returns `(seal_target, share_target)` at height `h`.
    fn targets_at(&self, h: u64) -> (Target, Target);
}

/// Computes `Θ_S = saturating_mul(Θ_B, ratio)` (§6.4).
pub fn share_target_for(seal: Target, ratio: u64) -> Target {
    Target(seal.0.saturating_mul(u128::from(ratio)))
}

/// Computes `(seal_target, share_target)` for the block at height `h >= 1` from its
/// ancestors only (§6.4).
pub fn expected_targets(h: u64, chain: &impl ChainView, g: &GenesisConfig) -> (Target, Target) {
    let prev_h = h.saturating_sub(1);
    let prev = if prev_h == 0 {
        g.initial_seal_target
    } else {
        chain.targets_at(prev_h).0
    };
    let seal = match g.difficulty {
        DifficultyMode::Windowed { window: n }
            if n > 0 && prev_h.is_multiple_of(n) && prev_h >= 2 * n =>
        {
            let actual = chain
                .time_bucket_at(prev_h)
                .saturating_sub(chain.time_bucket_at(prev_h - n));
            let expected = n.saturating_mul(g.target_block_secs / g.time_bucket_secs);
            Target(scale_target(prev.0, actual, expected))
        }
        _ => prev,
    };
    (seal, share_target_for(seal, g.share_ratio))
}

/// `floor(T * actual / expected)`, with `actual` clamped to `[ceil(expected/4), 4*expected]`,
/// exact in `u128`, saturating at `u128::MAX`, floored at `MIN_TARGET` (§6.4).
pub fn scale_target(t: u128, actual: u64, expected: u64) -> u128 {
    let e = expected.max(1);
    let a = u128::from(actual.clamp(e.div_ceil(4), e.saturating_mul(4)));
    let e = u128::from(e);
    (t / e)
        .checked_mul(a)
        .and_then(|x| x.checked_add((t % e) * a / e))
        .unwrap_or(u128::MAX)
        .max(MIN_TARGET)
}

/// Work of a target in units of `2^-32` attempts: `floor((2^128 - 1) / floor(T / 2^32))` (§6.5).
///
/// Targets are at least `MIN_TARGET = 2^64`, so the divisor is never zero for valid
/// headers; the `max(1)` only guards malformed input.
pub fn work_of(t: Target) -> u128 {
    u128::MAX / (t.0 >> 32).max(1)
}

/// Seal weight `d_B` of a block header, WP (5.10) (§6.5).
pub fn seal_weight(h: &BlockHeader) -> u128 {
    work_of(h.seal_target)
}

/// Share weight `w_s` of a share target, WP (6.1) (§6.5).
pub fn share_weight(t: Target) -> u64 {
    u64::try_from(work_of(t)).unwrap_or(u64::MAX)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn appendix_b_difficulty_and_weight_vectors() {
        assert_eq!(scale_target(1u128 << 100, 320, 320), 1u128 << 100);
        assert_eq!(scale_target(1u128 << 100, 640, 320), 1u128 << 101);
        assert_eq!(scale_target(1u128 << 100, 10_000, 320), 1u128 << 102);
        assert_eq!(scale_target(1u128 << 100, 1, 320), 1u128 << 98);
        assert_eq!(scale_target(u128::MAX, 640, 320), u128::MAX);
        assert_eq!(scale_target(1000, 320, 320), 1u128 << 64);

        let default_seal = Target(u128::MAX / 32);
        assert_eq!(work_of(default_seal), 137_438_953_472);
        assert_eq!(work_of(default_seal), 32 * (1u128 << 32));
        assert_eq!(work_of(Target(u128::MAX / 64)) >> 32, 64);
        assert_eq!(
            share_weight(share_target_for(default_seal, 4)),
            34_359_738_368
        );
        assert_eq!(share_weight(share_target_for(default_seal, 4)), 1u64 << 35);
    }

    struct Flat {
        tb: Vec<u64>,
        seal: Target,
    }

    impl ChainView for Flat {
        fn block_id_at(&self, _h: u64) -> Digest {
            Digest::ZERO
        }
        fn time_bucket_at(&self, h: u64) -> u64 {
            self.tb[h as usize]
        }
        fn targets_at(&self, _h: u64) -> (Target, Target) {
            (self.seal, share_target_for(self.seal, 4))
        }
    }

    #[test]
    fn windowed_retarget_fires_only_at_window_boundaries() {
        let mut g = GenesisConfig::default_testnet(0);
        g.difficulty = DifficultyMode::Windowed { window: 4 };
        g.target_block_secs = 10;
        let seal = Target(1u128 << 100);
        // Blocks arrive twice as slowly as targeted: 20 s apart.
        let chain = Flat {
            tb: (0..20).map(|h| h * 20).collect(),
            seal,
        };
        for h in 1..=8 {
            assert_eq!(
                expected_targets(h, &chain, &g).0,
                if h == 1 { g.initial_seal_target } else { seal }
            );
        }
        // h - 1 = 8 = 2n: the first retarget doubles the target.
        assert_eq!(expected_targets(9, &chain, &g).0, Target(1u128 << 101));
        assert_eq!(expected_targets(10, &chain, &g).0, seal);
        assert_eq!(expected_targets(13, &chain, &g).0, Target(1u128 << 101));
    }
}
EOF

cat << 'EOF' > chain/src/keys.rs
//! Keys (`chain::keys`): ML-DSA-87 owner keys from a FIPS 204 seed, which sign
//! headers, shares and jobs, and the treasury key pair (ML-DSA-87 plus an
//! SLH-DSA-SHAKE-256s co-signer, FIPS 205), which signs InitialProtocolPool
//! withdrawals.
//!
//! Verification lives in [`crate::core_adapter`]; this module only signs.

use core::fmt;

use fips205::slh_dsa_shake_256s;
use fips205::traits::{KeyGen as _, SerDes as _, Signer as _};
use ml_dsa::common::getrandom::SysRng;
use ml_dsa::{ExpandedSigningKey, MlDsa87, Seed};
use wire::{
    BlockHeader, Digest, InitialPoolWithdrawal, JobTransaction, PublicKey, SLH_DSA_SIGNATURE_LEN,
    ShareProof, Signature, SlhDsaPublicKey, SlhDsaSignature,
};

use crate::core_adapter::{
    SIGNATURE_CONTEXT, cosigner_key_id, header_signing_digest, job_signing_digest,
    owner_id_from_key_id, owner_key_id, share_signing_digest, withdrawal_signing_digest,
};

/// Length of the FIPS 204 key-generation seed `ξ`, the only secret that is stored.
pub const SEED_LEN: usize = 32;

/// An ML-DSA-87 key pair with its on-chain identity.
pub struct OwnerKeypair {
    seed: [u8; SEED_LEN],
    /// Boxed: the expanded key is about 100 KB, too large to move around by value
    /// (unoptimized builds overflow a 2 MiB thread stack).
    signing_key: Box<ExpandedSigningKey<MlDsa87>>,
    public_key: PublicKey,
    key_id: Digest,
}

impl OwnerKeypair {
    /// Derives the key pair from a 32-byte seed (FIPS 204 `ML-DSA.KeyGen_internal`).
    pub fn from_seed(seed: &[u8; SEED_LEN]) -> Self {
        let signing_key = Box::new(ExpandedSigningKey::<MlDsa87>::from_seed(&Seed::from(*seed)));
        let encoded = signing_key.verifying_key().encode();
        let public_key =
            PublicKey::from_slice(&encoded).expect("invariant: ML-DSA-87 keys are 2,592 bytes");
        let key_id = owner_key_id(&public_key);
        Self {
            seed: *seed,
            signing_key,
            public_key,
            key_id,
        }
    }

    /// Generates a fresh key pair from the operating system's RNG.
    pub fn generate() -> Result<Self, String> {
        let mut seed = [0u8; SEED_LEN];
        ml_dsa::common::getrandom::fill(&mut seed)
            .map_err(|e| format!("OS random number generator failed: {e}"))?;
        Ok(Self::from_seed(&seed))
    }

    /// The secret seed. Treat it as key material.
    pub fn seed(&self) -> &[u8; SEED_LEN] {
        &self.seed
    }

    /// The encoded public key.
    pub fn public_key(&self) -> &PublicKey {
        &self.public_key
    }

    /// The owner key id, `H(PLAU/OWNER, public key)`.
    pub fn key_id(&self) -> Digest {
        self.key_id
    }

    /// The 64-bit `scheduler::OwnerId` derived from the key id.
    pub fn owner_id(&self) -> u64 {
        owner_id_from_key_id(&self.key_id)
    }

    /// Signs a domain-separated digest with hedged (randomized) FIPS 204 `ML-DSA.Sign`
    /// and the context [`SIGNATURE_CONTEXT`].
    pub fn sign_digest(&self, digest: &Digest) -> Result<Signature, String> {
        let sig = self
            .signing_key
            .sign_randomized(&digest.0, SIGNATURE_CONTEXT, &mut SysRng)
            .map_err(|e| format!("ML-DSA-87 signing failed: {e}"))?;
        Signature::from_slice(&sig.encode())
    }

    /// Sets `header.miner_key` to this key and signs the header.
    pub fn sign_header(&self, header: &mut BlockHeader) -> Result<(), String> {
        header.miner_key = self.public_key.clone();
        header.signature = self.sign_digest(&header_signing_digest(header)?)?;
        Ok(())
    }

    /// Sets `share.owner_key` to this key and signs the share.
    pub fn sign_share(&self, share: &mut ShareProof) -> Result<(), String> {
        share.owner_key = self.public_key.clone();
        share.signature = self.sign_digest(&share_signing_digest(share)?)?;
        Ok(())
    }

    /// Sets `tx.client_key` to this key and signs the job for the chain with `genesis_id`.
    pub fn sign_job(&self, tx: &mut JobTransaction, genesis_id: &Digest) -> Result<(), String> {
        tx.client_key = self.public_key.clone();
        tx.signature = self.sign_digest(&job_signing_digest(tx, genesis_id)?)?;
        Ok(())
    }
}

impl fmt::Debug for OwnerKeypair {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("OwnerKeypair")
            .field("key_id", &self.key_id)
            .finish_non_exhaustive()
    }
}

/// An all-zero signature: the placeholder a freshly built object carries until it is signed.
pub fn unsigned() -> Signature {
    Signature(Box::new([0u8; wire::SIGNATURE_LEN]))
}

/// An all-zero SLH-DSA-SHAKE-256s signature, the co-signature placeholder.
pub fn unsigned_cosignature() -> SlhDsaSignature {
    SlhDsaSignature(Box::new([0u8; SLH_DSA_SIGNATURE_LEN]))
}

/// Length of the SLH-DSA-SHAKE-256s key-generation seeds `SK.seed || SK.prf || PK.seed`
/// (FIPS 205 §10.1, `n = 32` bytes each), the co-signer's only stored secret.
pub const COSIGNER_SEED_LEN: usize = 96;

/// The treasury key pair guarding the InitialProtocolPool: an ML-DSA-87 signer and an
/// independent SLH-DSA-SHAKE-256s co-signer. Withdrawals need both signatures (spec
/// eq. 2.5).
pub struct TreasuryKeypair {
    signer: OwnerKeypair,
    cosigner_seed: [u8; COSIGNER_SEED_LEN],
    cosigner: slh_dsa_shake_256s::PrivateKey,
    cosigner_public_key: SlhDsaPublicKey,
    cosigner_key_id: Digest,
}

impl TreasuryKeypair {
    /// Derives both keys from their seeds (FIPS 204 `ML-DSA.KeyGen_internal` and
    /// FIPS 205 `slh_keygen_internal`).
    pub fn from_seeds(
        signer_seed: &[u8; SEED_LEN],
        cosigner_seed: &[u8; COSIGNER_SEED_LEN],
    ) -> Self {
        let part = |i: usize| -> [u8; 32] {
            cosigner_seed[32 * i..32 * (i + 1)]
                .try_into()
                .expect("invariant: three 32-byte seeds")
        };
        let (public, cosigner) =
            slh_dsa_shake_256s::KG::keygen_from_seed(&part(0), &part(1), &part(2));
        let cosigner_public_key = SlhDsaPublicKey(Box::new(public.into_bytes()));
        Self {
            signer: OwnerKeypair::from_seed(signer_seed),
            cosigner_seed: *cosigner_seed,
            cosigner,
            cosigner_key_id: cosigner_key_id(&cosigner_public_key),
            cosigner_public_key,
        }
    }

    /// Generates a fresh treasury key pair from the operating system's RNG.
    pub fn generate() -> Result<Self, String> {
        let mut signer_seed = [0u8; SEED_LEN];
        let mut cosigner_seed = [0u8; COSIGNER_SEED_LEN];
        ml_dsa::common::getrandom::fill(&mut signer_seed)
            .and_then(|()| ml_dsa::common::getrandom::fill(&mut cosigner_seed))
            .map_err(|e| format!("OS random number generator failed: {e}"))?;
        Ok(Self::from_seeds(&signer_seed, &cosigner_seed))
    }

    /// The ML-DSA-87 signer.
    pub fn signer(&self) -> &OwnerKeypair {
        &self.signer
    }

    /// The co-signer's secret seeds. Treat them as key material.
    pub fn cosigner_seed(&self) -> &[u8; COSIGNER_SEED_LEN] {
        &self.cosigner_seed
    }

    /// The co-signer's encoded public key.
    pub fn cosigner_public_key(&self) -> &SlhDsaPublicKey {
        &self.cosigner_public_key
    }

    /// `GenesisConfig::treasury_key_id`: the signer's key id, `H(PLAU/OWNER, public key)`.
    pub fn key_id(&self) -> Digest {
        self.signer.key_id()
    }

    /// `GenesisConfig::treasury_cosigner_key_id`: `H(PLAU/COSIGNER, public key)`.
    pub fn cosigner_key_id(&self) -> Digest {
        self.cosigner_key_id
    }

    /// Sets both treasury keys on the withdrawal and signs it for the chain with
    /// `genesis_id`, with hedged ML-DSA-87 and hedged SLH-DSA-SHAKE-256s. The
    /// SLH-DSA signature takes seconds.
    pub fn sign_withdrawal(
        &self,
        withdrawal: &mut InitialPoolWithdrawal,
        genesis_id: &Digest,
    ) -> Result<(), String> {
        withdrawal.ml_dsa_key = self.signer.public_key().clone();
        withdrawal.slh_dsa_key = self.cosigner_public_key.clone();
        let digest = withdrawal_signing_digest(withdrawal, genesis_id)?;
        withdrawal.ml_dsa_signature = self.signer.sign_digest(&digest)?;
        withdrawal.slh_dsa_signature = self.cosign_digest(&digest)?;
        Ok(())
    }

    /// Hedged SLH-DSA-SHAKE-256s signature (FIPS 205 `SLH-DSA.Sign`, pure, context
    /// `PLAU/TX`) over a domain-separated digest. Takes seconds.
    pub fn cosign_digest(&self, digest: &Digest) -> Result<SlhDsaSignature, String> {
        let cosignature = self
            .cosigner
            .try_sign(&digest.0, SIGNATURE_CONTEXT, true)
            .map_err(|e| format!("SLH-DSA-SHAKE-256s signing failed: {e}"))?;
        Ok(SlhDsaSignature(Box::new(cosignature)))
    }
}

impl fmt::Debug for TreasuryKeypair {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("TreasuryKeypair")
            .field("key_id", &self.key_id())
            .field("cosigner_key_id", &self.cosigner_key_id)
            .finish_non_exhaustive()
    }
}
EOF

