cat << 'EOF' > chain/src/stf.rs
//! State transition function (`chain::stf`, §7).
//!
//! [`apply_body`] opens every block `k = h - h_G >= 1` with the decoupled primary
//! issuance (spec eqs. 7.19b–7.19g) and admits InitialProtocolPool withdrawals only
//! under `InitialOK` (eq. 7.19j), the 720-block InitialValve included.

use core::fmt;
use std::collections::BTreeMap;

use ledger::{BalanceDelta, INITIAL_VALVE_LIMIT, JobId, Ledger, LedgerError, StateCategory};
use primitives::{Atoms, ShareWeight};
use scheduler::{Capacity, Cohort, OwnerId, ShareID};
use wire::{
    CategoryDelta, Digest, FeeTransition, GenesisConfig, InitialPoolWithdrawal, JobTransaction,
    LeaseAssignment, MAX_WITHDRAWALS_PER_BLOCK, OwnerReward, SettlementReceipt, ShareProof,
    WithdrawalOutput,
};

use crate::core_adapter::{
    JobValidationError, LABEL_LEDGER, SignatureError, VerifiedOwner, WithdrawalError,
    compute_result_digest, compute_withdrawal_id, digest_to_hash, domain_hash,
    validate_job_stateless, validate_withdrawal_stateless, verify_share_owner,
    verify_withdrawal_signatures,
};
use crate::difficulty::share_weight;

/// Registered Fresh Work share in `NodeState` (§7.1).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ShareRecord {
    /// ShareID.
    pub work_id: Digest,
    /// Beneficiary, whose signature was verified before registration.
    pub owner: VerifiedOwner,
    /// `w_s`, fixed by the share target at the share's height.
    pub weight: u64,
    /// Height the share was mined at.
    pub height: u64,
    /// Height of the block that registered it.
    pub included_at: u64,
    /// Cumulative D'Hondt slots `a_s`, retained until this share is pruned.
    pub allocated_slots: u64,
}

/// Admitted commercial job awaiting settlement in `NodeState` (§7.1).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct OpenJob {
    /// Job identifier.
    pub job_id: u64,
    /// Transaction identifier.
    pub tx_id: Digest,
    /// Height of `JOB_ADMIT_AND_LEASE`.
    pub admitted_at: u64,
    /// Lease owner's key id (executor by attribution).
    pub owner: Digest,
    /// Leased ShareID.
    pub share_id: Digest,
    /// Executor remuneration.
    pub v_exec: u64,
    /// Data-availability remuneration.
    pub v_da: u64,
    /// Refund share.
    pub v_ref: u64,
    /// Exact dot product computed at admission.
    pub result: i128,
}

/// Immutable per-block state snapshot (§7.1).
#[derive(Clone, Debug)]
pub struct NodeState {
    /// Height of the block this state follows.
    pub height: u64,
    /// The ten-category core ledger.
    pub ledger: Ledger,
    /// Registered shares by ShareID (pruned per §6.7).
    pub shares: BTreeMap<Digest, ShareRecord>,
    /// Admitted, unsettled jobs by `job_id`.
    pub open_jobs: BTreeMap<u64, OpenJob>,
    /// Used `tx_id`s with their expiry height (pruned once expired).
    pub used_tx: BTreeMap<Digest, u64>,
    /// Used `job_id`s with their expiry height (pruned once expired).
    pub used_job_ids: BTreeMap<u64, u64>,
}

impl NodeState {
    /// Builds the genesis `NodeState` at height 0 (§3.4).
    pub fn genesis(ledger: Ledger) -> Self {
        Self {
            height: 0,
            ledger,
            shares: BTreeMap::new(),
            open_jobs: BTreeMap::new(),
            used_tx: BTreeMap::new(),
            used_job_ids: BTreeMap::new(),
        }
    }

    /// Returns the mature D'Hondt lease cohort for a block at height `h`, sorted by
    /// ShareID (§6.7).
    pub fn lease_cohort(&self, h: u64, g: &GenesisConfig) -> Vec<ShareRecord> {
        let Some(max_inc) = h.checked_sub(g.share_maturity_depth) else {
            return Vec::new();
        };
        let min_inc = h.saturating_sub(g.snapshot_window);
        self.shares_included_in(min_inc, max_inc)
    }

    /// Returns the shares weighed at the epoch boundary `h`: those included in the
    /// previous epoch, sorted by ShareID (§6.7).
    pub fn epoch_shares(&self, h: u64, g: &GenesisConfig) -> Vec<ShareRecord> {
        let Some(max_inc) = h.checked_sub(1) else {
            return Vec::new();
        };
        self.shares_included_in(h.saturating_sub(g.blocks_per_epoch), max_inc)
    }

    fn shares_included_in(&self, min_inc: u64, max_inc: u64) -> Vec<ShareRecord> {
        // `shares` is a BTreeMap keyed by work_id, so the result is in ShareID order.
        self.shares
            .values()
            .filter(|s| (min_inc..=max_inc).contains(&s.included_at))
            .cloned()
            .collect()
    }
}

/// Share pre-validated (Stage A and B) for `apply_body` (§7.2).
///
/// The fields are private and [`VerifiedShare::verify`] is the only constructor: it
/// checks the proof's own ML-DSA-87 owner signature and takes every field from that
/// same proof, so `apply_body` never registers a share its owner did not sign.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct VerifiedShare {
    work_id: Digest,
    owner: VerifiedOwner,
    weight: u64,
    height: u64,
}

impl VerifiedShare {
    /// Verifies the share's owner signature and returns its `apply_body` view.
    pub fn verify(share: &ShareProof) -> Result<Self, SignatureError> {
        Ok(Self {
            work_id: share.work_id,
            owner: verify_share_owner(share)?,
            weight: share_weight(share.share_target),
            height: share.context.height,
        })
    }

    /// ShareID.
    pub fn work_id(&self) -> Digest {
        self.work_id
    }

    /// Beneficiary, whose signature on this share verified.
    pub fn owner(&self) -> VerifiedOwner {
        self.owner
    }

    /// `w_s`, from the share target.
    pub fn weight(&self) -> u64 {
        self.weight
    }

    /// Height the share was mined at.
    pub fn height(&self) -> u64 {
        self.height
    }
}

/// A share proof together with its [`VerifiedShare`] view, as kept in a share pool.
///
/// [`SignedShare::verify`] is the only constructor, so the two always belong
/// together and the owner signature is checked exactly once, on entry.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SignedShare {
    proof: ShareProof,
    verified: VerifiedShare,
}

impl SignedShare {
    /// Verifies the proof's owner signature (not its work) and pairs it with its view.
    pub fn verify(proof: ShareProof) -> Result<Self, SignatureError> {
        let verified = VerifiedShare::verify(&proof)?;
        Ok(Self { proof, verified })
    }

    /// The share proof.
    pub fn proof(&self) -> &ShareProof {
        &self.proof
    }

    /// Its verified `apply_body` view.
    pub fn verified(&self) -> &VerifiedShare {
        &self.verified
    }
}

/// An InitialProtocolPool withdrawal whose treasury dual signature verified under the
/// genesis treasury keys: the `Accept_treasury` conjunct of `InitialOK` (spec eqs.
/// 2.5, 7.19j).
///
/// The fields are private and [`VerifiedWithdrawal::verify`] is the only constructor,
/// so `apply_body` never debits the InitialProtocolPool for a withdrawal the treasury
/// did not sign with both keys.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct VerifiedWithdrawal {
    tx_id: Digest,
    expected_nonce: u64,
    amount: u64,
    fee: u64,
    outputs: Vec<WithdrawalOutput>,
}

impl VerifiedWithdrawal {
    /// Checks the withdrawal against the genesis treasury policy, then verifies its
    /// ML-DSA-87 signature and SLH-DSA-SHAKE-256s co-signature for `genesis_id`.
    pub fn verify(
        withdrawal: &InitialPoolWithdrawal,
        genesis: &GenesisConfig,
        genesis_id: &Digest,
    ) -> Result<Self, WithdrawalError> {
        let (amount, fee) = validate_withdrawal_stateless(withdrawal, genesis)?;
        verify_withdrawal_signatures(withdrawal, genesis_id).map_err(WithdrawalError::Signature)?;
        let tx_id = compute_withdrawal_id(withdrawal)
            .map_err(|e| WithdrawalError::Signature(SignatureError::Encoding(e)))?;
        Ok(Self {
            tx_id,
            expected_nonce: withdrawal.expected_nonce,
            amount,
            fee,
            outputs: withdrawal.outputs.clone(),
        })
    }

    /// The withdrawal's `TxID`.
    pub fn tx_id(&self) -> Digest {
        self.tx_id
    }

    /// `ν_expected`.
    pub fn expected_nonce(&self) -> u64 {
        self.expected_nonce
    }

    /// `v`, paid to `U`.
    pub fn amount(&self) -> u64 {
        self.amount
    }

    /// `f`, paid to `R_l`.
    pub fn fee(&self) -> u64 {
        self.fee
    }

    /// The public outputs.
    pub fn outputs(&self) -> &[WithdrawalOutput] {
        &self.outputs
    }
}

/// A withdrawal together with its [`VerifiedWithdrawal`] view, as kept in a mempool.
///
/// [`SignedWithdrawal::verify`] is the only constructor, so both treasury signatures
/// are checked exactly once, on entry.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SignedWithdrawal {
    withdrawal: InitialPoolWithdrawal,
    verified: VerifiedWithdrawal,
}

impl SignedWithdrawal {
    /// Verifies the withdrawal (see [`VerifiedWithdrawal::verify`]) and pairs it with its view.
    pub fn verify(
        withdrawal: InitialPoolWithdrawal,
        genesis: &GenesisConfig,
        genesis_id: &Digest,
    ) -> Result<Self, WithdrawalError> {
        let verified = VerifiedWithdrawal::verify(&withdrawal, genesis, genesis_id)?;
        Ok(Self {
            withdrawal,
            verified,
        })
    }

    /// The withdrawal.
    pub fn withdrawal(&self) -> &InitialPoolWithdrawal {
        &self.withdrawal
    }

    /// Its verified `apply_body` view.
    pub fn verified(&self) -> &VerifiedWithdrawal {
        &self.verified
    }
}

/// Derived body commitments produced by `apply_body` (§5.3, §7.2).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct DerivedBody {
    /// `leases[i]` belongs to `jobs[i]`.
    pub leases: Vec<LeaseAssignment>,
    /// Receipts of the jobs settled in this block.
    pub receipts: Vec<SettlementReceipt>,
    /// Every ledger operation, in execution order.
    pub fee_transitions: Vec<FeeTransition>,
    /// Commitment to the post-state.
    pub ledger_digest: Digest,
}

/// Errors produced by `apply_body` (§7.2). Any error rejects the whole block.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum StfError {
    /// A core ledger operation was rejected.
    Ledger(LedgerError),
    /// More than `max_jobs_per_block` jobs.
    TooManyJobs(usize),
    /// More than `max_shares_per_block` shares.
    TooManyShares(usize),
    /// More than `MAX_WITHDRAWALS_PER_BLOCK` withdrawals.
    TooManyWithdrawals(usize),
    /// Withdrawals are not strictly increasing by `expected_nonce`.
    WithdrawalsNotSorted,
    /// `InitialOK`: the withdrawal does not carry the current `InitialNonce`.
    InitialNonce {
        /// The current `InitialNonce`.
        expected: u64,
        /// The nonce the withdrawal carries.
        found: u64,
    },
    /// `InitialOK`: the InitialProtocolPool cannot cover `v + f`.
    InsufficientInitialPool {
        /// `U_initial`.
        available: u64,
        /// `v + f`.
        requested: u64,
    },
    /// `InitialOK`: the rolling 720-block InitialValve would exceed `L_I`.
    InitialValveExceeded {
        /// Gross outflow already in the window.
        rolling: u64,
        /// `v + f`.
        requested: u64,
    },
    /// Jobs are not strictly increasing by `tx_id`.
    JobsNotSortedOrUnique,
    /// Shares are not strictly increasing by `work_id`.
    SharesNotSortedOrUnique,
    /// A job fails stateless validation.
    InvalidJob(JobValidationError),
    /// A job is included after its expiry height.
    JobExpired {
        /// The job.
        job_id: u64,
        /// Its expiry height.
        expiry: u64,
        /// The including height.
        height: u64,
    },
    /// The job would retain replay state beyond the allowed lifetime.
    JobExpiryTooFar,
    /// Jobs would spend more than one sixteenth of this block's spendable faucet.
    FaucetBudgetExceeded,
    /// The block would exceed the active plus locked fee-lot bound.
    FeeLotCapacity,
    /// The `tx_id` was already used.
    DuplicateTx(Digest),
    /// The `job_id` was already used.
    DuplicateJobId(u64),
    /// Jobs were included while the mature share cohort is empty.
    EmptyLeaseCohort,
    /// The D'Hondt scheduler rejected the cohort or did not fill every slot.
    SchedulerError(String),
    /// The share is already registered.
    DuplicateShare(Digest),
}

impl fmt::Display for StfError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            StfError::Ledger(e) => write!(f, "ledger error: {e}"),
            StfError::TooManyJobs(n) => write!(f, "too many jobs in block: {n}"),
            StfError::TooManyShares(n) => write!(f, "too many shares in block: {n}"),
            StfError::TooManyWithdrawals(n) => write!(f, "too many withdrawals in block: {n}"),
            StfError::WithdrawalsNotSorted => {
                write!(f, "withdrawals must be strictly sorted by expected_nonce")
            }
            StfError::InitialNonce { expected, found } => write!(
                f,
                "InitialNonce is {expected}, the withdrawal carries {found}"
            ),
            StfError::InsufficientInitialPool {
                available,
                requested,
            } => write!(
                f,
                "InitialProtocolPool holds {available} atoms, the withdrawal needs {requested}"
            ),
            StfError::InitialValveExceeded { rolling, requested } => write!(
                f,
                "InitialValve: {rolling} atoms already in the 720-block window plus {requested} exceeds {}",
                INITIAL_VALVE_LIMIT.get()
            ),
            StfError::JobsNotSortedOrUnique => {
                write!(f, "jobs must be strictly sorted by tx_id")
            }
            StfError::SharesNotSortedOrUnique => {
                write!(f, "shares must be strictly sorted by work_id")
            }
            StfError::InvalidJob(e) => write!(f, "invalid job: {e}"),
            StfError::JobExpired {
                job_id,
                expiry,
                height,
            } => write!(f, "job {job_id} expired at {expiry} (height {height})"),
            StfError::JobExpiryTooFar => write!(f, "job expiry exceeds maximum lifetime"),
            StfError::FaucetBudgetExceeded => write!(f, "per-block faucet debit limit exceeded"),
            StfError::FeeLotCapacity => write!(f, "live fee-lot capacity exceeded"),
            StfError::DuplicateTx(id) => write!(f, "duplicate tx_id {id:?}"),
            StfError::DuplicateJobId(id) => write!(f, "duplicate job_id {id}"),
            StfError::EmptyLeaseCohort => {
                write!(f, "cannot admit jobs with an empty mature share cohort")
            }
            StfError::SchedulerError(msg) => write!(f, "scheduler error: {msg}"),
            StfError::DuplicateShare(id) => write!(f, "duplicate share work_id {id:?}"),
        }
    }
}

impl std::error::Error for StfError {}

impl From<LedgerError> for StfError {
    fn from(e: LedgerError) -> Self {
        StfError::Ledger(e)
    }
}

/// Converts a `ledger::BalanceDelta` to a wire `CategoryDelta` in `StateCategory::ALL` order (§5.7).
pub fn to_category_delta(delta: &BalanceDelta) -> CategoryDelta {
    StateCategory::ALL.map(|c| delta.get(c))
}

/// Computes `ledger_digest` from the post-state (§3.3, §5.8): the height and epoch,
/// the ten category balances, the fee and reward sub-ledgers, the emission counters,
/// `InitialNonce` and the InitialValve ring, in that order.
pub fn compute_ledger_digest(state: &NodeState) -> Digest {
    let ledger = &state.ledger;
    let emission = ledger.emission();
    let valve = ledger.initial_valve();
    let balances = StateCategory::ALL.map(|c| ledger.balance(c).get().to_be_bytes());
    let head = [state.height.to_be_bytes(), ledger.epoch().to_be_bytes()];
    let tail = [
        ledger.segregated_dust().get().to_be_bytes(),
        (ledger.fee_lots().len() as u64).to_be_bytes(),
        (ledger.locked_fees().len() as u64).to_be_bytes(),
        ledger.booked_rewards().get().to_be_bytes(),
        ledger.unbooked_release().get().to_be_bytes(),
        emission.block().to_be_bytes(),
        emission.initial_released().get().to_be_bytes(),
        ledger.initial_nonce().to_be_bytes(),
        valve.head().to_be_bytes(),
        valve.rolling_outflow().get().to_be_bytes(),
    ];
    let miner_state = emission.miner_state().to_be_bytes();
    let buckets: Vec<u8> = valve
        .buckets()
        .iter()
        .flat_map(|b| b.get().to_be_bytes())
        .collect();
    let parts: Vec<&[u8]> = head
        .iter()
        .chain(&balances)
        .chain(&tail)
        .map(|p| p.as_slice())
        .chain([miner_state.as_slice(), buckets.as_slice()])
        .collect();
    domain_hash(LABEL_LEDGER, &parts)
}

/// Normative state transition function `apply_body` (§7.2).
///
/// In order: (0) primary issuance, (1) epoch maintenance, (2) settlements,
/// (3) InitialProtocolPool withdrawals, (4) job funding, (5) leases, (6) share
/// registration, (7) pruning and the invariant check.
///
/// Works on a clone of `parent`; on any error the clone is discarded, so a block
/// applies all-or-nothing (spec eq. 7.10).
pub fn apply_body(
    parent: &NodeState,
    g: &GenesisConfig,
    h: u64,
    jobs: &[JobTransaction],
    shares: &[VerifiedShare],
    withdrawals: &[VerifiedWithdrawal],
) -> Result<(NodeState, DerivedBody), StfError> {
    if jobs.len() as u64 > g.max_jobs_per_block {
        return Err(StfError::TooManyJobs(jobs.len()));
    }
    if shares.len() as u64 > g.max_shares_per_block {
        return Err(StfError::TooManyShares(shares.len()));
    }
    if withdrawals.len() as u64 > MAX_WITHDRAWALS_PER_BLOCK {
        return Err(StfError::TooManyWithdrawals(withdrawals.len()));
    }
    if withdrawals
        .windows(2)
        .any(|w| w[0].expected_nonce >= w[1].expected_nonce)
    {
        return Err(StfError::WithdrawalsNotSorted);
    }
    if shares.windows(2).any(|w| w[0].work_id >= w[1].work_id) {
        return Err(StfError::SharesNotSortedOrUnique);
    }
    if let Some(dup) = shares
        .iter()
        .find(|sh| parent.shares.contains_key(&sh.work_id))
    {
        return Err(StfError::DuplicateShare(dup.work_id));
    }

    let mut s = parent.clone();
    let mut fee_transitions = Vec::new();
    let mut receipts = Vec::new();
    let mut leases = Vec::with_capacity(jobs.len());

    // (0) Primary issuance opens block k = h - h_G (spec eqs. 7.19b–7.19g): the linear
    // initial release R_I -> U_initial and the exact Q64 miner release R_M -> P_pending.
    // `begin_block` also slides the InitialValve window to k and admits only h = parent + 1.
    let (d_primary, release) = s.ledger.begin_block(h)?;
    fee_transitions.push(FeeTransition::PrimaryRelease {
        block: release.block,
        initial: release.initial.get(),
        miner: release.miner.get(),
        delta: to_category_delta(&d_primary),
    });

    // (1) Epoch boundary, spec eqs. (7.20)-(7.22)
    if h.is_multiple_of(g.blocks_per_epoch) {
        let e = s.ledger.epoch();
        let (d_mat, lots) = s.ledger.reserve_mature()?;
        fee_transitions.push(FeeTransition::ReserveMature {
            epoch: e,
            matured_lots: lots.into_iter().map(|l| l.0).collect(),
            delta: to_category_delta(&d_mat),
        });

        // The previous boundary's booking is paid now.
        let paid = s.ledger.booked_rewards();
        let d_rew = s.ledger.fw_reward(paid)?;
        fee_transitions.push(FeeTransition::FwReward {
            epoch: e,
            amount: paid.get(),
            delta: to_category_delta(&d_rew),
        });

        let epoch_cohort = s.epoch_shares(h, g);
        let weights: Vec<ShareWeight> = epoch_cohort.iter().map(|sh| sh.weight).collect();
        let (d_book, payout) = s.ledger.book_epoch(&weights)?;

        // Rewards are keyed by the full 512-bit key id, never by the 64-bit OwnerId.
        let mut owner_totals: BTreeMap<Digest, u64> = BTreeMap::new();
        for (sh, reward) in epoch_cohort.iter().zip(&payout.per_share) {
            if reward.get() > 0 {
                *owner_totals.entry(sh.owner.key_id()).or_insert(0) += reward.get();
            }
        }
        let per_owner: Vec<OwnerReward> = owner_totals
            .into_iter()
            .map(|(owner, atoms)| OwnerReward { owner, atoms })
            .collect();

        fee_transitions.push(FeeTransition::EpochBooked {
            epoch: e,
            budget: payout.budget.get(),
            booked: payout.booked.get(),
            dust: payout.dust.get(),
            release_budget: payout.release_budget.get(),
            release_booked: payout.release_booked.get(),
            release_carry: payout.release_carry.get(),
            lots: payout.lots.len() as u32,
            shares: weights.len() as u32,
            per_owner,
            delta: to_category_delta(&d_book),
        });
    }

    // (2) Settle the jobs admitted at h - settle_delay, in job_id order
    let due_ids: Vec<u64> = s
        .open_jobs
        .values()
        .filter(|j| j.admitted_at.saturating_add(g.settle_delay) == h)
        .map(|j| j.job_id)
        .collect();
    for job_id in due_ids {
        let Some(j) = s.open_jobs.remove(&job_id) else {
            continue;
        };
        let d = s.ledger.result_settle(
            JobId(j.job_id),
            Atoms(j.v_exec),
            Atoms(j.v_da),
            Atoms(j.v_ref),
        )?;
        fee_transitions.push(FeeTransition::ResultSettle {
            job_id: j.job_id,
            v_exec: j.v_exec,
            v_da: j.v_da,
            v_ref: j.v_ref,
            delta: to_category_delta(&d),
        });
        receipts.push(SettlementReceipt {
            job_id: j.job_id,
            tx_id: j.tx_id,
            executor_owner: j.owner,
            admitted_at: j.admitted_at,
            result: j.result,
            result_digest: compute_result_digest(j.job_id, j.result),
            v_exec: j.v_exec,
            v_da: j.v_da,
            v_ref: j.v_ref,
        });
    }

    // (3) InitialProtocolPool withdrawals, each under InitialOK (spec eq. 7.19j)
    for w in withdrawals {
        fee_transitions.push(apply_initial_pool_withdrawal(&mut s.ledger, w)?);
    }

    // Maintenance, settlements and withdrawals above may free fee lots and return
    // value to U. Fix the faucet budget once; each job debits the same cumulative budget.
    let faucet_budget = s.ledger.balance(StateCategory::Circulating).get() / 16;
    let mut faucet_debit = 0u64;
    let live_lots = s
        .ledger
        .fee_lots()
        .len()
        .checked_add(s.ledger.locked_fees().len())
        .and_then(|n| {
            jobs.len()
                .checked_mul(2)
                .and_then(|extra| n.checked_add(extra))
        })
        .ok_or(StfError::FeeLotCapacity)?;
    if live_lots > wire::MAX_LIVE_FEE_LOTS {
        return Err(StfError::FeeLotCapacity);
    }

    // (4) Fund the new jobs (sorted by tx_id)
    let mut validated: Vec<(Digest, u64, i128)> = Vec::with_capacity(jobs.len());
    for tx in jobs {
        let (tx_id, job_id, deposit, dot_result) =
            validate_job_stateless(tx).map_err(StfError::InvalidJob)?;
        if validated.last().is_some_and(|&(prev, _, _)| prev >= tx_id) {
            return Err(StfError::JobsNotSortedOrUnique);
        }
        if h > tx.expiry_height {
            return Err(StfError::JobExpired {
                job_id,
                expiry: tx.expiry_height,
                height: h,
            });
        }
        if tx.expiry_height - h > wire::MAX_JOB_TTL {
            return Err(StfError::JobExpiryTooFar);
        }
        let charge = tx
            .checked_total_charge()
            .ok_or(StfError::InvalidJob(JobValidationError::AmountOverflow))?;
        faucet_debit = faucet_debit
            .checked_add(charge)
            .ok_or(StfError::FaucetBudgetExceeded)?;
        if faucet_debit > faucet_budget {
            return Err(StfError::FaucetBudgetExceeded);
        }
        if s.used_tx.contains_key(&tx_id) {
            return Err(StfError::DuplicateTx(tx_id));
        }
        if s.used_job_ids.contains_key(&job_id) || validated.iter().any(|v| v.1 == job_id) {
            return Err(StfError::DuplicateJobId(job_id));
        }

        let d =
            s.ledger
                .escrow_fund_and_queue(JobId(job_id), Atoms(deposit), Atoms(tx.queue_fee))?;
        fee_transitions.push(FeeTransition::EscrowFundAndQueue {
            job_id,
            deposit,
            queue_fee: tx.queue_fee,
            delta: to_category_delta(&d),
        });
        validated.push((tx_id, job_id, dot_result));
    }

    // (5) Allocate leases with D'Hondt over the mature cohort, spec eq. (6.4)
    if !jobs.is_empty() {
        let cohort = s.lease_cohort(h, g);
        if cohort.is_empty() {
            return Err(StfError::EmptyLeaseCohort);
        }
        let share_ids: Vec<ShareID> = cohort
            .iter()
            .map(|sh| ShareID {
                id: digest_to_hash(&sh.work_id),
                weight: sh.weight,
                owner: OwnerId(sh.owner.owner_id()),
            })
            .collect();

        // Restore each share's history from the parent state. Epoch boundaries and
        // changes to the eligible set must not reset surviving shares' counters.
        let counters: Vec<u64> = cohort.iter().map(|sh| sh.allocated_slots).collect();
        if counters
            .iter()
            .any(|&count| count.checked_add(jobs.len() as u64).is_none())
        {
            return Err(StfError::SchedulerError(
                "D'Hondt allocation counter would overflow".to_string(),
            ));
        }
        let mut scheduler = Cohort::with_counters(share_ids, counters)
            .map_err(|e| StfError::SchedulerError(e.to_string()))?;
        let alloc = scheduler.allocate_batch(jobs.len(), &Capacity::Unbounded);
        if alloc.assigned() != jobs.len() {
            return Err(StfError::SchedulerError(
                "D'Hondt did not assign all requested job slots".to_string(),
            ));
        }

        for (share, &won_slots) in cohort.iter().zip(&alloc.per_share) {
            let record = s.shares.get_mut(&share.work_id).ok_or_else(|| {
                StfError::SchedulerError("allocated share missing from state".to_string())
            })?;
            // The batch-size check above bounds every possible increment.
            record.allocated_slots += won_slots;
        }

        for ((tx, &(tx_id, job_id, dot_result)), &slot) in
            jobs.iter().zip(&validated).zip(&alloc.slots)
        {
            let share = cohort.get(slot).ok_or_else(|| {
                StfError::SchedulerError(format!("slot index {slot} outside the cohort"))
            })?;
            let d = s
                .ledger
                .job_admit_and_lease(JobId(job_id), Atoms(tx.base_fee))?;
            let owner = share.owner.key_id();
            fee_transitions.push(FeeTransition::JobAdmitAndLease {
                job_id,
                base_fee: tx.base_fee,
                owner,
                delta: to_category_delta(&d),
            });
            leases.push(LeaseAssignment {
                job_id,
                share_id: share.work_id,
                owner,
            });
            s.open_jobs.insert(
                job_id,
                OpenJob {
                    job_id,
                    tx_id,
                    admitted_at: h,
                    owner,
                    share_id: share.work_id,
                    v_exec: tx.v_exec,
                    v_da: tx.v_da,
                    v_ref: tx.v_ref,
                    result: dot_result,
                },
            );
            s.used_tx.insert(tx_id, tx.expiry_height);
            s.used_job_ids.insert(job_id, tx.expiry_height);
        }
    }

    // (6) Register the shares of the body
    for sh in shares {
        s.shares.insert(
            sh.work_id,
            ShareRecord {
                work_id: sh.work_id,
                owner: sh.owner,
                weight: sh.weight,
                height: sh.height,
                included_at: h,
                allocated_slots: 0,
            },
        );
    }

    // (7) Prune, check, commit
    s.used_tx.retain(|_, &mut expiry| expiry >= h);
    s.used_job_ids.retain(|_, &mut expiry| expiry >= h);
    let retain = g
        .snapshot_window
        .max(g.blocks_per_epoch)
        .max(g.share_inclusion_window)
        .saturating_add(1);
    if let Some(min_keep) = h.checked_sub(retain) {
        s.shares.retain(|_, sh| sh.included_at >= min_keep);
    }

    s.ledger.check_invariants()?;
    s.height = h;
    let ledger_digest = compute_ledger_digest(&s);

    Ok((
        s,
        DerivedBody {
            leases,
            receipts,
            fee_transitions,
            ledger_digest,
        },
    ))
}

/// `INITIAL_POOL_WITHDRAWAL` under `InitialOK(tx, Σ, k)` (spec eq. 7.19j):
///
/// ```text
/// Accept_treasury(tx) ∧ ν_expected = InitialNonce ∧ U_initial ≥ v + f
///                     ∧ w_rolling + v + f ≤ L_I
/// ```
///
/// `Accept_treasury` holds by construction of [`VerifiedWithdrawal`]; the other three
/// conjuncts are checked here against the state after this block's primary release,
/// whose InitialValve window already ends at block `k` (spec eq. 7.19h). On success
/// `U_initial` pays `v` to `U` and `f` to `R_l`, `InitialNonce` advances and `v + f`
/// enters the window.
fn apply_initial_pool_withdrawal(
    ledger: &mut Ledger,
    w: &VerifiedWithdrawal,
) -> Result<FeeTransition, StfError> {
    let expected = ledger.initial_nonce();
    if w.expected_nonce != expected {
        return Err(StfError::InitialNonce {
            expected,
            found: w.expected_nonce,
        });
    }
    // validate_withdrawal_stateless bounded v + f by M, so this cannot overflow.
    let gross = w.amount + w.fee;
    let available = ledger.balance(StateCategory::InitialProtocolPool).get();
    if available < gross {
        return Err(StfError::InsufficientInitialPool {
            available,
            requested: gross,
        });
    }
    let valve = ledger.initial_valve();
    if !valve.admits(Atoms(gross)) {
        return Err(StfError::InitialValveExceeded {
            rolling: valve.rolling_outflow().get(),
            requested: gross,
        });
    }
    let delta = ledger.initial_pool_withdrawal(w.expected_nonce, Atoms(w.amount), Atoms(w.fee))?;
    Ok(FeeTransition::InitialPoolWithdrawal {
        tx_id: w.tx_id,
        nonce: w.expected_nonce,
        amount: w.amount,
        fee: w.fee,
        valve_rolling: ledger.initial_valve().rolling_outflow().get(),
        delta: to_category_delta(&delta),
    })
}
EOF

cat << 'EOF' > chain/src/template.rs
//! Block template building (`chain::template`, §7.4).

use std::sync::Arc;
use wire::{
    Block, BlockBody, BlockHeader, CORE_PROTOCOL_ID, CRYPTO_SUITE_ID, Digest, FwContext,
    GenesisConfig, InitialPoolWithdrawal, JobTransaction, MAX_WITHDRAWALS_PER_BLOCK, ShareProof,
    Target, codec,
};
use work::FreshWorkIds;

use crate::core_adapter::{
    compute_body_root, compute_difficulty_context, compute_job_ids, compute_miner_policy_digest,
    compute_payout_policy_digest, compute_program_and_air_ids, fresh_work_ids_to_digests,
    owner_key_id, scheduled_generator_id,
};
use crate::difficulty::{ChainView, expected_targets};
use crate::keys::{OwnerKeypair, unsigned};
use crate::stf::{
    NodeState, SignedShare, SignedWithdrawal, StfError, VerifiedShare, VerifiedWithdrawal,
    apply_body,
};

/// Mining template published to the `ConsensusEngine` (§7.4, §8.5).
#[derive(Clone, Debug)]
pub struct Template {
    /// Increases with every published template.
    pub generation: u64,
    /// Context of the next block, with `attempt_nonce = 0`.
    pub context: FwContext,
    /// Body committed by `context.body_core_root`.
    pub body: Arc<BlockBody>,
    /// `Θ_B` of the next height.
    pub seal_target: Target,
    /// `Θ_S` of the next height.
    pub share_target: Target,
    /// Beneficiary of everything mined on this template; signs its blocks and shares.
    pub miner: Arc<OwnerKeypair>,
}

impl Template {
    /// Returns a copy of `context` with `attempt_nonce` set to `nonce`.
    pub fn context_with_nonce(&self, nonce: u64) -> FwContext {
        let mut ctx = self.context.clone();
        ctx.attempt_nonce = nonce;
        ctx
    }

    /// Seals this template into a signed `Block` using the given `nonce` and `FreshWorkIds`.
    /// Errors only if the OS random number generator fails while signing.
    pub fn seal(&self, nonce: u64, ids: &FreshWorkIds) -> Result<Block, String> {
        let d = fresh_work_ids_to_digests(ids);
        let mut header = BlockHeader {
            context: self.context_with_nonce(nonce),
            output_root: d.output_root,
            work_id: d.work_id,
            block_id: d.block_id,
            share_ticket: d.share_ticket,
            seal_ticket: d.seal_ticket,
            seal_target: self.seal_target,
            share_target: self.share_target,
            miner_key: self.miner.public_key().clone(),
            signature: unsigned(),
        };
        self.miner.sign_header(&mut header)?;
        Ok(Block {
            header,
            body: (*self.body).clone(),
        })
    }

    /// Packages an attempt on this template into a signed `ShareProof` using `nonce` and
    /// `FreshWorkIds`. Errors only if the OS random number generator fails while signing.
    pub fn share(&self, nonce: u64, ids: &FreshWorkIds) -> Result<ShareProof, String> {
        let d = fresh_work_ids_to_digests(ids);
        let mut share = ShareProof {
            context: self.context_with_nonce(nonce),
            owner_key: self.miner.public_key().clone(),
            output_root: d.output_root,
            work_id: d.work_id,
            share_ticket: d.share_ticket,
            share_target: self.share_target,
            signature: unsigned(),
        };
        self.miner.sign_share(&mut share)?;
        Ok(share)
    }

    /// True when `other` would make the miners evaluate exactly the same contexts.
    pub fn same_work_as(&self, other: &Template) -> bool {
        self.context == other.context
            && self.seal_target == other.seal_target
            && self.share_target == other.share_target
            && self.miner.key_id() == other.miner.key_id()
    }
}

/// The pool shares to include in a block at height `h` on `chain`.
///
/// A share qualifies if it satisfies the §6.7 inclusion rules on this branch: inside
/// the inclusion window, not yet registered, and mined on this chain's ancestor with
/// its context and target. Pool shares are signature-checked on entry
/// ([`SignedShare`]) and gossiped ones also work-checked, so neither is redone here.
///
/// Up to `max_shares_per_block` shares are taken, oldest height first (those leave the
/// window soonest), then lowest `work_id`; the result is sorted by `work_id` as
/// `apply_body` requires.
fn includable_shares(
    genesis: &GenesisConfig,
    genesis_id: Digest,
    chain: &impl ChainView,
    tip_state: &NodeState,
    pool: &[SignedShare],
    h: u64,
) -> Vec<SignedShare> {
    let (program_id, air_id) = compute_program_and_air_ids();
    let mut shares: Vec<&SignedShare> = pool
        .iter()
        .filter(|signed| {
            let sh = signed.proof();
            let s = sh.context.height;
            if s < 1 || s >= h || s < h.saturating_sub(genesis.share_inclusion_window) {
                return false;
            }
            if tip_state.shares.contains_key(&sh.work_id) {
                return false;
            }
            let (exp_seal, exp_share) = chain.targets_at(s);
            let c = &sh.context;
            let key_id = owner_key_id(&sh.owner_key);
            c.chain_id == genesis.chain_id
                && c.genesis_id == genesis_id
                && c.protocol_id == CORE_PROTOCOL_ID
                && c.crypto_suite_id == CRYPTO_SUITE_ID
                && c.program_id == program_id
                && c.air_id == air_id
                && c.generator_id == scheduled_generator_id(s)
                && c.parent_canonical_id == chain.block_id_at(s - 1)
                && c.stable_anchor_id == chain.block_id_at(s.saturating_sub(genesis.anchor_depth))
                && c.miner_policy_digest == compute_miner_policy_digest(&key_id)
                && c.payout_policy_digest == compute_payout_policy_digest(&key_id)
                && c.parent_derived_difficulty_context
                    == compute_difficulty_context(exp_seal, exp_share)
                && sh.share_target == exp_share
        })
        .collect();
    shares.sort_by_key(|s| (s.proof().work_id, s.proof().context.height));
    shares.dedup_by_key(|s| s.proof().work_id);
    shares.sort_by_key(|s| (s.proof().context.height, s.proof().work_id));
    shares.truncate(genesis.max_shares_per_block as usize);
    shares.sort_by_key(|s| s.proof().work_id);
    shares.into_iter().cloned().collect()
}

/// The pool withdrawals to include at height `h`: the run of consecutive nonces from
/// the tip's `InitialNonce`, up to `MAX_WITHDRAWALS_PER_BLOCK`, while the body stays
/// valid. A withdrawal the InitialValve or the pool balance does not admit yet ends
/// the run and waits for a later block. Of competing withdrawals for one nonce the
/// lowest `TxID` is taken.
fn includable_withdrawals(
    tip_state: &NodeState,
    genesis: &GenesisConfig,
    h: u64,
    shares: &[VerifiedShare],
    pool: &[SignedWithdrawal],
) -> Vec<SignedWithdrawal> {
    let mut selected: Vec<SignedWithdrawal> = Vec::new();
    let mut verified: Vec<VerifiedWithdrawal> = Vec::new();
    let mut nonce = tip_state.ledger.initial_nonce();
    while (selected.len() as u64) < MAX_WITHDRAWALS_PER_BLOCK {
        let Some(next) = pool
            .iter()
            .filter(|w| w.verified().expected_nonce() == nonce)
            .min_by_key(|w| w.verified().tx_id())
        else {
            break;
        };
        verified.push(next.verified().clone());
        if apply_body(tip_state, genesis, h, &[], shares, &verified).is_err() {
            break;
        }
        selected.push(next.clone());
        nonce += 1;
    }
    selected
}

/// Runs `apply_body` and assembles the body with its derived fields.
fn derive_body(
    tip_state: &NodeState,
    genesis: &GenesisConfig,
    h: u64,
    jobs: Vec<JobTransaction>,
    shares: &[ShareProof],
    verified: &[VerifiedShare],
    withdrawals: &[SignedWithdrawal],
) -> Result<BlockBody, StfError> {
    let verified_withdrawals: Vec<VerifiedWithdrawal> =
        withdrawals.iter().map(|w| w.verified().clone()).collect();
    let (_, derived) = apply_body(
        tip_state,
        genesis,
        h,
        &jobs,
        verified,
        &verified_withdrawals,
    )?;
    Ok(BlockBody {
        jobs,
        shares: shares.to_vec(),
        withdrawals: withdrawals
            .iter()
            .map(|w| w.withdrawal().clone())
            .collect::<Vec<InitialPoolWithdrawal>>(),
        leases: derived.leases,
        receipts: derived.receipts,
        fee_transitions: derived.fee_transitions,
        ledger_digest: derived.ledger_digest,
    })
}

/// Builds a new mining `Template` on top of the tip at `tip_height` of `chain` (§7.4).
///
/// Shares come from `share_pool`, which holds this node's own shares and the verified
/// gossiped ones (see `includable_shares`), and withdrawals from `withdrawal_pool`
/// (see `includable_withdrawals`). Jobs are taken in FIFO order (no fee priority,
/// spec eq. 6.16) as long as the body stays valid; unfundable jobs are skipped and stay
/// in the mempool. Errors only if even an empty body cannot be derived, which would
/// indicate a corrupted tip state.
#[allow(clippy::too_many_arguments)]
pub fn build_template(
    generation: u64,
    genesis: &GenesisConfig,
    genesis_id: Digest,
    chain: &impl ChainView,
    tip_height: u64,
    tip_state: &NodeState,
    mempool_fifo: &[JobTransaction],
    share_pool: &[SignedShare],
    withdrawal_pool: &[SignedWithdrawal],
    miner: &Arc<OwnerKeypair>,
    now_bucket: u64,
) -> Result<Template, StfError> {
    let h = tip_height + 1;
    let (mut shares, mut verified): (Vec<ShareProof>, Vec<VerifiedShare>) =
        includable_shares(genesis, genesis_id, chain, tip_state, share_pool, h)
            .into_iter()
            .map(|signed| (signed.proof().clone(), signed.verified().clone()))
            .unzip();
    if apply_body(tip_state, genesis, h, &[], &verified, &[]).is_err() {
        shares.clear();
        verified.clear();
    }
    let withdrawals = includable_withdrawals(tip_state, genesis, h, &verified, withdrawal_pool);
    let verified_withdrawals: Vec<VerifiedWithdrawal> =
        withdrawals.iter().map(|w| w.verified().clone()).collect();

    // Greedily add jobs in FIFO order; the body itself stays sorted by tx_id (§7.4).
    let mut selected: Vec<(Digest, JobTransaction)> = Vec::new();
    for tx in mempool_fifo {
        if selected.len() as u64 >= genesis.max_jobs_per_block {
            break;
        }
        let Ok((tx_id, _)) = compute_job_ids(tx) else {
            continue;
        };
        let Err(pos) = selected.binary_search_by_key(&tx_id, |(id, _)| *id) else {
            continue;
        };
        let mut candidate = selected.clone();
        candidate.insert(pos, (tx_id, tx.clone()));
        let jobs: Vec<JobTransaction> = candidate.iter().map(|(_, j)| j.clone()).collect();
        if apply_body(
            tip_state,
            genesis,
            h,
            &jobs,
            &verified,
            &verified_withdrawals,
        )
        .is_ok()
        {
            selected = candidate;
        }
    }

    let mut jobs: Vec<JobTransaction> = selected.into_iter().map(|(_, j)| j).collect();
    let mut body = derive_body(
        tip_state,
        genesis,
        h,
        jobs.clone(),
        &shares,
        &verified,
        &withdrawals,
    )?;
    // A block encodes as its header followed by its body, so the body gets everything
    // but the fixed-width header.
    let size_limit = genesis
        .max_block_bytes
        .saturating_sub(wire::ENCODED_HEADER_LEN as u64) as usize;
    let oversized = |body: &BlockBody| codec::encode(body).map_or(true, |b| b.len() > size_limit);
    while oversized(&body) && !(jobs.is_empty() && shares.is_empty()) {
        if jobs.pop().is_none() {
            // validate_genesis leaves BLOCK_HEADROOM beyond a full set of shares and
            // withdrawals for the body's framing and derived fields, so this needs a
            // degenerate genesis or huge derived fields. Drop the newest share (most time
            // left in the window).
            let newest = (0..shares.len())
                .max_by_key(|&i| (shares[i].context.height, shares[i].work_id))
                .expect("invariant: shares is not empty here");
            shares.remove(newest);
            verified.remove(newest);
        }
        body = derive_body(
            tip_state,
            genesis,
            h,
            jobs.clone(),
            &shares,
            &verified,
            &withdrawals,
        )?;
    }

    let (seal_target, share_target) = expected_targets(h, chain, genesis);
    let body_core_root = compute_body_root(&body).map_err(StfError::SchedulerError)?;
    let (program_id, air_id) = compute_program_and_air_ids();
    let context = FwContext {
        chain_id: genesis.chain_id,
        genesis_id,
        protocol_id: CORE_PROTOCOL_ID,
        crypto_suite_id: CRYPTO_SUITE_ID,
        program_id,
        air_id,
        generator_id: scheduled_generator_id(h),
        parent_canonical_id: chain.block_id_at(tip_height),
        stable_anchor_id: chain.block_id_at(h.saturating_sub(genesis.anchor_depth)),
        height: h,
        miner_policy_digest: compute_miner_policy_digest(&miner.key_id()),
        payout_policy_digest: compute_payout_policy_digest(&miner.key_id()),
        attempt_nonce: 0,
        body_core_root,
        parent_derived_difficulty_context: compute_difficulty_context(seal_target, share_target),
        time_bucket: chain.time_bucket_at(tip_height).max(now_bucket),
    };

    Ok(Template {
        generation,
        context,
        body: Arc::new(body),
        seal_target,
        share_target,
        miner: miner.clone(),
    })
}
EOF

cat << 'EOF' > chain/src/tree.rs
//! BlockTree, Stage B validation, fork choice, and block summaries (`chain::tree`, §6, §8.3).

use core::fmt;
use std::collections::HashMap;
use std::sync::Arc;

use ledger::StateCategory;
use wire::{
    Block, CORE_PROTOCOL_ID, CRYPTO_SUITE_ID, Digest, FeeTransition, GenesisConfig,
    MAX_FUTURE_SECS, MAX_REORG_DEPTH, MAX_WITHDRAWALS_PER_BLOCK, ShareProof, Target, codec,
};

use crate::core_adapter::{
    ClaimedWork, Lottery, WorkError, compute_body_root, compute_difficulty_context,
    compute_job_ids, compute_miner_policy_digest, compute_payout_policy_digest,
    compute_program_and_air_ids, compute_withdrawal_id, owner_key_id, scheduled_generator_id,
    top128, validate_genesis, validate_withdrawal_stateless, verify_fresh_work,
    verify_header_miner, verify_job_client, verify_share_owner, verify_withdrawal_signatures,
};
use crate::difficulty::{ChainView, expected_targets, seal_weight, share_target_for, share_weight};
use crate::stf::{NodeState, ShareRecord, VerifiedShare, VerifiedWithdrawal, apply_body};

/// Metadata stored per validated block in `BlockTree` (§8.3).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct BlockMeta {
    /// `block_id` (or `genesis_id` for the virtual height 0).
    pub id: Digest,
    /// Parent `block_id` (`Digest::ZERO` for genesis).
    pub parent: Digest,
    /// Height.
    pub height: u64,
    /// Context field 16.
    pub time_bucket: u64,
    /// `Θ_B` of this height.
    pub seal_target: Target,
    /// `Θ_S` of this height.
    pub share_target: Target,
    /// `work_of(seal_target)`.
    pub seal_weight: u128,
    /// Sum of seal weights from genesis.
    pub cumulative_weight: u128,
    /// Beneficiary's key id (`Digest::ZERO` for genesis).
    pub miner_key_id: Digest,
}

/// Summary of an admitted job inside a block for `/api/blocks` (§9.4).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct JobSummary {
    /// Job identifier.
    pub job_id: u64,
    /// Transaction identifier.
    pub tx_id: Digest,
    /// Lease owner's key id.
    pub executor_owner: Digest,
    /// Escrow deposit.
    pub deposit: u64,
    /// Queue fee.
    pub queue_fee: u64,
    /// Base Fee.
    pub base_fee: u64,
}

/// Summary of a settlement receipt inside a block for `/api/blocks` (§9.4).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ReceiptSummary {
    /// Settled job.
    pub job_id: u64,
    /// Exact dot product.
    pub result: i128,
    /// Lease owner's key id.
    pub executor_owner: Digest,
    /// Height of admission.
    pub admitted_at: u64,
}

/// Summary of an included share inside a block for `/api/blocks` (§9.4).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ShareSummary {
    /// ShareID.
    pub work_id: Digest,
    /// Beneficiary's key id.
    pub owner: Digest,
    /// Height the share was mined at.
    pub height: u64,
    /// `w_s`.
    pub weight: u64,
}

/// Summary of an included InitialProtocolPool withdrawal for `/api/blocks` (§9.4).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct WithdrawalSummary {
    /// Transaction identifier.
    pub tx_id: Digest,
    /// `ν_expected`.
    pub nonce: u64,
    /// `v`, paid to `U`.
    pub amount: u64,
    /// `f`, paid to `R_l`.
    pub fee: u64,
    /// Number of public outputs.
    pub outputs: usize,
}

/// Summary of a block and its post-state balances for `/api/blocks` (§9.4).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct BlockSummary {
    /// Height.
    pub height: u64,
    /// `block_id`.
    pub block_id: Digest,
    /// Parent `block_id`.
    pub parent_id: Digest,
    /// `stable_anchor_id`.
    pub anchor_id: Digest,
    /// Beneficiary's key id.
    pub miner_key_id: Digest,
    /// Context field 16.
    pub time_bucket: u64,
    /// Winning nonce.
    pub attempt_nonce: u64,
    /// The diagnostic generator of the block's Fresh Work.
    pub generator_id: u64,
    /// Ledger epoch after the block.
    pub epoch: u64,
    /// `θ_B`.
    pub seal_ticket: Digest,
    /// Seal weight.
    pub seal_weight: u128,
    /// Cumulative chain weight.
    pub cumulative_weight: u128,
    /// Admitted jobs.
    pub jobs: Vec<JobSummary>,
    /// Settled jobs.
    pub receipts: Vec<ReceiptSummary>,
    /// Included share proofs.
    pub shares: Vec<ShareSummary>,
    /// Included InitialProtocolPool withdrawals.
    pub withdrawals: Vec<WithdrawalSummary>,
    /// Whether the header's own work registered as a share.
    pub header_share: bool,
    /// Ledger transitions in execution order.
    pub fee_transitions: Vec<FeeTransition>,
    /// The ten category balances after the block, in `StateCategory::ALL` order.
    pub balances_after: [u64; StateCategory::COUNT],
    /// Sum of `balances_after` (always `M`).
    pub total_after: u128,
}

/// View over one branch of a `BlockTree`, from genesis up to a given block.
///
/// Heights at or below `fork_height` are on the canonical chain; the side branch above
/// it is stored explicitly, so building the view costs only the side-branch length.
pub struct AncestorChainView<'a> {
    tree: &'a BlockTree,
    fork_height: u64,
    branch: Vec<Digest>, // heights fork_height+1 ..= top, ascending
}

impl AncestorChainView<'_> {
    /// Highest height covered by the view.
    pub fn top_height(&self) -> u64 {
        self.fork_height + self.branch.len() as u64
    }

    fn meta_at(&self, h: u64) -> Option<&BlockMeta> {
        self.tree.metas.get(&self.block_id_at(h))
    }
}

impl ChainView for AncestorChainView<'_> {
    fn block_id_at(&self, h: u64) -> Digest {
        if h <= self.fork_height {
            self.tree.canonical_id_at(h).unwrap_or(Digest::ZERO)
        } else {
            self.branch
                .get((h - self.fork_height - 1) as usize)
                .copied()
                .unwrap_or(Digest::ZERO)
        }
    }

    fn time_bucket_at(&self, h: u64) -> u64 {
        self.meta_at(h)
            .map_or(self.tree.genesis.genesis_time_bucket, |m| m.time_bucket)
    }

    fn targets_at(&self, h: u64) -> (Target, Target) {
        self.meta_at(h).map_or_else(
            || self.tree.genesis_targets(),
            |m| (m.seal_target, m.share_target),
        )
    }
}

impl ChainView for BlockTree {
    fn block_id_at(&self, h: u64) -> Digest {
        self.canonical_id_at(h).unwrap_or(Digest::ZERO)
    }

    fn time_bucket_at(&self, h: u64) -> u64 {
        self.canonical_meta_at(h)
            .map_or(self.genesis.genesis_time_bucket, |m| m.time_bucket)
    }

    fn targets_at(&self, h: u64) -> (Target, Target) {
        self.canonical_meta_at(h).map_or_else(
            || self.genesis_targets(),
            |m| (m.seal_target, m.share_target),
        )
    }
}

/// Validation or tree error (§6.8).
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum TreeError {
    /// The block is already known.
    Duplicate,
    /// The parent is not in the tree.
    Orphan {
        /// The missing parent.
        parent: Digest,
    },
    /// The fork point is deeper than `MAX_REORG_DEPTH` or its snapshot was pruned.
    TooDeep,
    /// The block's `time_bucket` is too far in the future; retry later.
    Deferred {
        /// The block's time bucket.
        time_bucket: u64,
    },
    /// The block violates a consensus rule.
    Invalid(String),
}

impl fmt::Display for TreeError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            TreeError::Duplicate => write!(f, "duplicate block"),
            TreeError::Orphan { parent } => write!(f, "unknown parent {parent:?}"),
            TreeError::TooDeep => write!(f, "parent fork exceeds MAX_REORG_DEPTH or is pruned"),
            TreeError::Deferred { time_bucket } => {
                write!(f, "block time_bucket {time_bucket} is in the future")
            }
            TreeError::Invalid(reason) => write!(f, "invalid block: {reason}"),
        }
    }
}

impl std::error::Error for TreeError {}

fn invalid(reason: impl Into<String>) -> TreeError {
    TreeError::Invalid(reason.into())
}

/// Outcome of the checks a gossiped share passes before its work is verified
/// ([`BlockTree::check_gossip_share`]).
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum ShareCheck {
    /// Every check that needs no work passed: verify the signature and the work next.
    Verify,
    /// The share's parent block is not in the tree; it may still be on its way.
    UnknownParent(Digest),
    /// Possibly honest but of no use here (stale, already registered, ...): drop it
    /// without penalizing the sender.
    Ignore(&'static str),
    /// No honest node relays this share: penalize the sender.
    Invalid(String),
}

/// Outcome of inserting a verified block into `BlockTree`.
#[derive(Clone, Debug)]
pub struct InsertOutcome {
    /// Metadata of the inserted block.
    pub meta: BlockMeta,
    /// Whether the block became the new tip.
    pub tip_changed: bool,
    /// Blocks that joined the canonical chain, ascending.
    pub connected: Vec<Arc<Block>>,
    /// Blocks that left the canonical chain, old tip first.
    pub disconnected: Vec<Arc<Block>>,
}

/// Multi-branch block tree and canonical chain tracker (§6, §8.3).
pub struct BlockTree {
    genesis: GenesisConfig,
    genesis_id: Digest,
    metas: HashMap<Digest, BlockMeta>,
    blocks: HashMap<Digest, Arc<Block>>,
    states: HashMap<Digest, Arc<NodeState>>,
    summaries: HashMap<Digest, BlockSummary>,
    canonical: Vec<Digest>, // index == height
    tip: Digest,
}

impl BlockTree {
    /// Creates a new `BlockTree` initialized at the virtual height 0 (§3.4).
    pub fn new(genesis: GenesisConfig) -> Result<Self, String> {
        let (_params, ledger, genesis_id) = validate_genesis(&genesis)?;
        let seal = genesis.initial_seal_target;
        let genesis_meta = BlockMeta {
            id: genesis_id,
            parent: Digest::ZERO,
            height: 0,
            time_bucket: genesis.genesis_time_bucket,
            seal_target: seal,
            share_target: share_target_for(seal, genesis.share_ratio),
            seal_weight: 0,
            cumulative_weight: 0,
            miner_key_id: Digest::ZERO,
        };
        Ok(Self {
            genesis,
            genesis_id,
            metas: HashMap::from([(genesis_id, genesis_meta)]),
            blocks: HashMap::new(),
            states: HashMap::from([(genesis_id, Arc::new(NodeState::genesis(ledger)))]),
            summaries: HashMap::new(),
            canonical: vec![genesis_id],
            tip: genesis_id,
        })
    }

    /// The genesis configuration.
    pub fn genesis(&self) -> &GenesisConfig {
        &self.genesis
    }

    /// `genesis_id`, the `block_id` of height 0.
    pub fn genesis_id(&self) -> Digest {
        self.genesis_id
    }

    fn genesis_targets(&self) -> (Target, Target) {
        let seal = self.genesis.initial_seal_target;
        (seal, share_target_for(seal, self.genesis.share_ratio))
    }

    /// Current tip `block_id`.
    pub fn tip_id(&self) -> Digest {
        self.tip
    }

    /// Current tip metadata.
    pub fn tip_meta(&self) -> &BlockMeta {
        self.metas
            .get(&self.tip)
            .expect("invariant: the tip is always in the tree")
    }

    /// Current tip post-state.
    pub fn tip_state(&self) -> Arc<NodeState> {
        self.states
            .get(&self.tip)
            .cloned()
            .expect("invariant: the tip state is never pruned")
    }

    /// Whether the block is in the tree (any branch).
    pub fn has_block(&self, id: &Digest) -> bool {
        self.metas.contains_key(id)
    }

    /// A block by id (any branch).
    pub fn get_block(&self, id: &Digest) -> Option<Arc<Block>> {
        self.blocks.get(id).cloned()
    }

    /// Metadata by id (any branch).
    pub fn get_meta(&self, id: &Digest) -> Option<&BlockMeta> {
        self.metas.get(id)
    }

    /// Post-state by id, if not pruned.
    pub fn get_state(&self, id: &Digest) -> Option<Arc<NodeState>> {
        self.states.get(id).cloned()
    }

    /// Canonical `block_id` at `height`.
    pub fn canonical_id_at(&self, height: u64) -> Option<Digest> {
        self.canonical.get(usize::try_from(height).ok()?).copied()
    }

    fn canonical_meta_at(&self, height: u64) -> Option<&BlockMeta> {
        self.metas.get(&self.canonical_id_at(height)?)
    }

    /// Canonical block at `height` (`None` for height 0).
    pub fn canonical_block_at(&self, height: u64) -> Option<Arc<Block>> {
        self.blocks.get(&self.canonical_id_at(height)?).cloned()
    }

    /// Summaries of canonical blocks with height `< before` (default: all), newest first.
    pub fn canonical_summaries(&self, before: Option<u64>, limit: usize) -> Vec<BlockSummary> {
        let tip_h = self.tip_meta().height;
        let max_h = before.map_or(tip_h, |b| b.saturating_sub(1).min(tip_h));
        (1..=max_h)
            .rev()
            .filter_map(|h| self.summaries.get(&self.canonical_id_at(h)?).cloned())
            .take(limit)
            .collect()
    }

    /// Whether a not-yet-expired transaction is included on the canonical chain.
    ///
    /// The tip state remembers every used `tx_id` until its expiry height, after which
    /// the transaction could not be included again anyway.
    pub fn is_tx_on_canonical(&self, tx_id: &Digest) -> bool {
        self.tip_state().used_tx.contains_key(tx_id)
    }

    fn is_canonical(&self, meta: &BlockMeta) -> bool {
        self.canonical_id_at(meta.height) == Some(meta.id)
    }

    /// Builds an `AncestorChainView` of the branch ending at `top_id`.
    pub fn ancestor_view(&self, top_id: Digest) -> Option<AncestorChainView<'_>> {
        let mut branch = Vec::new();
        let mut meta = self.metas.get(&top_id)?;
        while !self.is_canonical(meta) {
            branch.push(meta.id);
            meta = self.metas.get(&meta.parent)?;
        }
        branch.reverse();
        Some(AncestorChainView {
            tree: self,
            fork_height: meta.height,
            branch,
        })
    }

    /// Runs §6.8 steps 1–6: size and ordering, duplicate, parent, depth, Stage B and time.
    ///
    /// `now_unix_secs = None` skips the local future-time check (disk replay, tests).
    pub fn pre_validate(&self, block: &Block, now_unix_secs: Option<u64>) -> Result<(), TreeError> {
        // Step 1: size and list caps, sorting and uniqueness
        let encoded = codec::encode(block).map_err(|e| invalid(e.to_string()))?;
        if encoded.len() as u64 > self.genesis.max_block_bytes {
            return Err(invalid(format!(
                "block size {} exceeds max_block_bytes {}",
                encoded.len(),
                self.genesis.max_block_bytes
            )));
        }
        let body = &block.body;
        if body.jobs.len() as u64 > self.genesis.max_jobs_per_block {
            return Err(invalid("too many jobs in block"));
        }
        if body.shares.len() as u64 > self.genesis.max_shares_per_block {
            return Err(invalid("too many shares in block"));
        }
        if body.withdrawals.len() as u64 > MAX_WITHDRAWALS_PER_BLOCK {
            return Err(invalid("too many withdrawals in block"));
        }
        if body
            .withdrawals
            .windows(2)
            .any(|w| w[0].expected_nonce >= w[1].expected_nonce)
        {
            return Err(invalid(
                "withdrawals must be strictly sorted by expected_nonce",
            ));
        }
        let mut prev_tx: Option<Digest> = None;
        for tx in &body.jobs {
            let (tx_id, _) =
                compute_job_ids(tx).map_err(|e| invalid(format!("job id failed: {e}")))?;
            if prev_tx.is_some_and(|p| p >= tx_id) {
                return Err(invalid("jobs must be strictly sorted by tx_id"));
            }
            prev_tx = Some(tx_id);
        }
        if body.shares.windows(2).any(|w| w[0].work_id >= w[1].work_id) {
            return Err(invalid("shares must be strictly sorted by work_id"));
        }

        // Step 2: duplicate
        if self.metas.contains_key(&block.header.block_id) {
            return Err(TreeError::Duplicate);
        }

        // Step 3: parent in tree
        let ctx = &block.header.context;
        let parent_id = ctx.parent_canonical_id;
        let Some(parent_meta) = self.metas.get(&parent_id) else {
            return Err(TreeError::Orphan { parent: parent_id });
        };

        // Step 4: parent snapshot missing or fork deeper than MAX_REORG_DEPTH
        let Some(parent_state) = self.states.get(&parent_id) else {
            return Err(TreeError::TooDeep);
        };
        let view = self.ancestor_view(parent_id).ok_or(TreeError::TooDeep)?;
        if self.tip_meta().height.saturating_sub(view.fork_height) > MAX_REORG_DEPTH {
            return Err(TreeError::TooDeep);
        }

        // Step 5: Stage B for the header (§6.3) and for each share (§6.3, §6.7)
        let h = parent_meta.height + 1;
        let (program_id, air_id) = compute_program_and_air_ids();
        if ctx.height != h {
            return Err(invalid(format!("expected height {h}, got {}", ctx.height)));
        }
        self.check_context_constants(ctx, program_id, air_id)?;
        let miner_key_id = owner_key_id(&block.header.miner_key);
        if ctx.miner_policy_digest != compute_miner_policy_digest(&miner_key_id)
            || ctx.payout_policy_digest != compute_payout_policy_digest(&miner_key_id)
        {
            return Err(invalid("policy digest does not match miner_key"));
        }
        if ctx.body_core_root != compute_body_root(body).map_err(invalid)? {
            return Err(invalid("body_core_root mismatch"));
        }
        if ctx.time_bucket < parent_meta.time_bucket {
            return Err(invalid("time_bucket regressed below parent"));
        }

        if ctx.stable_anchor_id != view.block_id_at(h.saturating_sub(self.genesis.anchor_depth)) {
            return Err(invalid("stable_anchor_id mismatch"));
        }
        let (exp_seal, exp_share) = expected_targets(h, &view, &self.genesis);
        if block.header.seal_target != exp_seal {
            return Err(invalid("seal_target mismatch"));
        }
        if block.header.share_target != exp_share {
            return Err(invalid("share_target mismatch"));
        }
        if ctx.parent_derived_difficulty_context != compute_difficulty_context(exp_seal, exp_share)
        {
            return Err(invalid("parent_derived_difficulty_context mismatch"));
        }
        for sh in &body.shares {
            self.validate_share_stage_b(sh, h, &view, parent_state, program_id, air_id)?;
        }
        // The treasury key ids bind each withdrawal to the genesis policy before Stage A
        // spends a signature check on it.
        for w in &body.withdrawals {
            validate_withdrawal_stateless(w, &self.genesis)
                .map_err(|e| invalid(format!("withdrawal: {e}")))?;
        }

        // Step 6: future time_bucket (§6.6), a local rule
        if let Some(now_secs) = now_unix_secs {
            let now_bucket = now_secs / self.genesis.time_bucket_secs;
            let max_lead = MAX_FUTURE_SECS / self.genesis.time_bucket_secs;
            if ctx.time_bucket > now_bucket.saturating_add(max_lead) {
                return Err(TreeError::Deferred {
                    time_bucket: ctx.time_bucket,
                });
            }
        }
        Ok(())
    }

    fn check_context_constants(
        &self,
        ctx: &wire::FwContext,
        program_id: Digest,
        air_id: Digest,
    ) -> Result<(), TreeError> {
        let checks = [
            (ctx.chain_id == self.genesis.chain_id, "chain_id"),
            (ctx.genesis_id == self.genesis_id, "genesis_id"),
            (ctx.protocol_id == CORE_PROTOCOL_ID, "protocol_id"),
            (ctx.crypto_suite_id == CRYPTO_SUITE_ID, "crypto_suite_id"),
            (ctx.program_id == program_id, "program_id"),
            (ctx.air_id == air_id, "air_id"),
            (
                ctx.generator_id == scheduled_generator_id(ctx.height),
                "generator_id",
            ),
        ];
        match checks.iter().find(|(ok, _)| !ok) {
            Some((_, field)) => Err(invalid(format!("{field} mismatch"))),
            None => Ok(()),
        }
    }

    fn validate_share_stage_b(
        &self,
        sh: &ShareProof,
        h: u64,
        view: &AncestorChainView<'_>,
        parent_state: &NodeState,
        program_id: Digest,
        air_id: Digest,
    ) -> Result<(), TreeError> {
        let s = sh.context.height;
        if s < 1 || s >= h || s < h.saturating_sub(self.genesis.share_inclusion_window) {
            return Err(invalid(format!(
                "share height {s} outside inclusion window at block height {h}"
            )));
        }
        if parent_state.shares.contains_key(&sh.work_id) {
            return Err(invalid("share work_id already registered"));
        }
        let c = &sh.context;
        self.check_context_constants(c, program_id, air_id)
            .map_err(|e| invalid(format!("share: {e}")))?;
        if c.parent_canonical_id != view.block_id_at(s - 1) {
            return Err(invalid("share parent_canonical_id mismatch"));
        }
        if c.stable_anchor_id != view.block_id_at(s.saturating_sub(self.genesis.anchor_depth)) {
            return Err(invalid("share stable_anchor_id mismatch"));
        }
        let owner_key_id = owner_key_id(&sh.owner_key);
        if c.miner_policy_digest != compute_miner_policy_digest(&owner_key_id)
            || c.payout_policy_digest != compute_payout_policy_digest(&owner_key_id)
        {
            return Err(invalid("share policy digest mismatch"));
        }
        let (exp_seal, exp_share) = view.targets_at(s);
        if sh.share_target != exp_share {
            return Err(invalid("share_target mismatch"));
        }
        if c.parent_derived_difficulty_context != compute_difficulty_context(exp_seal, exp_share) {
            return Err(invalid("share difficulty context mismatch"));
        }
        Ok(())
    }

    /// Checks a gossiped share against everything that needs no work recomputation,
    /// before it may enter the share pool.
    ///
    /// Context constants and the owner binding must hold on any chain. If the parent is
    /// known, the height, anchor and targets are checked on the parent's own branch, so
    /// an honest share from a side branch still passes. Shares outside the inclusion
    /// window of the canonical tip, or already registered on it, are ignored. Whether a
    /// pooled share fits a given template is decided again when the template is built.
    pub fn check_gossip_share(&self, sh: &ShareProof) -> ShareCheck {
        let (program_id, air_id) = compute_program_and_air_ids();
        let c = &sh.context;
        if let Err(e) = self.check_context_constants(c, program_id, air_id) {
            return ShareCheck::Invalid(format!("share: {e}"));
        }
        let owner_key_id = owner_key_id(&sh.owner_key);
        if c.miner_policy_digest != compute_miner_policy_digest(&owner_key_id)
            || c.payout_policy_digest != compute_payout_policy_digest(&owner_key_id)
        {
            return ShareCheck::Invalid("share policy digest mismatch".into());
        }
        let s = c.height;
        if s < 1 {
            return ShareCheck::Invalid("share height 0".into());
        }
        let next = self.tip_meta().height + 1;
        if s < next.saturating_sub(self.genesis.share_inclusion_window) {
            return ShareCheck::Ignore("share is outside the inclusion window");
        }
        if self.tip_state().shares.contains_key(&sh.work_id) {
            return ShareCheck::Ignore("share already registered");
        }
        let Some(parent) = self.metas.get(&c.parent_canonical_id) else {
            return ShareCheck::UnknownParent(c.parent_canonical_id);
        };
        if parent.height + 1 != s {
            return ShareCheck::Invalid(format!(
                "share height {s} does not follow its parent at {}",
                parent.height
            ));
        }
        let Some(view) = self.ancestor_view(parent.id) else {
            return ShareCheck::Ignore("share parent branch unavailable");
        };
        if c.stable_anchor_id != view.block_id_at(s.saturating_sub(self.genesis.anchor_depth)) {
            return ShareCheck::Invalid("share stable_anchor_id mismatch".into());
        }
        let (exp_seal, exp_share) = expected_targets(s, &view, &self.genesis);
        if sh.share_target != exp_share {
            return ShareCheck::Invalid("share_target mismatch".into());
        }
        if c.parent_derived_difficulty_context != compute_difficulty_context(exp_seal, exp_share) {
            return ShareCheck::Invalid("share difficulty context mismatch".into());
        }
        ShareCheck::Verify
    }

    /// Verifies the ML-DSA-87 signatures of the header, every job and every share, and
    /// both treasury signatures of every withdrawal.
    ///
    /// Cheap next to a tile recomputation (about 0.5 ms each, a few ms for an
    /// SLH-DSA-SHAKE-256s co-signature), so Stage A runs it first. Jobs and withdrawals
    /// are checked against the header's `genesis_id`, which Stage B pins to ours.
    pub fn verify_signatures(block: &Block) -> Result<(), WorkError> {
        verify_header_miner(&block.header).map_err(|e| WorkError::Signature("header", e))?;
        let genesis_id = block.header.context.genesis_id;
        for tx in &block.body.jobs {
            verify_job_client(tx, &genesis_id).map_err(|e| WorkError::Signature("job", e))?;
        }
        for sh in &block.body.shares {
            verify_share_owner(sh).map_err(|e| WorkError::Signature("share", e))?;
        }
        for w in &block.body.withdrawals {
            verify_withdrawal_signatures(w, &genesis_id)
                .map_err(|e| WorkError::Signature("withdrawal", e))?;
        }
        Ok(())
    }

    /// Runs Stage A synchronously: every signature, then VerifyFW on the header and all
    /// shares (§6.2).
    pub fn verify_stage_a(block: &Block) -> Result<(), WorkError> {
        Self::verify_signatures(block)?;
        verify_fresh_work(
            &block.header.context,
            &ClaimedWork::from_header(&block.header),
            block.header.seal_target,
            Lottery::Seal,
        )?;
        for sh in &block.body.shares {
            verify_fresh_work(
                &sh.context,
                &ClaimedWork::from_share(sh),
                sh.share_target,
                Lottery::Share,
            )?;
        }
        Ok(())
    }

    /// Applies §6.8 steps 8–9: `apply_body`, header share registration, insertion and fork
    /// choice. The caller must have run `pre_validate` and Stage A (or trust the block).
    ///
    /// Owners enter the state only through verified signatures: the miner's and every
    /// share owner's ML-DSA-87 signature, and both treasury signatures of every
    /// withdrawal, are checked here even for trusted blocks.
    pub fn apply_verified_block(&mut self, block: Arc<Block>) -> Result<InsertOutcome, TreeError> {
        let id = block.header.block_id;
        if self.metas.contains_key(&id) {
            return Err(TreeError::Duplicate);
        }
        let parent_id = block.header.context.parent_canonical_id;
        let parent_meta = self
            .metas
            .get(&parent_id)
            .ok_or(TreeError::Orphan { parent: parent_id })?
            .clone();
        let parent_state = self.states.get(&parent_id).ok_or(TreeError::TooDeep)?;

        // Step 8: apply_body and require the body's derived fields to match
        let h = parent_meta.height + 1;
        let miner = verify_header_miner(&block.header)
            .map_err(|e| invalid(format!("header signature: {e}")))?;
        let verified: Vec<VerifiedShare> = block
            .body
            .shares
            .iter()
            .map(VerifiedShare::verify)
            .collect::<Result<_, _>>()
            .map_err(|e| invalid(format!("share signature: {e}")))?;
        let withdrawals: Vec<VerifiedWithdrawal> = block
            .body
            .withdrawals
            .iter()
            .map(|w| VerifiedWithdrawal::verify(w, &self.genesis, &self.genesis_id))
            .collect::<Result<_, _>>()
            .map_err(|e| invalid(format!("withdrawal: {e}")))?;
        let (mut post_state, derived) = apply_body(
            parent_state,
            &self.genesis,
            h,
            &block.body.jobs,
            &verified,
            &withdrawals,
        )
        .map_err(|e| invalid(e.to_string()))?;
        if derived.leases != block.body.leases {
            return Err(invalid("derived leases mismatch"));
        }
        if derived.receipts != block.body.receipts {
            return Err(invalid("derived receipts mismatch"));
        }
        if derived.fee_transitions != block.body.fee_transitions {
            return Err(invalid("derived fee_transitions mismatch"));
        }
        if derived.ledger_digest != block.body.ledger_digest {
            return Err(invalid("derived ledger_digest mismatch"));
        }

        // Step 9: the header's own work is a share if θ_S < Θ_S (§6.7)
        let header_share = top128(&block.header.share_ticket) < block.header.share_target.0;
        if header_share {
            post_state
                .shares
                .entry(block.header.work_id)
                .or_insert(ShareRecord {
                    work_id: block.header.work_id,
                    owner: miner,
                    weight: share_weight(block.header.share_target),
                    height: h,
                    included_at: h,
                    allocated_slots: 0,
                });
        }

        let sw = seal_weight(&block.header);
        let cw = parent_meta
            .cumulative_weight
            .checked_add(sw)
            .ok_or_else(|| invalid("cumulative_weight overflow"))?;
        let meta = BlockMeta {
            id,
            parent: parent_id,
            height: h,
            time_bucket: block.header.context.time_bucket,
            seal_target: block.header.seal_target,
            share_target: block.header.share_target,
            seal_weight: sw,
            cumulative_weight: cw,
            miner_key_id: miner.key_id(),
        };

        // Fork choice (§6.5): strictly heavier wins; a tie keeps the current tip.
        // The reorg path is computed before anything is inserted, so a too-deep
        // reorg leaves the tree untouched.
        let reorg = if cw > self.tip_meta().cumulative_weight {
            Some(self.reorg_path(parent_id)?)
        } else {
            None
        };

        let summary = build_summary(&block, &meta, &post_state, header_share)?;
        self.metas.insert(id, meta.clone());
        self.blocks.insert(id, block.clone());
        self.states.insert(id, Arc::new(post_state));
        self.summaries.insert(id, summary);

        let Some((fork_height, branch)) = reorg else {
            return Ok(InsertOutcome {
                meta,
                tip_changed: false,
                connected: Vec::new(),
                disconnected: Vec::new(),
            });
        };
        let keep = (fork_height + 1) as usize;
        let disconnected = self.canonical[keep..]
            .iter()
            .rev()
            .filter_map(|old| self.blocks.get(old).cloned())
            .collect();
        self.canonical.truncate(keep);
        self.canonical.extend(&branch);
        self.canonical.push(id);
        let connected = branch
            .iter()
            .chain(std::iter::once(&id))
            .filter_map(|new| self.blocks.get(new).cloned())
            .collect();
        self.tip = id;
        self.prune_old_snapshots();
        Ok(InsertOutcome {
            meta,
            tip_changed: true,
            connected,
            disconnected,
        })
    }

    /// Fork height and side branch (ascending, up to and including `parent_id`) of a new
    /// tip whose parent is `parent_id`.
    fn reorg_path(&self, parent_id: Digest) -> Result<(u64, Vec<Digest>), TreeError> {
        let view = self.ancestor_view(parent_id).ok_or(TreeError::TooDeep)?;
        if self.tip_meta().height.saturating_sub(view.fork_height) > MAX_REORG_DEPTH {
            return Err(TreeError::TooDeep);
        }
        Ok((view.fork_height, view.branch))
    }

    fn prune_old_snapshots(&mut self) {
        let Some(cutoff) = self.tip_meta().height.checked_sub(MAX_REORG_DEPTH) else {
            return;
        };
        // Collect before deleting ancestors; retain canonical history for sync.
        let doomed: Vec<_> = self
            .metas
            .values()
            .filter(|meta| !self.is_canonical(meta))
            .filter(|meta| {
                self.ancestor_view(meta.id)
                    .is_none_or(|view| view.fork_height < cutoff)
            })
            .map(|meta| meta.id)
            .collect();
        for id in doomed {
            self.states.remove(&id);
            self.blocks.remove(&id);
            self.summaries.remove(&id);
            self.metas.remove(&id);
        }
        let (metas, genesis_id) = (&self.metas, self.genesis_id);
        self.states
            .retain(|id, _| *id == genesis_id || metas.get(id).is_some_and(|m| m.height >= cutoff));
    }
}

fn build_summary(
    block: &Block,
    meta: &BlockMeta,
    post_state: &NodeState,
    header_share: bool,
) -> Result<BlockSummary, TreeError> {
    let mut jobs = Vec::with_capacity(block.body.jobs.len());
    for (i, tx) in block.body.jobs.iter().enumerate() {
        let (tx_id, job_id) = compute_job_ids(tx).map_err(invalid)?;
        let deposit = tx
            .checked_deposit()
            .ok_or_else(|| invalid("job deposit overflow"))?;
        jobs.push(JobSummary {
            job_id,
            tx_id,
            executor_owner: block.body.leases.get(i).map_or(Digest::ZERO, |l| l.owner),
            deposit,
            queue_fee: tx.queue_fee,
            base_fee: tx.base_fee,
        });
    }
    let receipts = block
        .body
        .receipts
        .iter()
        .map(|r| ReceiptSummary {
            job_id: r.job_id,
            result: r.result,
            executor_owner: r.executor_owner,
            admitted_at: r.admitted_at,
        })
        .collect();
    let shares = block
        .body
        .shares
        .iter()
        .map(|s| ShareSummary {
            work_id: s.work_id,
            owner: owner_key_id(&s.owner_key),
            height: s.context.height,
            weight: share_weight(s.share_target),
        })
        .collect();
    let mut withdrawals = Vec::with_capacity(block.body.withdrawals.len());
    for w in &block.body.withdrawals {
        let gross = w
            .checked_gross()
            .ok_or_else(|| invalid("withdrawal amount overflow"))?;
        withdrawals.push(WithdrawalSummary {
            tx_id: compute_withdrawal_id(w).map_err(invalid)?,
            nonce: w.expected_nonce,
            amount: gross - w.fee,
            fee: w.fee,
            outputs: w.outputs.len(),
        });
    }

    Ok(BlockSummary {
        height: meta.height,
        block_id: meta.id,
        parent_id: meta.parent,
        anchor_id: block.header.context.stable_anchor_id,
        miner_key_id: meta.miner_key_id,
        time_bucket: meta.time_bucket,
        attempt_nonce: block.header.context.attempt_nonce,
        generator_id: block.header.context.generator_id,
        epoch: post_state.ledger.epoch(),
        seal_ticket: block.header.seal_ticket,
        seal_weight: meta.seal_weight,
        cumulative_weight: meta.cumulative_weight,
        jobs,
        receipts,
        shares,
        withdrawals,
        header_share,
        fee_transitions: block.body.fee_transitions.clone(),
        balances_after: StateCategory::ALL.map(|c| post_state.ledger.balance(c).get()),
        total_after: post_state.ledger.total(),
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::core_adapter::fw_context_to_core;
    use crate::keys::{OwnerKeypair, unsigned};
    use crate::template::build_template;
    use primitives::TOTAL_SUPPLY;
    use wire::{DifficultyMode, JobPayload, JobTransaction};
    use work::FreshWorkIds;

    fn key(i: u8) -> Arc<OwnerKeypair> {
        Arc::new(OwnerKeypair::from_seed(&[i; 32]))
    }

    fn test_genesis() -> GenesisConfig {
        let mut g = GenesisConfig::default_testnet(1_700_000_000);
        g.initial_seal_target = Target(u128::MAX);
        g.share_ratio = 1;
        g.difficulty = DifficultyMode::Fixed;
        g.blocks_per_epoch = 4;
        g.settle_delay = 2;
        g.share_maturity_depth = 1;
        g.snapshot_window = 20;
        g.share_inclusion_window = 10;
        g
    }

    fn mine_one(
        tree: &BlockTree,
        parent_id: Digest,
        owner: &Arc<OwnerKeypair>,
        mempool: &[JobTransaction],
        nonce: u64,
        time_bucket: u64,
    ) -> Block {
        let anc = tree.ancestor_view(parent_id).unwrap();
        let parent_meta = tree.get_meta(&parent_id).unwrap();
        let parent_state = tree.get_state(&parent_id).unwrap();
        let tpl = build_template(
            1,
            tree.genesis(),
            tree.genesis_id(),
            &anc,
            parent_meta.height,
            &parent_state,
            mempool,
            &[],
            &[],
            owner,
            time_bucket,
        )
        .unwrap();
        let ctx = fw_context_to_core(&tpl.context_with_nonce(nonce)).unwrap();
        let inst = ctx.instance().unwrap();
        let z = inst.x.product(&inst.y);
        tpl.seal(nonce, &FreshWorkIds::derive(&ctx, &z)).unwrap()
    }

    /// A 1 PLAU job: one epoch of miner release funds it.
    fn sample_job(nonce: u64, expiry_height: u64, genesis_id: &Digest) -> JobTransaction {
        let client = key(200);
        let mut tx = JobTransaction {
            client_key: client.public_key().clone(),
            queue_fee: 1_000_000,
            base_fee: 10_000_000,
            v_exec: 79_000_000,
            v_da: 5_000_000,
            v_ref: 5_000_000,
            expiry_height,
            nonce,
            payload: JobPayload::ExactDot {
                xs: (1..=512).map(|i| i as f64).collect(),
                ys: (1..=512).rev().map(|i| i as f64).collect(),
            },
            signature: unsigned(),
        };
        client.sign_job(&mut tx, genesis_id).unwrap();
        tx
    }

    #[test]
    fn stf_job_lifecycle_and_tamper_rejection() {
        let g = test_genesis();
        let mut tree = BlockTree::new(g.clone()).unwrap();
        let tx = sample_job(1, 100, &tree.genesis_id());
        let miner = key(1);

        // Epoch 1 (boundary h = 4) books the miner release of blocks 1..=4 to the header
        // shares of blocks 1..=3; that booking is paid into U at the epoch-2 boundary
        // h = 8. Until then U is empty, so the template leaves the job out.
        let b1 = mine_one(
            &tree,
            tree.tip_id(),
            &miner,
            std::slice::from_ref(&tx),
            0,
            1_700_000_001,
        );
        assert!(b1.body.jobs.is_empty());
        tree.pre_validate(&b1, None).unwrap();
        BlockTree::verify_stage_a(&b1).unwrap();
        tree.apply_verified_block(Arc::new(b1)).unwrap();

        for h in 2..=7 {
            let b = mine_one(
                &tree,
                tree.tip_id(),
                &miner,
                std::slice::from_ref(&tx),
                h,
                1_700_000_000 + h,
            );
            assert!(b.body.jobs.is_empty(), "job must wait for spendable U");
            tree.pre_validate(&b, None).unwrap();
            let out = tree.apply_verified_block(Arc::new(b)).unwrap();
            assert!(out.tip_changed);
            assert_eq!(
                tree.tip_state().ledger.total(),
                u128::from(TOTAL_SUPPLY.get())
            );
        }

        // At h = 8 the epoch-1 booking is paid and a mature cohort exists: the job is admitted.
        let b8 = mine_one(
            &tree,
            tree.tip_id(),
            &miner,
            std::slice::from_ref(&tx),
            8,
            1_700_000_008,
        );
        assert_eq!(b8.body.jobs.len(), 1);
        assert_eq!(b8.body.leases.len(), 1);

        // Another key cannot claim the block: the work binds the miner's key id.
        let mut tampered = b8.clone();
        key(9).sign_header(&mut tampered.header).unwrap();
        assert!(tree.pre_validate(&tampered, None).is_err());

        tree.pre_validate(&b8, None).unwrap();
        BlockTree::verify_stage_a(&b8).unwrap();
        tree.apply_verified_block(Arc::new(b8)).unwrap();
        assert_eq!(tree.tip_state().open_jobs.len(), 1);

        // settle_delay = 2: the job settles at h = 10.
        for h in 9..=10 {
            let b = mine_one(&tree, tree.tip_id(), &miner, &[], h, 1_700_000_000 + h);
            assert_eq!(b.body.receipts.len(), usize::from(h == 10));
            tree.pre_validate(&b, None).unwrap();
            tree.apply_verified_block(Arc::new(b)).unwrap();
        }
        assert!(tree.tip_state().open_jobs.is_empty());
        assert_eq!(
            tree.tip_state().ledger.balance(StateCategory::Escrow).get(),
            0
        );
        let summaries = tree.canonical_summaries(None, 100);
        assert_eq!(summaries.len(), 10);
        assert!(
            summaries
                .iter()
                .all(|s| s.total_after == u128::from(TOTAL_SUPPLY.get()))
        );
    }

    #[test]
    fn fork_choice_heaviest_branch_and_tie_rule() {
        let g = test_genesis();
        let mut tree = BlockTree::new(g).unwrap();
        let genesis_id = tree.genesis_id();

        let (k1, k2) = (key(1), key(2));
        let a1 = mine_one(&tree, genesis_id, &k1, &[], 1, 1_700_000_001);
        let b1 = mine_one(&tree, genesis_id, &k2, &[], 2, 1_700_000_001);

        let out_a1 = tree.apply_verified_block(Arc::new(a1.clone())).unwrap();
        assert!(out_a1.tip_changed);
        assert_eq!(tree.tip_id(), a1.header.block_id);

        // A tie at height 1 keeps the current tip (a1).
        let out_b1 = tree.apply_verified_block(Arc::new(b1.clone())).unwrap();
        assert!(!out_b1.tip_changed);
        assert_eq!(tree.tip_id(), a1.header.block_id);

        // Extending branch B to height 2 makes it heavier: reorg.
        let b2 = mine_one(&tree, b1.header.block_id, &k2, &[], 3, 1_700_000_002);
        tree.pre_validate(&b2, None).unwrap();
        let out_b2 = tree.apply_verified_block(Arc::new(b2.clone())).unwrap();
        assert!(out_b2.tip_changed);
        assert_eq!(tree.tip_id(), b2.header.block_id);
        assert_eq!(out_b2.disconnected.len(), 1);
        assert_eq!(out_b2.disconnected[0].header.block_id, a1.header.block_id);
        let connected: Vec<Digest> = out_b2.connected.iter().map(|b| b.header.block_id).collect();
        assert_eq!(connected, vec![b1.header.block_id, b2.header.block_id]);
        assert_eq!(tree.canonical_id_at(1), Some(b1.header.block_id));
        assert_eq!(tree.canonical_id_at(2), Some(b2.header.block_id));

        // A block on the abandoned branch still validates against its own ancestry.
        let a2 = mine_one(&tree, a1.header.block_id, &k1, &[], 4, 1_700_000_002);
        tree.pre_validate(&a2, None).unwrap();
        let out_a2 = tree.apply_verified_block(Arc::new(a2)).unwrap();
        assert!(!out_a2.tip_changed, "equal weight keeps the current tip");
    }

    #[test]
    fn stale_tall_fork_is_rejected_then_removed_from_all_indexes() {
        let mut tree = BlockTree::new(test_genesis()).unwrap();
        let genesis = tree.genesis_id();
        let block = Arc::new(mine_one(&tree, genesis, &key(1), &[], 1, 1_700_000_001));
        tree.apply_verified_block(block.clone()).unwrap();
        let summary = tree.summaries[&tree.tip_id()].clone();
        let snapshot = tree.tip_state();
        // Synthetic ancestry isolates fork-depth accounting from work verification.
        let id = |branch: u8, h: u64| {
            let mut bytes = [branch; 64];
            bytes[..8].copy_from_slice(&h.to_be_bytes());
            Digest(bytes)
        };
        let mut canonical_parent = tree.tip_id();
        for h in 2..=MAX_REORG_DEPTH + 1 {
            let next = id(100, h);
            let mut meta = tree.tip_meta().clone();
            meta.id = next;
            meta.parent = canonical_parent;
            meta.height = h;
            tree.metas.insert(next, meta);
            tree.states.insert(next, snapshot.clone());
            tree.blocks.insert(next, block.clone());
            tree.summaries.insert(next, summary.clone());
            tree.canonical.push(next);
            tree.tip = next;
            canonical_parent = next;
        }
        let mut parent = genesis;
        for h in 1..=MAX_REORG_DEPTH {
            let next = id(200, h);
            let mut meta = tree.tip_meta().clone();
            meta.id = next;
            meta.parent = parent;
            meta.height = h;
            tree.metas.insert(next, meta);
            tree.states.insert(next, snapshot.clone());
            tree.blocks.insert(next, block.clone());
            tree.summaries.insert(next, summary.clone());
            parent = next;
        }
        // Parent is only one height behind the tip, but fork point is too old.
        let mut candidate = (*block).clone();
        candidate.header.block_id = id(201, MAX_REORG_DEPTH + 1);
        candidate.header.context.parent_canonical_id = parent;
        assert_eq!(tree.pre_validate(&candidate, None), Err(TreeError::TooDeep));

        // A branch rooted exactly at the allowed boundary remains eligible.
        let boundary = id(210, 2);
        let mut meta = tree.tip_meta().clone();
        meta.id = boundary;
        meta.parent = tree.canonical_id_at(1).unwrap();
        meta.height = 2;
        tree.metas.insert(boundary, meta);
        tree.states.insert(boundary, snapshot);
        tree.prune_old_snapshots();
        for h in 1..=MAX_REORG_DEPTH {
            let doomed = id(200, h);
            assert!(!tree.states.contains_key(&doomed));
            assert!(!tree.blocks.contains_key(&doomed));
            assert!(!tree.summaries.contains_key(&doomed));
            assert!(!tree.metas.contains_key(&doomed));
        }
        assert!(tree.states.contains_key(&boundary));
        assert!(tree.metas.contains_key(&boundary));
        assert!(tree.blocks.contains_key(&block.header.block_id));
        assert!(tree.states.contains_key(&genesis));
    }
}
EOF

cat << 'EOF' > chain/tests/consensus_suite.rs
//! Consensus and STF tests (§11 unit tests 3–7).

#![forbid(unsafe_code)]

use std::sync::{Arc, OnceLock};

use chain::core_adapter::fw_context_to_core;
use chain::keys::{unsigned, unsigned_cosignature};
use chain::{
    BlockTree, OwnerKeypair, ShareCheck, SignatureError, SignedShare, SignedWithdrawal, StfError,
    TreasuryKeypair, TreeError, VerifiedShare, VerifiedWithdrawal, WithdrawalError, WorkError,
    apply_body, build_template, compute_body_root, compute_difficulty_context, compute_job_ids,
    scheduled_generator_id, verify_ml_dsa_87,
};
use ledger::{
    INITIAL_ALLOCATION, INITIAL_VALVE_LIMIT, INITIAL_VALVE_WINDOW, MINER_ALLOCATION, StateCategory,
    initial_release_cumulative,
};
use primitives::{Atoms, TOTAL_SUPPLY};
use wire::{
    Block, DIGEST_LEN, DifficultyMode, Digest, FeeTransition, FwContext, GenesisConfig,
    InitialPoolWithdrawal, JobPayload, JobTransaction, MAX_REORG_DEPTH, ShareProof, Target,
    WithdrawalOutput,
};
use work::{FreshWorkIds, GeneratorProfile};

/// One PLAU in atoms.
const PLAU: u64 = 100_000_000;

/// Test owner `i`, derived from a fixed seed so runs are reproducible.
fn key(i: u8) -> Arc<OwnerKeypair> {
    Arc::new(OwnerKeypair::from_seed(&[i; 32]))
}

/// A share proof for `apply_body`-level tests: synthetic work, a real owner signature.
/// `VerifiedShare::verify` is the only way to obtain a `VerifiedShare`.
fn synthetic_share(owner: &OwnerKeypair, work_id: Digest, height: u64) -> VerifiedShare {
    let zero = Digest::ZERO;
    let mut share = ShareProof {
        context: FwContext {
            chain_id: 0,
            genesis_id: zero,
            protocol_id: 0,
            crypto_suite_id: 0,
            program_id: zero,
            air_id: zero,
            generator_id: 0,
            parent_canonical_id: zero,
            stable_anchor_id: zero,
            height,
            miner_policy_digest: zero,
            payout_policy_digest: zero,
            attempt_nonce: 0,
            body_core_root: zero,
            parent_derived_difficulty_context: zero,
            time_bucket: 0,
        },
        owner_key: owner.public_key().clone(),
        output_root: zero,
        work_id,
        share_ticket: zero,
        share_target: Target(1 << 125),
        signature: unsigned(),
    };
    owner.sign_share(&mut share).unwrap();
    VerifiedShare::verify(&share).unwrap()
}

fn fast_genesis() -> GenesisConfig {
    let mut g = GenesisConfig::default_testnet(1_700_000_000);
    // Every attempt seals and every header is a share: one tile per block.
    g.initial_seal_target = Target(u128::MAX);
    g.share_ratio = 1;
    g.difficulty = DifficultyMode::Fixed;
    g.blocks_per_epoch = 5;
    g.maturation_delay = 2;
    g.settle_delay = 2;
    g.share_maturity_depth = 1;
    g.snapshot_window = 30;
    g.share_inclusion_window = 15;
    g
}

fn make_job(
    seed: u64,
    queue_fee: u64,
    base_fee: u64,
    v_exec: u64,
    expiry_height: u64,
    genesis_id: &Digest,
) -> JobTransaction {
    let mut s = seed.wrapping_add(1);
    let mut next_val = || -> f64 {
        s ^= s << 13;
        s ^= s >> 7;
        s ^= s << 17;
        ((s % 2000) as i64 - 1000) as f64
    };
    let xs: Vec<f64> = (0..512).map(|_| next_val()).collect();
    let ys: Vec<f64> = (0..512).map(|_| next_val()).collect();
    let client = key(100);
    let mut tx = JobTransaction {
        client_key: client.public_key().clone(),
        queue_fee,
        base_fee,
        v_exec,
        v_da: 5_000_000,
        v_ref: 5_000_000,
        expiry_height,
        nonce: seed,
        payload: JobPayload::ExactDot { xs, ys },
        signature: unsigned(),
    };
    client.sign_job(&mut tx, genesis_id).unwrap();
    tx
}

fn template_on(
    tree: &BlockTree,
    parent_id: Digest,
    owner: &Arc<OwnerKeypair>,
    mempool: &[JobTransaction],
    shares: &[ShareProof],
) -> chain::Template {
    template_with_withdrawals(tree, parent_id, owner, mempool, shares, &[])
}

fn template_with_withdrawals(
    tree: &BlockTree,
    parent_id: Digest,
    owner: &Arc<OwnerKeypair>,
    mempool: &[JobTransaction],
    shares: &[ShareProof],
    withdrawals: &[SignedWithdrawal],
) -> chain::Template {
    let anc = tree.ancestor_view(parent_id).unwrap();
    let parent_meta = tree.get_meta(&parent_id).unwrap();
    let parent_state = tree.get_state(&parent_id).unwrap();
    // As a share pool would: only signature-checked shares enter.
    let pool: Vec<SignedShare> = shares
        .iter()
        .filter_map(|sh| SignedShare::verify(sh.clone()).ok())
        .collect();
    build_template(
        1,
        tree.genesis(),
        tree.genesis_id(),
        &anc,
        parent_meta.height,
        &parent_state,
        mempool,
        &pool,
        withdrawals,
        owner,
        parent_meta.time_bucket + 1,
    )
    .unwrap()
}

fn work_ids(ctx: &wire::FwContext) -> FreshWorkIds {
    let core_ctx = fw_context_to_core(ctx).unwrap();
    let inst = core_ctx.instance().unwrap();
    let z = inst.x.product(&inst.y);
    FreshWorkIds::derive(&core_ctx, &z)
}

fn mine_block_on(
    tree: &BlockTree,
    parent_id: Digest,
    owner: &Arc<OwnerKeypair>,
    mempool: &[JobTransaction],
    shares: &[ShareProof],
    nonce: u64,
) -> Block {
    let tpl = template_on(tree, parent_id, owner, mempool, shares);
    tpl.seal(nonce, &work_ids(&tpl.context_with_nonce(nonce)))
        .unwrap()
}

fn mine_block_with_withdrawals(
    tree: &BlockTree,
    owner: &Arc<OwnerKeypair>,
    withdrawals: &[SignedWithdrawal],
    nonce: u64,
) -> Block {
    let tpl = template_with_withdrawals(tree, tree.tip_id(), owner, &[], &[], withdrawals);
    tpl.seal(nonce, &work_ids(&tpl.context_with_nonce(nonce)))
        .unwrap()
}

fn mine_share_on(
    tree: &BlockTree,
    parent_id: Digest,
    owner: &Arc<OwnerKeypair>,
    nonce: u64,
) -> ShareProof {
    let tpl = template_on(tree, parent_id, owner, &[], &[]);
    tpl.share(nonce, &work_ids(&tpl.context_with_nonce(nonce)))
        .unwrap()
}

fn extend(tree: &mut BlockTree, block: Block) {
    tree.pre_validate(&block, None).unwrap();
    BlockTree::verify_stage_a(&block).unwrap();
    tree.apply_verified_block(Arc::new(block)).unwrap();
}

/// Two equal-weight shares; the first reward becomes spendable at height 10.
fn scheduler_state(g: &GenesisConfig) -> (chain::NodeState, Digest, [Digest; 2]) {
    let (_, ledger, genesis_id) = chain::validate_genesis(g).unwrap();
    let mut state = chain::NodeState::genesis(ledger);
    let ids = [Digest([1; DIGEST_LEN]), Digest([2; DIGEST_LEN])];
    for h in 1..=9 {
        let shares = if h <= 2 {
            vec![synthetic_share(&key(h as u8), ids[h as usize - 1], h)]
        } else {
            vec![]
        };
        state = apply_body(&state, g, h, &[], &shares, &[]).unwrap().0;
    }
    assert!(state.shares.values().all(|s| s.allocated_slots == 0));
    (state, genesis_id, ids)
}

#[test]
fn dhondt_counters_persist_across_blocks_idle_blocks_and_epochs() {
    let g = fast_genesis();
    let (mut state, genesis_id, ids) = scheduler_state(&g);
    let mut assigned = 0;
    for h in 10..=16 {
        let jobs = if h == 12 {
            vec![]
        } else {
            vec![make_job(h, 1, 1, 1, 100, &genesis_id)]
        };
        let (next, derived) = apply_body(&state, &g, h, &jobs, &[], &[]).unwrap();
        if !jobs.is_empty() {
            assert_eq!(derived.leases[0].share_id, ids[assigned % 2]);
            assigned += 1;
        }
        assert_eq!(
            next.shares[&ids[0]].allocated_slots,
            assigned.div_ceil(2) as u64
        );
        assert_eq!(next.shares[&ids[1]].allocated_slots, (assigned / 2) as u64);
        assert_eq!(
            state
                .shares
                .values()
                .map(|s| s.allocated_slots)
                .sum::<u64>(),
            (assigned - jobs.len()) as u64,
            "constructing the child must not mutate the parent snapshot"
        );
        state = next;
    }
    assert_eq!(assigned, 6);
    assert_eq!(state.ledger.total(), u128::from(TOTAL_SUPPLY.get()));
}

#[test]
fn dhondt_new_and_expiring_shares_preserve_survivors_counters() {
    let mut g = fast_genesis();
    g.snapshot_window = 10;
    g.share_inclusion_window = 3;
    let (state, genesis_id, ids) = scheduler_state(&g);
    let job = make_job(10, 1, 1, 1, 100, &genesis_id);
    let (s10, first) = apply_body(&state, &g, 10, &[job], &[], &[]).unwrap();
    assert_eq!(first.leases[0].share_id, ids[0]);

    let newcomer = Digest([0; DIGEST_LEN]);
    let new_share = synthetic_share(&key(3), newcomer, 11);
    let (s11, _) = apply_body(&s10, &g, 11, &[], &[new_share], &[]).unwrap();
    assert_eq!(s11.shares[&newcomer].allocated_slots, 0);
    assert_eq!(s11.shares[&ids[0]].allocated_slots, 1);

    // The first share is no longer eligible at height 12. Its history is kept
    // until ordinary pruning, while the newcomer becomes eligible with a_s = 0.
    let job = make_job(12, 1, 1, 1, 100, &genesis_id);
    let (s12, next) = apply_body(&s11, &g, 12, &[job], &[], &[]).unwrap();
    assert_eq!(next.leases[0].share_id, newcomer);
    assert_eq!(s12.shares[&ids[0]].allocated_slots, 1);
    assert_eq!(s12.shares[&newcomer].allocated_slots, 1);
    let job = make_job(13, 1, 1, 1, 100, &genesis_id);
    let (s13, next) = apply_body(&s12, &g, 13, &[job], &[], &[]).unwrap();
    assert_eq!(next.leases[0].share_id, newcomer);
    assert!(!s13.shares.contains_key(&ids[0]));
    assert_eq!(s13.shares[&newcomer].allocated_slots, 2);
    assert_eq!(s13.shares[&ids[1]].allocated_slots, 0);
}

#[test]
fn dhondt_counter_overflow_rejects_without_mutating_parent() {
    let g = fast_genesis();
    let (mut state, genesis_id, ids) = scheduler_state(&g);
    state.shares.get_mut(&ids[0]).unwrap().allocated_slots = u64::MAX;
    let job = make_job(10, 1, 1, 1, 100, &genesis_id);
    assert!(matches!(
        apply_body(&state, &g, 10, &[job], &[], &[]),
        Err(StfError::SchedulerError(message)) if message.contains("overflow")
    ));
    assert_eq!(state.height, 9);
    assert_eq!(state.shares[&ids[0]].allocated_slots, u64::MAX);
    assert_eq!(state.shares[&ids[1]].allocated_slots, 0);
    assert_eq!(state.ledger.balance(StateCategory::Escrow), Atoms::ZERO);
}

#[test]
fn dhondt_counters_follow_branch_state_on_reorg() {
    let g = fast_genesis();
    let mut tree = BlockTree::new(g).unwrap();
    let miner = key(1);
    for h in 1..=9 {
        let block = mine_block_on(&tree, tree.tip_id(), &miner, &[], &[], h);
        extend(&mut tree, block);
    }
    let fork = tree.tip_id();
    let job = make_job(10, 1, 1, 1, 100, &tree.genesis_id());
    let a10 = mine_block_on(&tree, fork, &miner, &[job], &[], 10);
    let winner = a10.body.leases[0].share_id;
    let a10_id = a10.header.block_id;
    extend(&mut tree, a10);
    assert_eq!(tree.tip_state().shares[&winner].allocated_slots, 1);

    let b10 = mine_block_on(&tree, fork, &miner, &[], &[], 100);
    let b10_id = b10.header.block_id;
    extend(&mut tree, b10);
    let b11 = mine_block_on(&tree, b10_id, &miner, &[], &[], 101);
    let b11_id = b11.header.block_id;
    extend(&mut tree, b11);
    assert_eq!(tree.tip_id(), b11_id);
    assert!(
        tree.tip_state()
            .shares
            .values()
            .all(|s| s.allocated_slots == 0)
    );
    assert_eq!(
        tree.get_state(&a10_id).unwrap().shares[&winner].allocated_slots,
        1
    );

    let a11 = mine_block_on(&tree, a10_id, &miner, &[], &[], 11);
    let a11_id = a11.header.block_id;
    extend(&mut tree, a11);
    let a12 = mine_block_on(&tree, a11_id, &miner, &[], &[], 12);
    let a12_id = a12.header.block_id;
    extend(&mut tree, a12);
    assert_eq!(tree.tip_id(), a12_id);
    assert_eq!(tree.tip_state().shares[&winner].allocated_slots, 1);
}

/// Unit test 3 (§11): 200 blocks with random job counts, random fees and epoch boundaries.
/// `apply_body` conserves `M = 1.5 * 10^15` atoms (spec eq. 7.15) and passes
/// `check_invariants()` after every block, and every block opens with its primary
/// release.
#[test]
fn randomized_200_blocks_conserve_supply_m() {
    let g = fast_genesis();
    let (_, ledger, genesis_id) = chain::validate_genesis(&g).unwrap();
    let mut state = chain::NodeState::genesis(ledger);
    let owners: Vec<Arc<OwnerKeypair>> = (1..=5).map(key).collect();

    let mut rng = 0x1234_5678_9abc_def0u64;
    let mut next_u64 = || -> u64 {
        rng ^= rng << 13;
        rng ^= rng >> 7;
        rng ^= rng << 17;
        rng
    };

    let mut admitted = 0usize;
    let mut settled = 0usize;
    for h in 1..=200u64 {
        let share_owner = &owners[(next_u64() % 5) as usize];
        let mut wid = [0u8; DIGEST_LEN];
        wid[0..8].copy_from_slice(&h.to_be_bytes());
        wid[8..16].copy_from_slice(&next_u64().to_be_bytes());
        let shares = vec![synthetic_share(
            share_owner,
            Digest(wid),
            h.saturating_sub(1).max(1),
        )];

        let mut jobs = Vec::new();
        // The epoch-1 booking (the miner release of blocks 1..=5) is paid at h = 10; from
        // then on U holds spendable rewards. At most three jobs of at most 0.55 PLAU stay
        // inside the per-block faucet, U / 16.
        if h >= 10 {
            let count = (next_u64() % 4) as usize;
            for j in 0..count {
                let seed = h * 100 + j as u64;
                let q_fee = ((next_u64() % 5) + 1) * 1_000_000;
                let b_fee = ((next_u64() % 10) + 1) * 2_000_000;
                let v_exec = ((next_u64() % 20) + 1) * 1_000_000;
                let job = make_job(seed, q_fee, b_fee, v_exec, h + 50, &genesis_id);
                // Stateless validation and compute_job_ids agree on tx_id.
                assert_eq!(
                    chain::validate_job_stateless(&job).unwrap().0,
                    compute_job_ids(&job).unwrap().0
                );
                jobs.push(job);
            }
            jobs.sort_by_key(|tx| compute_job_ids(tx).unwrap().0);
        }

        let (next_state, derived) = apply_body(&state, &g, h, &jobs, &shares, &[]).unwrap();
        assert_eq!(next_state.ledger.total(), u128::from(TOTAL_SUPPLY.get()));
        next_state.ledger.check_invariants().unwrap();
        assert!(matches!(
            derived.fee_transitions[0],
            FeeTransition::PrimaryRelease { block, .. } if block == h
        ));
        for ft in &derived.fee_transitions {
            let sum: i128 = ft.delta().iter().sum();
            assert_eq!(sum, 0, "every fee transition delta must sum to zero");
        }
        assert_eq!(derived.leases.len(), jobs.len());
        admitted += jobs.len();
        settled += derived.receipts.len();
        state = next_state;
    }
    assert!(admitted > 100, "the random schedule must admit many jobs");
    assert_eq!(
        settled + state.open_jobs.len(),
        admitted,
        "every admitted job settles after settle_delay"
    );
}

/// Unit test 4 (§11): tampering with a derived field, a context field, a target,
/// `miner_owner`, an operand, or the fee-transition order is rejected.
#[test]
fn tampering_with_block_fields_is_rejected() {
    let g = fast_genesis();
    let mut tree = BlockTree::new(g).unwrap();
    let miner = key(1);

    // Advance to height 10, where the epoch-1 booking is paid into U.
    for h in 1..=10 {
        let blk = mine_block_on(&tree, tree.tip_id(), &miner, &[], &[], h);
        extend(&mut tree, blk);
    }

    let job = make_job(
        555,
        1_000_000,
        10_000_000,
        80_000_000,
        100,
        &tree.genesis_id(),
    );
    let honest = mine_block_on(&tree, tree.tip_id(), &miner, &[job], &[], 11);
    assert_eq!(honest.body.jobs.len(), 1);
    assert!(honest.body.fee_transitions.len() >= 2);

    // Derived fields: rejected by apply_verified_block even in a block that is otherwise
    // fully valid (body recommitted, work re-sealed, header re-signed), so the failure
    // is the derived-field check itself.
    let rejects_with = |tree: &mut BlockTree, mut block: Block, expected: &str| {
        reseal(&mut block, &miner);
        BlockTree::verify_stage_a(&block).unwrap();
        match tree.apply_verified_block(Arc::new(block)) {
            Err(TreeError::Invalid(reason)) => {
                assert!(reason.contains(expected), "{reason:?} lacks {expected:?}")
            }
            other => panic!("expected {expected:?}, got {other:?}"),
        }
    };
    let mut bad_digest = honest.clone();
    bad_digest.body.ledger_digest.0[0] ^= 0x01;
    rejects_with(&mut tree, bad_digest, "derived ledger_digest mismatch");

    let mut bad_ft_order = honest.clone();
    bad_ft_order.body.fee_transitions.reverse();
    rejects_with(&mut tree, bad_ft_order, "derived fee_transitions mismatch");

    let mut bad_leases = honest.clone();
    bad_leases.body.leases[0].owner = key(9).key_id();
    rejects_with(&mut tree, bad_leases, "derived leases mismatch");

    // Context field: rejected by Stage B.
    let mut bad_ctx = honest.clone();
    bad_ctx.header.context.height += 1;
    assert!(tree.pre_validate(&bad_ctx, None).is_err());

    // Targets, even with a matching difficulty context digest.
    let mut bad_target = honest.clone();
    bad_target.header.seal_target = Target(u128::MAX - 1);
    bad_target.header.context.parent_derived_difficulty_context = compute_difficulty_context(
        bad_target.header.seal_target,
        bad_target.header.share_target,
    );
    assert!(tree.pre_validate(&bad_target, None).is_err());

    // Another key re-signing the header cannot claim the block.
    let mut bad_owner = honest.clone();
    key(2).sign_header(&mut bad_owner.header).unwrap();
    assert!(tree.pre_validate(&bad_owner, None).is_err());

    // One operand changed without updating body_core_root.
    let mut bad_operand = honest.clone();
    let JobPayload::ExactDot { ref mut xs, .. } = bad_operand.body.jobs[0].payload;
    xs[0] += 1.0;
    assert!(tree.pre_validate(&bad_operand, None).is_err());

    // Stage A: a forged nonce no longer matches the claimed work, even when the miner
    // re-signs the header (so the work check, not the signature, rejects it).
    let mut bad_nonce = honest.clone();
    bad_nonce.header.context.attempt_nonce += 1;
    miner.sign_header(&mut bad_nonce.header).unwrap();
    BlockTree::verify_signatures(&bad_nonce).unwrap();
    assert!(matches!(
        BlockTree::verify_stage_a(&bad_nonce),
        Err(WorkError::OutputRootMismatch)
    ));

    // The honest block still applies.
    extend(&mut tree, honest);
    assert_eq!(tree.tip_meta().height, 11);
}

/// Unit test 5 (§11): job flow, the empty faucet before the first reward payment, and
/// `R_l -> R_a` as two lots.
#[test]
fn job_fee_lock_and_two_lot_maturation_flow() {
    let g = fast_genesis(); // blocks_per_epoch = 5, maturation_delay = 2, settle_delay = 2
    let mut tree = BlockTree::new(g.clone()).unwrap();
    let miner = key(1);
    let job = make_job(
        999,
        1_000_000,
        10_000_000,
        80_000_000,
        100,
        &tree.genesis_id(),
    );

    // All supply starts unissued and the miner release waits in P_pending until the
    // first payment, so U is empty and funding fails on the faucet budget.
    let sh = synthetic_share(&miner, Digest([1u8; DIGEST_LEN]), 1);
    let (s1, _) = apply_body(&tree.tip_state(), &g, 1, &[], &[sh], &[]).unwrap();
    let res = apply_body(&s1, &g, 2, std::slice::from_ref(&job), &[], &[]);
    assert!(matches!(res, Err(StfError::FaucetBudgetExceeded)));

    // Blocks 1..=9: the job stays out of the template.
    for h in 1..=9 {
        let blk = mine_block_on(
            &tree,
            tree.tip_id(),
            &miner,
            std::slice::from_ref(&job),
            &[],
            h,
        );
        assert!(blk.body.jobs.is_empty(), "h = {h}");
        extend(&mut tree, blk);
    }

    // h = 10 (epoch 2): the epoch-1 booking is paid into U and the job is admitted;
    // R_l holds queue_fee + base_fee = 1.1 * 10^7 atoms as two locked fees.
    let b10 = mine_block_on(
        &tree,
        tree.tip_id(),
        &miner,
        std::slice::from_ref(&job),
        &[],
        10,
    );
    assert_eq!(b10.body.jobs.len(), 1);
    assert!(matches!(
        b10.body.fee_transitions[0],
        FeeTransition::PrimaryRelease { block: 10, .. }
    ));
    assert!(matches!(
        b10.body.fee_transitions[2],
        FeeTransition::FwReward { amount, .. } if amount > 0
    ));
    extend(&mut tree, b10);
    let ledger = &tree.tip_state().ledger;
    assert_eq!(
        ledger.balance(StateCategory::LockedBaseFees),
        Atoms(11_000_000)
    );
    // After admission the escrow holds exactly v_exec + v_da + v_ref.
    assert_eq!(ledger.balance(StateCategory::Escrow), Atoms(90_000_000));
    assert_eq!(ledger.locked_fees().len(), 2);

    // Paid in epoch 2 with L = 2: maturity epoch 2 + 2 + 1 = 5, i.e. h = 25.
    for h in 11..=25 {
        let blk = mine_block_on(&tree, tree.tip_id(), &miner, &[], &[], h);
        assert_eq!(blk.body.receipts.len(), usize::from(h == 12), "h = {h}");
        if h == 25 {
            let mat = blk
                .body
                .fee_transitions
                .iter()
                .find_map(|ft| match ft {
                    FeeTransition::ReserveMature { matured_lots, .. } => Some(matured_lots.clone()),
                    _ => None,
                })
                .unwrap();
            assert_eq!(
                mat.len(),
                2,
                "queue_fee and base_fee mature as 2 independent lots"
            );
        }
        extend(&mut tree, blk);
    }

    let ledger = &tree.tip_state().ledger;
    assert_eq!(ledger.balance(StateCategory::LockedBaseFees), Atoms::ZERO);
    assert_eq!(ledger.balance(StateCategory::Escrow), Atoms::ZERO);
    assert_eq!(
        ledger.fee_lots().len(),
        2,
        "the 2 matured fee lots; R_a has no Genesis lot"
    );
}

/// Unit tests 6 and 7 (§11): share inclusion rules and `MAX_REORG_DEPTH`.
#[test]
fn share_validation_rules_and_max_reorg_depth() {
    let mut g = fast_genesis();
    g.share_inclusion_window = 3;
    let mut tree = BlockTree::new(g).unwrap();
    let (miner, sharer) = (key(1), key(2));

    for h in 1..=5 {
        let blk = mine_block_on(&tree, tree.tip_id(), &miner, &[], &[], h);
        extend(&mut tree, blk);
    }

    // A share mined at height 1 is outside the window (3) at height 6.
    let p0 = tree.canonical_id_at(0).unwrap();
    let old_share = mine_share_on(&tree, p0, &sharer, 77);
    assert_eq!(old_share.context.height, 1);
    let mut blk_with_old = mine_block_on(&tree, tree.tip_id(), &miner, &[], &[], 6);
    blk_with_old.body.shares.push(old_share);
    blk_with_old.header.context.body_core_root = compute_body_root(&blk_with_old.body).unwrap();
    assert!(tree.pre_validate(&blk_with_old, None).is_err());

    // A valid share mined at height 5 on the canonical parent.
    let p4 = tree.canonical_id_at(4).unwrap();
    let valid_share = mine_share_on(&tree, p4, &sharer, 88);
    assert_eq!(valid_share.context.height, 5);

    // Another owner re-signing the share: its key id does not match the policy digests.
    let mut bad_owner_share = valid_share.clone();
    key(99).sign_share(&mut bad_owner_share).unwrap();
    let mut blk_bad_owner = mine_block_on(&tree, tree.tip_id(), &miner, &[], &[], 6);
    blk_bad_owner.body.shares.push(bad_owner_share);
    blk_bad_owner.header.context.body_core_root = compute_body_root(&blk_bad_owner.body).unwrap();
    assert!(tree.pre_validate(&blk_bad_owner, None).is_err());

    // Wrong share target.
    let mut bad_target_share = valid_share.clone();
    bad_target_share.share_target = Target(u128::MAX - 10);
    let mut blk_bad_target = mine_block_on(&tree, tree.tip_id(), &miner, &[], &[], 6);
    blk_bad_target.body.shares.push(bad_target_share);
    blk_bad_target.header.context.body_core_root = compute_body_root(&blk_bad_target.body).unwrap();
    assert!(tree.pre_validate(&blk_bad_target, None).is_err());

    // The valid share goes through the template and registers with its owner.
    let with_share = mine_block_on(
        &tree,
        tree.tip_id(),
        &miner,
        &[],
        std::slice::from_ref(&valid_share),
        6,
    );
    assert_eq!(with_share.body.shares, vec![valid_share.clone()]);
    extend(&mut tree, with_share);
    let registered = tree.tip_state().shares[&valid_share.work_id].owner;
    assert_eq!(
        registered.key_id(),
        sharer.key_id(),
        "share registered for its owner"
    );
    assert_eq!(registered.owner_id(), sharer.owner_id());

    // Advance past MAX_REORG_DEPTH and check that a fork from genesis is TooDeep.
    for h in 7..=MAX_REORG_DEPTH + 6 {
        let blk = mine_block_on(&tree, tree.tip_id(), &miner, &[], &[], h);
        tree.pre_validate(&blk, None).unwrap();
        tree.apply_verified_block(Arc::new(blk)).unwrap();
    }
    let deep_fork_blk = mine_block_on(&tree, tree.genesis_id(), &sharer, &[], &[], 999);
    assert_eq!(
        tree.pre_validate(&deep_fork_blk, None),
        Err(TreeError::TooDeep)
    );
}

/// Recommits a hand-edited body and re-seals the block for `miner`: the attacker's
/// path to a self-consistent block (every attempt seals under `fast_genesis`).
fn reseal(block: &mut Block, miner: &OwnerKeypair) {
    block.header.context.body_core_root = compute_body_root(&block.body).unwrap();
    let ids = chain::core_adapter::fresh_work_ids_to_digests(&work_ids(&block.header.context));
    block.header.output_root = ids.output_root;
    block.header.work_id = ids.work_id;
    block.header.block_id = ids.block_id;
    block.header.share_ticket = ids.share_ticket;
    block.header.seal_ticket = ids.seal_ticket;
    miner.sign_header(&mut block.header).unwrap();
}

/// ML-DSA-87 rules: a forged header, share or job signature rejects the block in
/// Stage A and in `apply_verified_block`; a job signed for another chain or under
/// another key does not verify; `tx_id` does not depend on the signature.
#[test]
fn signatures_bind_headers_shares_and_jobs() {
    let g = fast_genesis();
    let mut tree = BlockTree::new(g).unwrap();
    let (miner, sharer) = (key(1), key(2));
    for h in 1..=10 {
        let blk = mine_block_on(&tree, tree.tip_id(), &miner, &[], &[], h);
        extend(&mut tree, blk);
    }
    let genesis_id = tree.genesis_id();
    // Mined at height 10 (on block 9), so includable at height 11.
    let share = mine_share_on(&tree, tree.canonical_id_at(9).unwrap(), &sharer, 31);
    let job = make_job(4242, 1_000_000, 10_000_000, 80_000_000, 100, &genesis_id);
    let honest = mine_block_on(
        &tree,
        tree.tip_id(),
        &miner,
        std::slice::from_ref(&job),
        std::slice::from_ref(&share),
        11,
    );
    assert_eq!((honest.body.jobs.len(), honest.body.shares.len()), (1, 1));
    BlockTree::verify_signatures(&honest).unwrap();

    // Header: one flipped signature byte. Stage B ignores signatures; Stage A and
    // apply_verified_block (which also serves trusted disk replay) reject it.
    let mut forged_header = honest.clone();
    forged_header.header.signature.0[100] ^= 0x01;
    tree.pre_validate(&forged_header, None).unwrap();
    assert!(matches!(
        BlockTree::verify_stage_a(&forged_header),
        Err(WorkError::Signature("header", _))
    ));
    assert!(tree.apply_verified_block(Arc::new(forged_header)).is_err());

    // Share: a forged owner signature inside an otherwise valid, re-sealed block.
    let mut forged_share = honest.clone();
    forged_share.body.shares[0].signature.0[7] ^= 0x80;
    reseal(&mut forged_share, &miner);
    tree.pre_validate(&forged_share, None).unwrap();
    assert!(matches!(
        BlockTree::verify_stage_a(&forged_share),
        Err(WorkError::Signature("share", _))
    ));
    assert!(tree.apply_verified_block(Arc::new(forged_share)).is_err());

    // A share whose signature fails never enters a share pool, so no template sees it.
    let mut bad_sig_share = share.clone();
    bad_sig_share.signature.0[0] ^= 0x01;
    assert!(SignedShare::verify(bad_sig_share).is_err());

    // Job: signed for another genesis, or carrying another client's key.
    let other_genesis = Digest([0xee; DIGEST_LEN]);
    let mut replayed = job.clone();
    key(100).sign_job(&mut replayed, &other_genesis).unwrap();
    assert!(chain::verify_job_client(&replayed, &other_genesis).is_ok());
    assert_eq!(
        chain::verify_job_client(&replayed, &genesis_id),
        Err(SignatureError::Invalid)
    );
    let mut wrong_job = honest.clone();
    wrong_job.body.jobs[0] = replayed;
    reseal(&mut wrong_job, &miner);
    tree.pre_validate(&wrong_job, None).unwrap();
    assert!(matches!(
        BlockTree::verify_stage_a(&wrong_job),
        Err(WorkError::Signature("job", SignatureError::Invalid))
    ));

    let mut swapped_key = job.clone();
    swapped_key.client_key = key(101).public_key().clone();
    assert!(chain::verify_job_client(&swapped_key, &genesis_id).is_err());

    // Hedged signing: re-signing yields new signature bytes but the same tx_id.
    let mut resigned = job.clone();
    key(100).sign_job(&mut resigned, &genesis_id).unwrap();
    assert_ne!(resigned.signature, job.signature);
    assert_eq!(
        compute_job_ids(&resigned).unwrap(),
        compute_job_ids(&job).unwrap()
    );
    assert!(chain::verify_job_client(&resigned, &genesis_id).is_ok());

    // The honest block applies; both owners enter the state through verified keys.
    extend(&mut tree, honest.clone());
    let state = tree.tip_state();
    assert_eq!(state.shares[&share.work_id].owner.key_id(), sharer.key_id());
    assert_eq!(
        state.shares[&honest.header.work_id].owner.key_id(),
        miner.key_id(),
        "the header share is registered for the miner"
    );
    assert_eq!(tree.tip_meta().miner_key_id, miner.key_id());
}

/// ML-DSA-87 interoperates with an independent FIPS 204 implementation: the
/// vectors come from OpenSSL 4.0 (via Python `cryptography`), with the seed
/// `00 01 .. 1f` and the context string `PLAU/TX`.
#[test]
fn ml_dsa_87_matches_an_independent_implementation() {
    let seed: [u8; 32] = core::array::from_fn(|i| i as u8);
    let kp = OwnerKeypair::from_seed(&seed);
    // FIPS 204 KeyGen_internal from the same seed gives the same public key, so the
    // same key id: H(PLAU/OWNER, pk) computed by Python hashlib.
    assert_eq!(
        kp.key_id().to_hex(),
        "63645aadf7d3818f1ebd1566e1166daeb650683912bb2a5c61f7dbb8dc2194c602f32fdfb9fec747fbdf0d1ba54fa83b0ded3ebf87f854663fd8de0a19141020"
    );

    // An OpenSSL signature over the digest 0x42 * 64 verifies here.
    let sig_hex = include_str!("vectors/ml_dsa_87_openssl.sig.hex").trim();
    let sig = wire::Signature::from_hex(sig_hex).unwrap();
    let digest = Digest([0x42; DIGEST_LEN]);
    verify_ml_dsa_87(kp.public_key(), &digest, &sig).unwrap();
    // Twice: the second check uses the cached decoded key and must agree.
    verify_ml_dsa_87(kp.public_key(), &digest, &sig).unwrap();

    // Any other digest, key or corrupted signature fails.
    assert_eq!(
        verify_ml_dsa_87(kp.public_key(), &Digest([0x43; DIGEST_LEN]), &sig),
        Err(SignatureError::Invalid)
    );
    assert!(verify_ml_dsa_87(key(5).public_key(), &digest, &sig).is_err());
    let mut corrupted = sig.clone();
    corrupted.0[4_000] ^= 0x10;
    assert!(verify_ml_dsa_87(kp.public_key(), &digest, &corrupted).is_err());
    assert!(verify_ml_dsa_87(kp.public_key(), &digest, &unsigned()).is_err());
}

/// SLH-DSA-SHAKE-256s interoperates with an independent FIPS 205 implementation: the
/// co-signer's public key and key id come from a Python implementation written from the
/// standard (hashlib SHAKE256) for the key-generation seeds `40 41 .. 9f`. That
/// implementation also verified the signature below, made here over the digest
/// `0x42 * 64` with the context string `PLAU/TX`.
#[test]
fn slh_dsa_shake_256s_matches_an_independent_implementation() {
    let seed: [u8; 32] = core::array::from_fn(|i| i as u8);
    let cosigner_seed: [u8; 96] = core::array::from_fn(|i| (0x40 + i) as u8);
    let kp = TreasuryKeypair::from_seeds(&seed, &cosigner_seed);
    assert_eq!(
        kp.cosigner_public_key().to_hex(),
        "808182838485868788898a8b8c8d8e8f909192939495969798999a9b9c9d9e9fff5518a08ea546fa12f0ac3922529aa694901c54ca5d313db9ec8361ab422f91"
    );
    // H(PLAU/COSIGNER, pk), computed by Python hashlib.
    assert_eq!(
        kp.cosigner_key_id().to_hex(),
        "62883b16f4df7490bb3639f63f9c2e3744b59352caafcf56bf2920576b97ec3478c98510ca16bbdd09b34a090251f0526c8dd99d34406010ec168cab0db45be7"
    );

    let sig_hex = include_str!("vectors/slh_dsa_shake_256s.sig.hex").trim();
    let sig = wire::SlhDsaSignature::from_hex(sig_hex).unwrap();
    let digest = Digest([0x42; DIGEST_LEN]);
    let key = kp.cosigner_public_key();
    chain::verify_slh_dsa_shake_256s(key, &digest, &sig).unwrap();

    // Any other digest, key or corrupted signature fails.
    assert_eq!(
        chain::verify_slh_dsa_shake_256s(key, &Digest([0x43; DIGEST_LEN]), &sig),
        Err(SignatureError::CoSignatureInvalid)
    );
    assert!(
        chain::verify_slh_dsa_shake_256s(treasury().cosigner_public_key(), &digest, &sig).is_err()
    );
    let mut corrupted = sig.clone();
    corrupted.0[20_000] ^= 0x10;
    assert!(chain::verify_slh_dsa_shake_256s(key, &digest, &corrupted).is_err());
    assert!(chain::verify_slh_dsa_shake_256s(key, &digest, &unsigned_cosignature()).is_err());
}

/// Templates draw shares from the pool, whoever mined them: shares of several owners
/// are included oldest height first, capped at `max_shares_per_block`, and emitted
/// strictly sorted by `work_id`. The rest follow in the next block.
#[test]
fn templates_include_pool_shares_from_every_owner() {
    let mut g = fast_genesis();
    g.max_shares_per_block = 4;
    let mut tree = BlockTree::new(g).unwrap();
    let (miner, alice, bob) = (key(1), key(2), key(3));
    for h in 1..=3 {
        let blk = mine_block_on(&tree, tree.tip_id(), &miner, &[], &[], h);
        extend(&mut tree, blk);
    }

    // Six shares by two other owners, mined at heights 1..=3 on the canonical chain.
    let mut pool_proofs = Vec::new();
    for (owner, parent_h, nonce) in [
        (&alice, 0, 100),
        (&alice, 1, 101),
        (&bob, 1, 102),
        (&alice, 2, 103),
        (&bob, 2, 104),
        (&bob, 2, 105),
    ] {
        let parent = tree.canonical_id_at(parent_h).unwrap();
        pool_proofs.push(mine_share_on(&tree, parent, owner, nonce));
    }
    let mut expected = pool_proofs.clone();
    expected.sort_by_key(|sh| (sh.context.height, sh.work_id));
    expected.truncate(4);
    expected.sort_by_key(|sh| sh.work_id);

    let blk = mine_block_on(&tree, tree.tip_id(), &miner, &[], &pool_proofs, 4);
    assert_eq!(blk.body.shares, expected, "oldest four, sorted by work_id");
    assert!(
        blk.body
            .shares
            .windows(2)
            .all(|w| w[0].work_id < w[1].work_id)
    );
    extend(&mut tree, blk);
    let state = tree.tip_state();
    for sh in &expected {
        let owner = state.shares[&sh.work_id].owner.key_id();
        assert_eq!(owner, chain::owner_key_id(&sh.owner_key));
        assert_ne!(owner, miner.key_id(), "included by another node's miner");
    }

    // The two left out are included next, while still inside the window.
    let next = mine_block_on(&tree, tree.tip_id(), &miner, &[], &pool_proofs, 5);
    assert_eq!(next.body.shares.len(), 2);
    assert!(next.body.shares.iter().all(|sh| !expected.contains(sh)));
    extend(&mut tree, next);
    assert!(
        template_on(&tree, tree.tip_id(), &miner, &[], &pool_proofs)
            .body
            .shares
            .is_empty(),
        "registered shares are never included twice"
    );
}

/// `check_gossip_share`: honest shares (also from a side branch) go on to work
/// verification; malformed ones are Invalid (their sender is penalized); stale,
/// registered or unknown-parent shares are harmless.
#[test]
fn gossip_share_checks_sort_honest_stale_and_invalid_shares() {
    let mut g = fast_genesis();
    g.share_inclusion_window = 4;
    let mut tree = BlockTree::new(g).unwrap();
    let (miner, alice) = (key(1), key(2));
    for h in 1..=3 {
        let blk = mine_block_on(&tree, tree.tip_id(), &miner, &[], &[], h);
        extend(&mut tree, blk);
    }
    let tip = tree.tip_id();
    let honest = mine_share_on(&tree, tip, &alice, 7);
    assert_eq!(tree.check_gossip_share(&honest), ShareCheck::Verify);

    // An honest share mined on a side branch is checked on its own branch.
    let side_parent = mine_block_on(
        &tree,
        tree.canonical_id_at(2).unwrap(),
        &alice,
        &[],
        &[],
        50,
    );
    tree.pre_validate(&side_parent, None).unwrap();
    let side_id = side_parent.header.block_id;
    assert!(
        !tree
            .apply_verified_block(Arc::new(side_parent))
            .unwrap()
            .tip_changed
    );
    let side_share = mine_share_on(&tree, side_id, &alice, 8);
    assert_eq!(tree.check_gossip_share(&side_share), ShareCheck::Verify);

    let invalid = |sh: &ShareProof| matches!(tree.check_gossip_share(sh), ShareCheck::Invalid(_));
    let mut other_owner = honest.clone();
    key(9).sign_share(&mut other_owner).unwrap();
    assert!(invalid(&other_owner), "the work binds the owner's key id");
    let mut easy_target = honest.clone();
    easy_target.share_target = Target(u128::MAX - 1);
    alice.sign_share(&mut easy_target).unwrap();
    assert!(invalid(&easy_target));
    let mut bad_anchor = honest.clone();
    bad_anchor.context.stable_anchor_id = Digest([3; DIGEST_LEN]);
    assert!(invalid(&bad_anchor));
    let mut wrong_chain = honest.clone();
    wrong_chain.context.chain_id ^= 1;
    assert!(invalid(&wrong_chain));
    let mut wrong_height = honest.clone();
    wrong_height.context.height += 1;
    assert!(invalid(&wrong_height));

    let mut orphan = honest.clone();
    orphan.context.parent_canonical_id = Digest([4; DIGEST_LEN]);
    assert_eq!(
        tree.check_gossip_share(&orphan),
        ShareCheck::UnknownParent(Digest([4; DIGEST_LEN]))
    );

    // Registered once included (the height-4 share fits from block 5 on), stale once it
    // leaves the window (4 blocks).
    let b4 = mine_block_on(&tree, tip, &miner, &[], &[], 4);
    extend(&mut tree, b4);
    assert_eq!(tree.check_gossip_share(&honest), ShareCheck::Verify);
    let with_share = mine_block_on(
        &tree,
        tree.tip_id(),
        &miner,
        &[],
        std::slice::from_ref(&honest),
        5,
    );
    assert_eq!(with_share.body.shares.len(), 1);
    extend(&mut tree, with_share);
    assert!(matches!(
        tree.check_gossip_share(&honest),
        ShareCheck::Ignore(_)
    ));
    let old = mine_share_on(&tree, tree.canonical_id_at(0).unwrap(), &alice, 9);
    assert!(matches!(
        tree.check_gossip_share(&old),
        ShareCheck::Ignore(_)
    ));
}

/// The bytes a block needs for its header, `shares` shares, a full set of withdrawals
/// and the headroom.
fn full_block_bytes(shares: u64) -> u64 {
    shares * wire::ENCODED_SHARE_LEN as u64
        + wire::MAX_WITHDRAWALS_PER_BLOCK * wire::ENCODED_WITHDRAWAL_MAX_LEN as u64
        + wire::ENCODED_HEADER_LEN as u64
        + chain::core_adapter::BLOCK_HEADROOM
}

/// A genesis whose blocks could not hold a full set of shares and withdrawals is
/// rejected: every node picks the same gossiped shares, so such a template could never
/// be a valid block.
#[test]
fn genesis_must_fit_a_full_set_of_shares() {
    let mut g = fast_genesis();
    let need = full_block_bytes(g.max_shares_per_block);
    g.max_block_bytes = need;
    assert!(chain::validate_genesis(&g).is_ok());
    g.max_block_bytes = need - 1;
    assert!(chain::validate_genesis(&g).is_err());
    g.max_shares_per_block = u64::MAX;
    assert!(chain::validate_genesis(&g).is_err(), "no overflow");
}

/// At the smallest `max_block_bytes` that `validate_genesis` accepts, a block still
/// holds a full set of pooled shares.
#[test]
fn a_full_set_of_shares_fits_the_smallest_valid_block() {
    let mut g = fast_genesis();
    g.max_shares_per_block = 4;
    g.max_block_bytes = full_block_bytes(4);
    let mut tree = BlockTree::new(g).unwrap();
    let (miner, alice) = (key(1), key(2));
    for h in 1..=2 {
        let blk = mine_block_on(&tree, tree.tip_id(), &miner, &[], &[], h);
        extend(&mut tree, blk);
    }
    let shares: Vec<ShareProof> = (0..4)
        .map(|i| mine_share_on(&tree, tree.canonical_id_at(i % 2).unwrap(), &alice, 300 + i))
        .collect();
    let blk = mine_block_on(&tree, tree.tip_id(), &miner, &[], &shares, 3);
    assert_eq!(blk.body.shares.len(), 4, "no share was trimmed");
    let size = wire::codec::encode(&blk).unwrap().len() as u64;
    assert!(size <= tree.genesis().max_block_bytes);
    extend(&mut tree, blk);
}

#[test]
fn job_charge_and_ttl_boundaries_are_enforced_without_mutating_parent() {
    use chain::JobValidationError;
    let g = fast_genesis();
    let (state, genesis_id, _) = scheduler_state(&g);
    let mut tx = make_job(900, 1, 1, 1, 10 + wire::MAX_JOB_TTL, &genesis_id);
    tx.v_da = 0;
    tx.v_ref = 0;
    tx.v_exec = wire::MAX_TESTNET_JOB_CHARGE - 2;
    assert!(chain::validate_job_stateless(&tx).is_ok());
    tx.v_exec += 1;
    assert_eq!(
        chain::validate_job_stateless(&tx),
        Err(JobValidationError::ChargeExceedsTestnetLimit)
    );
    tx.v_exec = TOTAL_SUPPLY.get();
    assert_eq!(
        chain::validate_job_stateless(&tx),
        Err(JobValidationError::ChargeExceedsSupply)
    );
    tx.v_exec = u64::MAX;
    assert_eq!(
        chain::validate_job_stateless(&tx),
        Err(JobValidationError::AmountOverflow)
    );
    tx.v_exec = 1;
    assert!(apply_body(&state, &g, 10, &[tx.clone()], &[], &[]).is_ok());
    tx.expiry_height += 1;
    assert!(matches!(
        apply_body(&state, &g, 10, &[tx], &[], &[]),
        Err(StfError::JobExpiryTooFar)
    ));
    assert_eq!(state.height, 9);
    assert_eq!(state.ledger.balance(StateCategory::Escrow), Atoms::ZERO);
}

/// The per-block faucet is `U / 16` of the circulating supply alone (the pool, the
/// pending rewards and both unissued reserves are not spendable by jobs), fixed once
/// per block and debited cumulatively by every job in it.
#[test]
fn faucet_cap_is_cumulative_and_counts_only_circulating_supply() {
    let g = fast_genesis();
    let (state, genesis_id, _) = scheduler_state(&g);
    // h = 10 pays the epoch-1 booking into U; h = 11 is no boundary, so the budget is
    // fixed by U after h = 10.
    let (state, _) = apply_body(&state, &g, 10, &[], &[], &[]).unwrap();
    let u = state.ledger.balance(StateCategory::Circulating).get();
    assert!(u > 0);
    for other in [
        StateCategory::InitialProtocolPool,
        StateCategory::PendingRewards,
        StateCategory::UnissuedInitial,
        StateCategory::UnissuedMiners,
    ] {
        assert!(
            state.ledger.balance(other) > Atoms::ZERO,
            "{other:?} is not spendable"
        );
    }
    let budget = u / 16;
    let make = |nonce: u64, charge: u64| {
        let mut tx = make_job(nonce, 1, 1, charge - 2, 100, &genesis_id);
        tx.v_da = 0;
        tx.v_ref = 0;
        tx
    };
    let (accepted, _) = apply_body(&state, &g, 11, &[make(1, budget)], &[], &[]).unwrap();
    assert_eq!(
        accepted.ledger.balance(StateCategory::Circulating).get(),
        u - budget
    );
    assert!(matches!(
        apply_body(&state, &g, 11, &[make(2, budget + 1)], &[], &[]),
        Err(StfError::FaucetBudgetExceeded)
    ));
    let mut jobs = vec![make(3, budget / 2 + 1), make(4, budget - budget / 2)];
    jobs.sort_by_key(|tx| compute_job_ids(tx).unwrap().0);
    assert!(matches!(
        apply_body(&state, &g, 11, &jobs, &[], &[]),
        Err(StfError::FaucetBudgetExceeded)
    ));
    assert_eq!(state.ledger.total(), u128::from(TOTAL_SUPPLY.get()));
    assert_eq!(state.ledger.balance(StateCategory::Escrow), Atoms::ZERO);
}

#[test]
fn live_fee_lot_limit_counts_locked_lots_and_both_fees_of_new_jobs() {
    let g = fast_genesis();
    let (state, genesis_id, _) = scheduler_state(&g);
    let mut state = apply_body(&state, &g, 10, &[], &[], &[]).unwrap().0;
    // R_a holds no Genesis lot: only these locked fees and the new job's two count.
    assert!(state.ledger.fee_lots().is_empty());
    for i in 0..(wire::MAX_LIVE_FEE_LOTS - 2) {
        state
            .ledger
            .escrow_fund_and_queue(ledger::JobId(1_000_000 + i as u64), Atoms(1), Atoms(1))
            .unwrap();
    }
    let tx = make_job(9999, 1, 1, 1, 100, &genesis_id);
    let (accepted, _) = apply_body(&state, &g, 11, std::slice::from_ref(&tx), &[], &[]).unwrap();
    assert_eq!(
        accepted.ledger.fee_lots().len() + accepted.ledger.locked_fees().len(),
        wire::MAX_LIVE_FEE_LOTS
    );
    state
        .ledger
        .escrow_fund_and_queue(ledger::JobId(2_000_000), Atoms(1), Atoms(1))
        .unwrap();
    assert!(matches!(
        apply_body(&state, &g, 11, &[tx], &[], &[]),
        Err(StfError::FeeLotCapacity)
    ));
    state.ledger.check_invariants().unwrap();
}

// ---------------------------------------------------------------------------
// Primary issuance, InitialProtocolPool withdrawals and the generator schedule
// ---------------------------------------------------------------------------

/// Genesis leaves all of `M` unissued (spec eq. 7.19a) and every `apply_body` opens
/// with block `k`'s primary release (eqs. 7.19b–7.19g), before any other transition:
/// `R_I -> U_initial` linearly and `R_M -> P_pending` by exact Q64 decay.
#[test]
fn primary_issuance_opens_every_block() {
    let g = fast_genesis();
    let (_, ledger, _) = chain::validate_genesis(&g).unwrap();
    for c in StateCategory::ALL {
        let expected = match c {
            StateCategory::UnissuedInitial => INITIAL_ALLOCATION,
            StateCategory::UnissuedMiners => MINER_ALLOCATION,
            _ => Atoms::ZERO,
        };
        assert_eq!(ledger.balance(c), expected, "{c:?} at genesis");
    }
    assert!(ledger.fee_lots().is_empty(), "no Genesis fee lot in R_a");
    let genesis = chain::NodeState::genesis(ledger);

    // Block 1: i_1 = floor(I / N_I), m_1 = R_M - floor(R_M * a / 2^64).
    let (s1, d1) = apply_body(&genesis, &g, 1, &[], &[], &[]).unwrap();
    let FeeTransition::PrimaryRelease {
        block,
        initial,
        miner,
        delta,
    } = &d1.fee_transitions[0]
    else {
        panic!("the block must open with its primary release");
    };
    assert_eq!((*block, *initial, *miner), (1, 142_694_063, 890_171_600));
    let mut expected_delta = [0i128; StateCategory::COUNT];
    expected_delta[StateCategory::UnissuedInitial.index()] = -142_694_063;
    expected_delta[StateCategory::InitialProtocolPool.index()] = 142_694_063;
    expected_delta[StateCategory::UnissuedMiners.index()] = -890_171_600;
    expected_delta[StateCategory::PendingRewards.index()] = 890_171_600;
    assert_eq!(*delta, expected_delta);
    assert_eq!(d1.fee_transitions.len(), 1, "an empty non-boundary block");

    // Heights are consecutive: no block may skip or repeat a release.
    for (parent, h) in [(&genesis, 2), (&s1, 1), (&s1, 3)] {
        assert!(matches!(
            apply_body(parent, &g, h, &[], &[], &[]),
            Err(StfError::Ledger(ledger::LedgerError::HeightSequence { .. }))
        ));
    }

    // 720 blocks (one day): the cumulative releases match the closed forms, and the
    // supply never moves out of the ten categories.
    let mut state = s1;
    let mut released = (142_694_063u64, 890_171_600u64);
    for h in 2..=720 {
        let (next, derived) = apply_body(&state, &g, h, &[], &[], &[]).unwrap();
        let FeeTransition::PrimaryRelease {
            block,
            initial,
            miner,
            ..
        } = derived.fee_transitions[0]
        else {
            panic!("h = {h} must open with its primary release");
        };
        assert_eq!(block, h);
        released.0 += initial;
        released.1 += miner;
        state = next;
    }
    let l = &state.ledger;
    l.check_invariants().unwrap();
    assert_eq!(Atoms(released.0), initial_release_cumulative(720));
    assert_eq!(
        l.balance(StateCategory::InitialProtocolPool),
        Atoms(released.0)
    );
    assert_eq!(
        l.balance(StateCategory::UnissuedInitial).get(),
        INITIAL_ALLOCATION.get() - released.0
    );
    assert_eq!(
        l.balance(StateCategory::UnissuedMiners),
        Atoms(1_349_359_228_355_031),
        "R_M after 720 exact decay steps"
    );
    assert_eq!(released.1, MINER_ALLOCATION.get() - 1_349_359_228_355_031);
    // Without shares nothing is booked or paid: the release waits in P_pending.
    assert_eq!(l.balance(StateCategory::PendingRewards), Atoms(released.1));
    assert_eq!(l.balance(StateCategory::Circulating), Atoms::ZERO);
}

/// The test treasury: fixed seeds, so the key pair is reproducible.
fn treasury() -> &'static TreasuryKeypair {
    static TREASURY: OnceLock<TreasuryKeypair> = OnceLock::new();
    TREASURY.get_or_init(|| TreasuryKeypair::from_seeds(&[0x71; 32], &[0x72; 96]))
}

/// `fast_genesis` with the test treasury's key ids, so pool withdrawals are enabled.
fn treasury_genesis() -> (GenesisConfig, Digest) {
    let mut g = fast_genesis();
    g.treasury_key_id = treasury().key_id();
    g.treasury_cosigner_key_id = treasury().cosigner_key_id();
    let (_, _, genesis_id) = chain::validate_genesis(&g).unwrap();
    (g, genesis_id)
}

/// A withdrawal of `outputs` with fee `fee` and nonce `nonce`, signed by both treasury
/// keys for the treasury genesis.
fn signed_withdrawal(nonce: u64, outputs: &[(u8, u64)], fee: u64) -> InitialPoolWithdrawal {
    let mut w = InitialPoolWithdrawal {
        expected_nonce: nonce,
        outputs: outputs
            .iter()
            .map(|&(tag, atoms)| WithdrawalOutput {
                recipient: Digest([tag; DIGEST_LEN]),
                atoms,
            })
            .collect(),
        fee,
        ml_dsa_key: key(0).public_key().clone(),
        slh_dsa_key: wire::SlhDsaPublicKey(Box::new([0; wire::SLH_DSA_PUBLIC_KEY_LEN])),
        ml_dsa_signature: unsigned(),
        slh_dsa_signature: unsigned_cosignature(),
    };
    treasury()
        .sign_withdrawal(&mut w, &treasury_genesis().1)
        .unwrap();
    w
}

/// Nonce 0: 1.20 PLAU to two recipients plus a 0.01 PLAU fee, within block 1's release.
fn small_withdrawal() -> &'static InitialPoolWithdrawal {
    static W: OnceLock<InitialPoolWithdrawal> = OnceLock::new();
    W.get_or_init(|| signed_withdrawal(0, &[(0xa1, PLAU), (0xa2, PLAU / 5)], PLAU / 100))
}

/// Nonce 0: 29,990 PLAU plus a 0.01 PLAU fee, 9.99 PLAU short of the InitialValve.
fn large_withdrawal() -> &'static InitialPoolWithdrawal {
    static W: OnceLock<InitialPoolWithdrawal> = OnceLock::new();
    W.get_or_init(|| signed_withdrawal(0, &[(0xb1, 29_990 * PLAU)], PLAU / 100))
}

/// Nonce 1: 10 PLAU plus a 0.01 PLAU fee, more than the valve leaves after
/// `large_withdrawal`.
fn follow_up_withdrawal() -> &'static InitialPoolWithdrawal {
    static W: OnceLock<InitialPoolWithdrawal> = OnceLock::new();
    W.get_or_init(|| signed_withdrawal(1, &[(0xb2, 10 * PLAU)], PLAU / 100))
}

fn verified(w: &InitialPoolWithdrawal) -> VerifiedWithdrawal {
    let (g, genesis_id) = treasury_genesis();
    VerifiedWithdrawal::verify(w, &g, &genesis_id).unwrap()
}

/// Applies empty blocks until `state` is at height `h`.
fn advance_to(state: &mut chain::NodeState, g: &GenesisConfig, h: u64) {
    while state.height < h {
        *state = apply_body(state, g, state.height + 1, &[], &[], &[])
            .unwrap()
            .0;
    }
}

/// `InitialOK` (spec eq. 7.19j) in `apply_body`: the expected nonce, `U_initial >= v + f`,
/// and the rolling 720-block InitialValve `w_rolling + v + f <= L_I = I / 50`. The
/// valve binds once the pool holds more than `L_I`, after about 21,000 blocks.
#[test]
fn initial_pool_withdrawals_obey_nonce_pool_and_valve() {
    let (g, genesis_id) = treasury_genesis();
    let (_, ledger, _) = chain::validate_genesis(&g).unwrap();
    let mut state = chain::NodeState::genesis(ledger);
    let (large, next) = (
        verified(large_withdrawal()),
        verified(follow_up_withdrawal()),
    );
    let large_gross = large.amount() + large.fee();
    let next_gross = next.amount() + next.fee();
    assert_eq!(INITIAL_VALVE_LIMIT, Atoms(30_000 * PLAU));
    assert!(INITIAL_VALVE_LIMIT.get() - large_gross < next_gross);

    // Framing: nonce order and the per-block count.
    assert!(matches!(
        apply_body(&state, &g, 1, &[], &[], &[next.clone(), large.clone()]),
        Err(StfError::WithdrawalsNotSorted)
    ));
    let three = vec![large.clone(); 3];
    assert!(matches!(
        apply_body(&state, &g, 1, &[], &[], &three),
        Err(StfError::TooManyWithdrawals(3))
    ));
    assert_eq!(
        apply_body(&state, &g, 1, &[], &[], std::slice::from_ref(&next)).unwrap_err(),
        StfError::InitialNonce {
            expected: 0,
            found: 1
        }
    );

    // The pool covers v + f from the first block k with sum_{t<=k} i_t >= v + f.
    let k_pool = (1..)
        .find(|&k| initial_release_cumulative(k).get() >= large_gross)
        .unwrap();
    assert!(
        k_pool > INITIAL_VALVE_WINDOW,
        "the valve binds only on a full pool"
    );
    advance_to(&mut state, &g, k_pool - 2);
    assert_eq!(
        apply_body(
            &state,
            &g,
            k_pool - 1,
            &[],
            &[],
            std::slice::from_ref(&large)
        )
        .unwrap_err(),
        StfError::InsufficientInitialPool {
            available: initial_release_cumulative(k_pool - 1).get(),
            requested: large_gross,
        }
    );
    advance_to(&mut state, &g, k_pool - 1);
    let u_before = state.ledger.balance(StateCategory::Circulating);
    let rl_before = state.ledger.balance(StateCategory::LockedBaseFees);
    let (after, derived) =
        apply_body(&state, &g, k_pool, &[], &[], std::slice::from_ref(&large)).unwrap();
    let l = &after.ledger;
    l.check_invariants().unwrap();
    assert_eq!(
        l.balance(StateCategory::Circulating).get(),
        u_before.get() + 29_990 * PLAU
    );
    assert_eq!(
        l.balance(StateCategory::LockedBaseFees).get(),
        rl_before.get() + PLAU / 100,
        "the pool-funded fee is a locked fee"
    );
    assert_eq!(
        l.balance(StateCategory::InitialProtocolPool).get(),
        initial_release_cumulative(k_pool).get() - large_gross
    );
    assert_eq!(l.initial_nonce(), 1);
    assert_eq!(l.initial_valve().rolling_outflow(), Atoms(large_gross));
    assert!(matches!(
        derived.fee_transitions.last(),
        Some(FeeTransition::InitialPoolWithdrawal { tx_id, nonce: 0, amount, fee, valve_rolling, .. })
            if *tx_id == large.tx_id() && *amount == 29_990 * PLAU
                && *fee == PLAU / 100 && *valve_rolling == large_gross
    ));
    state = after;

    // A replay carries a spent nonce.
    assert_eq!(
        apply_body(
            &state,
            &g,
            k_pool + 1,
            &[],
            &[],
            std::slice::from_ref(&large)
        )
        .unwrap_err(),
        StfError::InitialNonce {
            expected: 1,
            found: 0
        }
    );
    // Once the releases have refilled the pool, the valve alone rejects the follow-up.
    let k_refill = (k_pool..)
        .find(|&k| initial_release_cumulative(k).get() - large_gross >= next_gross)
        .unwrap();
    let valve_rejects = |state: &chain::NodeState| {
        apply_body(
            state,
            &g,
            state.height + 1,
            &[],
            &[],
            std::slice::from_ref(&next),
        )
    };
    advance_to(&mut state, &g, k_refill - 1);
    assert_eq!(
        valve_rejects(&state).unwrap_err(),
        StfError::InitialValveExceeded {
            rolling: large_gross,
            requested: next_gross,
        }
    );

    // Block k_pool leaves the window at block k_pool + 720.
    advance_to(&mut state, &g, k_pool + INITIAL_VALVE_WINDOW - 2);
    assert!(matches!(
        valve_rejects(&state),
        Err(StfError::InitialValveExceeded { .. })
    ));
    advance_to(&mut state, &g, k_pool + INITIAL_VALVE_WINDOW - 1);
    let (after, _) = valve_rejects(&state).unwrap();
    assert_eq!(
        after.ledger.initial_valve().rolling_outflow(),
        Atoms(next_gross)
    );
    assert_eq!(after.ledger.initial_nonce(), 2);
    after.ledger.check_invariants().unwrap();

    // The withdrawal binds the chain: the same bytes do not verify for another genesis.
    assert!(matches!(
        VerifiedWithdrawal::verify(large_withdrawal(), &g, &Digest([0xee; DIGEST_LEN])),
        Err(WithdrawalError::Signature(SignatureError::Invalid))
    ));
    assert_ne!(genesis_id, Digest([0xee; DIGEST_LEN]));
}

/// `Accept_treasury` (spec eq. 2.5): both signatures must verify under the genesis
/// treasury key ids; a disjunction is not admitted.
#[test]
fn withdrawals_need_both_treasury_signatures_under_the_genesis_keys() {
    let (g, genesis_id) = treasury_genesis();
    let w = small_withdrawal();
    VerifiedWithdrawal::verify(w, &g, &genesis_id).unwrap();

    let mut bad_cosig = w.clone();
    bad_cosig.slh_dsa_signature.0[1_000] ^= 0x01;
    assert_eq!(
        VerifiedWithdrawal::verify(&bad_cosig, &g, &genesis_id),
        Err(WithdrawalError::Signature(
            SignatureError::CoSignatureInvalid
        ))
    );
    let mut bad_sig = w.clone();
    bad_sig.ml_dsa_signature.0[1_000] ^= 0x01;
    assert_eq!(
        VerifiedWithdrawal::verify(&bad_sig, &g, &genesis_id),
        Err(WithdrawalError::Signature(SignatureError::Invalid))
    );
    let mut more = w.clone();
    more.outputs[0].atoms += 1;
    assert!(
        VerifiedWithdrawal::verify(&more, &g, &genesis_id).is_err(),
        "the signatures cover every output"
    );

    // Keys that are not the genesis treasury keys never reach signature checks.
    let disabled = fast_genesis();
    assert_eq!(disabled.treasury_key_id, Digest::ZERO, "default genesis");
    assert_eq!(
        chain::validate_withdrawal_stateless(w, &disabled),
        Err(WithdrawalError::PolicyMismatch("ML-DSA-87"))
    );
    let mut other_cosigner = g.clone();
    other_cosigner.treasury_cosigner_key_id = Digest([0x55; DIGEST_LEN]);
    assert_eq!(
        chain::validate_withdrawal_stateless(w, &other_cosigner),
        Err(WithdrawalError::PolicyMismatch("SLH-DSA-SHAKE-256s"))
    );

    // Stateless shape checks.
    let mut none = w.clone();
    none.outputs.clear();
    assert_eq!(
        chain::validate_withdrawal_stateless(&none, &g),
        Err(WithdrawalError::NoOutputs)
    );
    let mut zero = w.clone();
    zero.outputs[1].atoms = 0;
    assert_eq!(
        chain::validate_withdrawal_stateless(&zero, &g),
        Err(WithdrawalError::ZeroOutput)
    );
    let mut many = w.clone();
    many.outputs = vec![many.outputs[0].clone(); wire::MAX_WITHDRAWAL_OUTPUTS + 1];
    assert!(matches!(
        chain::validate_withdrawal_stateless(&many, &g),
        Err(WithdrawalError::TooManyOutputs(_))
    ));
    let mut huge = w.clone();
    huge.outputs[0].atoms = u64::MAX;
    assert_eq!(
        chain::validate_withdrawal_stateless(&huge, &g),
        Err(WithdrawalError::AmountOverflow)
    );
    huge.outputs = vec![huge.outputs[1].clone()];
    huge.outputs[0].atoms = TOTAL_SUPPLY.get();
    assert_eq!(
        chain::validate_withdrawal_stateless(&huge, &g),
        Err(WithdrawalError::ExceedsSupply)
    );

    // The TxID covers everything but the signatures.
    let mut stripped = w.clone();
    stripped.ml_dsa_signature = unsigned();
    stripped.slh_dsa_signature = unsigned_cosignature();
    assert_eq!(
        chain::compute_withdrawal_id(&stripped).unwrap(),
        chain::compute_withdrawal_id(w).unwrap()
    );
    assert_ne!(
        chain::compute_withdrawal_id(&more).unwrap(),
        chain::compute_withdrawal_id(w).unwrap()
    );
}

/// A dual-signed withdrawal travels from the pool through the template into a block:
/// Stage B checks its framing and treasury policy, Stage A both signatures, and the
/// STF pays `U` from the pool. A spent nonce is never included again.
#[test]
fn withdrawals_ride_templates_and_are_checked_in_both_stages() {
    let (g, genesis_id) = treasury_genesis();
    let mut tree = BlockTree::new(g.clone()).unwrap();
    assert_eq!(tree.genesis_id(), genesis_id);
    let miner = key(1);
    let pool = vec![SignedWithdrawal::verify(small_withdrawal().clone(), &g, &genesis_id).unwrap()];

    let honest = mine_block_with_withdrawals(&tree, &miner, &pool, 1);
    assert_eq!(honest.body.withdrawals, vec![small_withdrawal().clone()]);
    assert!(matches!(
        honest.body.fee_transitions.last(),
        Some(FeeTransition::InitialPoolWithdrawal { nonce: 0, .. })
    ));
    BlockTree::verify_signatures(&honest).unwrap();

    // Stage A: a forged co-signature or signature in an otherwise valid, re-sealed block.
    let mut forged_cosig = honest.clone();
    forged_cosig.body.withdrawals[0].slh_dsa_signature.0[42] ^= 0x01;
    reseal(&mut forged_cosig, &miner);
    tree.pre_validate(&forged_cosig, None).unwrap();
    assert!(matches!(
        BlockTree::verify_stage_a(&forged_cosig),
        Err(WorkError::Signature(
            "withdrawal",
            SignatureError::CoSignatureInvalid
        ))
    ));
    assert!(tree.apply_verified_block(Arc::new(forged_cosig)).is_err());
    let mut forged_sig = honest.clone();
    forged_sig.body.withdrawals[0].ml_dsa_signature.0[42] ^= 0x01;
    reseal(&mut forged_sig, &miner);
    assert!(matches!(
        BlockTree::verify_stage_a(&forged_sig),
        Err(WorkError::Signature("withdrawal", SignatureError::Invalid))
    ));

    // Stage B: a non-treasury co-signing key, and a repeated nonce.
    let mut foreign_key = honest.clone();
    foreign_key.body.withdrawals[0].slh_dsa_key.0[0] ^= 0x01;
    reseal(&mut foreign_key, &miner);
    assert!(matches!(
        tree.pre_validate(&foreign_key, None),
        Err(TreeError::Invalid(reason)) if reason.contains("SLH-DSA-SHAKE-256s")
    ));
    let mut repeated = honest.clone();
    repeated.body.withdrawals.push(small_withdrawal().clone());
    reseal(&mut repeated, &miner);
    assert!(matches!(
        tree.pre_validate(&repeated, None),
        Err(TreeError::Invalid(reason)) if reason.contains("sorted")
    ));

    extend(&mut tree, honest);
    let ledger = &tree.tip_state().ledger;
    assert_eq!(ledger.initial_nonce(), 1);
    assert_eq!(
        ledger.balance(StateCategory::Circulating),
        Atoms(PLAU + PLAU / 5),
        "U held nothing before the withdrawal"
    );
    assert_eq!(
        ledger.balance(StateCategory::InitialProtocolPool).get(),
        initial_release_cumulative(1).get() - (PLAU + PLAU / 5 + PLAU / 100)
    );
    let next = mine_block_with_withdrawals(&tree, &miner, &pool, 2);
    assert!(next.body.withdrawals.is_empty(), "nonce 0 is spent");
    extend(&mut tree, next);
}

/// Fresh Work follows `profile = (height - 1) mod 3` with no fallback (spec eq. 5.3):
/// headers carry the scheduled generator id, and a block whose work was computed
/// under another profile, or an unknown generator id, is rejected.
#[test]
fn fresh_work_follows_the_modulo_three_generator_schedule() {
    let g = fast_genesis();
    let mut tree = BlockTree::new(g).unwrap();
    let miner = key(1);
    for h in 1..=6u64 {
        let blk = mine_block_on(&tree, tree.tip_id(), &miner, &[], &[], h);
        let profile = GeneratorProfile::ALL[((h - 1) % 3) as usize];
        assert_eq!(
            blk.header.context.generator_id,
            u64::from(profile.generator_id())
        );
        assert_eq!(blk.header.context.generator_id, scheduled_generator_id(h));
        extend(&mut tree, blk);
    }

    // Height 7 is profile 0 (outlier fuzzing). Valid work under profile 1 is still
    // rejected: the generator id is a consensus field of the context.
    let honest = mine_block_on(&tree, tree.tip_id(), &miner, &[], &[], 7);
    let mut other_profile = honest.clone();
    other_profile.header.context.generator_id =
        u64::from(GeneratorProfile::ArithmeticGraph.generator_id());
    reseal(&mut other_profile, &miner);
    BlockTree::verify_stage_a(&other_profile).unwrap();
    assert!(matches!(
        tree.pre_validate(&other_profile, None),
        Err(TreeError::Invalid(reason)) if reason.contains("generator_id")
    ));

    // There is no fourth generator.
    let unknown = u64::from(work::GENERATOR_ID_BASE) + 3;
    let mut fourth = honest.clone();
    fourth.header.context.generator_id = unknown;
    miner.sign_header(&mut fourth.header).unwrap();
    assert!(tree.pre_validate(&fourth, None).is_err());
    assert_eq!(
        BlockTree::verify_stage_a(&fourth),
        Err(WorkError::UnknownGenerator(unknown))
    );
    extend(&mut tree, honest);
}
