//! CLI definition (`node::cli`, §1.2, §10).

use std::net::SocketAddr;
use std::path::PathBuf;
use std::str::FromStr;

use clap::{Args, Parser, Subcommand, ValueEnum};
use wire::Digest;

use crate::net::PeerAddr;

const KNOWN_GAPS_HELP: &str = "\
KNOWN TESTNET GAPS (blueprint §1.2; gaps 1, 2 and 4 are closed in this testnet):
  3. VerifyFW by recomputation: validators recompute 512x512 INT8 tiles (no Circle STARK, no P-DAL).
  5. Commercial execution is replicated: every validator recomputes Ozaki-II dot products (consensus weight 0).
  6. No refunds or timeouts: every admitted job settles deterministically after settle_delay blocks.
  7. Primary issuance (N_I = H_M = 1,051,200 blocks) and the 720-block InitialValve count blocks,
     which the specification times at 120 seconds; at a shorter target block time they pass sooner.
  8. Canonical block history remains in memory; expired side branches and exhausted fee lots are pruned.
  Note: Circulating (U) is a shared testnet faucet. The core ledger has no per-account balances, so a
  job's ML-DSA-87 signature authenticates its client, but the deposit is debited from the aggregate U,
  and an InitialProtocolPool withdrawal's outputs are credited to it. Jobs are capped at 100 PLAU and
  120 blocks of remaining lifetime. Each block may debit at most one sixteenth of U, and active plus
  locked fee lots are capped at 16384.

IMPLEMENTED:
  1. Hashing is SHA3-512 and SHAKE256 (FIPS 202).
  2. Owners are ML-DSA-87 keys (FIPS 204) that sign every block header, share proof and job.
  4. Shares are gossiped (GossipShare): verified shares from every node enter each miner's blocks.
  Ledger: 10 transparent categories; all of M = 15,000,000 PLAU starts unissued (R_I 10%, R_M 90%)
  and every block opens with its primary release. Fresh Work follows the modulo-3 schedule of
  diagnostic generators. InitialProtocolPool withdrawals need the treasury's ML-DSA-87 signature
  and SLH-DSA-SHAKE-256s co-signature and stay within 30,000 PLAU per 720 blocks.";

/// Plauthium multi-node P2P testnet daemon.
#[derive(Debug, Parser)]
#[command(name = "plauthium-node", about, after_help = KNOWN_GAPS_HELP)]
pub struct Cli {
    /// Subcommand to run.
    #[command(subcommand)]
    pub command: Command,
}

/// `plauthium-node` subcommands.
#[derive(Debug, Subcommand)]
pub enum Command {
    /// Generate a consensus genesis JSON file.
    Genesis(GenesisArgs),
    /// Run a Plauthium Public Testnet node.
    Run(RunArgs),
    /// Create the miner key if it does not exist yet, then print its identity.
    Key(KeyArgs),
    /// Treasury key pair of the InitialProtocolPool and offline withdrawal signing.
    #[command(subcommand)]
    Treasury(TreasuryCommand),
}

/// `plauthium-node treasury` subcommands.
#[derive(Debug, Subcommand)]
pub enum TreasuryCommand {
    /// Generate a treasury key pair (ML-DSA-87 signer and SLH-DSA-SHAKE-256s co-signer)
    /// and print the two key ids a genesis needs.
    Keygen(TreasuryKeyArgs),
    /// Print the key ids of a treasury key file.
    Show(TreasuryKeyArgs),
    /// Sign an InitialProtocolPool withdrawal with both treasury keys. Prints the hex
    /// encoding to POST to /api/submit_withdrawal as {"withdrawal": "<hex>"}.
    Withdraw(WithdrawArgs),
}

/// A treasury key file.
#[derive(Clone, Debug, Args)]
pub struct TreasuryKeyArgs {
    /// Treasury key file (keep it offline; nodes never need it).
    #[arg(long, default_value = "treasury_key.bin")]
    pub key_file: PathBuf,
}

/// Arguments of `plauthium-node treasury withdraw`.
#[derive(Clone, Debug, Args)]
pub struct WithdrawArgs {
    /// Treasury key file.
    #[arg(long, default_value = "treasury_key.bin")]
    pub key_file: PathBuf,
    /// Genesis file of the chain (default: the embedded testnet genesis).
    #[arg(long)]
    pub genesis: Option<PathBuf>,
    /// The withdrawal's expected InitialNonce: `ledger.initial_pool.next_nonce` of
    /// /api/status, plus one per withdrawal signed but not yet included.
    #[arg(long)]
    pub nonce: u64,
    /// A public output as RECIPIENT:ATOMS, RECIPIENT being a 128-hex-digit key id
    /// (as `plauthium-node key` prints it). Repeat for up to 16 outputs.
    #[arg(long = "output", required = true)]
    pub outputs: Vec<OutputArg>,
    /// Fee in atoms, paid from the pool into R_l.
    #[arg(long, default_value_t = 1_000_000)]
    pub fee: u64,
    /// Write the hex encoding to this file instead of standard output.
    #[arg(long)]
    pub out: Option<PathBuf>,
}

/// `RECIPIENT:ATOMS` of `treasury withdraw --output`.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct OutputArg {
    /// Recipient key id.
    pub recipient: Digest,
    /// Amount in atoms.
    pub atoms: u64,
}

impl FromStr for OutputArg {
    type Err = String;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let (recipient, atoms) = s.split_once(':').ok_or("expected RECIPIENT:ATOMS")?;
        Ok(Self {
            recipient: Digest::from_hex(recipient)?,
            atoms: atoms
                .parse()
                .map_err(|_| format!("{atoms:?} is not an amount in atoms"))?,
        })
    }
}

/// Difficulty adjustment mode for `genesis`.
#[derive(Clone, Copy, Debug, ValueEnum)]
pub enum DifficultyArg {
    /// Retarget every `--retarget-window` blocks towards `--target-block-secs`.
    Windowed,
    /// Keep the initial seal target forever.
    Fixed,
}

/// Arguments of `plauthium-node genesis`.
#[derive(Clone, Debug, Args)]
pub struct GenesisArgs {
    /// Output file path.
    #[arg(long, default_value = "genesis.json")]
    pub out: PathBuf,
    /// Chain human-readable name.
    #[arg(long, default_value = "Plauthium Public Testnet")]
    pub name: String,
    /// Expected Fresh Work attempts per block seal.
    #[arg(long, default_value_t = 32)]
    pub seal_attempts: u64,
    /// Share target multiplier ratio (Θ_S / Θ_B).
    #[arg(long, default_value_t = 4)]
    pub share_ratio: u64,
    /// Difficulty adjustment mode.
    #[arg(long, value_enum, default_value_t = DifficultyArg::Windowed)]
    pub difficulty: DifficultyArg,
    /// Window size in blocks when difficulty is windowed.
    #[arg(long, default_value_t = 32)]
    pub retarget_window: u64,
    /// Target block interval in seconds.
    #[arg(long, default_value_t = 10)]
    pub target_block_secs: u64,
    /// Number of blocks per reward epoch.
    #[arg(long, default_value_t = 30)]
    pub blocks_per_epoch: u64,
    /// Number of blocks after admission when a commercial job settles.
    #[arg(long, default_value_t = 2)]
    pub settle_delay: u64,
    /// Treasury ML-DSA-87 key id (`plauthium-node treasury keygen`). Without the two
    /// treasury key ids the InitialProtocolPool cannot be withdrawn from.
    #[arg(long, value_parser = Digest::from_hex, requires = "treasury_cosigner_key_id")]
    pub treasury_key_id: Option<Digest>,
    /// Treasury SLH-DSA-SHAKE-256s co-signer key id.
    #[arg(long, value_parser = Digest::from_hex, requires = "treasury_key_id")]
    pub treasury_cosigner_key_id: Option<Digest>,
}

/// Arguments of `plauthium-node key`.
#[derive(Clone, Debug, Args)]
pub struct KeyArgs {
    /// Node data directory (holds the miner key by default).
    #[arg(long)]
    pub data_dir: PathBuf,
    /// ML-DSA-87 miner key file (default: <DATA_DIR>/miner_key.bin).
    #[arg(long)]
    pub key_file: Option<PathBuf>,
}

/// Arguments of `plauthium-node run`.
#[derive(Clone, Debug, Args)]
pub struct RunArgs {
    /// Node data directory (stores blocks.log and, by default, the miner key).
    #[arg(long)]
    pub data_dir: PathBuf,
    /// ML-DSA-87 miner key file (default: <DATA_DIR>/miner_key.bin). Created with a fresh
    /// key on the first run and loaded on every later run; its key signs this node's
    /// blocks, shares and RPC-submitted jobs.
    #[arg(long)]
    pub key_file: Option<PathBuf>,
    /// Optional path to a custom genesis.json file (default: embedded testnet genesis).
    #[arg(long)]
    pub genesis: Option<PathBuf>,
    /// TCP listen address for the P2P protocol.
    #[arg(long, default_value = "0.0.0.0:30333")]
    pub p2p_listen: SocketAddr,
    /// HTTP listen address for the JSON RPC and web explorer.
    #[arg(long, default_value = "127.0.0.1:8080")]
    pub rpc_listen: SocketAddr,
    /// Static peer, as IP:port or host:port (may be passed multiple times). Host names
    /// are resolved again before every connection attempt.
    #[arg(long = "peer")]
    pub peers: Vec<PeerAddr>,
    /// Number of OS threads for Fresh Work tile mining.
    #[arg(long, default_value_t = 1)]
    pub mining_threads: usize,
    /// Disable block mining on this node.
    #[arg(long, default_value_t = false)]
    pub no_mine: bool,
    /// Start mining only once connected to a peer and caught up with the best height
    /// peers report (or once the tip has not moved for a minute while connected), and
    /// pause again whenever no peer is connected, so a node that cannot reach the
    /// network does not mine a private fork.
    #[arg(long, default_value_t = false)]
    pub mine_when_synced: bool,
    /// Number of concurrent Stage A verification tasks (default: CPUs / 2). Gossiped
    /// shares get half as many again (at least one) for their work checks.
    #[arg(long)]
    pub verify_threads: Option<usize>,
    /// Delete the chain data in the data directory before starting. The miner key file
    /// is kept, so the node keeps its identity.
    #[arg(long, default_value_t = false)]
    pub reset: bool,
}
