cat << 'EOF' > node/src/engine.rs
//! ConsensusEngine: multi-threaded Fresh Work miner (`node::engine`, §8.5).

use std::sync::Arc;
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::time::{Duration, Instant};

/// How long a miner waits after a seal for the template built on its block.
const SEAL_HANDOFF: Duration = Duration::from_secs(2);

use chain::core_adapter::{fw_context_to_core, hash_to_digest};
use chain::{Template, top128};
use tokio::sync::{mpsc, watch};
use tracing::error;
use work::{DEFAULT_FREIVALDS_ROUNDS, FreshWorkIds, verify_freivalds_rounds};

use crate::chain_actor::ChainCmd;

/// Mining statistics and runtime controls of the `ConsensusEngine` (§8.5).
pub struct ConsensusEngine {
    threads: usize,
    enabled: AtomicBool,
    /// Closed while `--mine-when-synced` waits for peers and sync; miners run only while
    /// both `enabled` and this hold.
    sync_gate: AtomicBool,
    shutdown: AtomicBool,
    attempts: AtomicU64,
    shares_found: AtomicU64,
    seals_found: AtomicU64,
    rate_bits: AtomicU64, // f64::to_bits of the EWMA attempts/sec
}

impl ConsensusEngine {
    /// Spawns `threads` OS miner threads and the EWMA rate task (§8.5). With
    /// `gated`, the miners wait until [`Self::set_sync_gate`] opens the sync gate.
    pub fn spawn(
        threads: usize,
        initially_enabled: bool,
        gated: bool,
        templates: watch::Receiver<Option<Arc<Template>>>,
        chain_tx: mpsc::Sender<ChainCmd>,
    ) -> std::io::Result<Arc<Self>> {
        let engine = Arc::new(Self {
            threads,
            enabled: AtomicBool::new(initially_enabled && threads > 0),
            sync_gate: AtomicBool::new(!gated),
            shutdown: AtomicBool::new(false),
            attempts: AtomicU64::new(0),
            shares_found: AtomicU64::new(0),
            seals_found: AtomicU64::new(0),
            rate_bits: AtomicU64::new(0.0f64.to_bits()),
        });

        for i in 0..threads {
            let eng = engine.clone();
            let tpl_rx = templates.clone();
            let tx = chain_tx.clone();
            std::thread::Builder::new()
                .name(format!("plau-miner-{i}"))
                .spawn(move || miner_thread_loop(i, threads, &eng, &tpl_rx, &tx))?;
        }

        // EWMA of attempts per second with a 10 s time constant.
        let eng_rate = engine.clone();
        tokio::spawn(async move {
            let mut prev_attempts = eng_rate.attempts.load(Ordering::Relaxed);
            let mut ewma = 0.0f64;
            let alpha = 1.0 - (-1.0f64 / 10.0).exp();
            let mut interval = tokio::time::interval(Duration::from_secs(1));
            loop {
                interval.tick().await;
                if eng_rate.shutdown.load(Ordering::Relaxed) {
                    break;
                }
                let cur = eng_rate.attempts.load(Ordering::Relaxed);
                let delta = cur.saturating_sub(prev_attempts) as f64;
                prev_attempts = cur;
                ewma = if ewma == 0.0 {
                    delta
                } else {
                    alpha * delta + (1.0 - alpha) * ewma
                };
                eng_rate.rate_bits.store(ewma.to_bits(), Ordering::Relaxed);
            }
        });

        Ok(engine)
    }

    /// Enables or pauses mining on every worker thread (§8.5).
    pub fn set_enabled(&self, enabled: bool) {
        if self.threads > 0 {
            self.enabled.store(enabled, Ordering::Relaxed);
        }
    }

    /// Whether mining is enabled (it may still wait for the sync gate).
    pub fn is_enabled(&self) -> bool {
        self.enabled.load(Ordering::Relaxed)
    }

    /// Opens or closes the sync gate (`--mine-when-synced`).
    pub fn set_sync_gate(&self, open: bool) {
        self.sync_gate.store(open, Ordering::Relaxed);
    }

    /// Whether the sync gate lets the miners run.
    pub fn sync_gate_open(&self) -> bool {
        self.sync_gate.load(Ordering::Relaxed)
    }

    /// Number of miner threads.
    pub fn threads(&self) -> usize {
        self.threads
    }

    /// EWMA of attempts per second.
    pub fn attempts_per_sec(&self) -> f64 {
        f64::from_bits(self.rate_bits.load(Ordering::Relaxed))
    }

    /// Total attempts evaluated.
    pub fn attempts(&self) -> u64 {
        self.attempts.load(Ordering::Relaxed)
    }

    /// Shares found.
    pub fn shares_found(&self) -> u64 {
        self.shares_found.load(Ordering::Relaxed)
    }

    /// Seals found.
    pub fn seals_found(&self) -> u64 {
        self.seals_found.load(Ordering::Relaxed)
    }

    /// Stops every miner thread for good.
    pub fn shutdown(&self) {
        self.shutdown.store(true, Ordering::Relaxed);
        self.enabled.store(false, Ordering::Relaxed);
    }
}

fn miner_thread_loop(
    thread_idx: usize,
    num_threads: usize,
    engine: &ConsensusEngine,
    templates: &watch::Receiver<Option<Arc<Template>>>,
    chain_tx: &mpsc::Sender<ChainCmd>,
) {
    let stride = num_threads.max(1) as u64;
    let mut generation = None;
    let mut nonce = thread_idx as u64;
    let mut sealed_at: Option<Instant> = None;
    while !engine.shutdown.load(Ordering::Relaxed) {
        if !engine.enabled.load(Ordering::Relaxed) || !engine.sync_gate.load(Ordering::Relaxed) {
            std::thread::sleep(Duration::from_millis(100));
            continue;
        }
        let Some(tpl) = templates.borrow().clone() else {
            std::thread::sleep(Duration::from_millis(200));
            continue;
        };
        if generation != Some(tpl.generation) {
            generation = Some(tpl.generation);
            nonce = thread_idx as u64;
            sealed_at = None;
        }
        // After a seal, give the ChainState actor time to publish the template built on
        // top of it; if the block did not become the tip, keep mining this template.
        if sealed_at.is_some_and(|t| t.elapsed() < SEAL_HANDOFF) {
            std::thread::sleep(Duration::from_millis(50));
            continue;
        }

        let Ok(ctx) = fw_context_to_core(&tpl.context_with_nonce(nonce)) else {
            error!("Template context does not fit the core types");
            std::thread::sleep(Duration::from_millis(200));
            continue;
        };
        let inst = match ctx.instance() {
            Ok(inst) => inst,
            Err(e) => {
                error!(error = %e, "Template names no scheduled generator");
                std::thread::sleep(Duration::from_millis(200));
                continue;
            }
        };
        let z = inst.x.product(&inst.y);
        let ids = FreshWorkIds::derive(&ctx, &z);
        engine.attempts.fetch_add(1, Ordering::Relaxed);

        let seal = top128(&hash_to_digest(&ids.seal_ticket)) < tpl.seal_target.0;
        let share = top128(&hash_to_digest(&ids.share_ticket)) < tpl.share_target.0;
        if (seal || share)
            && !verify_freivalds_rounds(&inst.x, &inst.y, &z, DEFAULT_FREIVALDS_ROUNDS)
        {
            error!("Freivalds self-check failed: engine or hardware fault");
        } else if seal {
            // The header share rule (§6.7) covers a sealing attempt; no ShareProof.
            engine.seals_found.fetch_add(1, Ordering::Relaxed);
            match tpl.seal(nonce, &ids) {
                Ok(block) => {
                    let _ = chain_tx.blocking_send(ChainCmd::SubmitLocalBlock(Box::new(block)));
                }
                Err(e) => error!(error = %e, "Could not sign a sealed block"),
            }
            sealed_at = Some(Instant::now());
        } else if share {
            engine.shares_found.fetch_add(1, Ordering::Relaxed);
            match tpl.share(nonce, &ids) {
                Ok(proof) => {
                    let _ = chain_tx.blocking_send(ChainCmd::SubmitLocalShare(Box::new(proof)));
                }
                Err(e) => error!(error = %e, "Could not sign a share proof"),
            }
        }
        nonce = nonce.wrapping_add(stride);
    }
}
EOF

cat << 'EOF' > node/src/keystore.rs
//! Persistent ML-DSA-87 miner key and treasury key pair (`node::keystore`).
//!
//! The miner key file holds only the 32-byte FIPS 204 seed behind a magic:
//! `PLAU/MLDSA87\n || seed`. The treasury key file holds the ML-DSA-87 seed and the
//! 96-byte SLH-DSA-SHAKE-256s seeds: `PLAU/TREASURY\n || seed || cosigner seeds`.
//! Key pairs are re-derived from the seeds on load.

use std::io::Write;
use std::path::{Path, PathBuf};

use chain::keys::{COSIGNER_SEED_LEN, SEED_LEN};
use chain::{OwnerKeypair, TreasuryKeypair};

use crate::NodeError;

/// Default key file name inside `--data-dir`.
pub const KEY_FILE_NAME: &str = "miner_key.bin";

/// Lock file a running node holds in its data directory.
pub const LOCK_FILE_NAME: &str = "LOCK";

/// header of the key file.
const KEY_FILE_MAGIC: &[u8; 13] = b"PLAU/MLDSA87\n";

/// Total key file length: magic plus seed.
#[cfg(test)]
const KEY_FILE_LEN: usize = KEY_FILE_MAGIC.len() + SEED_LEN;

/// Header of the treasury key file.
const TREASURY_FILE_MAGIC: &[u8; 14] = b"PLAU/TREASURY\n";

/// Total treasury key file length: magic plus both seeds.
const TREASURY_FILE_LEN: usize = TREASURY_FILE_MAGIC.len() + SEED_LEN + COSIGNER_SEED_LEN;

/// Generates a treasury key pair and saves it to `path`, which must not exist yet.
/// SLH-DSA-SHAKE-256s key generation takes a moment.
pub fn create_treasury_key(path: &Path) -> Result<TreasuryKeypair, NodeError> {
    if std::fs::symlink_metadata(path).is_ok() {
        return Err(format!("{} exists; refusing to replace a key file", path.display()).into());
    }
    let keypair = TreasuryKeypair::generate()?;
    let mut secret = Vec::with_capacity(SEED_LEN + COSIGNER_SEED_LEN);
    secret.extend_from_slice(keypair.signer().seed());
    secret.extend_from_slice(keypair.cosigner_seed());
    publish_key_file(path, TREASURY_FILE_MAGIC, &secret)
        .map_err(|e| format!("cannot write treasury key {}: {e}", path.display()))?;
    Ok(keypair)
}

/// Loads the treasury key pair saved by [`create_treasury_key`].
pub fn load_treasury_key(path: &Path) -> Result<TreasuryKeypair, NodeError> {
    let bytes = std::fs::read(path)
        .map_err(|e| format!("cannot read treasury key {}: {e}", path.display()))?;
    let Some(secret) = bytes
        .strip_prefix(TREASURY_FILE_MAGIC.as_slice())
        .filter(|_| bytes.len() == TREASURY_FILE_LEN)
    else {
        return Err(format!(
            "{} is not a Plauthium treasury key file ({} bytes)",
            path.display(),
            bytes.len()
        )
        .into());
    };
    let (seed, cosigner_seed) = secret.split_at(SEED_LEN);
    let seed: [u8; SEED_LEN] = seed.try_into().map_err(|_| "treasury seed length")?;
    let cosigner_seed: [u8; COSIGNER_SEED_LEN] = cosigner_seed
        .try_into()
        .map_err(|_| "treasury co-signer seed length")?;
    Ok(TreasuryKeypair::from_seeds(&seed, &cosigner_seed))
}

/// The key file to use: `key_file` if given, else `miner_key.bin` in `data_dir`.
pub fn key_path(data_dir: &Path, key_file: Option<&Path>) -> PathBuf {
    key_file.map_or_else(|| data_dir.join(KEY_FILE_NAME), Path::to_path_buf)
}

/// Loads the miner key from `path`, or generates one and saves it there if the file
/// does not exist. Returns the key pair and whether it was created.
///
/// An existing key file is never overwritten: a file that is not a valid key file,
/// or a symlink whose target is missing, is an error. If another process creates the
/// file at the same moment, its key is loaded instead.
pub fn load_or_create(path: &Path) -> Result<(OwnerKeypair, bool), NodeError> {
    match std::fs::read(path) {
        Ok(bytes) => Ok((parse_key_file(path, &bytes)?, false)),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
            if std::fs::symlink_metadata(path).is_ok() {
                return Err(format!(
                    "miner key {} is a symlink to a missing file; refusing to replace it",
                    path.display()
                )
                .into());
            }
            let keypair = OwnerKeypair::generate()?;
            match publish_key_file(path, KEY_FILE_MAGIC, keypair.seed()) {
                Ok(()) => Ok((keypair, true)),
                Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => {
                    Ok((parse_key_file(path, &std::fs::read(path)?)?, false))
                }
                Err(e) => Err(format!("cannot write miner key {}: {e}", path.display()).into()),
            }
        }
        Err(e) => Err(format!("cannot read miner key {}: {e}", path.display()).into()),
    }
}

fn parse_key_file(path: &Path, bytes: &[u8]) -> Result<OwnerKeypair, NodeError> {
    let split = bytes.len().saturating_sub(SEED_LEN);
    let (header, seed) = bytes.split_at(split);
    // Keep existing identities readable. Older seed containers used an ASCII
    // format tag after the algorithm name; new files use the neutral header.
    let tagged = header.strip_prefix(b"PLAU/MLDSA87/").is_some_and(|tag| {
        tag.strip_suffix(b"\n").is_some_and(|tag| {
            !tag.is_empty() && tag.len() <= 16 && tag.iter().all(u8::is_ascii_alphanumeric)
        })
    });
    if seed.len() != SEED_LEN || (header != KEY_FILE_MAGIC && !tagged) {
        return Err(format!(
            "{} is not a Plauthium ML-DSA-87 key file ({} bytes); move it away to generate a new key",
            path.display(),
            bytes.len()
        )
        .into());
    }
    let seed: [u8; SEED_LEN] = seed
        .try_into()
        .map_err(|_| "key file seed has the wrong length")?;
    Ok(OwnerKeypair::from_seed(&seed))
}

/// Writes a key file (`magic || secret`) without ever replacing an existing one. The
/// secret goes to a uniquely named temporary file (created exclusively, owner-only on
/// Unix), which is then hard-linked to `path`. Linking fails with `AlreadyExists` if
/// `path` exists, so a crash never leaves a truncated key and a concurrent start never
/// overwrites one.
fn publish_key_file(path: &Path, magic: &[u8], secret: &[u8]) -> std::io::Result<()> {
    let parent = path.parent().filter(|p| !p.as_os_str().is_empty());
    if let Some(parent) = parent {
        std::fs::create_dir_all(parent)?;
    }
    let nanos = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos();
    let mut tmp_name = path.as_os_str().to_owned();
    tmp_name.push(format!(".{}.{nanos}.tmp", std::process::id()));
    let tmp_path = Path::new(&tmp_name);

    let mut options = std::fs::OpenOptions::new();
    options.write(true).create_new(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt;
        options.mode(0o600);
    }
    let result = (|| {
        let mut file = options.open(tmp_path)?;
        file.write_all(magic)?;
        file.write_all(secret)?;
        file.sync_all()?;
        drop(file);
        std::fs::hard_link(tmp_path, path)
    })();
    let _ = std::fs::remove_file(tmp_path);
    result?;
    // Make the new directory entry durable (best effort; not every platform allows it).
    if let Some(parent) = parent
        && let Ok(dir) = std::fs::File::open(parent)
    {
        let _ = dir.sync_all();
    }
    Ok(())
}

/// Locks `data_dir` (creating it if needed) for as long as the returned file stays
/// open: two nodes on one data directory would corrupt each other's `blocks.log`.
pub fn lock_data_dir(data_dir: &Path) -> Result<std::fs::File, NodeError> {
    std::fs::create_dir_all(data_dir)?;
    let path = data_dir.join(LOCK_FILE_NAME);
    let file = std::fs::OpenOptions::new()
        .create(true)
        .truncate(false)
        .write(true)
        .open(&path)?;
    match file.try_lock() {
        Ok(()) => Ok(file),
        Err(std::fs::TryLockError::WouldBlock) => Err(format!(
            "data directory {} is in use by another plauthium-node",
            data_dir.display()
        )
        .into()),
        Err(std::fs::TryLockError::Error(e)) => {
            Err(format!("cannot lock {}: {e}", path.display()).into())
        }
    }
}

/// `--reset`: deletes everything in `data_dir` except the key file at `key_path` (so
/// the node keeps its identity across resets) and the lock file.
///
/// Directories on the way to the key file are emptied instead of deleted. Symlinks
/// are never followed: one leading to the key file or to a directory holding it is
/// kept, any other is removed as a link.
pub fn reset_data_dir(data_dir: &Path, key_path: &Path) -> Result<(), NodeError> {
    let keep: Vec<PathBuf> = [key_path.to_path_buf(), data_dir.join(LOCK_FILE_NAME)]
        .iter()
        .filter_map(|p| p.canonicalize().ok())
        .collect();
    clear_dir(data_dir, &keep)?;
    Ok(())
}

fn clear_dir(dir: &Path, keep: &[PathBuf]) -> std::io::Result<()> {
    for entry in std::fs::read_dir(dir)? {
        let entry = entry?;
        let path = entry.path();
        let file_type = entry.file_type()?; // does not follow symlinks
        if let Ok(canonical) = path.canonicalize()
            && keep.iter().any(|k| k.starts_with(&canonical))
        {
            // A kept file itself, or a directory or symlink on the way to one.
            if file_type.is_dir() && !keep.contains(&canonical) {
                clear_dir(&path, keep)?;
            }
            continue;
        }
        if file_type.is_dir() {
            std::fs::remove_dir_all(&path)?;
        } else {
            std::fs::remove_file(&path)?;
        }
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn temp_dir(label: &str) -> std::path::PathBuf {
        let dir = std::env::temp_dir().join(format!(
            "plau-keystore-{label}-{}-{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        dir
    }

    #[test]
    fn key_is_created_once_then_loaded_and_survives_reset() {
        let dir = temp_dir("persist");
        let key_path = dir.join(KEY_FILE_NAME);

        let (created, was_new) = load_or_create(&key_path).unwrap();
        assert!(was_new);
        let bytes = std::fs::read(&key_path).unwrap();
        assert_eq!(bytes.len(), KEY_FILE_LEN);
        assert!(bytes.starts_with(KEY_FILE_MAGIC));
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let mode = std::fs::metadata(&key_path).unwrap().permissions().mode();
            assert_eq!(mode & 0o777, 0o600, "the key file is private");
        }

        let (loaded, was_new) = load_or_create(&key_path).unwrap();
        assert!(!was_new);
        assert_eq!(loaded.key_id(), created.key_id());
        assert_eq!(loaded.public_key(), created.public_key());

        // --reset wipes the chain data but keeps the key and the lock file.
        std::fs::write(dir.join("blocks.log"), b"chain data").unwrap();
        std::fs::create_dir_all(dir.join("sub")).unwrap();
        let lock = lock_data_dir(&dir).unwrap();
        reset_data_dir(&dir, &key_path).unwrap();
        assert!(!dir.join("blocks.log").exists());
        assert!(!dir.join("sub").exists());
        assert!(dir.join(LOCK_FILE_NAME).exists());
        // While it is locked, a second node cannot use the directory.
        assert!(lock_data_dir(&dir).is_err());
        drop(lock);
        drop(lock_data_dir(&dir).unwrap());
        let (after_reset, was_new) = load_or_create(&key_path).unwrap();
        assert!(!was_new);
        assert_eq!(after_reset.key_id(), created.key_id());

        // Two fresh key files hold two different identities.
        let other_path = dir.join("other.bin");
        let (other, _) = load_or_create(&other_path).unwrap();
        assert_ne!(other.key_id(), created.key_id());
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn reset_keeps_a_nested_key_and_never_follows_symlinks() {
        let dir = temp_dir("nested");
        let key_path = dir.join("keys").join("miner.bin");
        let (created, _) = load_or_create(&key_path).unwrap();
        std::fs::write(dir.join("keys").join("other"), b"x").unwrap();
        std::fs::write(dir.join("blocks.log"), b"chain data").unwrap();

        // Outside data: a directory reached through a symlink must survive the reset.
        let outside = temp_dir("nested-outside");
        std::fs::write(outside.join("precious"), b"keep me").unwrap();
        #[cfg(unix)]
        std::os::unix::fs::symlink(&outside, dir.join("link")).unwrap();

        reset_data_dir(&dir, &key_path).unwrap();
        assert!(key_path.exists(), "the nested key file survives");
        assert!(!dir.join("keys").join("other").exists());
        assert!(!dir.join("blocks.log").exists());
        assert!(
            outside.join("precious").exists(),
            "symlinks are not followed"
        );
        #[cfg(unix)]
        assert!(std::fs::symlink_metadata(dir.join("link")).is_err());
        let (loaded, was_new) = load_or_create(&key_path).unwrap();
        assert!(!was_new);
        assert_eq!(loaded.key_id(), created.key_id());
        let _ = std::fs::remove_dir_all(&dir);
        let _ = std::fs::remove_dir_all(&outside);
    }

    #[test]
    fn an_existing_key_is_never_overwritten() {
        let dir = temp_dir("exclusive");
        let key_path = dir.join(KEY_FILE_NAME);
        let (first, _) = load_or_create(&key_path).unwrap();
        let before = std::fs::read(&key_path).unwrap();

        // Publishing over an existing key fails instead of replacing it...
        let err = publish_key_file(&key_path, KEY_FILE_MAGIC, &[9; SEED_LEN]).unwrap_err();
        assert_eq!(err.kind(), std::io::ErrorKind::AlreadyExists);
        assert_eq!(std::fs::read(&key_path).unwrap(), before);
        // ...and leaves no temporary file behind.
        let leftovers = std::fs::read_dir(&dir).unwrap().count();
        assert_eq!(leftovers, 1);
        assert_eq!(
            load_or_create(&key_path).unwrap().0.key_id(),
            first.key_id()
        );

        // A symlink to a missing file is refused rather than replaced.
        #[cfg(unix)]
        {
            let link = dir.join("dangling.bin");
            std::os::unix::fs::symlink(dir.join("missing"), &link).unwrap();
            assert!(load_or_create(&link).is_err());
            assert!(
                std::fs::symlink_metadata(&link)
                    .unwrap()
                    .file_type()
                    .is_symlink()
            );
        }
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn a_damaged_key_file_is_rejected_and_kept() {
        let dir = temp_dir("damaged");
        let key_path = dir.join(KEY_FILE_NAME);
        std::fs::write(&key_path, b"not a key").unwrap();
        assert!(load_or_create(&key_path).is_err());
        assert_eq!(std::fs::read(&key_path).unwrap(), b"not a key");

        let mut wrong_magic = vec![0u8; KEY_FILE_LEN];
        wrong_magic[..4].copy_from_slice(b"PLAU");
        std::fs::write(&key_path, &wrong_magic).unwrap();
        assert!(load_or_create(&key_path).is_err());
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn tagged_seed_containers_keep_their_original_identity() {
        let mut bytes = b"PLAU/MLDSA87/legacy\n".to_vec();
        bytes.extend_from_slice(&[7; SEED_LEN]);
        let parsed = parse_key_file(Path::new("miner_key.bin"), &bytes).unwrap();
        assert_eq!(
            parsed.public_key(),
            OwnerKeypair::from_seed(&[7; SEED_LEN]).public_key()
        );
    }

    #[test]
    fn a_treasury_key_round_trips_and_is_never_overwritten() {
        let dir = temp_dir("treasury");
        let path = dir.join("treasury_key.bin");
        let created = create_treasury_key(&path).unwrap();
        let bytes = std::fs::read(&path).unwrap();
        assert_eq!(bytes.len(), TREASURY_FILE_LEN);
        let loaded = load_treasury_key(&path).unwrap();
        assert_eq!(loaded.key_id(), created.key_id());
        assert_eq!(loaded.cosigner_key_id(), created.cosigner_key_id());
        assert!(create_treasury_key(&path).is_err());
        assert_eq!(std::fs::read(&path).unwrap(), bytes);

        // A miner key file is not a treasury key file, and a truncated one is refused.
        let miner = dir.join(KEY_FILE_NAME);
        load_or_create(&miner).unwrap();
        assert!(load_treasury_key(&miner).is_err());
        std::fs::write(&path, &bytes[..bytes.len() - 1]).unwrap();
        assert!(load_treasury_key(&path).is_err());
        let _ = std::fs::remove_dir_all(&dir);
    }
}
EOF

cat << 'EOF' > node/src/lib.rs
//! Plauthium Public Testnet node library: actors, P2P networking, miner, RPC and explorer.
//!
//! The `plauthium-node` binary (`src/main.rs`) is a thin CLI over [`start_node`] and
//! [`run_genesis_cmd`]; integration tests start several nodes in one process through
//! the same entry points.

#![forbid(unsafe_code)]

pub mod chain_actor;
pub mod cli;
pub mod engine;
pub mod keystore;
pub mod mempool;
pub mod net;
pub mod rpc;
pub mod share_pool;
pub mod store;

use std::net::SocketAddr;
use std::sync::Arc;
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};

use tokio::sync::{Semaphore, broadcast, mpsc, watch};
use tokio::task::JoinHandle;
use tracing::{info, warn};
use wire::{DifficultyMode, Digest, GenesisConfig, Target};

use crate::chain_actor::{ChainActor, ChainCmd, ChainEvent, StatusSnapshot};
use crate::cli::{DifficultyArg, GenesisArgs, KeyArgs, RunArgs, TreasuryCommand, WithdrawArgs};
use crate::engine::ConsensusEngine;
use crate::mempool::{MempoolActor, MempoolCmd, MempoolEvent, MempoolView};
use crate::net::PeerManager;
use crate::rpc::spawn_rpc_server;
use crate::store::BlockStore;

/// Embedded default genesis JSON (§3.4).
pub const DEFAULT_GENESIS_JSON: &str = include_str!("../genesis.testnet.json");

/// Boxed error type of the node entry points.
pub type NodeError = Box<dyn std::error::Error + Send + Sync>;

/// Handle to a running in-process node (used by `main` and the integration tests).
pub struct NodeHandle {
    /// Bound P2P listen address.
    pub p2p_addr: SocketAddr,
    /// Bound RPC / explorer address.
    pub rpc_addr: SocketAddr,
    /// Key id of this node's ML-DSA-87 miner key.
    pub miner_key_id: Digest,
    /// Command channel of the ChainState actor.
    pub chain_tx: mpsc::Sender<ChainCmd>,
    /// Command channel of the mempool actor.
    pub mempool_tx: mpsc::Sender<MempoolCmd>,
    /// Latest chain status.
    pub status_rx: watch::Receiver<Arc<StatusSnapshot>>,
    /// The Fresh Work miner.
    pub engine: Arc<ConsensusEngine>,
    /// The P2P layer.
    pub peer_manager: Arc<PeerManager>,
    shutdown_tx: watch::Sender<bool>,
    tasks: Vec<JoinHandle<()>>,
    /// Held until the node is dropped: no second node can use the data directory.
    _data_dir_lock: std::fs::File,
}

impl NodeHandle {
    /// Signals graceful shutdown of every task, connection and miner thread.
    pub fn shutdown(&self) {
        self.engine.shutdown();
        let _ = self.shutdown_tx.send(true);
    }

    /// Signals shutdown and waits until the ChainState and mempool actors have exited
    /// (the ChainState actor flushes `blocks.log` on exit).
    pub async fn stop(self) {
        self.shutdown();
        for task in self.tasks {
            let _ = task.await;
        }
    }
}

fn unix_now_secs() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

/// Builds the genesis configuration for `plauthium-node genesis` with
/// `genesis_time_bucket = now`.
pub fn genesis_from_args(args: &GenesisArgs) -> Result<GenesisConfig, NodeError> {
    let mut cfg = GenesisConfig::default_testnet(0);
    cfg.genesis_time_bucket = unix_now_secs() / cfg.time_bucket_secs;
    cfg.name = args.name.clone();
    cfg.initial_seal_target = Target(u128::MAX / u128::from(args.seal_attempts.max(1)));
    cfg.share_ratio = args.share_ratio;
    cfg.difficulty = match args.difficulty {
        DifficultyArg::Fixed => DifficultyMode::Fixed,
        DifficultyArg::Windowed => DifficultyMode::Windowed {
            window: args.retarget_window,
        },
    };
    cfg.target_block_secs = args.target_block_secs;
    cfg.blocks_per_epoch = args.blocks_per_epoch;
    cfg.settle_delay = args.settle_delay;
    if let (Some(key_id), Some(cosigner_key_id)) =
        (args.treasury_key_id, args.treasury_cosigner_key_id)
    {
        cfg.treasury_key_id = key_id;
        cfg.treasury_cosigner_key_id = cosigner_key_id;
    }
    chain::validate_genesis(&cfg)?;
    Ok(cfg)
}

/// `plauthium-node genesis`: writes a validated genesis JSON file.
pub fn run_genesis_cmd(args: GenesisArgs) -> Result<(), NodeError> {
    let cfg = genesis_from_args(&args)?;
    let genesis_id = chain::compute_genesis_id(&cfg)?;
    if let Some(parent) = args.out.parent()
        && !parent.as_os_str().is_empty()
    {
        std::fs::create_dir_all(parent)?;
    }
    std::fs::write(&args.out, serde_json::to_string_pretty(&cfg)?)?;
    info!(path = %args.out.display(), %genesis_id, "Wrote genesis configuration");
    Ok(())
}

/// `plauthium-node key`: loads the miner key, creating it first if it does not exist,
/// and prints where it is and the identity it gives the node.
pub fn run_key_cmd(args: KeyArgs) -> Result<(), NodeError> {
    let key_path = keystore::key_path(&args.data_dir, args.key_file.as_deref());
    let (key, created) = keystore::load_or_create(&key_path)?;
    println!("key_file: {}", key_path.display());
    println!("status: {}", if created { "created" } else { "loaded" });
    println!("key_id: {}", key.key_id().to_hex());
    println!("owner_id: {}", key.owner_id());
    Ok(())
}

/// `plauthium-node treasury ...`: treasury key management and offline withdrawal signing.
pub fn run_treasury_cmd(cmd: TreasuryCommand) -> Result<(), NodeError> {
    let print_ids = |key: &chain::TreasuryKeypair| {
        println!("treasury_key_id: {}", key.key_id().to_hex());
        println!(
            "treasury_cosigner_key_id: {}",
            key.cosigner_key_id().to_hex()
        );
    };
    match cmd {
        TreasuryCommand::Keygen(args) => {
            let key = keystore::create_treasury_key(&args.key_file)?;
            println!("key_file: {}", args.key_file.display());
            print_ids(&key);
        }
        TreasuryCommand::Show(args) => print_ids(&keystore::load_treasury_key(&args.key_file)?),
        TreasuryCommand::Withdraw(args) => {
            let hex = sign_withdrawal_cmd(&args)?;
            match &args.out {
                Some(path) => std::fs::write(path, format!("{hex}\n"))?,
                None => println!("{hex}"),
            }
        }
    }
    Ok(())
}

/// Builds and signs the withdrawal of `treasury withdraw`, checked against the
/// genesis treasury policy and both signatures, and returns its hex encoding.
pub fn sign_withdrawal_cmd(args: &WithdrawArgs) -> Result<String, NodeError> {
    let genesis = read_genesis(args.genesis.as_deref())?;
    let genesis_id = chain::compute_genesis_id(&genesis)?;
    let key = keystore::load_treasury_key(&args.key_file)?;
    let mut withdrawal = wire::InitialPoolWithdrawal {
        expected_nonce: args.nonce,
        outputs: args
            .outputs
            .iter()
            .map(|o| wire::WithdrawalOutput {
                recipient: o.recipient,
                atoms: o.atoms,
            })
            .collect(),
        fee: args.fee,
        ml_dsa_key: key.signer().public_key().clone(),
        slh_dsa_key: key.cosigner_public_key().clone(),
        ml_dsa_signature: chain::keys::unsigned(),
        slh_dsa_signature: chain::keys::unsigned_cosignature(),
    };
    key.sign_withdrawal(&mut withdrawal, &genesis_id)?;
    chain::SignedWithdrawal::verify(withdrawal.clone(), &genesis, &genesis_id)
        .map_err(|e| format!("the withdrawal would be rejected: {e}"))?;
    Ok(withdrawal.to_hex()?)
}

/// Reads and validates the genesis file at `path`, or the embedded default.
fn read_genesis(path: Option<&std::path::Path>) -> Result<GenesisConfig, NodeError> {
    let genesis: GenesisConfig = match path {
        Some(path) => serde_json::from_str(&std::fs::read_to_string(path)?)?,
        None => serde_json::from_str(DEFAULT_GENESIS_JSON)?,
    };
    chain::validate_genesis(&genesis)?;
    Ok(genesis)
}

/// Loads the genesis file named by `--genesis`, or the embedded default.
pub fn load_genesis(args: &RunArgs) -> Result<GenesisConfig, NodeError> {
    read_genesis(args.genesis.as_deref())
}

/// Grace period before warning that no peer is connected, and the interval between
/// such warnings.
const NO_PEER_GRACE: Duration = Duration::from_secs(30);
const NO_PEER_WARNING_INTERVAL: Duration = Duration::from_secs(60);
/// With `--mine-when-synced`, mining also starts once the tip has not moved for this
/// long while a peer is connected: a peer may claim a height it cannot deliver.
const SYNC_STALL: Duration = Duration::from_secs(60);

/// Watches the connection to the network. A node with static peers warns while none is
/// connected. With `--mine-when-synced` (`gated`) it also opens the mining gate once a
/// peer is connected and the node has caught up with the best height peers report, or
/// syncing has stalled; the gate then stays open until no peer is left.
fn spawn_peer_watch(
    engine: Arc<ConsensusEngine>,
    peers: Arc<PeerManager>,
    status_rx: watch::Receiver<Arc<StatusSnapshot>>,
    mut shutdown: watch::Receiver<bool>,
    gated: bool,
    has_static_peers: bool,
) {
    if !gated && !has_static_peers {
        return;
    }
    tokio::spawn(async move {
        let mut alone_since = Instant::now();
        let mut last_warning: Option<Instant> = None;
        let mut progress = (status_rx.borrow().tip.height, Instant::now());
        loop {
            let tip = status_rx.borrow().tip.height;
            if tip != progress.0 {
                progress = (tip, Instant::now());
            }
            let connected = peers.peer_count() > 0;
            if connected {
                alone_since = Instant::now();
            } else {
                // Only time spent connected without progress counts as a stalled sync.
                progress = (tip, Instant::now());
                if has_static_peers
                    && alone_since.elapsed() >= NO_PEER_GRACE
                    && last_warning.is_none_or(|t| t.elapsed() >= NO_PEER_WARNING_INTERVAL)
                {
                    warn!(
                        mining_paused = gated,
                        "No peer connected; check the --peer addresses and the network"
                    );
                    last_warning = Some(Instant::now());
                }
            }
            if gated {
                let caught_up = peers.best_peer_height().is_some_and(|best| tip >= best);
                let stalled = progress.1.elapsed() >= SYNC_STALL;
                let open = connected && (engine.sync_gate_open() || caught_up || stalled);
                if open != engine.sync_gate_open() {
                    engine.set_sync_gate(open);
                    if open {
                        info!(height = tip, "Connected and caught up; mining");
                    } else {
                        info!("No peer connected; mining paused until the node is caught up again");
                    }
                }
            }
            tokio::select! {
                () = tokio::time::sleep(Duration::from_secs(1)) => {}
                res = shutdown.changed() => {
                    if res.is_err() || *shutdown.borrow() {
                        break;
                    }
                }
            }
        }
    });
}

/// Starts all actors, P2P networking, the ConsensusEngine and the Axum RPC for one node.
pub async fn start_node(args: RunArgs) -> Result<NodeHandle, NodeError> {
    let profile_check = chain::testnet_ozaki_profile().validate();
    profile_check.map_err(|e| format!("TESTNET_PROFILE validation failed: {e}"))?;
    let genesis = load_genesis(&args)?;

    let key_path = keystore::key_path(&args.data_dir, args.key_file.as_deref());
    let data_dir_lock = keystore::lock_data_dir(&args.data_dir)?;
    if args.reset {
        keystore::reset_data_dir(&args.data_dir, &key_path)?;
    }
    let (miner, created) = keystore::load_or_create(&key_path)?;
    let miner = Arc::new(miner);
    info!(
        key_id = %miner.key_id().short_hex(16),
        owner_id = miner.owner_id(),
        path = %key_path.display(),
        "{} ML-DSA-87 miner key",
        if created { "Generated a new" } else { "Loaded the" }
    );
    let (log_writer, disk_blocks) = BlockStore::open(&args.data_dir.join("blocks.log"))?;

    let (chain_tx, chain_rx) = mpsc::channel::<ChainCmd>(1_024);
    let (mempool_tx, mempool_rx) = mpsc::channel::<MempoolCmd>(1_024);
    let (chain_event_tx, _) = broadcast::channel::<ChainEvent>(1_024);
    let (mempool_event_tx, _) = broadcast::channel::<MempoolEvent>(1_024);
    let (mempool_view_tx, mempool_view_rx) = watch::channel(Arc::new(MempoolView::default()));
    let (template_tx, template_rx) = watch::channel(None);
    let (shutdown_tx, shutdown_rx) = watch::channel(false);

    let verify_threads = args.verify_threads.unwrap_or_else(|| {
        std::thread::available_parallelism().map_or(2, |n| (n.get() / 2).max(1))
    });
    let verify_semaphore = Arc::new(Semaphore::new(verify_threads.max(1)));

    let (mut chain_actor, status_rx) = ChainActor::new(
        genesis.clone(),
        miner.clone(),
        log_writer,
        chain_tx.clone(),
        chain_rx,
        chain_event_tx.clone(),
        template_tx,
        mempool_view_rx.clone(),
        verify_semaphore,
    )?;
    // Persisted blocks are replayed before any peer connects (Origin::Disk, §8.7).
    chain_actor.replay_disk_blocks(disk_blocks);

    let mining_threads = if args.no_mine { 0 } else { args.mining_threads };
    let gated = args.mine_when_synced && mining_threads > 0;
    let engine = ConsensusEngine::spawn(
        mining_threads,
        mining_threads > 0,
        gated,
        template_rx,
        chain_tx.clone(),
    )?;

    let mempool_actor = MempoolActor::new(
        mempool_rx,
        chain_tx.clone(),
        chain_event_tx.subscribe(),
        mempool_event_tx.clone(),
        mempool_view_tx,
        status_rx.clone(),
    );
    let mut tasks = vec![tokio::spawn(mempool_actor.run(shutdown_rx.clone()))];
    tasks.push(tokio::spawn(chain_actor.run(shutdown_rx.clone())));

    let peer_manager = PeerManager::start(
        args.p2p_listen,
        args.peers.clone(),
        genesis.chain_id,
        chain_tx.clone(),
        mempool_tx.clone(),
        chain_event_tx.subscribe(),
        mempool_event_tx.subscribe(),
        status_rx.clone(),
        shutdown_rx.clone(),
    )
    .await?;
    let p2p_addr = peer_manager.local_addr();
    spawn_peer_watch(
        engine.clone(),
        peer_manager.clone(),
        status_rx.clone(),
        shutdown_rx.clone(),
        gated,
        !args.peers.is_empty(),
    );

    let rpc_addr = spawn_rpc_server(
        args.rpc_listen,
        status_rx.clone(),
        mempool_view_rx,
        chain_tx.clone(),
        mempool_tx.clone(),
        engine.clone(),
        peer_manager.clone(),
        miner.clone(),
        shutdown_rx,
    )
    .await?;

    Ok(NodeHandle {
        p2p_addr,
        rpc_addr,
        miner_key_id: miner.key_id(),
        chain_tx,
        mempool_tx,
        status_rx,
        engine,
        peer_manager,
        shutdown_tx,
        tasks,
        _data_dir_lock: data_dir_lock,
    })
}
EOF

cat << 'EOF' > node/src/main.rs
//! `plauthium-node`: the Plauthium Public Testnet daemon.

#![forbid(unsafe_code)]

use clap::Parser;
use node::NodeError;
use node::cli::{Cli, Command};
use tracing::info;

#[tokio::main]
async fn main() -> Result<(), NodeError> {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("info")),
        )
        .init();

    match Cli::parse().command {
        Command::Genesis(args) => node::run_genesis_cmd(args)?,
        Command::Key(args) => node::run_key_cmd(args)?,
        Command::Treasury(cmd) => node::run_treasury_cmd(cmd)?,
        Command::Run(args) => {
            let handle = node::start_node(args).await?;
            info!(
                p2p = %handle.p2p_addr,
                rpc = %handle.rpc_addr,
                "plauthium-node started; press Ctrl-C to stop"
            );
            tokio::signal::ctrl_c().await?;
            info!("Ctrl-C received; shutting down gracefully");
            handle.stop().await;
            info!("Shutdown complete");
        }
    }
    Ok(())
}
EOF

cat << 'EOF' > node/src/mempool.rs
//! Mempool actor (`node::mempool`, §8.4): pooled jobs and InitialProtocolPool
//! withdrawals.

use std::collections::{BTreeMap, HashMap, HashSet, VecDeque};
use std::sync::Arc;

use chain::{
    JobValidationError, SignedWithdrawal, WithdrawalError, compute_job_ids, compute_withdrawal_id,
    validate_job_stateless, validate_withdrawal_stateless, verify_job_client,
};
use tokio::sync::{broadcast, mpsc, oneshot, watch};
use tracing::warn;
use wire::{Block, Digest, InitialPoolWithdrawal, JobTransaction, MEMPOOL_CAPACITY};

use crate::chain_actor::{ChainCmd, ChainEvent, Origin, StatusSnapshot};

/// Pooled withdrawals: the InitialNonce run a template draws from is short (at most
/// `MAX_WITHDRAWALS_PER_BLOCK` per block), so the pool only holds nonces up to this far
/// ahead of the tip's `InitialNonce`, and at most this many withdrawals.
pub const MAX_POOLED_WITHDRAWALS: u64 = 16;

/// Rotating snapshot of pooled transactions, published to the ChainState actor for templates.
#[derive(Clone, Debug, Default)]
pub struct MempoolView {
    /// Rotating FIFO window, at most `4 * max_jobs_per_block` entries.
    pub txs: Vec<JobTransaction>,
    /// Total number of pooled transactions.
    pub size: usize,
    /// Every pooled withdrawal, both treasury signatures verified, by `TxID`.
    pub withdrawals: Vec<SignedWithdrawal>,
}

/// Event broadcast by `MempoolActor` when a transaction is accepted.
#[derive(Clone, Debug)]
pub enum MempoolEvent {
    /// A new job entered the pool (relayed to peers except `origin`).
    Accepted {
        /// The job.
        tx: JobTransaction,
        /// Where it came from.
        origin: Origin,
    },
    /// A new InitialProtocolPool withdrawal entered the pool (relayed likewise).
    WithdrawalAccepted {
        /// The withdrawal.
        withdrawal: Box<InitialPoolWithdrawal>,
        /// Where it came from.
        origin: Origin,
    },
}

/// Successful withdrawal insertion receipt.
#[derive(Clone, Debug)]
pub struct WithdrawalInsertOk {
    /// The withdrawal's `TxID`.
    pub tx_id: Digest,
    /// `ν_expected`.
    pub expected_nonce: u64,
    /// `v`, paid to `U`.
    pub amount: u64,
    /// `f`, paid to `R_l`.
    pub fee: u64,
}

/// Successful insertion receipt returned to RPC and P2P callers.
#[derive(Clone, Debug)]
pub struct MempoolInsertOk {
    /// Transaction identifier.
    pub tx_id: Digest,
    /// Job identifier.
    pub job_id: u64,
    /// Escrow deposit `D`.
    pub deposit: u64,
    /// `D + f_queue`.
    pub total_charge: u64,
    /// Exact dot product the job will settle with.
    pub expected_result: i128,
}

/// Rejection reasons of `MempoolCmd::Insert`.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum MempoolReject {
    /// Same `tx_id` or `job_id` already pooled.
    Duplicate,
    /// The pool holds `MEMPOOL_CAPACITY` transactions (no fee-based eviction).
    Full,
    /// The transaction is invalid.
    Invalid {
        /// Stable error code for the RPC (§9.5).
        code: &'static str,
        /// Human-readable reason.
        message: String,
    },
}

/// Commands accepted by `MempoolActor`.
pub enum MempoolCmd {
    /// Validates and pools a job.
    Insert {
        /// The job.
        tx: JobTransaction,
        /// Where it came from.
        origin: Origin,
        /// Outcome.
        reply: oneshot::Sender<Result<MempoolInsertOk, MempoolReject>>,
    },
    /// Validates and pools an InitialProtocolPool withdrawal.
    InsertWithdrawal {
        /// The withdrawal.
        withdrawal: Box<InitialPoolWithdrawal>,
        /// Where it came from.
        origin: Origin,
        /// Outcome.
        reply: oneshot::Sender<Result<WithdrawalInsertOk, MempoolReject>>,
    },
    /// Number of pooled transactions.
    Stats {
        /// Pool size.
        reply: oneshot::Sender<usize>,
    },
    /// The oldest `limit` pooled transactions.
    List {
        /// Maximum entries.
        limit: usize,
        /// Transactions, oldest first.
        reply: oneshot::Sender<Vec<JobTransaction>>,
    },
}

struct PooledEntry {
    tx_id: Digest,
    job_id: u64,
    tx: JobTransaction,
}

/// Asynchronous mempool actor (§8.4).
pub struct MempoolActor {
    cmd_rx: mpsc::Receiver<MempoolCmd>,
    chain_tx: mpsc::Sender<ChainCmd>,
    chain_events: broadcast::Receiver<ChainEvent>,
    event_tx: broadcast::Sender<MempoolEvent>,
    view_tx: watch::Sender<Arc<MempoolView>>,
    status_rx: watch::Receiver<Arc<StatusSnapshot>>,
    fifo: VecDeque<PooledEntry>,
    view_cursor: usize,
    by_tx_id: HashSet<Digest>,
    by_job_id: HashMap<u64, Digest>,
    // Jobs on the canonical chain that have not expired, by tx_id and by job_id, with
    // their expiry height (as the STF keeps them): a copy submitted again is a duplicate.
    included_tx: HashMap<Digest, u64>,
    included_jobs: HashMap<u64, u64>,
    // Withdrawals with nonces at or past the tip's InitialNonce, by TxID. Spent nonces
    // are pruned on every tip change, so an included withdrawal is never pooled again.
    withdrawals: BTreeMap<Digest, SignedWithdrawal>,
}

fn withdrawal_rejection_code(err: &WithdrawalError) -> &'static str {
    match err {
        WithdrawalError::NoOutputs => "no_outputs",
        WithdrawalError::TooManyOutputs(_) => "too_many_outputs",
        WithdrawalError::ZeroOutput => "zero_output",
        WithdrawalError::AmountOverflow => "amount_overflow",
        WithdrawalError::ExceedsSupply => "charge_exceeds_supply",
        WithdrawalError::PolicyMismatch(_) => "not_treasury_key",
        WithdrawalError::Signature(_) => "bad_signature",
    }
}

fn rejection_code(err: &JobValidationError) -> &'static str {
    match err {
        JobValidationError::ZeroFee(_) => "zero_fee",
        JobValidationError::AmountOverflow => "amount_overflow",
        JobValidationError::ChargeExceedsSupply => "charge_exceeds_supply",
        JobValidationError::ChargeExceedsTestnetLimit => "charge_exceeds_testnet_limit",
        JobValidationError::TooLarge(_) => "too_large",
        JobValidationError::InvalidPayload(_) => "invalid_payload",
    }
}

impl MempoolActor {
    /// Creates the actor; call [`MempoolActor::run`] to start it.
    pub fn new(
        cmd_rx: mpsc::Receiver<MempoolCmd>,
        chain_tx: mpsc::Sender<ChainCmd>,
        chain_events: broadcast::Receiver<ChainEvent>,
        event_tx: broadcast::Sender<MempoolEvent>,
        view_tx: watch::Sender<Arc<MempoolView>>,
        status_rx: watch::Receiver<Arc<StatusSnapshot>>,
    ) -> Self {
        Self {
            cmd_rx,
            chain_tx,
            chain_events,
            event_tx,
            view_tx,
            status_rx,
            fifo: VecDeque::new(),
            view_cursor: 0,
            by_tx_id: HashSet::new(),
            by_job_id: HashMap::new(),
            included_tx: HashMap::new(),
            included_jobs: HashMap::new(),
            withdrawals: BTreeMap::new(),
        }
    }

    /// Runs until `shutdown` turns true (or its sender is dropped).
    pub async fn run(mut self, mut shutdown: watch::Receiver<bool>) {
        let mut rotate = tokio::time::interval(std::time::Duration::from_secs(5));
        rotate.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
        loop {
            tokio::select! {
                res = shutdown.changed() => {
                    if res.is_err() || *shutdown.borrow() {
                        break;
                    }
                }
                Some(cmd) = self.cmd_rx.recv() => self.handle_cmd(cmd),
                _ = rotate.tick() => self.publish_view(),
                ev = self.chain_events.recv() => match ev {
                    Ok(ChainEvent::TipChanged { tip, connected, disconnected }) => {
                        self.handle_tip_changed(tip.height, &connected, &disconnected);
                    }
                    Ok(_) => {}
                    Err(broadcast::error::RecvError::Lagged(skipped)) => {
                        warn!(skipped, "Mempool lagged behind chain events; asking ChainState");
                        self.recover_from_lag().await;
                    }
                    Err(broadcast::error::RecvError::Closed) => break,
                },
            }
        }
    }

    fn handle_cmd(&mut self, cmd: MempoolCmd) {
        match cmd {
            MempoolCmd::Insert { tx, origin, reply } => {
                let _ = reply.send(self.insert_tx(tx, origin));
            }
            MempoolCmd::InsertWithdrawal {
                withdrawal,
                origin,
                reply,
            } => {
                let _ = reply.send(self.insert_withdrawal(*withdrawal, origin));
            }
            MempoolCmd::Stats { reply } => {
                let _ = reply.send(self.fifo.len());
            }
            MempoolCmd::List { limit, reply } => {
                let _ = reply.send(self.fifo.iter().take(limit).map(|e| e.tx.clone()).collect());
            }
        }
    }

    fn next_height(&self) -> u64 {
        self.status_rx.borrow().tip.height + 1
    }

    fn insert_tx(
        &mut self,
        tx: JobTransaction,
        origin: Origin,
    ) -> Result<MempoolInsertOk, MempoolReject> {
        // Duplicates first: a re-signed or forged copy of a pooled job has the same
        // tx_id, and rejecting it costs one hash instead of a full validation.
        if let Ok((tx_id, job_id)) = compute_job_ids(&tx)
            && (self.by_tx_id.contains(&tx_id)
                || self.by_job_id.contains_key(&job_id)
                || self.included_tx.contains_key(&tx_id)
                || self.included_jobs.contains_key(&job_id))
        {
            return Err(MempoolReject::Duplicate);
        }
        let (tx_id, job_id, deposit, expected_result) =
            validate_job_stateless(&tx).map_err(|err| MempoolReject::Invalid {
                code: rejection_code(&err),
                message: err.to_string(),
            })?;
        let total_charge = tx
            .checked_total_charge()
            .ok_or_else(|| MempoolReject::Invalid {
                code: "amount_overflow",
                message: "total charge overflow".to_string(),
            })?;
        let next_height = self.next_height();
        if tx.expiry_height < next_height {
            return Err(MempoolReject::Invalid {
                code: "bad_request",
                message: format!(
                    "job expiry_height {} < next block height {next_height}",
                    tx.expiry_height
                ),
            });
        }
        if tx.expiry_height - next_height > wire::MAX_JOB_TTL {
            return Err(MempoolReject::Invalid {
                code: "expiry_too_far",
                message: format!("job lifetime exceeds {} blocks", wire::MAX_JOB_TTL),
            });
        }
        if self.by_tx_id.contains(&tx_id) || self.by_job_id.contains_key(&job_id) {
            return Err(MempoolReject::Duplicate);
        }
        if self.fifo.len() >= MEMPOOL_CAPACITY {
            return Err(MempoolReject::Full);
        }
        // Last, so duplicates relayed by several peers never pay for a verification.
        let genesis_id = self.status_rx.borrow().genesis_id;
        verify_job_client(&tx, &genesis_id).map_err(|err| MempoolReject::Invalid {
            code: "bad_signature",
            message: format!("client signature: {err}"),
        })?;

        self.push(tx_id, job_id, tx.clone());
        self.publish_view();
        let _ = self.event_tx.send(MempoolEvent::Accepted { tx, origin });
        Ok(MempoolInsertOk {
            tx_id,
            job_id,
            deposit,
            total_charge,
            expected_result,
        })
    }

    /// Pools a withdrawal for nonces `InitialNonce ..< InitialNonce + MAX_POOLED_WITHDRAWALS`.
    /// A spent nonce counts as a duplicate (it may just have been included); a nonce too
    /// far ahead or a full pool is `Full`. Neither penalizes a relaying peer. The
    /// policy check against the genesis treasury key ids runs before the signatures,
    /// and the cheap ML-DSA-87 signature before the SLH-DSA co-signature.
    fn insert_withdrawal(
        &mut self,
        withdrawal: InitialPoolWithdrawal,
        origin: Origin,
    ) -> Result<WithdrawalInsertOk, MempoolReject> {
        let invalid = |err: WithdrawalError| MempoolReject::Invalid {
            code: withdrawal_rejection_code(&err),
            message: err.to_string(),
        };
        let tx_id = compute_withdrawal_id(&withdrawal).map_err(|e| MempoolReject::Invalid {
            code: "bad_request",
            message: e,
        })?;
        if self.withdrawals.contains_key(&tx_id) {
            return Err(MempoolReject::Duplicate);
        }
        let (genesis, genesis_id, initial_nonce) = {
            let status = self.status_rx.borrow();
            (
                status.genesis.clone(),
                status.genesis_id,
                status.initial_nonce,
            )
        };
        let (amount, fee) =
            validate_withdrawal_stateless(&withdrawal, &genesis).map_err(invalid)?;
        if withdrawal.expected_nonce < initial_nonce {
            return Err(MempoolReject::Duplicate);
        }
        if withdrawal.expected_nonce - initial_nonce >= MAX_POOLED_WITHDRAWALS
            || self.withdrawals.len() as u64 >= MAX_POOLED_WITHDRAWALS
        {
            return Err(MempoolReject::Full);
        }
        let signed =
            SignedWithdrawal::verify(withdrawal, &genesis, &genesis_id).map_err(invalid)?;
        let expected_nonce = signed.withdrawal().expected_nonce;
        let relayed = Box::new(signed.withdrawal().clone());
        self.withdrawals.insert(tx_id, signed);
        self.publish_view();
        let _ = self.event_tx.send(MempoolEvent::WithdrawalAccepted {
            withdrawal: relayed,
            origin,
        });
        Ok(WithdrawalInsertOk {
            tx_id,
            expected_nonce,
            amount,
            fee,
        })
    }

    /// Drops pooled withdrawals whose nonce the tip has spent.
    fn prune_withdrawals(&mut self) {
        let initial_nonce = self.status_rx.borrow().initial_nonce;
        self.withdrawals
            .retain(|_, w| w.withdrawal().expected_nonce >= initial_nonce);
    }

    fn push(&mut self, tx_id: Digest, job_id: u64, tx: JobTransaction) {
        self.by_tx_id.insert(tx_id);
        self.by_job_id.insert(job_id, tx_id);
        self.fifo.push_back(PooledEntry { tx_id, job_id, tx });
    }

    fn handle_tip_changed(
        &mut self,
        tip_height: u64,
        connected: &[Arc<Block>],
        disconnected: &[Arc<Block>],
    ) {
        let connected_txs: HashSet<Digest> = connected
            .iter()
            .flat_map(|blk| &blk.body.jobs)
            .filter_map(|tx| compute_job_ids(tx).ok().map(|(id, _)| id))
            .collect();
        let next_height = tip_height + 1;

        // Track the unexpired jobs of the canonical chain: the abandoned branch's leave,
        // the new branch's join.
        for tx in disconnected.iter().flat_map(|blk| &blk.body.jobs) {
            if let Ok((tx_id, job_id)) = compute_job_ids(tx) {
                self.included_tx.remove(&tx_id);
                self.included_jobs.remove(&job_id);
            }
        }
        for tx in connected.iter().flat_map(|blk| &blk.body.jobs) {
            if let Ok((tx_id, job_id)) = compute_job_ids(tx) {
                self.included_tx.insert(tx_id, tx.expiry_height);
                self.included_jobs.insert(job_id, tx.expiry_height);
            }
        }
        self.included_tx.retain(|_, expiry| *expiry >= next_height);
        self.included_jobs
            .retain(|_, expiry| *expiry >= next_height);

        // Remove txs included by the new branch, and txs that expired.
        self.remove_where(|e| {
            connected_txs.contains(&e.tx_id)
                || e.tx.expiry_height < next_height
                || e.tx.expiry_height.saturating_sub(next_height) > wire::MAX_JOB_TTL
        });

        // Return the txs of the abandoned branch (already validated statelessly).
        for tx in disconnected.iter().flat_map(|blk| &blk.body.jobs) {
            if tx.expiry_height < next_height
                || tx.expiry_height.saturating_sub(next_height) > wire::MAX_JOB_TTL
                || self.fifo.len() >= MEMPOOL_CAPACITY
            {
                continue;
            }
            let Ok((tx_id, job_id)) = compute_job_ids(tx) else {
                continue;
            };
            if connected_txs.contains(&tx_id)
                || self.by_tx_id.contains(&tx_id)
                || self.by_job_id.contains_key(&job_id)
            {
                continue;
            }
            self.push(tx_id, job_id, tx.clone());
        }

        // Withdrawals: those the new branch included leave the pool, those of the
        // abandoned branch return to it (their signatures were checked on import).
        let genesis = self.status_rx.borrow().genesis.clone();
        let genesis_id = self.status_rx.borrow().genesis_id;
        for w in connected.iter().flat_map(|blk| &blk.body.withdrawals) {
            if let Ok(tx_id) = compute_withdrawal_id(w) {
                self.withdrawals.remove(&tx_id);
            }
        }
        for w in disconnected.iter().flat_map(|blk| &blk.body.withdrawals) {
            let Ok(tx_id) = compute_withdrawal_id(w) else {
                continue;
            };
            let included = connected
                .iter()
                .flat_map(|blk| &blk.body.withdrawals)
                .any(|c| c == w);
            if !included
                && !self.withdrawals.contains_key(&tx_id)
                && (self.withdrawals.len() as u64) < MAX_POOLED_WITHDRAWALS
                && let Ok(signed) = SignedWithdrawal::verify(w.clone(), &genesis, &genesis_id)
            {
                self.withdrawals.insert(tx_id, signed);
            }
        }
        self.prune_withdrawals();
        self.publish_view();
    }

    async fn recover_from_lag(&mut self) {
        let tx_ids: Vec<Digest> = self.by_tx_id.iter().copied().collect();
        let (reply_tx, reply_rx) = oneshot::channel();
        let request = ChainCmd::FilterIncluded {
            tx_ids,
            reply: reply_tx,
        };
        if self.chain_tx.send(request).await.is_err() {
            return;
        }
        let Ok(included) = reply_rx.await else {
            return;
        };
        let included: HashSet<Digest> = included.into_iter().collect();
        let next_height = self.next_height();
        self.remove_where(|e| {
            included.contains(&e.tx_id)
                || e.tx.expiry_height < next_height
                || e.tx.expiry_height.saturating_sub(next_height) > wire::MAX_JOB_TTL
        });
        self.prune_withdrawals();
        self.publish_view();
    }

    fn remove_where(&mut self, pred: impl Fn(&PooledEntry) -> bool) {
        let (by_tx_id, by_job_id) = (&mut self.by_tx_id, &mut self.by_job_id);
        self.fifo.retain(|entry| {
            let remove = pred(entry);
            if remove {
                by_tx_id.remove(&entry.tx_id);
                by_job_id.remove(&entry.job_id);
            }
            !remove
        });
    }

    fn publish_view(&mut self) {
        let max_jobs = usize::try_from(self.status_rx.borrow().max_jobs_per_block).unwrap_or(32);
        let cap = max_jobs.saturating_mul(4).max(32).min(self.fifo.len());
        let txs = rotating_view(&self.fifo, &mut self.view_cursor, cap);
        let _ = self.view_tx.send(Arc::new(MempoolView {
            txs,
            size: self.fifo.len(),
            withdrawals: self.withdrawals.values().cloned().collect(),
        }));
    }
}

// Rotate even while the tip is stationary: temporarily unfundable FIFO entries
// must not hide the rest of the pool indefinitely.
fn rotating_view(
    fifo: &VecDeque<PooledEntry>,
    cursor: &mut usize,
    cap: usize,
) -> Vec<JobTransaction> {
    if fifo.is_empty() {
        *cursor = 0;
        return Vec::new();
    }
    let start = *cursor % fifo.len();
    let count = cap.min(fifo.len());
    let txs = fifo
        .iter()
        .cycle()
        .skip(start)
        .take(count)
        .map(|e| e.tx.clone())
        .collect();
    *cursor = (start + count) % fifo.len();
    txs
}

#[cfg(test)]
mod hardening_tests {
    use super::*;
    use chain::{OwnerKeypair, keys::unsigned};
    use wire::{DOT_LEN, JobPayload, MAX_JOB_TTL};

    fn actor() -> (MempoolActor, watch::Receiver<Arc<MempoolView>>) {
        actor_with(crate::chain_actor::test_snapshot())
    }
    fn actor_with(
        snapshot: Arc<StatusSnapshot>,
    ) -> (MempoolActor, watch::Receiver<Arc<MempoolView>>) {
        let (_, commands) = mpsc::channel(16);
        let (chain, _) = mpsc::channel(16);
        let (_, events) = broadcast::channel(16);
        let (out, _) = broadcast::channel(16);
        let (view, rx) = watch::channel(Arc::new(MempoolView::default()));
        let (_, status) = watch::channel(snapshot);
        (
            MempoolActor::new(commands, chain, events, out, view, status),
            rx,
        )
    }
    fn job(nonce: u64, expiry: u64) -> JobTransaction {
        JobTransaction {
            client_key: OwnerKeypair::from_seed(&[8; 32]).public_key().clone(),
            queue_fee: 1,
            base_fee: 1,
            v_exec: 1,
            v_da: 0,
            v_ref: 0,
            expiry_height: expiry,
            nonce,
            payload: JobPayload::ExactDot {
                xs: vec![1.0; DOT_LEN],
                ys: vec![1.0; DOT_LEN],
            },
            signature: unsigned(),
        }
    }
    #[test]
    fn publishing_rotates_past_a_full_unfundable_prefix() {
        let (mut actor, view) = actor();
        for nonce in 0..260u64 {
            let tx = job(nonce, 100);
            let (id, job_id) = compute_job_ids(&tx).unwrap();
            actor.push(id, job_id, tx);
        }
        let mut seen = HashSet::new();
        for _ in 0..3 {
            actor.publish_view();
            let v = view.borrow();
            assert_eq!(v.txs.len(), 128);
            seen.extend(v.txs.iter().map(|tx| tx.nonce));
        }
        assert_eq!(seen.len(), 260);
        actor.remove_where(|_| true);
        actor.publish_view();
        assert!(view.borrow().txs.is_empty());
        assert_eq!(actor.view_cursor, 0);
    }
    #[test]
    fn mempool_enforces_expiry_before_signature_work() {
        let (mut actor, _) = actor();
        let next = actor.next_height();
        assert!(matches!(
            actor.insert_tx(job(1, next + MAX_JOB_TTL + 1), Origin::Local),
            Err(MempoolReject::Invalid {
                code: "expiry_too_far",
                ..
            })
        ));
        let mut tx = job(2, next + MAX_JOB_TTL);
        OwnerKeypair::from_seed(&[8; 32])
            .sign_job(&mut tx, &actor.status_rx.borrow().genesis_id)
            .unwrap();
        assert!(actor.insert_tx(tx, Origin::Local).is_ok());
    }

    fn withdrawal(treasury: &chain::TreasuryKeypair, nonce: u64) -> InitialPoolWithdrawal {
        InitialPoolWithdrawal {
            expected_nonce: nonce,
            outputs: vec![wire::WithdrawalOutput {
                recipient: Digest([5; 64]),
                atoms: 1_000,
            }],
            fee: 10,
            ml_dsa_key: treasury.signer().public_key().clone(),
            slh_dsa_key: treasury.cosigner_public_key().clone(),
            ml_dsa_signature: unsigned(),
            slh_dsa_signature: chain::keys::unsigned_cosignature(),
        }
    }

    /// The policy check precedes the nonce window, which precedes any signature work;
    /// a spent nonce is a duplicate and a far one does not fit, neither penalized.
    #[test]
    fn withdrawals_meet_the_treasury_policy_and_the_nonce_window_before_signatures() {
        let treasury = chain::TreasuryKeypair::from_seeds(&[3; 32], &[4; 96]);
        let (mut disabled, _) = actor();
        assert!(matches!(
            disabled.insert_withdrawal(withdrawal(&treasury, 0), Origin::Local),
            Err(MempoolReject::Invalid {
                code: "not_treasury_key",
                ..
            })
        ));

        let mut genesis = wire::GenesisConfig::default_testnet(0);
        genesis.treasury_key_id = treasury.key_id();
        genesis.treasury_cosigner_key_id = treasury.cosigner_key_id();
        let mut snapshot = (*crate::chain_actor::test_snapshot_for(genesis)).clone();
        snapshot.initial_nonce = 3;
        let (mut actor, view) = actor_with(Arc::new(snapshot));
        assert_eq!(
            actor
                .insert_withdrawal(withdrawal(&treasury, 2), Origin::Local)
                .unwrap_err(),
            MempoolReject::Duplicate
        );
        assert_eq!(
            actor
                .insert_withdrawal(
                    withdrawal(&treasury, 3 + MAX_POOLED_WITHDRAWALS),
                    Origin::Local
                )
                .unwrap_err(),
            MempoolReject::Full
        );
        assert!(matches!(
            actor.insert_withdrawal(withdrawal(&treasury, 3), Origin::Local),
            Err(MempoolReject::Invalid {
                code: "bad_signature",
                ..
            })
        ));
        let mut empty = withdrawal(&treasury, 3);
        empty.outputs.clear();
        assert!(matches!(
            actor.insert_withdrawal(empty, Origin::Local),
            Err(MempoolReject::Invalid {
                code: "no_outputs",
                ..
            })
        ));
        assert!(view.borrow().withdrawals.is_empty());
    }
}
EOF

