/// Request body limit of `/api/submit_withdrawal`: a hex-encoded withdrawal with the
/// maximum number of outputs (about 75 KB) and room for the JSON around it.
const WITHDRAWAL_BODY_LIMIT: usize = 2 * wire::ENCODED_WITHDRAWAL_MAX_LEN + 4_096;
use crate::net::PeerManager;

const INDEX_HTML: &str = include_str!("../static/index.html");

#[derive(Clone)]
struct RpcState {
    status_rx: watch::Receiver<Arc<StatusSnapshot>>,
    mempool_view: watch::Receiver<Arc<MempoolView>>,
    chain_tx: mpsc::Sender<ChainCmd>,
    mempool_tx: mpsc::Sender<MempoolCmd>,
    engine: Arc<ConsensusEngine>,
    peer_manager: Arc<PeerManager>,
    signer: Arc<OwnerKeypair>,
}

/// Spawns the Axum HTTP server and returns the bound local address (§9.1).
#[allow(clippy::too_many_arguments)]
pub async fn spawn_rpc_server(
    listen_addr: SocketAddr,
    status_rx: watch::Receiver<Arc<StatusSnapshot>>,
    mempool_view: watch::Receiver<Arc<MempoolView>>,
    chain_tx: mpsc::Sender<ChainCmd>,
    mempool_tx: mpsc::Sender<MempoolCmd>,
    engine: Arc<ConsensusEngine>,
    peer_manager: Arc<PeerManager>,
    signer: Arc<OwnerKeypair>,
    mut shutdown_rx: watch::Receiver<bool>,
) -> std::io::Result<SocketAddr> {
    let state = RpcState {
        status_rx,
        mempool_view,
        chain_tx,
        mempool_tx,
        engine,
        peer_manager,
        signer,
    };
    let app = Router::new()
        .route("/", get(handle_index))
        .route("/api/status", get(handle_status))
        .route("/api/blocks", get(handle_blocks))
        .route("/api/submit_job", post(handle_submit_job))
        .layer(DefaultBodyLimit::max(65_536))
        .route(
            "/api/submit_withdrawal",
            post(handle_submit_withdrawal).layer(DefaultBodyLimit::max(WITHDRAWAL_BODY_LIMIT)),
        )
        .with_state(state);

    let listener = TcpListener::bind(listen_addr).await?;
    let local_addr = listener.local_addr()?;
    tokio::spawn(async move {
        let _ = axum::serve(listener, app)
            .with_graceful_shutdown(async move {
                while !*shutdown_rx.borrow() {
                    if shutdown_rx.changed().await.is_err() {
                        break;
                    }
                }
            })
            .await;
    });
    Ok(local_addr)
}

async fn handle_index() -> impl IntoResponse {
    (
        [(header::CACHE_CONTROL, HeaderValue::from_static("no-cache"))],
        Html(INDEX_HTML),
    )
}

// ---------------------------------------------------------------------------
// GET /api/status (§9.3)
// ---------------------------------------------------------------------------

#[derive(Serialize)]
struct StatusResponse {
    chain: ChainInfoDto,
    node: NodeInfoDto,
    tip: TipInfoDto,
    mining: MiningInfoDto,
    verification: VerificationInfoDto,
    mempool: MempoolInfoDto,
    ledger: LedgerInfoDto,
    commercial_consensus_weight: u64,
}

#[derive(Serialize)]
struct ChainInfoDto {
    name: String,
    chain_id: String,
    genesis_id: String,
    wire_protocol_id: u32,
    blocks_per_epoch: u64,
    target_block_secs: u64,
}

#[derive(Serialize)]
struct NodeInfoDto {
    owner_id: String,
    owner_key_id: String,
    peers: usize,
    uptime_secs: u64,
}

#[derive(Serialize)]
struct TipInfoDto {
    height: u64,
    block_id: String,
    time_bucket: u64,
    epoch: u64,
    cumulative_weight: String,
    seal_target: String,
    share_target: String,
    expected_attempts_per_seal: String,
    next_generator: GeneratorDto,
}

/// A diagnostic generator of the modulo-3 schedule (spec eq. 5.3).
#[derive(Serialize)]
struct GeneratorDto {
    id: u64,
    profile: Option<u32>,
    name: &'static str,
}

fn generator_dto(id: u64) -> GeneratorDto {
    let profile = u32::try_from(id)
        .ok()
        .and_then(GeneratorProfile::from_generator_id);
    GeneratorDto {
        id,
        profile: profile.map(GeneratorProfile::index),
        name: profile.map_or("none", |p| p.name()),
    }
}

#[derive(Serialize)]
struct MiningInfoDto {
    enabled: bool,
    threads: usize,
    attempts_per_sec: f64,
    shares_found: u64,
    seals_found: u64,
    /// Verified shares (own and gossiped) waiting for a block.
    share_pool: usize,
    /// `--mine-when-synced`: mining is enabled but waits for peers and sync.
    waiting_for_sync: bool,
}

#[derive(Serialize)]
struct VerificationInfoDto {
    /// Blocks in Stage A (signatures and tile recomputation).
    verifying_blocks: usize,
    /// Blocks waiting for a Stage A slot.
    queued_blocks: usize,
    /// Blocks kept for a retry because their time bucket is ahead of the local clock.
    deferred_blocks: usize,
    /// Blocks that entered Stage A since the node started.
    stage_a_started: u64,
    /// Blocks parked until their parent arrives.
    orphans: usize,
}

#[derive(Serialize)]
struct MempoolInfoDto {
    size: usize,
    withdrawals: usize,
}

#[derive(Serialize)]
struct CategoryBalanceDto {
    symbol: &'static str,
    name: String,
    atoms: String,
}

#[derive(Serialize)]
struct LedgerInfoDto {
    categories: Vec<CategoryBalanceDto>,
    total: String,
    supply_m: String,
    conserved: bool,
    issuance: IssuanceDto,
    initial_pool: InitialPoolDto,
    segregated_dust: String,
    fee_lots: usize,
    locked_fees: usize,
    booked_rewards: String,
    unbooked_release: String,
    open_jobs: usize,
}

/// Primary issuance (spec eqs. 7.19b–7.19g).
#[derive(Serialize)]
struct IssuanceDto {
    /// Block `k` of the next primary release, with its `i_k` and `m_k`.
    next_block: u64,
    next_initial: String,
    next_miner: String,
    initial_released: String,
    miner_released: String,
    initial_release_blocks: u64,
    miner_half_life_blocks: u64,
}

/// The InitialProtocolPool and its InitialValve (spec eqs. 7.19h–7.19j).
#[derive(Serialize)]
struct InitialPoolDto {
    /// Whether the genesis names treasury keys; without them no withdrawal verifies.
    treasury_enabled: bool,
    treasury_key_id: String,
    treasury_cosigner_key_id: String,
    next_nonce: u64,
    valve_window_blocks: u64,
    valve_limit: String,
    valve_rolling: String,
    valve_headroom: String,
}

async fn handle_status(State(state): State<RpcState>) -> Json<StatusResponse> {
    let snap = state.status_rx.borrow().clone();
    let (mempool_size, mempool_withdrawals) = {
        let view = state.mempool_view.borrow();
        (view.size, view.withdrawals.len())
    };
    let expected_attempts = u128::MAX / snap.tip.seal_target.0.max(1);
    let categories = StateCategory::ALL
        .iter()
        .map(|&c| CategoryBalanceDto {
            symbol: c.symbol(),
            name: format!("{c:?}"),
            atoms: snap.balances[c.index()].to_string(),
        })
        .collect();
    let supply_m = u128::from(TOTAL_SUPPLY.get());

    Json(StatusResponse {
        chain: ChainInfoDto {
            name: snap.chain_name.clone(),
            chain_id: format!("0x{:08x}", snap.chain_id),
            genesis_id: snap.genesis_id.to_hex(),
            wire_protocol_id: WIRE_PROTOCOL_ID,
            blocks_per_epoch: snap.blocks_per_epoch,
            target_block_secs: snap.target_block_secs,
        },
        node: NodeInfoDto {
            owner_id: snap.owner_id.to_string(),
            owner_key_id: snap.miner_key_id.to_hex(),
            peers: state.peer_manager.peer_count(),
            uptime_secs: snap.start_instant.elapsed().as_secs(),
        },
        tip: TipInfoDto {
            height: snap.tip.height,
            block_id: snap.tip.id.to_hex(),
            time_bucket: snap.tip.time_bucket,
            epoch: snap.epoch,
            cumulative_weight: snap.tip.cumulative_weight.to_string(),
            seal_target: snap.tip.seal_target.to_hex(),
            share_target: snap.tip.share_target.to_hex(),
            expected_attempts_per_seal: expected_attempts.to_string(),
            next_generator: generator_dto(snap.next_generator_id),
        },
        mining: MiningInfoDto {
            enabled: state.engine.is_enabled(),
            threads: state.engine.threads(),
            attempts_per_sec: (state.engine.attempts_per_sec() * 10.0).round() / 10.0,
            shares_found: state.engine.shares_found(),
            seals_found: state.engine.seals_found(),
            share_pool: snap.share_pool,
            waiting_for_sync: state.engine.is_enabled() && !state.engine.sync_gate_open(),
        },
        verification: VerificationInfoDto {
            verifying_blocks: snap.verifying_blocks,
            queued_blocks: snap.queued_blocks,
            deferred_blocks: snap.deferred_blocks,
            stage_a_started: snap.stage_a_started,
            orphans: snap.orphan_count,
        },
        mempool: MempoolInfoDto {
            size: mempool_size,
            withdrawals: mempool_withdrawals,
        },
        ledger: LedgerInfoDto {
            categories,
            total: snap.total.to_string(),
            supply_m: supply_m.to_string(),
            conserved: snap.total == supply_m,
            issuance: IssuanceDto {
                next_block: snap.next_release.block,
                next_initial: snap.next_release.initial.get().to_string(),
                next_miner: snap.next_release.miner.get().to_string(),
                initial_released: snap.initial_released.to_string(),
                miner_released: snap.miner_released.to_string(),
                initial_release_blocks: INITIAL_RELEASE_BLOCKS,
                miner_half_life_blocks: MINER_HALF_LIFE_BLOCKS,
            },
            initial_pool: InitialPoolDto {
                treasury_enabled: snap.genesis.treasury_key_id != Digest::ZERO
                    && snap.genesis.treasury_cosigner_key_id != Digest::ZERO,
                treasury_key_id: snap.genesis.treasury_key_id.to_hex(),
                treasury_cosigner_key_id: snap.genesis.treasury_cosigner_key_id.to_hex(),
                next_nonce: snap.initial_nonce,
                valve_window_blocks: INITIAL_VALVE_WINDOW,
                valve_limit: INITIAL_VALVE_LIMIT.get().to_string(),
                valve_rolling: snap.valve_rolling.to_string(),
                valve_headroom: snap.valve_headroom.to_string(),
            },
            segregated_dust: snap.segregated_dust.to_string(),
            fee_lots: snap.fee_lots,
            locked_fees: snap.locked_fees,
            booked_rewards: snap.booked_rewards.to_string(),
            unbooked_release: snap.unbooked_release.to_string(),
            open_jobs: snap.open_jobs,
        },
        commercial_consensus_weight: CONSENSUS_WEIGHT,
    })
}

// ---------------------------------------------------------------------------
// GET /api/blocks (§9.4)
// ---------------------------------------------------------------------------

#[derive(Deserialize)]
struct BlocksQuery {
    limit: Option<usize>,
    before: Option<u64>,
}

#[derive(Serialize)]
struct BlocksResponse {
    tip_height: u64,
    blocks: Vec<BlockSummaryDto>,
}

#[derive(Serialize)]
struct BlockSummaryDto {
    height: u64,
    block_id: String,
    parent_id: String,
    anchor_id: String,
    miner_owner: String,
    time_bucket: u64,
    attempt_nonce: String,
    generator: GeneratorDto,
    epoch: u64,
    seal_ticket: String,
    seal_weight: String,
    cumulative_weight: String,
    jobs: Vec<JobDto>,
    receipts: Vec<ReceiptDto>,
    shares: Vec<ShareDto>,
    withdrawals: Vec<WithdrawalDto>,
    header_share: bool,
    fee_transitions: Vec<FeeTransitionDto>,
    balances_after: BTreeMap<&'static str, String>,
    total_after: String,
}

#[derive(Serialize)]
struct JobDto {
    job_id: String,
    tx_id: String,
    executor_owner: String,
    deposit: String,
    queue_fee: String,
    base_fee: String,
}

#[derive(Serialize)]
struct ReceiptDto {
    job_id: String,
    result: String,
    executor_owner: String,
    admitted_at: u64,
}

#[derive(Serialize)]
struct ShareDto {
    work_id: String,
    owner: String,
    height: u64,
    weight: String,
}

#[derive(Serialize)]
struct WithdrawalDto {
    tx_id: String,
    nonce: u64,
    amount: String,
    fee: String,
    outputs: usize,
}

#[derive(Serialize)]
struct FeeTransitionDto {
    op: &'static str,
    #[serde(skip_serializing_if = "Option::is_none")]
    job_id: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    epoch: Option<u64>,
    /// Primary release: block `k`.
    #[serde(skip_serializing_if = "Option::is_none")]
    block: Option<u64>,
    /// InitialProtocolPool withdrawal: its nonce.
    #[serde(skip_serializing_if = "Option::is_none")]
    nonce: Option<u64>,
    delta: BTreeMap<&'static str, String>,
}

async fn handle_blocks(
    State(state): State<RpcState>,
    Query(q): Query<BlocksQuery>,
) -> Json<BlocksResponse> {
    let tip_height = state.status_rx.borrow().tip.height;
    let limit = q.limit.unwrap_or(20).min(100);
    let (tx, rx) = oneshot::channel();
    let cmd = ChainCmd::GetBlocks {
        before: q.before,
        limit,
        reply: tx,
    };
    let summaries = if state.chain_tx.send(cmd).await.is_ok() {
        rx.await.unwrap_or_default()
    } else {
        Vec::new()
    };
    Json(BlocksResponse {
        tip_height,
        blocks: summaries.into_iter().map(summary_to_dto).collect(),
    })
}

fn category_map<T: ToString>(values: &[T]) -> BTreeMap<&'static str, String> {
    StateCategory::ALL
        .iter()
        .zip(values)
        .map(|(c, v)| (c.symbol(), v.to_string()))
        .collect()
}

fn fee_transition_dto(ft: &FeeTransition) -> FeeTransitionDto {
    let delta: &CategoryDelta = ft.delta();
    let mut dto = FeeTransitionDto {
        op: "",
        job_id: None,
        epoch: None,
        block: None,
        nonce: None,
        delta: category_map(delta),
    };
    match ft {
        FeeTransition::PrimaryRelease { block, .. } => {
            dto.op = "PrimaryRelease";
            dto.block = Some(*block);
        }
        FeeTransition::ReserveMature { epoch, .. } => {
            dto.op = "ReserveMature";
            dto.epoch = Some(*epoch);
        }
        FeeTransition::FwReward { epoch, .. } => {
            dto.op = "FwReward";
            dto.epoch = Some(*epoch);
        }
        FeeTransition::EpochBooked { epoch, .. } => {
            dto.op = "EpochBooked";
            dto.epoch = Some(*epoch);
        }
        FeeTransition::ResultSettle { job_id, .. } => {
            dto.op = "ResultSettle";
            dto.job_id = Some(job_id.to_string());
        }
        FeeTransition::EscrowFundAndQueue { job_id, .. } => {
            dto.op = "EscrowFundAndQueue";
            dto.job_id = Some(job_id.to_string());
        }
        FeeTransition::JobAdmitAndLease { job_id, .. } => {
            dto.op = "JobAdmitAndLease";
            dto.job_id = Some(job_id.to_string());
        }
        FeeTransition::InitialPoolWithdrawal { nonce, .. } => {
            dto.op = "InitialPoolWithdrawal";
            dto.nonce = Some(*nonce);
        }
    }
    dto
}

fn summary_to_dto(s: BlockSummary) -> BlockSummaryDto {
    BlockSummaryDto {
        height: s.height,
        block_id: s.block_id.to_hex(),
        parent_id: s.parent_id.to_hex(),
        anchor_id: s.anchor_id.to_hex(),
        miner_owner: s.miner_key_id.to_hex(),
        time_bucket: s.time_bucket,
        attempt_nonce: s.attempt_nonce.to_string(),
        generator: generator_dto(s.generator_id),
        epoch: s.epoch,
        seal_ticket: s.seal_ticket.to_hex(),
        seal_weight: s.seal_weight.to_string(),
        cumulative_weight: s.cumulative_weight.to_string(),
        jobs: s
            .jobs
            .into_iter()
            .map(|j| JobDto {
                job_id: j.job_id.to_string(),
                tx_id: j.tx_id.to_hex(),
                executor_owner: j.executor_owner.to_hex(),
                deposit: j.deposit.to_string(),
                queue_fee: j.queue_fee.to_string(),
                base_fee: j.base_fee.to_string(),
            })
            .collect(),
        receipts: s
            .receipts
            .into_iter()
            .map(|r| ReceiptDto {
                job_id: r.job_id.to_string(),
                result: r.result.to_string(),
                executor_owner: r.executor_owner.to_hex(),
                admitted_at: r.admitted_at,
            })
            .collect(),
        shares: s
            .shares
            .into_iter()
            .map(|sh| ShareDto {
                work_id: sh.work_id.to_hex(),
                owner: sh.owner.to_hex(),
                height: sh.height,
                weight: sh.weight.to_string(),
            })
            .collect(),
        withdrawals: s
            .withdrawals
            .into_iter()
            .map(|w| WithdrawalDto {
                tx_id: w.tx_id.to_hex(),
                nonce: w.nonce,
                amount: w.amount.to_string(),
                fee: w.fee.to_string(),
                outputs: w.outputs,
            })
            .collect(),
        header_share: s.header_share,
        fee_transitions: s.fee_transitions.iter().map(fee_transition_dto).collect(),
        balances_after: category_map(&s.balances_after),
        total_after: s.total_after.to_string(),
    }
}

// ---------------------------------------------------------------------------
// POST /api/submit_job (§9.5)
// ---------------------------------------------------------------------------

/// The job is signed with this node's ML-DSA-87 key, which becomes its `client_key`.
#[derive(Deserialize)]
struct SubmitJobRequest {
    queue_fee: Option<String>,
    base_fee: Option<String>,
    v_exec: Option<String>,
    v_da: Option<String>,
    v_ref: Option<String>,
    expiry_blocks: Option<u64>,
    nonce: Option<String>,
    payload: SubmitJobPayloadDto,
}

#[derive(Deserialize)]
struct SubmitJobPayloadDto {
    #[serde(rename = "type")]
    payload_type: String,
    xs: Vec<i64>,
    ys: Vec<i64>,
}

#[derive(Serialize)]
struct SubmitJobResponse {
    tx_id: String,
    job_id: String,
    client_key_id: String,
    deposit: String,
    total_charge: String,
    expected_result: String,
    expiry_height: u64,
    status: &'static str,
}

#[derive(Serialize)]
struct RpcErrorBody {
    error: &'static str,
    message: String,
}

/// An RPC error: HTTP status, stable error code and message (§9.1).
struct ApiError {
    status: StatusCode,
    code: &'static str,
    message: String,
}

impl ApiError {
    fn new(status: StatusCode, code: &'static str, message: impl Into<String>) -> Self {
        Self {
            status,
            code,
            message: message.into(),
        }
    }

    fn bad_request(message: impl Into<String>) -> Self {
        Self::new(StatusCode::BAD_REQUEST, "bad_request", message)
    }

    fn invalid_payload(message: impl Into<String>) -> Self {
        Self::new(StatusCode::BAD_REQUEST, "invalid_payload", message)
    }
}

impl IntoResponse for ApiError {
    fn into_response(self) -> Response {
        let body = RpcErrorBody {
            error: self.code,
            message: self.message,
        };
        (self.status, Json(body)).into_response()
    }
}

fn parse_u64_field(opt: Option<String>, default: u64, name: &str) -> Result<u64, ApiError> {
    match opt {
        Some(s) => s
            .parse::<u64>()
            .map_err(|_| ApiError::bad_request(format!("{name} must be a decimal u64 string"))),
        None => Ok(default),
    }
}

/// Largest integer magnitude that converts to `f64` exactly.
const MAX_EXACT_INT: u64 = (1u64 << 53) - 1;

fn to_operands(values: &[i64]) -> Result<Vec<f64>, ApiError> {
    values
        .iter()
        .map(|&v| {
            if v.unsigned_abs() > MAX_EXACT_INT {
                Err(ApiError::invalid_payload("operand magnitude exceeds 2^53"))
            } else {
                Ok(v as f64)
            }
        })
        .collect()
}

/// Builds the job for `client_key` from the request, still unsigned.
fn build_job(
    req: SubmitJobRequest,
    tip_height: u64,
    client_key: PublicKey,
) -> Result<JobTransaction, ApiError> {
    // The defaults charge 1 PLAU: every block may debit U / 16, and U only fills
    // with the miner rewards paid at each epoch boundary.
    let queue_fee = parse_u64_field(req.queue_fee, 1_000_000, "queue_fee")?;
    let base_fee = parse_u64_field(req.base_fee, 10_000_000, "base_fee")?;
    let v_exec = parse_u64_field(req.v_exec, 79_000_000, "v_exec")?;
    let v_da = parse_u64_field(req.v_da, 5_000_000, "v_da")?;
    let v_ref = parse_u64_field(req.v_ref, 5_000_000, "v_ref")?;

    let expiry_blocks = req.expiry_blocks.unwrap_or(wire::MAX_JOB_TTL);
    if !(1..=wire::MAX_JOB_TTL).contains(&expiry_blocks) {
        return Err(ApiError::bad_request("expiry_blocks must be in 1..=120"));
    }
    let nonce = match req.nonce {
        Some(s) => s
            .parse::<u64>()
            .map_err(|_| ApiError::bad_request("nonce must be a decimal u64 string"))?,
        None => {
            let nanos = SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap_or_default()
                .as_nanos() as u64;
            nanos ^ 0x9e37_79b9_7f4a_7c15
        }
    };

    if req.payload.payload_type != "exact_dot" {
        return Err(ApiError::invalid_payload(
            "payload.type must be 'exact_dot'",
        ));
    }
    if req.payload.xs.len() != DOT_LEN || req.payload.ys.len() != DOT_LEN {
        return Err(ApiError::invalid_payload(format!(
            "xs and ys must each have {DOT_LEN} elements"
        )));
    }
    Ok(JobTransaction {
        client_key,
        queue_fee,
        base_fee,
        v_exec,
        v_da,
        v_ref,
        expiry_height: tip_height.saturating_add(expiry_blocks),
        nonce,
        payload: JobPayload::ExactDot {
            xs: to_operands(&req.payload.xs)?,
            ys: to_operands(&req.payload.ys)?,
        },
        signature: unsigned(),
    })
}

async fn handle_submit_job(
    State(state): State<RpcState>,
    Json(req): Json<SubmitJobRequest>,
) -> Result<(StatusCode, Json<SubmitJobResponse>), ApiError> {
    let (tip_height, genesis_id) = {
        let snap = state.status_rx.borrow();
        (snap.tip.height, snap.genesis_id)
    };
    let mut tx = build_job(req, tip_height, state.signer.public_key().clone())?;
    let signer = state.signer.clone();
    let tx =
        tokio::task::spawn_blocking(move || signer.sign_job(&mut tx, &genesis_id).map(|()| tx))
            .await
            .map_err(|e| {
                ApiError::new(StatusCode::INTERNAL_SERVER_ERROR, "internal", e.to_string())
            })?
            .map_err(|e| ApiError::new(StatusCode::INTERNAL_SERVER_ERROR, "internal", e))?;
    let expiry_height = tx.expiry_height;
    let client_key_id = owner_key_id(&tx.client_key);

    let unavailable = |what: &str| {
        ApiError::new(
            StatusCode::SERVICE_UNAVAILABLE,
            "mempool_full",
            format!("mempool {what}"),
        )
    };
    let (reply_tx, reply_rx) = oneshot::channel();
    let cmd = MempoolCmd::Insert {
        tx,
        origin: Origin::Rpc,
        reply: reply_tx,
    };
    state
        .mempool_tx
        .send(cmd)
        .await
        .map_err(|_| unavailable("actor unavailable"))?;
    let ok = match reply_rx
        .await
        .map_err(|_| unavailable("reply channel closed"))?
    {
        Ok(ok) => ok,
        Err(MempoolReject::Duplicate) => {
            return Err(ApiError::new(
                StatusCode::CONFLICT,
                "duplicate",
                "job transaction already in mempool",
            ));
        }
        Err(MempoolReject::Full) => return Err(unavailable("is full")),
        Err(MempoolReject::Invalid { code, message }) => {
            return Err(ApiError::new(StatusCode::BAD_REQUEST, code, message));
        }
    };
    Ok((
        StatusCode::ACCEPTED,
        Json(SubmitJobResponse {
            tx_id: ok.tx_id.to_hex(),
            job_id: ok.job_id.to_string(),
            client_key_id: client_key_id.to_hex(),
            deposit: ok.deposit.to_string(),
            total_charge: ok.total_charge.to_string(),
            expected_result: ok.expected_result.to_string(),
            expiry_height,
            status: "pending",
        }),
    ))
}

// ---------------------------------------------------------------------------
// POST /api/submit_withdrawal
// ---------------------------------------------------------------------------

/// A treasury-signed InitialProtocolPool withdrawal, as produced by
/// `plauthium-node treasury withdraw`: its canonical encoding in hex. The node never
/// holds treasury keys; it only checks and relays what the treasury signed.
#[derive(Deserialize)]
struct SubmitWithdrawalRequest {
    withdrawal: String,
}

#[derive(Serialize)]
struct SubmitWithdrawalResponse {
    tx_id: String,
    expected_nonce: u64,
    amount: String,
    fee: String,
    status: &'static str,
}

async fn handle_submit_withdrawal(
    State(state): State<RpcState>,
    Json(req): Json<SubmitWithdrawalRequest>,
) -> Result<(StatusCode, Json<SubmitWithdrawalResponse>), ApiError> {
    let withdrawal = InitialPoolWithdrawal::from_hex(&req.withdrawal)
        .map_err(|e| ApiError::bad_request(format!("withdrawal: {e}")))?;
    let unavailable = |what: &str| {
        ApiError::new(
            StatusCode::SERVICE_UNAVAILABLE,
            "mempool_full",
            format!("withdrawal pool {what}"),
        )
    };
    let (reply_tx, reply_rx) = oneshot::channel();
    let cmd = MempoolCmd::InsertWithdrawal {
        withdrawal: Box::new(withdrawal),
        origin: Origin::Rpc,
        reply: reply_tx,
    };
    state
        .mempool_tx
        .send(cmd)
        .await
        .map_err(|_| unavailable("actor unavailable"))?;
    let ok = match reply_rx
        .await
        .map_err(|_| unavailable("reply channel closed"))?
    {
        Ok(ok) => ok,
        Err(MempoolReject::Duplicate) => {
            return Err(ApiError::new(
                StatusCode::CONFLICT,
                "duplicate",
                "withdrawal already pooled, or its nonce is spent",
            ));
        }
        Err(MempoolReject::Full) => {
            return Err(unavailable("is full, or the nonce is too far ahead"));
        }
        Err(MempoolReject::Invalid { code, message }) => {
            return Err(ApiError::new(StatusCode::BAD_REQUEST, code, message));
        }
    };
    Ok((
        StatusCode::ACCEPTED,
        Json(SubmitWithdrawalResponse {
            tx_id: ok.tx_id.to_hex(),
            expected_nonce: ok.expected_nonce,
            amount: ok.amount.to_string(),
            fee: ok.fee.to_string(),
            status: "pending",
        }),
    ))
}
EOF

cat << 'EOF' > node/src/share_pool.rs
//! Share pool (`node::share_pool`, §6.7): verified share proofs waiting for a block.
//!
//! It holds this node's own shares and the gossiped shares that passed every check,
//! signature and work included, one per `work_id`. Templates pick from it
//! (`chain::build_template`), so any miner can include any owner's share.

use std::collections::HashSet;

use chain::SignedShare;
use wire::Digest;

/// Maximum pooled shares. The inclusion window holds far fewer in a healthy network
/// (about `share_ratio` shares per height).
pub const SHARE_POOL_CAPACITY: usize = 1_024;

/// Verified shares by `work_id`.
pub struct SharePool {
    shares: Vec<SignedShare>,
    work_ids: HashSet<Digest>,
    capacity: usize,
}

impl SharePool {
    /// An empty pool holding at most `capacity` shares.
    pub fn new(capacity: usize) -> Self {
        Self {
            shares: Vec::new(),
            work_ids: HashSet::new(),
            capacity,
        }
    }

    /// Number of pooled shares.
    pub fn len(&self) -> usize {
        self.shares.len()
    }

    /// Whether the pool is empty.
    pub fn is_empty(&self) -> bool {
        self.shares.is_empty()
    }

    /// Whether a share with this `work_id` is pooled.
    pub fn contains(&self, work_id: &Digest) -> bool {
        self.work_ids.contains(work_id)
    }

    /// The pooled shares, in no particular order.
    pub fn as_slice(&self) -> &[SignedShare] {
        &self.shares
    }

    /// Adds a share; returns false if its `work_id` is already pooled. A full pool
    /// evicts its oldest share (lowest height, then lowest `work_id`), unless the new
    /// share would be that oldest one, in which case it is not added.
    pub fn insert(&mut self, share: SignedShare) -> bool {
        let work_id = share.proof().work_id;
        if self.work_ids.contains(&work_id) {
            return false;
        }
        if self.shares.len() >= self.capacity {
            let key = |s: &SignedShare| (s.proof().context.height, s.proof().work_id);
            let Some(oldest) = self
                .shares
                .iter()
                .enumerate()
                .min_by_key(|(_, s)| key(s))
                .map(|(i, _)| i)
            else {
                return false;
            };
            if key(&share) <= key(&self.shares[oldest]) {
                return false;
            }
            let evicted = self.shares.swap_remove(oldest);
            self.work_ids.remove(&evicted.proof().work_id);
        }
        self.work_ids.insert(work_id);
        self.shares.push(share);
        true
    }

    /// Drops the shares mined below `min_height` (outside the inclusion window) and
    /// those for which `registered` holds (already included on the canonical chain).
    pub fn prune(&mut self, min_height: u64, registered: impl Fn(&Digest) -> bool) {
        let work_ids = &mut self.work_ids;
        self.shares.retain(|s| {
            let keep = s.proof().context.height >= min_height && !registered(&s.proof().work_id);
            if !keep {
                work_ids.remove(&s.proof().work_id);
            }
            keep
        });
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use chain::OwnerKeypair;
    use chain::keys::unsigned;
    use wire::{FwContext, ShareProof, Target};

    fn share(owner: &OwnerKeypair, height: u64, tag: u8) -> SignedShare {
        let zero = Digest::ZERO;
        let mut proof = ShareProof {
            context: FwContext {
                chain_id: 0,
                genesis_id: zero,
                protocol_id: 0,
                crypto_suite_id: 0,
                program_id: zero,
                air_id: zero,
                generator_id: 0,
                parent_canonical_id: zero,
                stable_anchor_id: zero,
                height,
                miner_policy_digest: zero,
                payout_policy_digest: zero,
                attempt_nonce: 0,
                body_core_root: zero,
                parent_derived_difficulty_context: zero,
                time_bucket: 0,
            },
            owner_key: owner.public_key().clone(),
            output_root: zero,
            work_id: Digest([tag; 64]),
            share_ticket: zero,
            share_target: Target(1 << 120),
            signature: unsigned(),
        };
        owner.sign_share(&mut proof).unwrap();
        SignedShare::verify(proof).unwrap()
    }

    #[test]
    fn dedupes_by_work_id_evicts_oldest_and_prunes() {
        let owner = OwnerKeypair::from_seed(&[1; 32]);
        let mut pool = SharePool::new(3);
        assert!(pool.insert(share(&owner, 5, 1)));
        assert!(!pool.insert(share(&owner, 5, 1)), "one share per work_id");
        assert!(pool.insert(share(&owner, 3, 2)));
        assert!(pool.insert(share(&owner, 7, 3)));
        assert_eq!(pool.len(), 3);

        // Full: a share older than everything pooled is not added...
        assert!(!pool.insert(share(&owner, 2, 4)));
        // ...a newer one evicts the oldest (height 3).
        assert!(pool.insert(share(&owner, 6, 5)));
        assert!(!pool.contains(&Digest([2; 64])));
        assert!(pool.contains(&Digest([5; 64])));

        // Pruning: below the window, or already registered on the chain.
        pool.prune(6, |w| *w == Digest([3; 64]));
        let left: Vec<Digest> = pool.as_slice().iter().map(|s| s.proof().work_id).collect();
        assert_eq!(left, vec![Digest([5; 64])]);
        assert!(!pool.contains(&Digest([1; 64])));
        assert!(
            pool.insert(share(&owner, 5, 1)),
            "a pruned work_id may return"
        );
    }
}
EOF

cat << 'EOF' > node/src/store.rs
//! Append-only block log persistence (`node::store`, §8.7).

use std::fs::{File, OpenOptions};
use std::io::{Read, Seek, SeekFrom, Write};
use std::path::Path;

use tracing::{info, warn};
use wire::{Block, MAX_FRAME_BYTES, codec};

/// Append-only writer for `blocks.log`.
pub struct BlockLogWriter {
    file: File,
}

impl BlockLogWriter {
    /// Appends a length-delimited (`u32` BE) encoded `Block`.
    pub fn append(&mut self, block: &Block) -> std::io::Result<()> {
        let bytes = codec::encode(block)
            .map_err(|e| std::io::Error::new(std::io::ErrorKind::InvalidData, e))?;
        let len = u32::try_from(bytes.len())
            .map_err(|_| std::io::Error::new(std::io::ErrorKind::InvalidData, "block too large"))?;
        let mut record = Vec::with_capacity(4 + bytes.len());
        record.extend_from_slice(&len.to_be_bytes());
        record.extend_from_slice(&bytes);
        self.file.write_all(&record)?;
        self.file.flush()
    }

    /// Flushes and fsyncs the underlying file.
    pub fn flush_and_sync(&mut self) -> std::io::Result<()> {
        self.file.flush()?;
        self.file.sync_all()
    }
}

/// Opens and replays `<data-dir>/blocks.log` (§8.7).
pub struct BlockStore;

impl BlockStore {
    /// Opens `blocks.log` (creating it if needed), reads every complete record, cuts off
    /// a truncated or corrupt tail, and returns the writer positioned at the end.
    pub fn open(path: &Path) -> std::io::Result<(BlockLogWriter, Vec<Block>)> {
        let mut file = OpenOptions::new()
            .create(true)
            .read(true)
            .write(true)
            .truncate(false)
            .open(path)?;
        let file_len = file.metadata()?.len();
        file.seek(SeekFrom::Start(0))?;

        let mut blocks = Vec::new();
        let mut valid_offset: u64 = 0;
        loop {
            let mut len_buf = [0u8; 4];
            match file.read_exact(&mut len_buf) {
                Ok(()) => {}
                Err(e) if e.kind() == std::io::ErrorKind::UnexpectedEof => break,
                Err(e) => return Err(e),
            }
            let frame_len = u32::from_be_bytes(len_buf) as usize;
            if frame_len == 0 || frame_len > MAX_FRAME_BYTES {
                warn!(
                    offset = valid_offset,
                    frame_len, "Invalid record length in blocks.log; truncating"
                );
                break;
            }
            let mut buf = vec![0u8; frame_len];
            match file.read_exact(&mut buf) {
                Ok(()) => {}
                Err(e) if e.kind() == std::io::ErrorKind::UnexpectedEof => {
                    warn!(
                        offset = valid_offset,
                        "Truncated trailing record in blocks.log; cutting it off"
                    );
                    break;
                }
                Err(e) => return Err(e),
            }
            match codec::decode::<Block>(&buf) {
                Ok(block) => {
                    blocks.push(block);
                    valid_offset += 4 + frame_len as u64;
                }
                Err(err) => {
                    warn!(offset = valid_offset, error = %err, "Corrupt record in blocks.log; truncating");
                    break;
                }
            }
        }

        if valid_offset < file_len {
            file.set_len(valid_offset)?;
        }
        file.seek(SeekFrom::End(0))?;
        if !blocks.is_empty() {
            info!(
                count = blocks.len(),
                "Loaded persisted blocks from blocks.log"
            );
        }
        Ok((BlockLogWriter { file }, blocks))
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use wire::{BlockBody, BlockHeader, Digest, FwContext, PUBLIC_KEY_LEN, PublicKey, Target};

    fn block(height: u64) -> Block {
        let d = Digest([height as u8; 64]);
        Block {
            header: BlockHeader {
                context: FwContext {
                    chain_id: 1,
                    genesis_id: d,
                    protocol_id: 2,
                    crypto_suite_id: 1,
                    program_id: d,
                    air_id: d,
                    generator_id: 2,
                    parent_canonical_id: d,
                    stable_anchor_id: d,
                    height,
                    miner_policy_digest: d,
                    payout_policy_digest: d,
                    attempt_nonce: 0,
                    body_core_root: d,
                    parent_derived_difficulty_context: d,
                    time_bucket: 0,
                },
                output_root: d,
                work_id: d,
                block_id: d,
                share_ticket: d,
                seal_ticket: d,
                seal_target: Target(u128::MAX),
                share_target: Target(u128::MAX),
                miner_key: PublicKey::from_slice(&[height as u8; PUBLIC_KEY_LEN]).unwrap(),
                signature: chain::keys::unsigned(),
            },
            body: BlockBody {
                jobs: vec![],
                shares: vec![],
                withdrawals: vec![],
                leases: vec![],
                receipts: vec![],
                fee_transitions: vec![],
                ledger_digest: d,
            },
        }
    }

    #[test]
    fn log_round_trips_and_cuts_a_torn_tail() {
        let dir = std::env::temp_dir().join(format!("plau-store-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("blocks.log");
        let _ = std::fs::remove_file(&path);

        let (mut writer, loaded) = BlockStore::open(&path).unwrap();
        assert!(loaded.is_empty());
        writer.append(&block(1)).unwrap();
        writer.append(&block(2)).unwrap();
        writer.flush_and_sync().unwrap();
        drop(writer);
        let good_len = std::fs::metadata(&path).unwrap().len();

        // Simulate a crash in the middle of a third record.
        let mut f = OpenOptions::new().append(true).open(&path).unwrap();
        f.write_all(&[0, 0, 4, 0, 1, 2, 3]).unwrap();
        drop(f);

        let (mut writer, loaded) = BlockStore::open(&path).unwrap();
        assert_eq!(loaded, vec![block(1), block(2)]);
        assert_eq!(std::fs::metadata(&path).unwrap().len(), good_len);
        writer.append(&block(3)).unwrap();
        drop(writer);
        let (_, loaded) = BlockStore::open(&path).unwrap();
        assert_eq!(loaded.len(), 3);
        let _ = std::fs::remove_dir_all(&dir);
    }
}
