    <span>Verifying: <b id="h-verifying">0</b> (+<b id="h-queued">0</b> queued)</span>
  </div>
</header>

<main>
  <section class="card">
    <h2>
      <span>Ledger State — 10 Disjoint Transparent Balance Categories</span>
      <span id="inv-badge" class="badge ok">Σ = M = 1,500,000,000,000,000 ✓</span>
    </h2>
    <div id="stack-bar" class="stack-bar"></div>
    <table>
      <thead>
        <tr>
          <th>Symbol</th>
          <th>Category</th>
          <th class="num">Atoms</th>
          <th class="num">PLAU (10^8 atoms)</th>
          <th class="num">Share (ppm)</th>
          <th>Log10 Scale</th>
        </tr>
      </thead>
      <tbody id="cat-tbody"></tbody>
    </table>
    <div class="sub-stats">
      <span>Segregated Dust: <b id="s-dust">-</b> atoms</span>
      <span>Fee Lots (R_a): <b id="s-lots">-</b></span>
      <span>Locked Fees (R_l): <b id="s-locked">-</b></span>
      <span>Booked Rewards: <b id="s-booked">-</b> atoms</span>
      <span>Unbooked Miner Release: <b id="s-unbooked">-</b> atoms</span>
      <span>Open Jobs: <b id="s-openjobs">-</b></span>
      <span>SciVM Consensus Weight: <b id="s-cw">0</b></span>
    </div>
    <div class="sub-stats">
      <span>Next Primary Release: block <b id="s-rel-block">-</b>,
        R_I→U_initial <b id="s-rel-initial">-</b>, R_M→P_pending <b id="s-rel-miner">-</b> atoms</span>
      <span>Released: initial <b id="s-initial-released">-</b>, miner <b id="s-miner-released">-</b> atoms</span>
    </div>
    <div class="sub-stats">
      <span>InitialValve (<b id="s-valve-window">720</b> blocks): <b id="s-valve-rolling">-</b> /
        <b id="s-valve-limit">-</b> atoms</span>
      <span>Next Pool Nonce: <b id="s-pool-nonce">-</b></span>
      <span>Treasury: <b id="s-treasury">-</b></span>
    </div>
  </section>

  <div class="grid-2">
    <section class="card">
      <h2>Live Block Feed (latest 20)</h2>
      <table>
        <thead>
          <tr>
            <th>Height</th>
            <th>BlockID</th>
            <th>Miner</th>
            <th class="num">Jobs</th>
            <th class="num">Receipts</th>
            <th class="num">Shares</th>
            <th class="num">Gen</th>
            <th class="num">ΔU (atoms)</th>
            <th class="num">ΔR_l (atoms)</th>
            <th class="num">Δt</th>
          </tr>
        </thead>
        <tbody id="blocks-tbody"></tbody>
      </table>
    </section>

    <section class="card">
      <h2>Submit SciVM Ozaki-II Commercial Job (512-dim ExactDot)</h2>
      <p style="font-size:12px;margin:0 0 8px;">Jobs are signed with this node's ML-DSA-87 miner key.</p>
      <div class="form-grid">
        <div><label for="f-qfee">Queue Fee (PLAU)</label><input id="f-qfee" value="0.01"></div>
        <div><label for="f-bfee">Base Fee (PLAU)</label><input id="f-bfee" value="0.1"></div>
        <div><label for="f-vexec">v_exec (PLAU)</label><input id="f-vexec" value="0.79"></div>
        <div><label for="f-vda">v_da (PLAU)</label><input id="f-vda" value="0.05"></div>
        <div><label for="f-vref">v_ref (PLAU)</label><input id="f-vref" value="0.05"></div>
        <div><label for="f-seed">Operand Seed</label><input id="f-seed" value="20261018"></div>
      </div>
      <div class="btn-row">
        <button type="button" class="secondary" id="btn-gen">Generate 512 Operands</button>
        <button type="button" id="btn-submit">Submit Job</button>
      </div>
      <div class="sub-stats">
        <span>Local BigInt Dot Product: <b id="local-dot">-</b></span>
        <span>Server Expected Result: <b id="server-dot">-</b></span>
      </div>
      <div id="submit-msg" style="margin-top:8px;font-size:12px;" class="mono"></div>

      <h2 style="margin-top:18px;">My Submitted Jobs</h2>
      <table>
        <thead>
          <tr>
            <th>Job ID</th>
            <th>Status</th>
            <th class="num">Reference Dot</th>
            <th class="num">Settled Result</th>
          </tr>
        </thead>
        <tbody id="myjobs-tbody"></tbody>
      </table>
    </section>
  </div>
</main>

<script>
(function() {
  const SUPPLY_M = 1500000000000000n;
  const LOG_M = Math.log10(1 + Number(SUPPLY_M));
  const COLORS = ["#2563eb", "#0ea5e9", "#d97706", "#94a3b8", "#a855f7", "#10b981", "#f59e0b", "#ec4899", "#64748b", "#475569"];
  const INACTIVE = new Set(["B_bond", "V_L2"]);

  let lastTipHeight = -1;
  const knownHeights = new Set();
  const expandedHeights = new Set();
  let latestBlocks = [];
  let xs = [];
  let ys = [];
  let localDot = 0n;
  let myJobs = loadMyJobs();

  function loadMyJobs() {
    try {
      const raw = localStorage.getItem("plauthium_my_jobs");
      const parsed = raw ? JSON.parse(raw) : [];
      return Array.isArray(parsed) ? parsed : [];
    } catch (_) {
      return [];
    }
  }
  function saveMyJobs() {
    try {
      localStorage.setItem("plauthium_my_jobs", JSON.stringify(myJobs));
    } catch (_) {}
  }

  function esc(value) {
    return String(value).replace(/[&<>"']/g, ch => ({
      "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;"
    })[ch]);
  }

  // Owners are 128-hex-character ML-DSA-87 key ids; show their first 12 characters.
  function shortKey(keyId) {
    const s = String(keyId || "");
    return s.length > 12 ? s.slice(0, 12) + ".." : s;
  }

  function groupBigInt(valStr) {
    const s = String(valStr);
    const neg = s.startsWith("-");
    const digits = neg ? s.slice(1) : s;
    const out = digits.replace(/\B(?=(\d{3})+(?!\d))/g, ",");
    return neg ? "-" + out : out;
  }

  function atomsToPlau(atomsStr) {
    const a = BigInt(atomsStr);
    const whole = a / 100000000n;
    const frac = (a % 100000000n).toString().padStart(8, "0");
    return groupBigInt(whole.toString()) + "." + frac;
  }

  function plauToAtoms(plauStr) {
    const s = plauStr.trim();
    if (!/^\d+(\.\d{1,8})?$/.test(s)) throw new Error("Invalid PLAU amount: " + s);
    const parts = s.split(".");
    const whole = BigInt(parts[0]) * 100000000n;
    const frac = parts[1] ? BigInt(parts[1].padEnd(8, "0")) : 0n;
    return (whole + frac).toString();
  }

  // xorshift64* stream; operands stay in [-(2^23 - 1), 2^23 - 1].
  function generateOperands() {
    let seed = BigInt(document.getElementById("f-seed").value || "1") & 0xffffffffffffffffn;
    if (seed === 0n) seed = 1n;
    function nextRand() {
      seed ^= seed >> 12n;
      seed = (seed ^ (seed << 25n)) & 0xffffffffffffffffn;
      seed ^= seed >> 27n;
      const r = (seed * 2685821657736338717n) & 0xffffffffffffffffn;
      return Number(r & 0xffffffn) - 8388607;
    }
    xs = [];
    ys = [];
    localDot = 0n;
    for (let i = 0; i < 512; i++) {
      const a = Math.max(-8388607, Math.min(8388607, nextRand()));
      const b = Math.max(-8388607, Math.min(8388607, nextRand()));
      xs.push(a);
      ys.push(b);
      localDot += BigInt(a) * BigInt(b);
    }
    document.getElementById("local-dot").textContent = groupBigInt(localDot.toString());
  }

  document.getElementById("btn-gen").addEventListener("click", generateOperands);

  document.getElementById("btn-submit").addEventListener("click", async function() {
    const msgEl = document.getElementById("submit-msg");
    msgEl.textContent = "Submitting...";
    try {
      const body = {
        queue_fee: plauToAtoms(document.getElementById("f-qfee").value),
        base_fee: plauToAtoms(document.getElementById("f-bfee").value),
        v_exec: plauToAtoms(document.getElementById("f-vexec").value),
        v_da: plauToAtoms(document.getElementById("f-vda").value),
        v_ref: plauToAtoms(document.getElementById("f-vref").value),
        expiry_blocks: 120,
        payload: { type: "exact_dot", xs: xs, ys: ys }
      };
      const resp = await fetch("/api/submit_job", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify(body)
      });
      const text = await resp.text();
      let data;
      try {
        data = JSON.parse(text);
      } catch (_) {
        msgEl.textContent = "Error (HTTP " + resp.status + "): " + text;
        return;
      }
      if (!resp.ok) {
        msgEl.textContent = "Error (" + data.error + "): " + data.message;
        return;
      }
      document.getElementById("server-dot").textContent = groupBigInt(data.expected_result);
      const match = BigInt(data.expected_result) === localDot;
      msgEl.textContent = "Accepted job_id=" + data.job_id + " (Ozaki-II match=" + (match ? "YES ✓" : "NO ✗") + ")";
      myJobs.unshift({
        job_id: data.job_id,
        tx_id: data.tx_id,
        ref_dot: localDot.toString(),
        expected_result: data.expected_result
      });
      myJobs = myJobs.slice(0, 25);
      saveMyJobs();
      renderMyJobs();
    } catch (e) {
      msgEl.textContent = "Submit failed: " + e.message;
    }
  });

  function renderLedger(ledger) {
    const stackEl = document.getElementById("stack-bar");
    const tbody = document.getElementById("cat-tbody");
    stackEl.innerHTML = "";
    tbody.innerHTML = "";

    let sum = 0n;
    ledger.categories.forEach((c, idx) => {
      const atoms = BigInt(c.atoms);
      sum += atoms;
      const pct = Number((atoms * 1000000n) / SUPPLY_M) / 10000;
      const seg = document.createElement("div");
      seg.className = "stack-seg";
      seg.style.background = COLORS[idx % COLORS.length];
      seg.style.width = pct + "%";
      if (atoms > 0n) seg.style.minWidth = "2px";
      seg.title = c.symbol + ": " + groupBigInt(c.atoms) + " atoms";
      stackEl.appendChild(seg);

      const ppm = ((atoms * 1000000n) / SUPPLY_M).toString();
      const logPct = atoms > 0n ? Math.min(100, (Math.log10(1 + Number(atoms)) / LOG_M) * 100) : 0;
      const inactiveNote = INACTIVE.has(c.symbol) ? ' <span class="muted">(inactive)</span>' : "";

      const tr = document.createElement("tr");
      tr.innerHTML =
        '<td class="mono"><b>' + esc(c.symbol) + '</b></td>' +
        '<td>' + esc(c.name) + inactiveNote + '</td>' +
        '<td class="num">' + groupBigInt(c.atoms) + '</td>' +
        '<td class="num">' + atomsToPlau(c.atoms) + '</td>' +
        '<td class="num">' + groupBigInt(ppm) + '</td>' +
        '<td><div class="log-bar-wrap"><div class="log-bar" style="width:' + logPct.toFixed(1) + '%;background:' + COLORS[idx % COLORS.length] + '"></div></div></td>';
      tbody.appendChild(tr);
    });

    const badge = document.getElementById("inv-badge");
    if (sum === SUPPLY_M && ledger.conserved) {
      badge.className = "badge ok";
      badge.textContent = "Σ = M = 1,500,000,000,000,000 ✓";
    } else {
      badge.className = "badge err";
      badge.textContent = "INVARIANT ALERT: Σ - M = " + (sum - SUPPLY_M).toString();
    }

    document.getElementById("s-dust").textContent = groupBigInt(ledger.segregated_dust);
    document.getElementById("s-lots").textContent = ledger.fee_lots;
    document.getElementById("s-locked").textContent = ledger.locked_fees;
    document.getElementById("s-booked").textContent = groupBigInt(ledger.booked_rewards);
    document.getElementById("s-unbooked").textContent = groupBigInt(ledger.unbooked_release);
    document.getElementById("s-openjobs").textContent = ledger.open_jobs;

    const iss = ledger.issuance;
    document.getElementById("s-rel-block").textContent = iss.next_block;
    document.getElementById("s-rel-initial").textContent = groupBigInt(iss.next_initial);
    document.getElementById("s-rel-miner").textContent = groupBigInt(iss.next_miner);
    document.getElementById("s-initial-released").textContent = groupBigInt(iss.initial_released);
    document.getElementById("s-miner-released").textContent = groupBigInt(iss.miner_released);

    const pool = ledger.initial_pool;
    document.getElementById("s-valve-window").textContent = pool.valve_window_blocks;
    document.getElementById("s-valve-rolling").textContent = groupBigInt(pool.valve_rolling);
    document.getElementById("s-valve-limit").textContent = groupBigInt(pool.valve_limit);
    document.getElementById("s-pool-nonce").textContent = pool.next_nonce;
    const treasuryEl = document.getElementById("s-treasury");
    treasuryEl.textContent = pool.treasury_enabled
      ? "ML-DSA-87 " + shortKey(pool.treasury_key_id) + " + SLH-DSA " + shortKey(pool.treasury_cosigner_key_id)
      : "none (withdrawals disabled)";
  }

  function renderBlocks(blocks) {
    const tbody = document.getElementById("blocks-tbody");
    tbody.innerHTML = "";
    for (let i = 0; i < blocks.length; i++) {
      const b = blocks[i];
      const prev = blocks[i + 1];
      const dt = prev ? (b.time_bucket - prev.time_bucket) + "s" : "-";

      let dU = 0n;
      let dRl = 0n;
      (b.fee_transitions || []).forEach(ft => {
        if (ft.delta && ft.delta.U) dU += BigInt(ft.delta.U);
        if (ft.delta && ft.delta.R_l) dRl += BigInt(ft.delta.R_l);
      });

      const isNew = knownHeights.size > 0 && !knownHeights.has(b.height);
      knownHeights.add(b.height);

      const tr = document.createElement("tr");
      tr.className = "clickable" + (isNew ? " flash-row" : "");
      const star = b.header_share ? " ★" : "";
      tr.innerHTML =
        '<td class="mono"><b>' + b.height + '</b></td>' +
        '<td class="mono">' + esc(b.block_id.slice(0, 12)) + '..</td>' +
        '<td class="mono" title="' + esc(b.miner_owner) + '">' + esc(shortKey(b.miner_owner)) + '</td>' +
        '<td class="num">' + b.jobs.length + '</td>' +
        '<td class="num">' + b.receipts.length + '</td>' +
        '<td class="num">' + b.shares.length + star + '</td>' +
        '<td class="num" title="' + esc(b.generator.name) + '">' + esc(b.generator.profile === null ? "-" : b.generator.profile) + '</td>' +
        '<td class="num">' + (dU >= 0n ? "+" : "") + groupBigInt(dU.toString()) + '</td>' +
        '<td class="num">' + (dRl >= 0n ? "+" : "") + groupBigInt(dRl.toString()) + '</td>' +
        '<td class="num">' + dt + '</td>';

      tr.addEventListener("click", function() {
        if (expandedHeights.has(b.height)) expandedHeights.delete(b.height);
        else expandedHeights.add(b.height);
        renderBlocks(latestBlocks);
      });
      tbody.appendChild(tr);

      if (expandedHeights.has(b.height)) {
        const dtr = document.createElement("tr");
        const td = document.createElement("td");
        td.colSpan = 10;
        td.className = "details-cell";
        const ftLines = (b.fee_transitions || []).map(ft =>
          esc(ft.op) + (ft.job_id ? " (job=" + esc(ft.job_id) + ")" : "") +
          (ft.block !== undefined ? " (k=" + esc(ft.block) + ")" : "") +
          (ft.nonce !== undefined ? " (nonce=" + esc(ft.nonce) + ")" : "") +
          Object.keys(ft.delta).filter(k => ft.delta[k] !== "0")
            .map(k => " Δ" + esc(k) + "=" + esc(ft.delta[k])).join("")
        ).join("<br>");
        const rcLines = (b.receipts || []).map(r =>
          "Receipt job=" + esc(r.job_id) + " executor=" + esc(shortKey(r.executor_owner)) + " result=" + esc(r.result)
        ).join("<br>");
        const wdLines = (b.withdrawals || []).map(w =>
          "Withdrawal nonce=" + esc(w.nonce) + " v=" + esc(w.amount) + " f=" + esc(w.fee) +
          " outputs=" + esc(w.outputs) + " tx=" + esc(shortKey(w.tx_id))
        ).join("<br>");
        td.innerHTML = "Generator " + esc(b.generator.id) + " (" + esc(b.generator.name) + ")<br>" +
          (ftLines || "No fee transitions") + (rcLines ? "<br>" + rcLines : "") +
          (wdLines ? "<br>" + wdLines : "");
        dtr.appendChild(td);
        tbody.appendChild(dtr);
      }
    }
  }

  function renderMyJobs() {
    const tbody = document.getElementById("myjobs-tbody");
    tbody.innerHTML = "";
    myJobs.forEach(mj => {
      let status = "pending";
      let settledResult = "-";
      for (const b of latestBlocks) {
        for (const r of (b.receipts || [])) {
          if (r.job_id === mj.job_id) {
            status = "settled @" + b.height + " (owner " + shortKey(r.executor_owner) + ")";
            settledResult = groupBigInt(r.result) + (r.result === mj.ref_dot ? " ✓" : " ✗");
          }
        }
        if (status === "pending") {
          for (const j of (b.jobs || [])) {
            if (j.job_id === mj.job_id) {
              status = "admitted @" + b.height + " (lease owner " + shortKey(j.executor_owner) + ")";
            }
          }
        }
      }
      const tr = document.createElement("tr");
      tr.innerHTML =
        '<td class="mono">' + esc(mj.job_id) + '</td>' +
        '<td class="mono">' + esc(status) + '</td>' +
        '<td class="num">' + groupBigInt(esc(mj.ref_dot)) + '</td>' +
        '<td class="num">' + esc(settledResult) + '</td>';
      tbody.appendChild(tr);
    });
  }

  async function poll() {
    if (document.hidden) return;
    const banner = document.getElementById("offline-banner");
    try {
      const resp = await fetch("/api/status");
      if (!resp.ok) throw new Error("HTTP " + resp.status);
      const st = await resp.json();
      banner.style.display = "none";

      document.getElementById("h-chain").textContent = st.chain.name;
      document.getElementById("h-chain-id").textContent = st.chain.chain_id;
      const ownerEl = document.getElementById("h-owner");
      ownerEl.textContent = shortKey(st.node.owner_key_id);
      ownerEl.title = "ML-DSA-87 key id " + st.node.owner_key_id + " (OwnerId " + st.node.owner_id + ")";
      document.getElementById("h-peers").textContent = st.node.peers;
      document.getElementById("h-height").textContent = st.tip.height;
      document.getElementById("h-tip-id").textContent = st.tip.block_id.slice(0, 10) + "..";
      document.getElementById("h-epoch").textContent = st.tip.epoch;
      document.getElementById("h-rate").textContent = st.mining.attempts_per_sec.toFixed(1);
      document.getElementById("h-exp").textContent = st.tip.expected_attempts_per_seal;
      document.getElementById("h-mempool").textContent = st.mempool.size;
      document.getElementById("h-withdrawals").textContent = st.mempool.withdrawals;
      document.getElementById("h-gen").textContent = st.tip.next_generator.profile + " " + st.tip.next_generator.name;
      document.getElementById("h-sharepool").textContent = st.mining.share_pool;
      document.getElementById("h-verifying").textContent = st.verification.verifying_blocks;
      document.getElementById("h-queued").textContent = st.verification.queued_blocks;
      document.getElementById("h-rate").title = st.mining.waiting_for_sync
        ? "Mining waits until this node is connected and caught up" : "";
      document.getElementById("s-cw").textContent = st.commercial_consensus_weight;

      renderLedger(st.ledger);

      if (st.tip.height !== lastTipHeight) {
        lastTipHeight = st.tip.height;
        const bResp = await fetch("/api/blocks?limit=20");
        if (bResp.ok) {
          const bData = await bResp.json();
          latestBlocks = bData.blocks || [];
          renderBlocks(latestBlocks);
          renderMyJobs();
        }
      }
    } catch (_) {
      banner.style.display = "block";
    }
  }

  generateOperands();
  renderMyJobs();
  poll();
  setInterval(poll, 2000);
})();
</script>
</body>
</html>
EOF

cat << 'EOF' > node/tests/public_testnet.rs
//! The public testnet's identity: every node built from this source must derive the
//! same genesis, so a change to `node/genesis.testnet.json` has to be deliberate.

#![forbid(unsafe_code)]

use node::cli::RunArgs;
use node::net::PeerAddr;
use node::{DEFAULT_GENESIS_JSON, start_node};
use wire::GenesisConfig;

/// 2026-10-21T00:00:00Z, the Public Testnet launch, in 1-second buckets.
const GENESIS_TIME_BUCKET: u64 = 1_792_540_800;

/// `genesis_id` of the embedded genesis.
const GENESIS_ID: &str = "55a515d5a46782d1373d0ad31a546ce816147514248556e664c973584fbab9a3b44d20eca91d029c5c875ea88019acaef4fc78eaac7008e979762f644b2f481f";

#[test]
fn the_embedded_genesis_is_the_public_testnet_genesis() {
    let genesis: GenesisConfig = serde_json::from_str(DEFAULT_GENESIS_JSON).unwrap();
    chain::validate_genesis(&genesis).unwrap();
    assert_eq!(genesis.time_bucket_secs, 1);
    assert_eq!(genesis.genesis_time_bucket, GENESIS_TIME_BUCKET);
    let id = chain::compute_genesis_id(&genesis).unwrap();
    assert_eq!(id.to_hex(), GENESIS_ID);
}

#[test]
fn peers_are_ip_or_host_name_with_a_port() {
    let socket = |s: &str| matches!(s.parse::<PeerAddr>(), Ok(PeerAddr::Socket(_)));
    let host = |s: &str| matches!(s.parse::<PeerAddr>(), Ok(PeerAddr::Host(_)));
    assert!(socket("203.0.113.7:30333"));
    assert!(socket("[2001:db8::1]:30333"));
    assert!(host("seed1.plauthium.network:30333"));
    assert!(host("localhost:30333"));
    for bad in [
        "seed1.plauthium.network",
        "seed1.plauthium.network:",
        "seed1.plauthium.network:70000",
        ":30333",
        "seed 1:30333",
        "user@seed1:30333",
        "2001:db8::1:30333x",
    ] {
        assert!(bad.parse::<PeerAddr>().is_err(), "{bad:?} must be refused");
    }
}

/// Two nodes on one data directory would corrupt each other's `blocks.log`: the second
/// one refuses to start until the first has stopped.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn a_data_directory_serves_one_node_at_a_time() {
    let dir = std::env::temp_dir().join(format!(
        "plauthium-lock-{}",
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap_or_default()
            .as_nanos()
    ));
    let args = || RunArgs {
        data_dir: dir.clone(),
        key_file: None,
        genesis: None,
        p2p_listen: "127.0.0.1:0".parse().unwrap(),
        rpc_listen: "127.0.0.1:0".parse().unwrap(),
        peers: vec![],
        mining_threads: 0,
        no_mine: true,
        mine_when_synced: false,
        verify_threads: Some(1),
        reset: true,
    };
    let first = start_node(args()).await.unwrap();
    let second = start_node(args()).await;
    let err = second
        .err()
        .expect("a second node on the same data directory");
    assert!(err.to_string().contains("in use"), "{err}");
    first.stop().await;
    let again = start_node(args()).await.unwrap();
    again.stop().await;
    let _ = std::fs::remove_dir_all(&dir);
}
EOF

cat << 'EOF' > node/tests/relay_poisoning.rs
//! Relay poisoning and share gossip over raw P2P connections.
//!
//! A peer that relays a copy of a block, job or share with a forged signature (or a
//! block with a forged body) first must not stop the genuine copy from being accepted:
//! `block_id`, `tx_id` and `work_id` deliberately exclude signatures, so the node's
//! relay and rejection caches key on the full signed encoding instead. Gossiped shares are pooled and relayed
//! only once verified, and a peer sending an invalid one is banned.

#![forbid(unsafe_code)]

use std::net::SocketAddr;
use std::path::PathBuf;
use std::sync::Arc;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

use bytes::Bytes;
use chain::core_adapter::fw_context_to_core;
use chain::keys::unsigned;
use chain::{BlockTree, OwnerKeypair, SignedShare, build_template};
use futures::{SinkExt, StreamExt};
use node::chain_actor::{ChainCmd, ImportAck, Origin, Source};
use node::cli::RunArgs;
use node::mempool::MempoolCmd;
use node::{NodeHandle, start_node};
use tokio::net::TcpStream;
use tokio::sync::oneshot;
use tokio::time::Instant;
use tokio_util::codec::{Framed, LengthDelimitedCodec};
use wire::{
    Block, DifficultyMode, Digest, GenesisConfig, JobPayload, JobTransaction, MAX_FRAME_BYTES,
    ShareProof, Target, WIRE_PROTOCOL_ID, WireMessage, codec,
};
use work::FreshWorkIds;

fn now_secs() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

/// Every attempt seals, so the test can build valid blocks with one tile each.
fn test_genesis() -> GenesisConfig {
    let mut g = GenesisConfig::default_testnet(1_700_000_000);
    g.initial_seal_target = Target(u128::MAX);
    g.share_ratio = 1;
    g.difficulty = DifficultyMode::Fixed;
    g
}

async fn start(genesis: &GenesisConfig) -> (NodeHandle, PathBuf) {
    let dir = std::env::temp_dir().join(format!("plauthium-relay-{}", now_secs_nanos()));
    std::fs::create_dir_all(&dir).unwrap();
    let genesis_path = dir.join("genesis.json");
    std::fs::write(&genesis_path, serde_json::to_string(genesis).unwrap()).unwrap();
    let node = start_node(RunArgs {
        data_dir: dir.join("node"),
        key_file: None,
        genesis: Some(genesis_path),
        p2p_listen: "127.0.0.1:0".parse().unwrap(),
        rpc_listen: "127.0.0.1:0".parse().unwrap(),
        peers: vec![],
        mining_threads: 0,
        no_mine: true,
        mine_when_synced: false,
        verify_threads: Some(2),
        reset: true,
    })
    .await
    .unwrap();
    (node, dir)
}

fn now_secs_nanos() -> u128 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos()
}

/// Mines the next block on the local replica `tree` for `miner`.
fn mine_next(tree: &BlockTree, miner: &Arc<OwnerKeypair>) -> Block {
    mine_on(tree, tree.tip_id(), miner, &[])
}

/// Mines a block on `parent` (any branch of the replica) including `pool` shares.
fn mine_on(
    tree: &BlockTree,
    parent: Digest,
    miner: &Arc<OwnerKeypair>,
    pool: &[ShareProof],
) -> Block {
    let tpl = template_on(tree, parent, miner, pool);
    let ctx = fw_context_to_core(&tpl.context_with_nonce(0)).unwrap();
    let inst = ctx.instance().unwrap();
    let z = inst.x.product(&inst.y);
    tpl.seal(0, &FreshWorkIds::derive(&ctx, &z)).unwrap()
}

/// Mines a share for `owner` with `nonce` on top of the replica's tip.
fn mine_share(tree: &BlockTree, owner: &Arc<OwnerKeypair>, nonce: u64) -> ShareProof {
    let tpl = template_on(tree, tree.tip_id(), owner, &[]);
    let ctx = fw_context_to_core(&tpl.context_with_nonce(nonce)).unwrap();
    let inst = ctx.instance().unwrap();
    let z = inst.x.product(&inst.y);
    tpl.share(nonce, &FreshWorkIds::derive(&ctx, &z)).unwrap()
}

fn template_on(
    tree: &BlockTree,
    parent: Digest,
    miner: &Arc<OwnerKeypair>,
    pool: &[ShareProof],
) -> chain::Template {
    template_on_at(tree, parent, miner, pool, now_secs())
}

/// A template whose time bucket is `now` (1-second buckets).
fn template_on_at(
    tree: &BlockTree,
    parent: Digest,
    miner: &Arc<OwnerKeypair>,
    pool: &[ShareProof],
    now: u64,
) -> chain::Template {
    let view = tree.ancestor_view(parent).unwrap();
    let meta = tree.get_meta(&parent).unwrap();
    let pool: Vec<SignedShare> = pool
        .iter()
        .map(|sh| SignedShare::verify(sh.clone()).unwrap())
        .collect();
    build_template(
        1,
        tree.genesis(),
        tree.genesis_id(),
        &view,
        meta.height,
        &tree.get_state(&parent).unwrap(),
        &[],
        &pool,
        &[],
        miner,
        now,
    )
    .unwrap()
}

/// `count` blocks on `parent` that pass Stage B but fail Stage A: each claims the work
/// outputs of another attempt (cheap to make, a full tile to check).
fn bogus_blocks(
    tree: &BlockTree,
    parent: Digest,
    miner: &Arc<OwnerKeypair>,
    count: u64,
) -> Vec<Block> {
    let tpl = template_on(tree, parent, miner, &[]);
    let ctx0 = fw_context_to_core(&tpl.context_with_nonce(0)).unwrap();
    let inst = ctx0.instance().unwrap();
    let z0 = inst.x.product(&inst.y);
    (1..=count)
        .map(|nonce| {
            let ctx = fw_context_to_core(&tpl.context_with_nonce(nonce)).unwrap();
            tpl.seal(nonce, &FreshWorkIds::derive(&ctx, &z0)).unwrap()
        })
        .collect()
}

/// Validates and applies `block` on the local replica.
fn extend(tree: &mut BlockTree, block: &Block) {
    tree.pre_validate(block, None).unwrap();
    tree.apply_verified_block(Arc::new(block.clone())).unwrap();
}

/// A raw P2P connection that has completed the handshake.
struct RawPeer {
    framed: Framed<TcpStream, LengthDelimitedCodec>,
}

impl RawPeer {
    async fn connect(addr: SocketAddr, genesis: &GenesisConfig, tree: &BlockTree) -> Self {
        Self::connect_claiming(addr, genesis, tree, 0, tree.genesis_id()).await
    }

    /// Connects with a Handshake that claims this tip.
    async fn connect_claiming(
        addr: SocketAddr,
        genesis: &GenesisConfig,
        tree: &BlockTree,
        best_height: u64,
        best_block_id: Digest,
    ) -> Self {
        let stream = TcpStream::connect(addr).await.unwrap();
        let codec = LengthDelimitedCodec::builder()
            .length_field_type::<u32>()
            .big_endian()
            .max_frame_length(MAX_FRAME_BYTES)
            .new_codec();
        let mut peer = RawPeer {
            framed: Framed::new(stream, codec),
        };
        peer.send(&WireMessage::Handshake {
            protocol_id: WIRE_PROTOCOL_ID,
            chain_id: genesis.chain_id,
            genesis_id: tree.genesis_id(),
            node_nonce: 7,
            best_height,
            best_block_id,
        })
        .await;
        let first = peer.framed.next().await.unwrap().unwrap();
        assert!(matches!(
            codec::decode::<WireMessage>(&first).unwrap(),
            WireMessage::Handshake { .. }
        ));
        peer
    }

    async fn send(&mut self, msg: &WireMessage) {
        let bytes = codec::encode(msg).unwrap();
        self.framed.send(Bytes::from(bytes)).await.unwrap();
    }

    /// The next frame within `wait`, or `None`.
    async fn recv(&mut self, wait: Duration) -> Option<WireMessage> {
        let frame = tokio::time::timeout(wait, self.framed.next())
            .await
            .ok()??;
        Some(codec::decode(&frame.unwrap()).unwrap())
    }
}

async fn wait_until(what: &str, mut cond: impl FnMut() -> bool) {
    let deadline = Instant::now() + Duration::from_secs(60);
    while !cond() {
        assert!(Instant::now() < deadline, "timed out waiting for {what}");
        tokio::time::sleep(Duration::from_millis(50)).await;
    }
}

async fn pooled_jobs(node: &NodeHandle) -> Vec<JobTransaction> {
    let (tx, rx) = oneshot::channel();
    node.mempool_tx
        .send(MempoolCmd::List {
            limit: 100,
            reply: tx,
        })
        .await
        .unwrap();
    rx.await.unwrap()
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn forged_copies_do_not_shadow_genuine_blocks_and_jobs() {
    let genesis = test_genesis();
    let (node, dir) = start(&genesis).await;
    let mut tree = BlockTree::new(genesis.clone()).unwrap();
    assert_eq!(tree.genesis_id(), node.status_rx.borrow().genesis_id);
    let miner = Arc::new(OwnerKeypair::from_seed(&[1; 32]));
    let height = |n: &NodeHandle| n.status_rx.borrow().tip.height;
    let peers = || node.peer_manager.peer_count();

    // 1. A forged-signature copy of block 1 (same block_id) is still being verified
    //    when the genuine copy arrives from an honest peer.
    let b1 = mine_next(&tree, &miner);
    let mut forged_b1 = b1.clone();
    forged_b1.header.signature.0[0] ^= 0x01;
    let mut attacker = RawPeer::connect(node.p2p_addr, &genesis, &tree).await;
    let mut first_honest = RawPeer::connect(node.p2p_addr, &genesis, &tree).await;
    wait_until("both peers registered", || peers() == 2).await;
    attacker
        .send(&WireMessage::GossipBlock(Box::new(forged_b1)))
        .await;
    first_honest
        .send(&WireMessage::GossipBlock(Box::new(b1.clone())))
        .await;
    wait_until("block 1 despite a forged copy in flight", || {
        height(&node) == 1
    })
    .await;
    assert_eq!(node.status_rx.borrow().tip.id, b1.header.block_id);
    wait_until("the first attacker banned", || peers() == 1).await;
    extend(&mut tree, &b1);

    // 2. The forged copy of block 2 is rejected first (its sender is banned and
    //    dropped); the genuine copy then arrives from another peer.
    let b2 = mine_next(&tree, &miner);
    let mut forged_b2 = b2.clone();
    forged_b2.header.signature = unsigned();
    let mut attacker = RawPeer::connect(node.p2p_addr, &genesis, &tree).await;
    wait_until("the attacker to be registered", || peers() == 2).await;
    attacker
        .send(&WireMessage::GossipBlock(Box::new(forged_b2)))
        .await;
    wait_until("the forged block 2 to be rejected", || peers() == 1).await;
    let mut honest = RawPeer::connect(node.p2p_addr, &genesis, &tree).await;
    honest
        .send(&WireMessage::GossipBlock(Box::new(b2.clone())))
        .await;
    wait_until("block 2 after its forged copy was rejected", || {
        height(&node) == 2
    })
    .await;
    assert_eq!(node.status_rx.borrow().tip.id, b2.header.block_id);
    extend(&mut tree, &b2);

    // 3. Genuine headers with forged bodies. A copy of block 4 arrives while block 3 is
    //    unknown and is parked as an orphan; the genuine block 4 must still be parked
    //    beside it. A copy of block 3 fails its body_core_root check at once (its
    //    sender is banned), and the genuine block 3 must still be accepted.
    let b3 = mine_next(&tree, &miner);
    let mut tree3 = BlockTree::new(genesis.clone()).unwrap();
    extend(&mut tree3, &b1);
    extend(&mut tree3, &b2);
    extend(&mut tree3, &b3);
    let b4 = mine_next(&tree3, &miner);
    let forge_body = |b: &Block| {
        let mut forged = b.clone();
        forged.body.ledger_digest.0[0] ^= 0x01;
        forged
    };
    let mut attacker = RawPeer::connect(node.p2p_addr, &genesis, &tree).await;
    wait_until("the attacker beside both honest peers", || peers() == 3).await;
    attacker
        .send(&WireMessage::GossipBlock(Box::new(forge_body(&b4))))
        .await;
    // The orphan makes the node ask its sender for the missing blocks.
    loop {
        match attacker.recv(Duration::from_secs(30)).await {
            Some(WireMessage::SyncRequest { .. }) => break,
            Some(_) => continue,
            None => panic!("the forged orphan was never processed"),
        }
    }
    honest
        .send(&WireMessage::GossipBlock(Box::new(b4.clone())))
        .await;
    attacker
        .send(&WireMessage::GossipBlock(Box::new(forge_body(&b3))))
        .await;
    wait_until("the forged-body sender banned", || peers() == 2).await;
    honest
        .send(&WireMessage::GossipBlock(Box::new(b3.clone())))
        .await;
    wait_until("blocks 3 and 4 despite forged bodies", || {
        height(&node) == 4
    })
    .await;
    assert_eq!(node.status_rx.borrow().tip.id, b4.header.block_id);

    // 4. Jobs: a forged-signature copy (same tx_id) is refused, and the genuine job
    //    relayed right after it still reaches the mempool.
    let client = OwnerKeypair::from_seed(&[2; 32]);
    let mut job = JobTransaction {
        client_key: client.public_key().clone(),
        queue_fee: 100_000_000,
        base_fee: 1_000_000_000,
        v_exec: 7_900_000_000,
        v_da: 500_000_000,
        v_ref: 500_000_000,
        expiry_height: 120,
        nonce: 42,
        payload: JobPayload::ExactDot {
            xs: vec![2.0; 512],
            ys: vec![3.0; 512],
        },
        signature: unsigned(),
    };
    client.sign_job(&mut job, &tree.genesis_id()).unwrap();
    let mut forged_job = job.clone();
    forged_job.signature.0[10] ^= 0x01;
    honest.send(&WireMessage::GossipJob(forged_job)).await;
    honest.send(&WireMessage::GossipJob(job.clone())).await;
    let deadline = Instant::now() + Duration::from_secs(30);
    loop {
        let pooled = pooled_jobs(&node).await;
        if let Some(found) = pooled.first() {
            assert_eq!(pooled.len(), 1);
            assert_eq!(found.signature, job.signature, "the genuine copy is pooled");
            break;
        }
        assert!(
            Instant::now() < deadline,
            "the genuine job never reached the mempool"
        );
        tokio::time::sleep(Duration::from_millis(50)).await;
    }

    node.stop().await;
    let _ = std::fs::remove_dir_all(&dir);
}

/// Gossiped shares, one path per step: a forged copy gets its sender banned (after
/// the signature check) without shadowing the genuine share, which is pooled and
/// relayed; a malformed share gets its sender banned at once; a share that arrives
/// while its parent block is in Stage A waits for it; a share whose parent is unknown
/// is ignored without penalty; a validly signed share with bogus work gets its sender
/// banned and is never relayed.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn gossiped_shares_are_verified_relayed_and_invalid_ones_banned() {
    let genesis = test_genesis();
    let (node, dir) = start(&genesis).await;
    let mut tree = BlockTree::new(genesis.clone()).unwrap();
    let owner = Arc::new(OwnerKeypair::from_seed(&[3; 32]));
    let miner = Arc::new(OwnerKeypair::from_seed(&[4; 32]));
    let pooled = |n: &NodeHandle| n.status_rx.borrow().share_pool;
    let peers = || node.peer_manager.peer_count();
    let closed = |end: Result<Option<Result<bytes::BytesMut, std::io::Error>>, _>| {
        matches!(end, Ok(None) | Ok(Some(Err(_))))
    };

    let mut listener = RawPeer::connect(node.p2p_addr, &genesis, &tree).await;
    let mut attacker = RawPeer::connect(node.p2p_addr, &genesis, &tree).await;
    let mut sender = RawPeer::connect(node.p2p_addr, &genesis, &tree).await;
    wait_until("three peers registered", || peers() == 3).await;

    // 1. A forged-signature copy (same work_id) gets the attacker banned and dropped...
    let share = mine_share(&tree, &owner, 11);
    let mut forged = share.clone();
    forged.signature.0[42] ^= 0x01;
    attacker
        .send(&WireMessage::GossipShare(Box::new(forged)))
        .await;
    wait_until("the attacker banned", || peers() == 2).await;
    let end = tokio::time::timeout(Duration::from_secs(5), attacker.framed.next()).await;
    assert!(
        closed(end),
        "the node closes the banned attacker's connection"
    );

    // 2. ...and the genuine share is still pooled and relayed.
    sender
        .send(&WireMessage::GossipShare(Box::new(share.clone())))
        .await;
    match listener.recv(Duration::from_secs(30)).await {
        Some(WireMessage::GossipShare(relayed)) => {
            assert_eq!(*relayed, share, "only the genuine share is relayed")
        }
        other => panic!("expected the relayed share, got {other:?}"),
    }
    wait_until("the share in the pool", || pooled(&node) == 1).await;

    // 3. A malformed share (wrong share_target, validly signed) is caught by the
    //    no-work checks: banned at once, no tile recomputed.
    let mut wrong_target = mine_share(&tree, &owner, 12);
    wrong_target.share_target = Target(u128::MAX - 1);
    owner.sign_share(&mut wrong_target).unwrap();
    let mut second_attacker = RawPeer::connect(node.p2p_addr, &genesis, &tree).await;
    wait_until("the second attacker registered", || peers() == 3).await;
    second_attacker
        .send(&WireMessage::GossipShare(Box::new(wrong_target)))
        .await;
    let end = tokio::time::timeout(Duration::from_secs(5), second_attacker.framed.next()).await;
    assert!(
        closed(end),
        "a malformed share closes the connection at once"
    );
    wait_until("the second attacker banned", || peers() == 2).await;

    // 4. Block 1, and right behind it on the same connection a share mined on it: the
    //    share waits while block 1 is in Stage A, then is verified, pooled, relayed.
    let p1 = mine_next(&tree, &miner);
    extend(&mut tree, &p1);
    let on_p1 = mine_share(&tree, &owner, 13);
    sender
        .send(&WireMessage::GossipBlock(Box::new(p1.clone())))
        .await;
    sender
        .send(&WireMessage::GossipShare(Box::new(on_p1.clone())))
        .await;
    loop {
        match listener.recv(Duration::from_secs(30)).await {
            Some(WireMessage::GossipBlock(b)) => assert_eq!(b.header.block_id, p1.header.block_id),
            Some(WireMessage::GossipShare(relayed)) => {
                assert_eq!(*relayed, on_p1);
                break;
            }
            other => panic!("expected block 1 and its share, got {other:?}"),
        }
    }
    wait_until("both shares pooled", || pooled(&node) == 2).await;

    // 5. A share with an unknown parent is ignored: no relay, no ban.
    let mut orphan = mine_share(&tree, &owner, 14);
    orphan.context.parent_canonical_id = Digest([9; 64]);
    owner.sign_share(&mut orphan).unwrap();
    sender
        .send(&WireMessage::GossipShare(Box::new(orphan)))
        .await;
    tokio::time::sleep(Duration::from_millis(300)).await;
    assert_eq!(peers(), 2, "no penalty for an orphan");

    // 6. Validly signed but with a ticket its work does not produce: the work check
    //    fails, the sender is banned and the share is neither pooled nor relayed.
    let mut bogus = mine_share(&tree, &owner, 15);
    bogus.share_ticket = Digest::ZERO;
    owner.sign_share(&mut bogus).unwrap();
    sender
        .send(&WireMessage::GossipShare(Box::new(bogus)))
        .await;
    wait_until("the sender of the bogus share banned", || peers() == 1).await;
    assert_eq!(pooled(&node), 2);
    assert!(
        listener.recv(Duration::from_millis(500)).await.is_none(),
        "nothing else is relayed"
    );

    node.stop().await;
    let _ = std::fs::remove_dir_all(&dir);
}

/// A share parked behind a bad copy of its parent is dropped when that copy fails
/// Stage A, without being remembered as seen: relayed again once the genuine parent
/// is in, it is pooled.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn a_share_parked_behind_a_bad_parent_copy_can_return() {
    let genesis = test_genesis();
    let (node, dir) = start(&genesis).await;
    let mut tree = BlockTree::new(genesis.clone()).unwrap();
    let owner = Arc::new(OwnerKeypair::from_seed(&[11; 32]));
    let miner = Arc::new(OwnerKeypair::from_seed(&[12; 32]));
    let pooled = |n: &NodeHandle| n.status_rx.borrow().share_pool;
    let peers = || node.peer_manager.peer_count();

    // The bad copy keeps block 1's block_id and a valid signature (its miner signed
    // it), so it fails only at its tile recomputation, well after the share arrives.
    let p1 = mine_next(&tree, &miner);
    let mut forged_p1 = p1.clone();
    forged_p1.header.seal_ticket.0[0] ^= 0x01;
    miner.sign_header(&mut forged_p1.header).unwrap();
    extend(&mut tree, &p1);
    let on_p1 = mine_share(&tree, &owner, 51);

    let mut attacker = RawPeer::connect(node.p2p_addr, &genesis, &tree).await;
    let mut honest = RawPeer::connect(node.p2p_addr, &genesis, &tree).await;
    wait_until("both peers registered", || peers() == 2).await;
    // The share follows the bad copy, so it parks while that copy is in Stage A; the
    // copy fails and the share is dropped with it.
    attacker
        .send(&WireMessage::GossipBlock(Box::new(forged_p1)))
        .await;
    attacker
        .send(&WireMessage::GossipShare(Box::new(on_p1.clone())))
        .await;
    wait_until("the attacker banned", || peers() == 1).await;
    assert_eq!(pooled(&node), 0);

    honest
        .send(&WireMessage::GossipBlock(Box::new(p1.clone())))
        .await;
    wait_until("the genuine block 1", || {
        node.status_rx.borrow().tip.id == p1.header.block_id
    })
    .await;
    honest
        .send(&WireMessage::GossipShare(Box::new(on_p1)))
        .await;
    wait_until("the share pooled once relayed again", || pooled(&node) == 1).await;

    node.stop().await;
    let _ = std::fs::remove_dir_all(&dir);
}

/// A reorg returns the shares of the abandoned blocks to the pool, so they can still
/// be included on the new branch.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn shares_of_abandoned_blocks_return_to_the_pool() {
    let genesis = test_genesis();
    let (node, dir) = start(&genesis).await;
    let mut tree = BlockTree::new(genesis.clone()).unwrap();
    let (miner_a, miner_b, owner) = (
        Arc::new(OwnerKeypair::from_seed(&[5; 32])),
        Arc::new(OwnerKeypair::from_seed(&[6; 32])),
        Arc::new(OwnerKeypair::from_seed(&[7; 32])),
    );
    let genesis_id = tree.genesis_id();
    let pooled = |n: &NodeHandle| n.status_rx.borrow().share_pool;
    let tip = |n: &NodeHandle| n.status_rx.borrow().tip.id;

    // Branch A: a1, then a2 including a share mined at height 1.
    let share = mine_share(&tree, &owner, 21);
    let a1 = mine_on(&tree, genesis_id, &miner_a, &[]);
    extend(&mut tree, &a1);
    let a2 = mine_on(
        &tree,
        a1.header.block_id,
        &miner_a,
        std::slice::from_ref(&share),
    );
    assert_eq!(a2.body.shares, vec![share.clone()]);
    extend(&mut tree, &a2);
    // Branch B: three blocks from genesis without the share, so it is heavier.
    let b1 = mine_on(&tree, genesis_id, &miner_b, &[]);
    extend(&mut tree, &b1);
    let b2 = mine_on(&tree, b1.header.block_id, &miner_b, &[]);
    extend(&mut tree, &b2);
    let b3 = mine_on(&tree, b2.header.block_id, &miner_b, &[]);
    extend(&mut tree, &b3);

    let mut peer = RawPeer::connect(node.p2p_addr, &genesis, &tree).await;
    for blk in [&a1, &a2] {
        peer.send(&WireMessage::GossipBlock(Box::new(blk.clone())))
            .await;
    }
    wait_until("branch A", || tip(&node) == a2.header.block_id).await;
    assert_eq!(pooled(&node), 0, "the share is registered on branch A");

    for blk in [&b1, &b2, &b3] {
        peer.send(&WireMessage::GossipBlock(Box::new(blk.clone())))
            .await;
    }
    wait_until("the reorg to branch B", || tip(&node) == b3.header.block_id).await;
    wait_until("the abandoned share back in the pool", || {
        pooled(&node) == 1
    })
    .await;

    node.stop().await;
    let _ = std::fs::remove_dir_all(&dir);
}

/// Only the work check ties a work_id to its owner, so pending shares are keyed by
/// (owner, work_id): a validly signed claim to an honest share's work_id under another
/// key cannot shadow the genuine share, and the claimant is banned.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn a_claim_to_another_owners_work_does_not_shadow_it() {
    let genesis = test_genesis();
    let (node, dir) = start(&genesis).await;
    let tree = BlockTree::new(genesis.clone()).unwrap();
    let honest_owner = Arc::new(OwnerKeypair::from_seed(&[8; 32]));
    let thief = Arc::new(OwnerKeypair::from_seed(&[9; 32]));
    let peers = || node.peer_manager.peer_count();
    let pooled = |n: &NodeHandle| n.status_rx.borrow().share_pool;

    let share = mine_share(&tree, &honest_owner, 31);
    // The thief's own valid share context, with the honest work_id and ticket copied in.
    let mut claim = mine_share(&tree, &thief, 32);
    claim.work_id = share.work_id;
    claim.share_ticket = share.share_ticket;
    claim.output_root = share.output_root;
    thief.sign_share(&mut claim).unwrap();

    let mut listener = RawPeer::connect(node.p2p_addr, &genesis, &tree).await;
    let mut attacker = RawPeer::connect(node.p2p_addr, &genesis, &tree).await;
    let mut sender = RawPeer::connect(node.p2p_addr, &genesis, &tree).await;
    wait_until("three peers registered", || peers() == 3).await;
    attacker
        .send(&WireMessage::GossipShare(Box::new(claim)))
        .await;
    sender
        .send(&WireMessage::GossipShare(Box::new(share.clone())))
        .await;
    match listener.recv(Duration::from_secs(30)).await {
        Some(WireMessage::GossipShare(relayed)) => assert_eq!(*relayed, share),
        other => panic!("expected the genuine share, got {other:?}"),
    }
    wait_until("the genuine share pooled", || pooled(&node) == 1).await;
    wait_until("the thief banned", || peers() == 2).await;

    node.stop().await;
    let _ = std::fs::remove_dir_all(&dir);
}

/// Useless shares (ignored, or duplicates under a new encoding) cost checks but no
/// work to make: past its budget a peer's shares are dropped unread. It is throttled,
/// not banned, since honest peers that are syncing send many useless shares too.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn a_flood_of_useless_shares_throttles_the_peer_without_a_ban() {
    let genesis = test_genesis();
    let (node, dir) = start(&genesis).await;
    let tree = BlockTree::new(genesis.clone()).unwrap();
    let owner = Arc::new(OwnerKeypair::from_seed(&[10; 32]));
    let mut orphan = mine_share(&tree, &owner, 41);
    orphan.context.parent_canonical_id = Digest([7; 64]);
    owner.sign_share(&mut orphan).unwrap();
    let genuine = mine_share(&tree, &owner, 42);
    let pooled = |n: &NodeHandle| n.status_rx.borrow().share_pool;

    let mut flooder = RawPeer::connect(node.p2p_addr, &genesis, &tree).await;
    let mut honest = RawPeer::connect(node.p2p_addr, &genesis, &tree).await;
    wait_until("both peers registered", || {
        node.peer_manager.peer_count() == 2
    })
    .await;
    // Ignored shares are not remembered as seen, so even the same bytes count again.
    for _ in 0..300 {
        flooder
            .send(&WireMessage::GossipShare(Box::new(orphan.clone())))
            .await;
    }
    // Over budget: a valid share from the flooder is dropped unread. The sync reply
    // shows that the node has handled every frame sent before it.
    flooder
        .send(&WireMessage::GossipShare(Box::new(genuine.clone())))
        .await;
    flooder
        .send(&WireMessage::SyncRequest { from_height: 1 })
        .await;
    loop {
        match flooder.recv(Duration::from_secs(30)).await {
            Some(WireMessage::SyncResponse { .. }) => break,
            Some(_) => continue,
            None => panic!("the flooding peer was disconnected"),
        }
    }

    // The same share from another peer is pooled and relayed to the flooder, which is
    // still connected. Had the flooder's own copy been imported, the node would never
    // relay the share back to it.
    honest
        .send(&WireMessage::GossipShare(Box::new(genuine.clone())))
        .await;
    wait_until("the share pooled from the other peer", || {
        pooled(&node) == 1
    })
    .await;
    loop {
        match flooder.recv(Duration::from_secs(30)).await {
            Some(WireMessage::GossipShare(sh)) => {
                assert_eq!(*sh, genuine);
                break;
            }
            Some(_) => continue,
            None => panic!("the share was not relayed to the throttled peer"),
        }
    }
    assert_eq!(node.peer_manager.peer_count(), 2, "no one was banned");

    node.stop().await;
    let _ = std::fs::remove_dir_all(&dir);
}

/// Status counters of the node.
fn snapshot(node: &NodeHandle) -> Arc<node::chain_actor::StatusSnapshot> {
    node.status_rx.borrow().clone()
}

/// Waits until the chain actor has handled every command sent before this one.
async fn actor_barrier(node: &NodeHandle) {
    let (tx, rx) = oneshot::channel();
    let cmd = ChainCmd::HasBlock {
        id: Digest::ZERO,
        reply: tx,
    };
    node.chain_tx.send(cmd).await.unwrap();
    rx.await.unwrap();
}

/// A peer streaming blocks that pass Stage B but fail Stage A gets at most two of them
/// verified (the limit per source); the rest wait in its queue or are refused, and are
/// dropped the moment its first block fails, before any of them starts.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn stage_a_is_limited_per_source_and_dropped_with_its_ban() {
    let genesis = test_genesis();
    let (node, dir) = start(&genesis).await;
    let tree = BlockTree::new(genesis.clone()).unwrap();
    let attacker_key = Arc::new(OwnerKeypair::from_seed(&[15; 32]));
    let miner = Arc::new(OwnerKeypair::from_seed(&[16; 32]));
    let peers = || node.peer_manager.peer_count();

    let bogus = bogus_blocks(&tree, tree.tip_id(), &attacker_key, 20);
    let b1 = mine_next(&tree, &miner);
    let mut attacker = RawPeer::connect(node.p2p_addr, &genesis, &tree).await;
    let mut honest = RawPeer::connect(node.p2p_addr, &genesis, &tree).await;
    wait_until("both peers registered", || peers() == 2).await;

    for block in &bogus {
        attacker
            .send(&WireMessage::GossipBlock(Box::new(block.clone())))
            .await;
    }
    wait_until("the attacker banned", || peers() == 1).await;
    // Its other Stage A task is aborted and its queued blocks dropped...
    wait_until("its pending blocks dropped", || {
        let snap = snapshot(&node);
        snap.verifying_blocks == 0 && snap.queued_blocks == 0
    })
    .await;
    // ...before any of those could start.
    let snap = snapshot(&node);
    assert!(
        snap.stage_a_started <= 2,
        "{} of the attacker's blocks entered Stage A",
        snap.stage_a_started
    );
    assert_eq!(snap.tip.height, 0);
    tokio::time::sleep(Duration::from_millis(500)).await;
    assert!(
        snapshot(&node).stage_a_started <= 2,
        "none of them started later"
    );

    // Honest blocks are verified at once.
    honest
        .send(&WireMessage::GossipBlock(Box::new(b1.clone())))
        .await;
    wait_until("block 1 from the honest peer", || {
        snapshot(&node).tip.id == b1.header.block_id
    })
    .await;

    node.stop().await;
    let _ = std::fs::remove_dir_all(&dir);
}

/// A block delivered first by a peer that then gets banned stays pending when another
/// peer delivered it too, now on that peer's behalf: honest peers relay a block only
/// once, so dropping it would lose it.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn a_block_another_peer_delivered_too_survives_its_first_senders_ban() {
    let genesis = test_genesis();
    let (node, dir) = start(&genesis).await;
    let mut tree = BlockTree::new(genesis.clone()).unwrap();
    let miner = Arc::new(OwnerKeypair::from_seed(&[17; 32]));
    let owner = Arc::new(OwnerKeypair::from_seed(&[18; 32]));
    let peers = || node.peer_manager.peer_count();

    let b1 = mine_next(&tree, &miner);
    let mut bad_share = mine_share(&tree, &owner, 71);
    bad_share.share_target = Target(u128::MAX - 1);
    owner.sign_share(&mut bad_share).unwrap();
    extend(&mut tree, &b1);
    let b2 = mine_next(&tree, &miner);

    let mut attacker = RawPeer::connect(node.p2p_addr, &genesis, &tree).await;
    let mut honest = RawPeer::connect(node.p2p_addr, &genesis, &tree).await;
    wait_until("both peers registered", || peers() == 2).await;

    // Block 2 arrives first from the attacker while block 1 is unknown: it is parked.
    attacker
        .send(&WireMessage::GossipBlock(Box::new(b2.clone())))
        .await;
    loop {
        match attacker.recv(Duration::from_secs(30)).await {
            Some(WireMessage::SyncRequest { .. }) => break,
            Some(_) => continue,
            None => panic!("block 2 from the attacker was never processed"),
        }
    }
    // The honest peer relays the same bytes; the sync reply shows it was handled.
    honest
        .send(&WireMessage::GossipBlock(Box::new(b2.clone())))
        .await;
    honest
        .send(&WireMessage::SyncRequest { from_height: 1 })
        .await;
    loop {
        match honest.recv(Duration::from_secs(30)).await {
            Some(WireMessage::SyncResponse { .. }) => break,
            Some(_) => continue,
            None => panic!("the honest peer was disconnected"),
        }
    }
    // The attacker is banned for an invalid share; block 2 stays parked for the honest peer.
    attacker
        .send(&WireMessage::GossipShare(Box::new(bad_share)))
        .await;
    wait_until("the attacker banned", || peers() == 1).await;
    honest
        .send(&WireMessage::GossipBlock(Box::new(b1.clone())))
        .await;
    wait_until("blocks 1 and 2", || snapshot(&node).tip.height == 2).await;
    assert_eq!(snapshot(&node).tip.id, b2.header.block_id);

    node.stop().await;
    let _ = std::fs::remove_dir_all(&dir);
}

/// Cancelling a source (as a ban does) aborts its Stage A tasks and drops its queued
/// blocks without condemning them: the same blocks from another source are accepted.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn cancelling_a_source_drops_its_pending_blocks_without_condemning_them() {
    let genesis = test_genesis();
    let (node, dir) = start(&genesis).await;
    let tree = BlockTree::new(genesis.clone()).unwrap();
    let blocks: Vec<Block> = (0..4u8)
        .map(|i| {
            let miner = Arc::new(OwnerKeypair::from_seed(&[20 + i; 32]));
            mine_on(&tree, tree.genesis_id(), &miner, &[])
        })
        .collect();
    let banned = Source::Addr("127.0.0.1:9".parse().unwrap());
    let other = Source::Addr("127.0.0.1:10".parse().unwrap());

    // All five commands reach the actor's mailbox before any Stage A (a full tile) ends.
    let mut acks = Vec::new();
    for block in &blocks {
        let (tx, rx) = oneshot::channel();
        let cmd = ChainCmd::ImportBlock {
            block: Arc::new(block.clone()),
            origin: Origin::Peer(9_001, banned),
            ack: Some(tx),
        };
        node.chain_tx.send(cmd).await.unwrap();
        acks.push(rx);
    }
    let cmd = ChainCmd::CancelSource {
        source: banned,
        ban: Duration::from_secs(60),
    };
    node.chain_tx.send(cmd).await.unwrap();
    for ack in acks {
        assert_eq!(ack.await.unwrap(), ImportAck::Queued);
    }
    actor_barrier(&node).await;
    let snap = snapshot(&node);
    assert_eq!(snap.stage_a_started, 2, "two in Stage A, two queued");
    assert_eq!((snap.verifying_blocks, snap.queued_blocks), (0, 0));

    // Nothing new is admitted from the banned source...
    let (tx, rx) = oneshot::channel();
    let cmd = ChainCmd::ImportBlock {
        block: Arc::new(blocks[0].clone()),
        origin: Origin::Peer(9_001, banned),
        ack: Some(tx),
    };
    node.chain_tx.send(cmd).await.unwrap();
    assert_eq!(rx.await.unwrap(), ImportAck::Busy);
    // ...the aborted blocks were not applied, and another source's copies are accepted.
    tokio::time::sleep(Duration::from_millis(500)).await;
    assert_eq!(snapshot(&node).tip.height, 0);
    for block in &blocks {
        let cmd = ChainCmd::ImportBlock {
            block: Arc::new(block.clone()),
            origin: Origin::Peer(9_002, other),
            ack: None,
        };
        node.chain_tx.send(cmd).await.unwrap();
    }
    for block in &blocks {
        let id = block.header.block_id;
        let deadline = Instant::now() + Duration::from_secs(60);
        loop {
            let (tx, rx) = oneshot::channel();
            node.chain_tx
                .send(ChainCmd::HasBlock { id, reply: tx })
                .await
                .unwrap();
            if rx.await.unwrap() {
                break;
            }
            assert!(
                Instant::now() < deadline,
                "a re-sent block was never applied"
            );
            tokio::time::sleep(Duration::from_millis(50)).await;
        }
    }

    node.stop().await;
    let _ = std::fs::remove_dir_all(&dir);
}

/// Sends a Handshake with `genesis_id` (and the node's own nonce if `echo_nonce`) after
/// reading the node's; returns whether the node keeps the connection.
async fn handshake_accepted(addr: SocketAddr, genesis_id: Digest, echo_nonce: bool) -> bool {
    let stream = TcpStream::connect(addr).await.unwrap();
    let codec = LengthDelimitedCodec::builder()
        .length_field_type::<u32>()
        .big_endian()
        .max_frame_length(MAX_FRAME_BYTES)
        .new_codec();
    let mut framed = Framed::new(stream, codec);
    let first = framed.next().await.unwrap().unwrap();
    let WireMessage::Handshake {
        chain_id,
        node_nonce,
        ..
    } = codec::decode::<WireMessage>(&first).unwrap()
    else {
        panic!("the node did not open with a Handshake");
    };
    let ours = WireMessage::Handshake {
        protocol_id: WIRE_PROTOCOL_ID,
        chain_id,
        genesis_id,
        node_nonce: if echo_nonce {
            node_nonce
        } else {
            node_nonce ^ 1
        },
        best_height: 0,
        best_block_id: genesis_id,
    };
    framed
        .send(Bytes::from(codec::encode(&ours).unwrap()))
        .await
        .unwrap();
    matches!(
        tokio::time::timeout(Duration::from_secs(1), framed.next()).await,
        Err(_) | Ok(Some(Ok(_)))
    )
}

/// The handshake carries the genesis id and a per-process nonce: a node on another
/// genesis with the same chain_id, or the node itself, is not kept as a peer.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn handshakes_from_another_genesis_or_from_the_node_itself_are_refused() {
    let genesis = test_genesis();
    let (node, dir) = start(&genesis).await;
    let genesis_id = BlockTree::new(genesis.clone()).unwrap().genesis_id();
    let peers = || node.peer_manager.peer_count();

    assert!(!handshake_accepted(node.p2p_addr, Digest([1; 64]), false).await);
    assert!(!handshake_accepted(node.p2p_addr, genesis_id, true).await);
    assert_eq!(peers(), 0);
    assert!(handshake_accepted(node.p2p_addr, genesis_id, false).await);

    node.stop().await;
    let _ = std::fs::remove_dir_all(&dir);
}

/// With `--mine-when-synced`, a node that cannot reach its peers does not mine (a
/// private fork it could never leave); a node joining a peer that is ahead starts
/// mining only once it has caught up.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn mining_waits_for_a_peer_and_for_sync_when_asked_to() {
    let genesis = test_genesis();
    let base = std::env::temp_dir().join(format!("plauthium-gate-{}", now_secs_nanos()));
    std::fs::create_dir_all(&base).unwrap();
    let genesis_path = base.join("genesis.json");
    std::fs::write(&genesis_path, serde_json::to_string(&genesis).unwrap()).unwrap();
    let args = |name: &str, peers: Vec<node::net::PeerAddr>, gated: bool| RunArgs {
        data_dir: base.join(name),
        key_file: None,
        genesis: Some(genesis_path.clone()),
        p2p_listen: "127.0.0.1:0".parse().unwrap(),
        rpc_listen: "127.0.0.1:0".parse().unwrap(),
        peers,
        mining_threads: 1,
        no_mine: false,
        mine_when_synced: gated,
        verify_threads: Some(2),
        reset: true,
    };
    let height = |n: &NodeHandle| n.status_rx.borrow().tip.height;

    // Its only peer does not exist: it waits instead of mining alone.
    let unreachable = "127.0.0.1:1".parse::<SocketAddr>().unwrap().into();
    let alone = start_node(args("alone", vec![unreachable], true))
        .await
        .unwrap();
    tokio::time::sleep(Duration::from_secs(3)).await;
    assert_eq!(height(&alone), 0);
    assert!(!alone.engine.sync_gate_open());
    alone.stop().await;

    // A peer that is 30 blocks ahead (and then stops mining: an attempt already under
    // way may still seal one more block, so wait until its height settles).
    let ahead = start_node(args("ahead", vec![], false)).await.unwrap();
    wait_until("the peer at height 30", || height(&ahead) >= 30).await;
    ahead.engine.set_enabled(false);
    let mut target = height(&ahead);
    loop {
        tokio::time::sleep(Duration::from_secs(2)).await;
        if height(&ahead) == target {
            break;
        }
        target = height(&ahead);
    }

    // The joining node opens its gate only at the peer's height, then mines on top.
    let joined = start_node(args("joined", vec![ahead.p2p_addr.into()], true))
        .await
        .unwrap();
    let deadline = Instant::now() + Duration::from_secs(60);
    while !joined.engine.sync_gate_open() {
        assert!(Instant::now() < deadline, "the gate never opened");
        tokio::time::sleep(Duration::from_millis(20)).await;
    }
    assert!(
        height(&joined) >= target,
        "the gate opened at height {} before catching up to {target}",
        height(&joined)
    );
    wait_until("a block mined on top by the joined node", || {
        let tip = ahead.status_rx.borrow().tip.clone();
        tip.height > target && tip.miner_key_id == joined.miner_key_id
    })
    .await;

    joined.stop().await;
    ahead.stop().await;
    let _ = std::fs::remove_dir_all(&base);
}

/// A peer that claims a height it never delivers holds `--mine-when-synced` back only
/// until its sync request times out: the claim then drops to what it delivered.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn a_peer_lying_about_its_height_holds_mining_back_only_briefly() {
    let genesis = test_genesis();
    let base = std::env::temp_dir().join(format!("plauthium-liar-{}", now_secs_nanos()));
    std::fs::create_dir_all(&base).unwrap();
    let genesis_path = base.join("genesis.json");
    std::fs::write(&genesis_path, serde_json::to_string(&genesis).unwrap()).unwrap();
    let node = start_node(RunArgs {
        data_dir: base.join("gated"),
        key_file: None,
        genesis: Some(genesis_path),
        p2p_listen: "127.0.0.1:0".parse().unwrap(),
        rpc_listen: "127.0.0.1:0".parse().unwrap(),
        peers: vec![],
        mining_threads: 1,
        no_mine: false,
        mine_when_synced: true,
        verify_threads: Some(2),
        reset: true,
    })
    .await
    .unwrap();
    let tree = BlockTree::new(genesis.clone()).unwrap();

    let _liar = RawPeer::connect_claiming(
        node.p2p_addr,
        &genesis,
        &tree,
        1_000_000_000,
        Digest([5; 64]),
    )
    .await;
    let connected = Instant::now();
    tokio::time::sleep(Duration::from_secs(5)).await;
    assert!(
        !node.engine.sync_gate_open(),
        "it first waits for the claimed height"
    );
    assert_eq!(node.status_rx.borrow().tip.height, 0);
    // SYNC_TIMEOUT (30 s) later the claim drops to our tip and mining starts, well before
    // the one-minute stall rule would open the gate.
    while node.status_rx.borrow().tip.height == 0 {
        assert!(
            connected.elapsed() < Duration::from_secs(50),
            "the lying peer held mining back past its sync timeout"
        );
        tokio::time::sleep(Duration::from_millis(100)).await;
    }

    node.stop().await;
    let _ = std::fs::remove_dir_all(&base);
}

/// Orphans released by their parent count against the deferred limits (8 per source):
/// a source cannot park future-dated blocks for free and have every one of them kept
/// once their parent arrives.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn released_orphans_count_against_the_deferred_limits() {
    let genesis = test_genesis();
    let (node, dir) = start(&genesis).await;
    let mut tree = BlockTree::new(genesis.clone()).unwrap();
    let miner = Arc::new(OwnerKeypair::from_seed(&[30; 32]));
    let attacker_key = Arc::new(OwnerKeypair::from_seed(&[31; 32]));
    let peers = || node.peer_manager.peer_count();

    let b1 = mine_next(&tree, &miner);
    extend(&mut tree, &b1);
    // Twenty children of block 1, 40 s ahead of the clock: past MAX_FUTURE_SECS, so
    // they are deferred, but within the slack, so they are not refused outright.
    let tpl = template_on_at(
        &tree,
        b1.header.block_id,
        &attacker_key,
        &[],
        now_secs() + 40,
    );
    let ctx0 = fw_context_to_core(&tpl.context_with_nonce(0)).unwrap();
    let inst = ctx0.instance().unwrap();
    let z0 = inst.x.product(&inst.y);
    let children: Vec<Block> = (1..=20u64)
        .map(|nonce| {
            let ctx = fw_context_to_core(&tpl.context_with_nonce(nonce)).unwrap();
            tpl.seal(nonce, &FreshWorkIds::derive(&ctx, &z0)).unwrap()
        })
        .collect();

    let mut attacker = RawPeer::connect(node.p2p_addr, &genesis, &tree).await;
    let mut honest = RawPeer::connect(node.p2p_addr, &genesis, &tree).await;
    wait_until("both peers registered", || peers() == 2).await;
    for child in &children {
        attacker
            .send(&WireMessage::GossipBlock(Box::new(child.clone())))
            .await;
    }
    attacker
        .send(&WireMessage::SyncRequest { from_height: 1 })
        .await;
    loop {
        match attacker.recv(Duration::from_secs(30)).await {
            Some(WireMessage::SyncResponse { .. }) => break,
            Some(_) => continue,
            None => panic!("the attacker was disconnected"),
        }
    }
    assert_eq!(
        snapshot(&node).orphan_count,
        20,
        "parked while block 1 is unknown"
    );

    honest
        .send(&WireMessage::GossipBlock(Box::new(b1.clone())))
        .await;
    // Released children obey the deferred limit: eight are deferred, and the twelve
    // refused as busy stay in the bounded orphan pool for the maintenance tick.
    wait_until("block 1 and its released orphans", || {
        let snap = snapshot(&node);
        snap.tip.height == 1 && snap.deferred_blocks == 8 && snap.orphan_count == 12
    })
    .await;
    assert_eq!(
        snapshot(&node).deferred_blocks,
        8,
        "the deferred limit per source"
    );

    node.stop().await;
    let _ = std::fs::remove_dir_all(&dir);
}

/// Orphans cost nothing to make (nothing is checked before the parent lookup), so each
/// source may park at most a sync batch's worth: a flood from one source evicts its own
/// orphans, not the honest blocks parked behind a missing parent.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn an_orphan_flood_does_not_evict_another_sources_parked_blocks() {
    let genesis = test_genesis();
    let (node, dir) = start(&genesis).await;
    let mut tree = BlockTree::new(genesis.clone()).unwrap();
    let miner = Arc::new(OwnerKeypair::from_seed(&[32; 32]));
    let peers = || node.peer_manager.peer_count();

    let mut chain = Vec::new();
    for _ in 0..41 {
        let block = mine_next(&tree, &miner);
        extend(&mut tree, &block);
        chain.push(block);
    }
    // Fake orphans: a real block under random parent and block ids (not at height 1,
    // where an orphan means another genesis and closes the connection).
    let fakes: Vec<Block> = (0..300u32)
        .map(|i| {
            let mut fake = chain[5].clone();
            let mut id = [0xEE; 64];
            id[..4].copy_from_slice(&i.to_le_bytes());
            fake.header.context.parent_canonical_id = Digest(id);
            id[4] = 0x01;
            fake.header.block_id = Digest(id);
            fake
        })
        .collect();

    let genesis_tree = BlockTree::new(genesis.clone()).unwrap();
    let mut honest = RawPeer::connect(node.p2p_addr, &genesis, &genesis_tree).await;
    let mut flooder = RawPeer::connect(node.p2p_addr, &genesis, &genesis_tree).await;
    wait_until("both peers registered", || peers() == 2).await;
    // Blocks 2..41 arrive before block 1: all forty are parked.
    for block in &chain[1..] {
        honest
            .send(&WireMessage::GossipBlock(Box::new(block.clone())))
            .await;
    }
    for fake in &fakes {
        flooder
            .send(&WireMessage::GossipBlock(Box::new(fake.clone())))
            .await;
    }
    flooder
        .send(&WireMessage::SyncRequest { from_height: 1 })
        .await;
    loop {
        match flooder.recv(Duration::from_secs(30)).await {
            Some(WireMessage::SyncResponse { .. }) => break,
            Some(_) => continue,
            None => panic!("the flooder was disconnected"),
        }
    }
    honest
        .send(&WireMessage::GossipBlock(Box::new(chain[0].clone())))
        .await;
    wait_until("all 41 honest blocks", || snapshot(&node).tip.height == 41).await;

    node.stop().await;
    let _ = std::fs::remove_dir_all(&dir);
}

/// A peer that answers a sync request with blocks from another height says nothing
/// about the height it claimed: the claim drops at once, and a node waiting for it to
/// catch up starts mining without waiting for a timeout.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn an_off_height_sync_answer_drops_the_claimed_height() {
    let genesis = test_genesis();
    let base = std::env::temp_dir().join(format!("plauthium-offheight-{}", now_secs_nanos()));
    std::fs::create_dir_all(&base).unwrap();
    let genesis_path = base.join("genesis.json");
    std::fs::write(&genesis_path, serde_json::to_string(&genesis).unwrap()).unwrap();
    let node = start_node(RunArgs {
        data_dir: base.join("gated"),
        key_file: None,
        genesis: Some(genesis_path),
        p2p_listen: "127.0.0.1:0".parse().unwrap(),
        rpc_listen: "127.0.0.1:0".parse().unwrap(),
        peers: vec![],
        mining_threads: 1,
        no_mine: false,
        mine_when_synced: true,
        verify_threads: Some(2),
        reset: true,
    })
    .await
    .unwrap();
    let mut tree = BlockTree::new(genesis.clone()).unwrap();
    let miner = Arc::new(OwnerKeypair::from_seed(&[33; 32]));
    let b1 = mine_next(&tree, &miner);
    extend(&mut tree, &b1);
    let b2 = mine_next(&tree, &miner);
    let genesis_tree = BlockTree::new(genesis.clone()).unwrap();

    let mut liar = RawPeer::connect_claiming(
        node.p2p_addr,
        &genesis,
        &genesis_tree,
        1_000_000_000,
        Digest([6; 64]),
    )
    .await;
    let connected = Instant::now();
    // Every request is answered with block 2, whatever height it asks for.
    let answer = tokio::spawn(async move {
        while let Some(msg) = liar.recv(Duration::from_secs(60)).await {
            if let WireMessage::SyncRequest { .. } = msg {
                liar.send(&WireMessage::SyncResponse {
                    blocks: vec![b2.clone()],
                })
                .await;
            }
        }
    });
    while node.status_rx.borrow().tip.height == 0 {
        assert!(
            connected.elapsed() < Duration::from_secs(15),
            "the off-height answer did not drop the claimed height"
        );
        tokio::time::sleep(Duration::from_millis(100)).await;
    }

    answer.abort();
    node.stop().await;
    let _ = std::fs::remove_dir_all(&base);
}
EOF

cat << 'EOF' > node/tests/testnet_integration.rs
//! Three-node integration test covering acceptance criteria A2–A6 (§11).
//!
//! Real 512x512 tiles are mined and verified, so run it with `--release`.

#![forbid(unsafe_code)]

use std::collections::HashSet;
use std::net::SocketAddr;
use std::path::{Path, PathBuf};
use std::time::{Duration, SystemTime, UNIX_EPOCH};

use chain::OwnerKeypair;
use chain::keys::unsigned;
use ledger::StateCategory;
use node::chain_actor::{ChainCmd, Origin};
use node::cli::{OutputArg, RunArgs, WithdrawArgs};
use node::mempool::{MempoolCmd, MempoolReject};
use node::net::PeerAddr;
use node::{NodeHandle, start_node};
use primitives::TOTAL_SUPPLY;
use serde_json::Value;
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::net::TcpStream;
use tokio::sync::oneshot;
use tokio::time::Instant;
use wire::{
    DifficultyMode, Digest, GenesisConfig, InitialPoolWithdrawal, JobPayload, JobTransaction,
    Target,
};

const PHASE_TIMEOUT: Duration = Duration::from_secs(240);

fn temp_test_dir(label: &str) -> PathBuf {
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos();
    std::env::temp_dir().join(format!("plauthium-it-{label}-{nanos}"))
}

/// About 64 attempts per seal (~1.5 s blocks with three miners) and roughly two
/// verified shares per block, so validation keeps up with production.
fn test_genesis() -> GenesisConfig {
    let mut g = GenesisConfig::default_testnet(1_700_000_000);
    g.initial_seal_target = Target(u128::MAX / 64);
    g.share_ratio = 2;
    g.difficulty = DifficultyMode::Fixed;
    g.blocks_per_epoch = 5;
    g.settle_delay = 1;
    g.share_maturity_depth = 1;
    g.snapshot_window = 30;
    g.share_inclusion_window = 15;
    g
}

/// Starts node `index` on `dir/n<index>`; its miner key is created there on first start.
async fn start(
    dir: &Path,
    index: u64,
    genesis: &Path,
    peers: Vec<PeerAddr>,
    mine: bool,
    reset: bool,
) -> NodeHandle {
    start_node(RunArgs {
        data_dir: dir.join(format!("n{index}")),
        key_file: None,
        genesis: Some(genesis.to_path_buf()),
        p2p_listen: "127.0.0.1:0".parse().unwrap(),
        rpc_listen: "127.0.0.1:0".parse().unwrap(),
        peers,
        mining_threads: 1,
        no_mine: !mine,
        mine_when_synced: false,
        verify_threads: Some(2),
        reset,
    })
    .await
    .unwrap()
}

fn height(n: &NodeHandle) -> u64 {
    n.status_rx.borrow().tip.height
}

fn tip_id(n: &NodeHandle) -> Digest {
    n.status_rx.borrow().tip.id
}

async fn wait_until(what: &str, mut cond: impl FnMut() -> bool) {
    let deadline = Instant::now() + PHASE_TIMEOUT;
    while !cond() {
        assert!(Instant::now() < deadline, "timed out waiting for {what}");
        tokio::time::sleep(Duration::from_millis(100)).await;
    }
}

/// Stops mining and waits until every node has the same tip and balances.
///
/// With mining stopped, two equal-weight tips both survive (a tie keeps the current
/// tip, §6.5), so a tie is broken by letting `tiebreaker` mine one more block.
async fn converge(nodes: &[&NodeHandle], tiebreaker: &NodeHandle) {
    for n in nodes {
        n.engine.set_enabled(false);
    }
    for _round in 0..5 {
        let deadline = Instant::now() + Duration::from_secs(20);
        while Instant::now() < deadline {
            let first = tip_id(nodes[0]);
            if nodes.iter().all(|n| tip_id(n) == first) {
                let balances = nodes[0].status_rx.borrow().balances;
                assert!(
                    nodes
                        .iter()
                        .all(|n| n.status_rx.borrow().balances == balances)
                );
                return;
            }
            tokio::time::sleep(Duration::from_millis(100)).await;
        }
        let h = height(tiebreaker);
        tiebreaker.engine.set_enabled(true);
        wait_until("tie-breaking block", || height(tiebreaker) > h).await;
        tiebreaker.engine.set_enabled(false);
    }
    panic!("nodes did not converge on one tip");
}

async fn http(addr: SocketAddr, method: &str, path: &str, body: Option<&str>) -> (u16, String) {
    let mut stream = TcpStream::connect(addr).await.unwrap();
    let body = body.unwrap_or("");
    let req = format!(
        "{method} {path} HTTP/1.1\r\nHost: {addr}\r\nContent-Type: application/json\r\n\
         Content-Length: {}\r\nConnection: close\r\n\r\n{body}",
        body.len()
    );
    stream.write_all(req.as_bytes()).await.unwrap();
    let mut resp = Vec::new();
    stream.read_to_end(&mut resp).await.unwrap();
    let text = String::from_utf8_lossy(&resp).to_string();
    let (head, body) = text.split_once("\r\n\r\n").unwrap();
    let status = head.split(' ').nth(1).unwrap().parse().unwrap();
    (status, body.to_string())
}

async fn status_json(n: &NodeHandle) -> Value {
    let (code, body) = http(n.rpc_addr, "GET", "/api/status", None).await;
    assert_eq!(code, 200);
    let v: Value = serde_json::from_str(&body).unwrap();
    // A6: the explorer's data source always reports a conserved supply.
    assert_eq!(v["ledger"]["conserved"], Value::Bool(true));
    let sum: u128 = v["ledger"]["categories"]
        .as_array()
        .unwrap()
        .iter()
        .map(|c| c["atoms"].as_str().unwrap().parse::<u128>().unwrap())
        .sum();
    assert_eq!(sum, u128::from(TOTAL_SUPPLY.get()));
    v
}

async fn mempool_size(n: &NodeHandle) -> usize {
    let (tx, rx) = oneshot::channel();
    n.mempool_tx
        .send(MempoolCmd::Stats { reply: tx })
        .await
        .unwrap();
    rx.await.unwrap()
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn acceptance_criteria_a2_to_a6() {
    let base_dir = temp_test_dir("full");
    std::fs::create_dir_all(&base_dir).unwrap();
    let genesis_path = base_dir.join("genesis.json");
    // The genesis names a treasury generated with the CLI's key store.
    let treasury_path = base_dir.join("treasury_key.bin");
    let treasury = node::keystore::create_treasury_key(&treasury_path).unwrap();
    let mut genesis = test_genesis();
    genesis.treasury_key_id = treasury.key_id();
    genesis.treasury_cosigner_key_id = treasury.cosigner_key_id();
    let genesis_json = serde_json::to_string_pretty(&genesis).unwrap();
    std::fs::write(&genesis_path, genesis_json).unwrap();

    let n1 = start(&base_dir, 1, &genesis_path, vec![], true, true).await;
    // Node 2 names node 1 by host name, as nodes name the public bootnodes.
    let n1_by_name = format!("localhost:{}", n1.p2p_addr.port()).parse().unwrap();
    let n2 = start(&base_dir, 2, &genesis_path, vec![n1_by_name], true, true).await;
    wait_until("node 2 to reach node 1 by host name", || {
        n1.peer_manager.peer_count() == 1 && n2.peer_manager.peer_count() == 1
    })
    .await;
    let n3 = start(
        &base_dir,
        3,
        &genesis_path,
        vec![n1.p2p_addr.into(), n2.p2p_addr.into()],
        true,
        true,
    )
    .await;

    // Every node generated its own ML-DSA-87 key in its data directory.
    let miner_keys: HashSet<String> = [&n1, &n2, &n3]
        .iter()
        .map(|n| n.miner_key_id.to_hex())
        .collect();
    assert_eq!(miner_keys.len(), 3, "three distinct miner identities");
    for i in 1..=3 {
        assert!(base_dir.join(format!("n{i}/miner_key.bin")).exists());
    }
    let n3_key_id = n3.miner_key_id;

    // A6: the explorer is served at `/` with the conservation badge.
    let (code, html) = http(n1.rpc_addr, "GET", "/", None).await;
    assert_eq!(code, 200);
    assert!(html.contains("Σ = M = 1,500,000,000,000,000 ✓"));
    let st = status_json(&n1).await;
    assert_eq!(st["node"]["owner_key_id"], n1.miner_key_id.to_hex());

    // A2 (part 1): all nodes advance; the epoch-1 booking is paid into U at h = 10.
    wait_until("height >= 11 on all nodes", || {
        [&n1, &n2, &n3].iter().all(|n| height(n) >= 11)
    })
    .await;

    // A3: submit a job to node 1 over HTTP; it must settle on node 3 with the exact result.
    let xs: Vec<i64> = (1..=512).collect();
    let ys: Vec<i64> = (1..=512).rev().collect();
    let direct_dot: i128 = xs.iter().zip(&ys).map(|(&a, &b)| i128::from(a * b)).sum();
    let body = serde_json::json!({
        "nonce": "777",
        "payload": { "type": "exact_dot", "xs": xs, "ys": ys }
    })
    .to_string();
    // The RPC sets expiry_height = tip + window, which is part of the job's identity, so
    // the tip must not move between the two submissions: pause mining until it settles.
    for n in [&n1, &n2, &n3] {
        n.engine.set_enabled(false);
    }
    let mut settled = (height(&n1), Instant::now());
    while settled.1.elapsed() < Duration::from_secs(2) {
        tokio::time::sleep(Duration::from_millis(100)).await;
        if height(&n1) != settled.0 {
            settled = (height(&n1), Instant::now());
        }
    }
    let (code, resp) = http(n1.rpc_addr, "POST", "/api/submit_job", Some(&body)).await;
    assert_eq!(code, 202, "{resp}");
    let resp: Value = serde_json::from_str(&resp).unwrap();
    assert_eq!(resp["expected_result"], direct_dot.to_string());
    // The RPC signs the job with node 1's miner key.
    assert_eq!(resp["client_key_id"], n1.miner_key_id.to_hex());
    // The default job charges 1 PLAU: the queue fee and the deposit
    // D = F_base + v_exec + v_da + v_ref (spec eq. 7.13).
    assert_eq!(resp["deposit"], "99000000");
    assert_eq!(resp["total_charge"], "100000000");
    let job_id = resp["job_id"].as_str().unwrap().to_string();
    let (code, _) = http(n1.rpc_addr, "POST", "/api/submit_job", Some(&body)).await;
    assert_eq!(code, 409, "resubmitting the same job is a duplicate");
    for n in [&n1, &n2, &n3] {
        n.engine.set_enabled(true);
    }

    let supply = TOTAL_SUPPLY.get().to_string();
    let deadline = Instant::now() + PHASE_TIMEOUT;
    let settled_at = loop {
        assert!(
            Instant::now() < deadline,
            "timed out waiting for A3 settlement"
        );
        status_json(&n3).await;
        let (code, blocks) = http(n3.rpc_addr, "GET", "/api/blocks?limit=100", None).await;
        assert_eq!(code, 200);
        let blocks: Value = serde_json::from_str(&blocks).unwrap();
        let blocks = blocks["blocks"].as_array().unwrap();
        assert!(
            blocks
                .iter()
                .all(|b| b["total_after"].as_str() == Some(supply.as_str()))
        );
        // Every block was mined, and signed, by one of the three node keys.
        assert!(
            blocks
                .iter()
                .all(|b| miner_keys.contains(b["miner_owner"].as_str().unwrap()))
        );
        let receipt = blocks.iter().find_map(|b| {
            b["receipts"]
                .as_array()
                .unwrap()
                .iter()
                .find(|r| r["job_id"] == job_id.as_str())
                .map(|r| (b["height"].as_u64().unwrap(), r["result"].clone()))
        });
        if let Some((h, result)) = receipt {
            assert_eq!(result, direct_dot.to_string());
            break h;
        }
        tokio::time::sleep(Duration::from_millis(250)).await;
    };
    assert!(settled_at >= 11);
    // Once on the chain (and out of the mempool), a copy of the job (replayed by a peer,
    // say) is still a duplicate: it cannot take mempool space until it expires.
    let (tx, rx) = oneshot::channel();
    let cmd = ChainCmd::GetCanonicalRange {
        from_height: 1,
        reply: tx,
    };
    n1.chain_tx.send(cmd).await.unwrap();
    let included = rx
        .await
        .unwrap()
        .iter()
        .flat_map(|b| b.body.jobs.clone())
        .find(|j| chain::compute_job_ids(j).map(|(_, id)| id.to_string()) == Ok(job_id.clone()))
        .expect("the job is on the canonical chain");
    let (tx, rx) = oneshot::channel();
    let cmd = MempoolCmd::Insert {
        tx: included,
        origin: Origin::Rpc,
        reply: tx,
    };
    n1.mempool_tx.send(cmd).await.unwrap();
    assert!(
        matches!(rx.await.unwrap(), Err(MempoolReject::Duplicate)),
        "an included job is a duplicate"
    );

    // InitialProtocolPool: a withdrawal signed offline by `treasury withdraw` is
    // submitted to node 1, relayed, and included by whichever node mines next.
    let recipient = n3.miner_key_id;
    let hex = node::sign_withdrawal_cmd(&WithdrawArgs {
        key_file: treasury_path.clone(),
        genesis: Some(genesis_path.clone()),
        nonce: 0,
        outputs: vec![OutputArg {
            recipient,
            atoms: 500_000_000,
        }],
        fee: 1_000_000,
        out: None,
    })
    .unwrap();
    let mut forged = InitialPoolWithdrawal::from_hex(&hex).unwrap();
    forged.slh_dsa_signature.0[100] ^= 0x01;
    let forged_body = serde_json::json!({ "withdrawal": forged.to_hex().unwrap() }).to_string();
    let (code, resp) = http(
        n1.rpc_addr,
        "POST",
        "/api/submit_withdrawal",
        Some(&forged_body),
    )
    .await;
    assert_eq!(code, 400, "{resp}");
    assert!(resp.contains("bad_signature"), "{resp}");
    let body = serde_json::json!({ "withdrawal": hex }).to_string();
    let (code, resp) = http(n1.rpc_addr, "POST", "/api/submit_withdrawal", Some(&body)).await;
    assert_eq!(code, 202, "{resp}");
    let resp: Value = serde_json::from_str(&resp).unwrap();
    assert_eq!(
        (resp["amount"].as_str(), resp["fee"].as_str()),
        (Some("500000000"), Some("1000000"))
    );
    let (code, _) = http(n1.rpc_addr, "POST", "/api/submit_withdrawal", Some(&body)).await;
    assert_eq!(code, 409, "resubmitting the same withdrawal is a duplicate");
    wait_until("the withdrawal is included on every node", || {
        [&n1, &n2, &n3]
            .iter()
            .all(|n| n.status_rx.borrow().initial_nonce == 1)
    })
    .await;
    let (code, blocks) = http(n3.rpc_addr, "GET", "/api/blocks?limit=100", None).await;
    assert_eq!(code, 200);
    let blocks: Value = serde_json::from_str(&blocks).unwrap();
    let included = blocks["blocks"]
        .as_array()
        .unwrap()
        .iter()
        .flat_map(|b| b["withdrawals"].as_array().unwrap().clone())
        .collect::<Vec<_>>();
    assert_eq!(included.len(), 1);
    assert_eq!(included[0]["tx_id"], resp["tx_id"]);
    let st = status_json(&n3).await;
    let pool = &st["ledger"]["initial_pool"];
    assert_eq!(pool["treasury_enabled"], Value::Bool(true));
    assert_eq!(pool["next_nonce"], 1);
    assert_eq!(pool["valve_rolling"], "501000000");
    let (code, _) = http(n2.rpc_addr, "POST", "/api/submit_withdrawal", Some(&body)).await;
    assert_eq!(code, 409, "a spent nonce is a duplicate");

    // A2: stop mining; tips and the 10 balances converge.
    converge(&[&n1, &n2, &n3], &n1).await;
    for n in [&n1, &n2, &n3] {
        let st = n.status_rx.borrow().clone();
        assert_eq!(st.total, u128::from(TOTAL_SUPPLY.get()));
        assert_eq!(
            st.balances[StateCategory::Escrow.index()],
            0,
            "E_esc drains once the job has settled"
        );
    }

    // GossipShare: a share found by node 2 is included in a block mined by node 3. From
    // here on one node mines at a time, so there is no fork and no reorg (which could
    // otherwise return another node's shares to a pool): only gossip can carry a share
    // mined after h0 from node 2 into node 3's blocks.
    let h0 = height(&n1);
    let (n2_key, n3_key) = (n2.miner_key_id.to_hex(), n3.miner_key_id.to_hex());
    let tips_agree = || tip_id(&n1) == tip_id(&n2) && tip_id(&n2) == tip_id(&n3);
    let deadline = Instant::now() + PHASE_TIMEOUT;
    loop {
        assert!(
            Instant::now() < deadline,
            "no share of node 2 reached a block of node 3"
        );
        let found = n2.engine.shares_found();
        n2.engine.set_enabled(true);
        wait_until("node 2 finds a share", || n2.engine.shares_found() > found).await;
        n2.engine.set_enabled(false);
        wait_until("all nodes on node 2's tip", tips_agree).await;
        // Gossip, the share's work check and node 3's template rebuild.
        tokio::time::sleep(Duration::from_millis(1_500)).await;
        // A share mined at height s fits blocks from s + 1 on: node 3 mines two.
        let h = height(&n3);
        n3.engine.set_enabled(true);
        wait_until("node 3 mines two blocks", || height(&n3) >= h + 2).await;
        n3.engine.set_enabled(false);
        wait_until("all nodes on node 3's tip", tips_agree).await;

        let (code, blocks) = http(n1.rpc_addr, "GET", "/api/blocks?limit=100", None).await;
        assert_eq!(code, 200);
        let blocks: Value = serde_json::from_str(&blocks).unwrap();
        let gossiped =
            blocks["blocks"].as_array().unwrap().iter().any(|b| {
                b["miner_owner"] == n3_key.as_str()
                    && b["shares"].as_array().unwrap().iter().any(|sh| {
                        sh["owner"] == n2_key.as_str() && sh["height"].as_u64().unwrap() > h0
                    })
            });
        if gossiped {
            break;
        }
    }
    let st = status_json(&n3).await;
    assert!(st["mining"]["share_pool"].is_u64());
    assert_eq!(st["mining"]["waiting_for_sync"], Value::Bool(false));
    assert!(st["verification"]["stage_a_started"].as_u64().unwrap() > 0);
    assert!(st["verification"]["queued_blocks"].is_u64());

    // A4: stop node 3, mine 10 blocks on nodes 1 and 2, restart node 3 on its data dir.
    let pre_stop_h = height(&n3);
    let (flush_tx, flush_rx) = oneshot::channel();
    n3.chain_tx
        .send(ChainCmd::FlushAndClose { reply: flush_tx })
        .await
        .unwrap();
    flush_rx.await.unwrap();
    n3.stop().await;

    n1.engine.set_enabled(true);
    n2.engine.set_enabled(true);
    wait_until("10 more blocks on node 1", || {
        height(&n1) >= pre_stop_h + 10
    })
    .await;
    converge(&[&n1, &n2], &n1).await;

    let n3 = start(
        &base_dir,
        3,
        &genesis_path,
        vec![n1.p2p_addr.into(), n2.p2p_addr.into()],
        false,
        false,
    )
    .await;
    assert!(
        height(&n3) >= pre_stop_h,
        "blocks.log is replayed before start_node returns"
    );
    assert_eq!(
        n3.miner_key_id, n3_key_id,
        "node 3 reloads its persisted miner key"
    );
    wait_until("node 3 resync", || tip_id(&n3) == tip_id(&n1)).await;
    assert_eq!(
        n3.status_rx.borrow().balances,
        n1.status_rx.borrow().balances
    );

    // A5: partition {1} | {2, 3}; mine 1 block on node 1 and 3 on node 2, then reconnect.
    n1.peer_manager.set_network_paused(true);
    let base_h = height(&n1);
    let client = OwnerKeypair::from_seed(&[7; 32]);
    let mut part_tx = JobTransaction {
        client_key: client.public_key().clone(),
        queue_fee: 1_000_000,
        base_fee: 10_000_000,
        v_exec: 79_000_000,
        v_da: 5_000_000,
        v_ref: 5_000_000,
        expiry_height: base_h + 120,
        nonce: 9_999,
        payload: JobPayload::ExactDot {
            xs: vec![2.0; 512],
            ys: vec![3.0; 512],
        },
        signature: unsigned(),
    };
    let genesis_id = n1.status_rx.borrow().genesis_id;
    client.sign_job(&mut part_tx, &genesis_id).unwrap();

    // A job whose signature does not verify is refused.
    let mut forged = part_tx.clone();
    forged.nonce += 1;
    let (f_tx, f_rx) = oneshot::channel();
    n1.mempool_tx
        .send(MempoolCmd::Insert {
            tx: forged,
            origin: Origin::Rpc,
            reply: f_tx,
        })
        .await
        .unwrap();
    assert!(matches!(
        f_rx.await.unwrap(),
        Err(node::mempool::MempoolReject::Invalid {
            code: "bad_signature",
            ..
        })
    ));
    let (p_tx, p_rx) = oneshot::channel();
    n1.mempool_tx
        .send(MempoolCmd::Insert {
            tx: part_tx,
            origin: Origin::Rpc,
            reply: p_tx,
        })
        .await
        .unwrap();
    p_rx.await.unwrap().unwrap();
    // Let the template pick the job up before mining.
    tokio::time::sleep(Duration::from_millis(800)).await;

    n1.engine.set_enabled(true);
    wait_until("node 1 mines inside the partition", || height(&n1) > base_h).await;
    n1.engine.set_enabled(false);
    tokio::time::sleep(Duration::from_millis(300)).await;
    let n1_branch_tip = tip_id(&n1);

    n2.engine.set_enabled(true);
    wait_until("node 2 mines 3 blocks", || height(&n2) >= base_h + 3).await;
    n2.engine.set_enabled(false);
    wait_until("node 3 follows node 2", || tip_id(&n3) == tip_id(&n2)).await;
    assert_ne!(tip_id(&n2), n1_branch_tip, "the partition holds");

    n1.peer_manager.set_network_paused(false);
    wait_until("node 1 reorgs to the heavier branch", || {
        tip_id(&n1) == tip_id(&n2)
    })
    .await;
    assert_eq!(
        n1.status_rx.borrow().balances,
        n2.status_rx.borrow().balances
    );
    assert!(
        mempool_size(&n1).await >= 1,
        "the losing branch's job is back in node 1's mempool"
    );
    status_json(&n1).await;
    status_json(&n2).await;
    status_json(&n3).await;

    n1.stop().await;
    n2.stop().await;
    n3.stop().await;
    let _ = std::fs::remove_dir_all(&base_dir);
}
EOF

cat << 'EOF' > poc/Cargo.toml
[package]
name = "poc"
version = "0.1.0"
edition = "2024"
description = "Plauthium proof-of-concept: mock block transitions with primary issuance, the modulo-3 generators and the InitialValve"

[dependencies]
primitives = { path = "../primitives" }
work = { path = "../work" }
scivm = { path = "../scivm" }
scheduler = { path = "../scheduler" }
ledger = { path = "../ledger" }

[lints]
workspace = true
EOF

cat << 'EOF' > poc/src/main.rs
//! Plauthium proof of concept: mock block transitions across the protocol modules.
//!
//! a) Genesis ledger: ten transparent categories, all of `M` unissued
//!    (`R_I` = 10 %, `R_M` = 90 %), no Genesis fee lot.
//! b) Blocks 1, 2 and 3: each opens with its primary issuance (the linear initial
//!    release `R_I -> U_initial` and the exact Q64 miner release `R_M -> P_pending`),
//!    then expands its Fresh Work seed with the diagnostic generator of the modulo-3
//!    schedule, computes the exact INT32 product and certifies it with six
//!    Freivalds rounds.
//! c) Scheduler: sequential D'Hondt lease allocation over discrete ShareIDs.
//! d) Ledger: the miner release is booked to shares and paid into `U`; a job's fees
//!    lock in `R_l`, mature into independent fee lots and pay rewards with
//!    segregated rounding dust.
//! e) InitialValve: InitialProtocolPool withdrawals within 30,000 PLAU per 720 blocks.
//! f) ASCII summary.
//!
//! Hashing is SHA3-512/SHAKE256 (see the `primitives` crate). The treasury's dual
//! signature (ML-DSA-87 and SLH-DSA-SHAKE-256s) is checked by `chain::stf`, which
//! this ledger-level PoC does not include.

use std::error::Error;

use ledger::{
    INITIAL_ALLOCATION, INITIAL_RELEASE_BLOCKS, INITIAL_VALVE_LIMIT, INITIAL_VALVE_WINDOW, JobId,
    Ledger, LedgerError, LedgerParams, MINER_ALLOCATION, MINER_DECAY_MULTIPLIER,
    MINER_HALF_LIFE_BLOCKS, PrimaryRelease, Q64, StateCategory, initial_release_cumulative,
    miner_decay_step,
};
use primitives::{Atoms, DomainSeparatedHash, TOTAL_SUPPLY};
use scheduler::{Allocation, OwnerId, ShareID, dhondt_allocation};
use scivm::{CONSENSUS_WEIGHT, OzakiIIProfile, RoundingMode};
use work::{
    ACCUMULATION_BOUND, CLASSICAL_MACS, DEFAULT_FREIVALDS_ROUNDS, FREIVALDS_FIELD_MULS,
    FreshWorkContext, FreshWorkIds, GENERATOR_ID_BASE, GeneratorProfile, TILE_DIM, WorkError,
    WorkUnit, verify_freivalds_rounds,
};

/// Execution slots (ready tiles) offered to the scheduler in this batch.
const LEASE_SLOTS: usize = 8;

type PocResult<T> = Result<T, Box<dyn Error>>;

fn main() -> PocResult<()> {
    println!("Plauthium PoC - mock block transitions");
    println!("(hash/XOF are SHA3-512/SHAKE256; treasury signatures are checked in chain::stf)\n");

    // ---------------------------------------------------------------- (a)
    section("a", "Genesis ledger: 100% of M unissued");
    let mut ledger = Ledger::genesis(LedgerParams::poc())?;
    print_categories(&ledger);
    ensure(
        ledger.fee_lots().is_empty(),
        "R_a must not hold a Genesis lot",
    )?;
    println!(
        "  R_I = {} (10%), R_M = {} (90%); the other 8 categories are zero, R_a has no lots\n",
        INITIAL_ALLOCATION, MINER_ALLOCATION
    );

    // ---------------------------------------------------------------- (b)
    section(
        "b",
        "Blocks 1..3: primary issuance, then Fresh Work under (h - 1) mod 3",
    );
    let mut blocks = Vec::new();
    for height in 1..=3 {
        let (_, release) = ledger.begin_block(height)?;
        print_release(&release);
        ledger.check_invariants()?;
        blocks.push(fresh_work(height)?);
    }
    println!();
    let unknown = mock_context(4, 0, GENERATOR_ID_BASE + 3).instance();
    ensure(
        matches!(unknown, Err(WorkError::UnknownGenerator(_))),
        "a fourth generator id must be rejected",
    )?;
    println!(
        "  generator id {} (a fourth profile) -> rejected: no fallback state\n",
        GENERATOR_ID_BASE + 3
    );
    let ids = blocks[0];

    // ---------------------------------------------------------------- (c)
    section("c", "Scheduler: sequential D'Hondt over discrete ShareIDs");
    let shares = mock_cohort(ids.work_id);
    let allocation = dhondt_allocation(&shares, LEASE_SLOTS)?;
    ensure(
        allocation.assigned() == LEASE_SLOTS,
        "D'Hondt left slots unassigned",
    )?;
    print_allocation(&shares, &allocation);

    // ---------------------------------------------------------------- (d)
    section(
        "d",
        "Ledger: miner release -> shares -> U; job fees -> fee lots",
    );
    let weights: Vec<u64> = shares.iter().map(|s| s.weight).collect();
    let epoch_blocks = ledger.params().blocks_per_epoch;

    // Epoch 1 ends at h = 720: the release of blocks 1..=720 is booked to the cohort
    // and, as in the STF, paid into U at the next boundary.
    advance(&mut ledger, epoch_blocks)?;
    let (_, booking) = ledger.book_epoch(&weights)?;
    step(
        &ledger,
        &format!("EPOCH_BOOKED (h={epoch_blocks})"),
        format!(
            "miner release {} booked, {} atoms carried",
            booking.release_booked,
            booking.release_carry.get()
        ),
    )?;
    advance(&mut ledger, 2 * epoch_blocks)?;
    let paid = ledger.booked_rewards();
    ledger.fw_reward(paid)?;
    step(
        &ledger,
        &format!("FW_REWARD (h={})", 2 * epoch_blocks),
        format!("{paid} paid into U"),
    )?;
    ledger.book_epoch(&weights)?;

    // The commercial job runs on the SciVM under a bound Ozaki-II profile.
    let profile = OzakiIIProfile {
        profile_id: 1,
        moduli: vec![255, 254, 253, 251, 247, 241, 239, 233],
        inner_dim: TILE_DIM as u64,
        bound_x: 1 << 23,
        bound_y: 1 << 23,
        rounding: RoundingMode::NearestTiesToEven,
    };
    profile.validate()?;
    let (xs, ys) = mock_scientific_operands();
    let dot = profile.exact_dot(&xs, &ys)?;
    let direct: i128 = xs
        .iter()
        .zip(&ys)
        .map(|(&a, &b)| a as i128 * b as i128)
        .sum();
    ensure(dot == direct, "Ozaki-II reconstruction mismatch")?;
    println!(
        "  SciVM Ozaki-II: {} moduli, Q ~ 2^{:.1} > 2*B_rec; exact dot = {} (consensus weight {CONSENSUS_WEIGHT})",
        profile.moduli.len(),
        (profile.reconstruction_modulus()? as f64).log2(),
        dot
    );

    // Worked budget of eq. (7.13): D = F_base + v_exec + v_DA + v_ref = 100 PLAU.
    let job = JobId(1);
    let (deposit, queue_fee, base_fee) = (plau(100)?, plau(1)?, plau(10)?);
    ledger.escrow_fund_and_queue(job, deposit, queue_fee)?;
    step(
        &ledger,
        "ESCROW_FUND_AND_QUEUE",
        format!("D = {deposit}, f_queue = {queue_fee}"),
    )?;
    ledger.job_admit_and_lease(job, base_fee)?;
    step(
        &ledger,
        "JOB_ADMIT_AND_LEASE",
        format!("Base Fee {base_fee} -> R_l (irretrievable)"),
    )?;
    ledger.result_settle(job, plau(80)?, plau(5)?, plau(5)?)?;
    step(
        &ledger,
        "RESULT_SETTLE",
        "v_exec 80 + v_DA 5 + v_ref 5 PLAU -> U".to_string(),
    )?;

    let maturity_epoch = ledger
        .locked_fees()
        .iter()
        .map(|f| f.maturity_epoch)
        .max()
        .ok_or("no locked fees")?;
    let maturity_height = ledger.params().genesis_height + maturity_epoch * epoch_blocks;
    advance(&mut ledger, maturity_height)?;
    let (_, matured) = ledger.reserve_mature()?;
    step(
        &ledger,
        "RESERVE_MATURE",
        format!(
            "h={maturity_height} (epoch {maturity_epoch}): {} lots R_l -> R_a",
            matured.len()
        ),
    )?;
    let paid = ledger.booked_rewards();
    ledger.fw_reward(paid)?;
    let (_, epoch) = ledger.book_epoch(&weights)?;
    step(
        &ledger,
        "EPOCH_BOOKED (fee lots)",
        format!(
            "{} from {} lots + {} miner release",
            epoch.booked,
            epoch.lots.len(),
            epoch.release_booked
        ),
    )?;
    for lot in epoch.lots.iter().filter(|l| matured.contains(&l.lot)) {
        let source = ledger
            .fee_lots()
            .iter()
            .find(|l| l.id() == lot.lot)
            .map_or(Atoms::ZERO, |l| l.source_fee());
        println!(
            "    fee lot #{} (F_c = {source}): budget {} atoms = {} booked + {} dust (segregated)",
            lot.lot.0,
            group(lot.budget.get()),
            group(lot.booked.get()),
            lot.dust.get()
        );
    }
    ledger.check_invariants()?;
    println!();
    print_categories(&ledger);

    // ---------------------------------------------------------------- (e)
    section(
        "e",
        "InitialValve: at most L_I = I/50 gross outflow per 720 blocks",
    );
    let valve = valve_demo(&mut ledger)?;
    println!();
    print_categories(&ledger);

    // ---------------------------------------------------------------- (f)
    let miner_at_half_life = issuance_projection()?;
    print_summary(
        &ledger,
        &ids,
        &allocation,
        matured.len(),
        epoch.dust,
        &valve,
        miner_at_half_life,
    )?;
    Ok(())
}

// ---------------------------------------------------------------------------
// Fresh Work under the modulo-3 schedule
// ---------------------------------------------------------------------------

/// Expands, multiplies and certifies the Fresh Work of block `height` under its
/// scheduled generator, and prints the profile's defining properties.
fn fresh_work(height: u64) -> PocResult<FreshWorkIds> {
    let profile = GeneratorProfile::for_height(height, 0).ok_or("no Fresh Work at Genesis")?;
    let context = mock_context(height, 0, profile.generator_id());
    let instance = context.instance()?;
    ensure(
        instance.profile == profile,
        "the context names another profile",
    )?;
    println!(
        "  h={height}: profile {} = {profile} (generator id {}), seed {}..",
        profile.index(),
        profile.generator_id(),
        instance.seed.short_hex(12)
    );
    let product = instance.x.product(&instance.y);
    match profile {
        GeneratorProfile::OutlierFuzzing => {
            let rows_ok = [&instance.x, &instance.y].iter().all(|m| {
                (0..TILE_DIM).all(|i| {
                    let row = m.row(i);
                    count(row, -127) == 8 && count(row, 127) == 8
                })
            });
            ensure(rows_ok, "a row lacks its eight -127 and eight +127")?;
            let zeros = count(instance.x.as_slice(), 0) + count(instance.y.as_slice(), 0);
            println!(
                "        every row of X and Y: exactly 8 x -127 and 8 x +127 (Fisher-Yates); zeros {:.3}%",
                100.0 * zeros as f64 / (2 * TILE_DIM * TILE_DIM) as f64
            );
        }
        GeneratorProfile::ArithmeticGraph => {
            let (lo, hi) = range(&instance.x, &instance.y);
            // i8 entries never exceed 127, so the lower end is the profile's property.
            ensure(lo >= 0, "graph entries leave [0, 127]")?;
            let mean =
                (sum(&instance.x) + sum(&instance.y)) as f64 / (2 * TILE_DIM * TILE_DIM) as f64;
            println!(
                "        entries = byte & 127 in [{lo}, {hi}], mean {mean:.2}; nonnegative, so Z >= 0"
            );
        }
        GeneratorProfile::CorrelatedAccumulatorStress => {
            let magnitudes_ok = [&instance.x, &instance.y].iter().all(|m| {
                m.as_slice()
                    .iter()
                    .all(|&v| (120..=127).contains(&v.unsigned_abs()))
            });
            ensure(magnitudes_ok, "|A_ik| leaves 127 - [0, 7]")?;
            let signs_ok = (0..TILE_DIM).all(|k| {
                let sigma = instance.x.get(0, k).signum();
                (0..TILE_DIM).all(|i| instance.x.get(i, k).signum() == sigma)
                    && (0..TILE_DIM).all(|j| instance.y.get(k, j).signum() == sigma)
            });
            ensure(
                signs_ok,
                "the carrier signs differ along an inner dimension",
            )?;
            let min_z = product.as_slice().iter().copied().min().unwrap_or(0);
            ensure(
                min_z >= 120 * 120 * TILE_DIM as i32,
                "a correlated sum is too small",
            )?;
            println!(
                "        A_ik = sigma_k (127 - (byte & 7)): carrier signs agree along k; min Z = {} >= 7,372,800",
                group(min_z as u64)
            );
        }
    }
    let accepted =
        verify_freivalds_rounds(&instance.x, &instance.y, &product, DEFAULT_FREIVALDS_ROUNDS);
    let mut forged = product.clone();
    let entry = forged.get(17, 42);
    forged.set(17, 42, if entry > 0 { entry - 1 } else { entry + 1 })?;
    let forged_rejected =
        !verify_freivalds_rounds(&instance.x, &instance.y, &forged, DEFAULT_FREIVALDS_ROUNDS);
    ensure(accepted, "Freivalds rejected the honest product")?;
    ensure(forged_rejected, "Freivalds accepted a forged product")?;
    ensure(
        product.max_abs() <= i64::from(ACCUMULATION_BOUND),
        "the product exceeds the accumulation bound",
    )?;
    let ids = FreshWorkIds::derive(&context, &product);
    println!(
        "        Z = XY: max|Z| = {} <= {}; Freivalds honest ACCEPT, forged REJECT; WorkID {}..",
        group(product.max_abs() as u64),
        group(ACCUMULATION_BOUND as u64),
        ids.work_id.short_hex(12)
    );
    Ok(ids)
}

fn count(values: &[i8], target: i8) -> usize {
    values.iter().filter(|&&v| v == target).count()
}

fn range(x: &WorkUnit, y: &WorkUnit) -> (i8, i8) {
    let all = x.as_slice().iter().chain(y.as_slice());
    let lo = all.clone().copied().min().unwrap_or(0);
    let hi = all.copied().max().unwrap_or(0);
    (lo, hi)
}

fn sum(m: &WorkUnit) -> i64 {
    m.as_slice().iter().map(|&v| i64::from(v)).sum()
}

// ---------------------------------------------------------------------------
// Issuance and the InitialValve
// ---------------------------------------------------------------------------

/// Opens empty blocks until the ledger is at `height`, re-checking the invariants.
fn advance(ledger: &mut Ledger, height: u64) -> PocResult<()> {
    while ledger.height() < height {
        ledger.begin_block(ledger.height() + 1)?;
    }
    ledger.check_invariants()?;
    Ok(())
}

/// Outcome of the InitialValve demonstration.
struct ValveRun {
    first_height: u64,
    rejected_height: u64,
    reopened_height: u64,
}

/// Waits for the pool to cover 29,990 PLAU, withdraws it, shows a 10 PLAU follow-up
/// rejected by the valve, then accepted once the first outflow leaves the window.
fn valve_demo(ledger: &mut Ledger) -> PocResult<ValveRun> {
    let fee = Atoms(1_000_000);
    let large = plau(29_990)?;
    let small = plau(10)?;
    let gross = large.get() + fee.get();
    let first_height = (ledger.height()..)
        .find(|&k| initial_release_cumulative(k).get() >= gross + 1_000 * 100_000_000)
        .ok_or("the pool never fills")?;
    advance(ledger, first_height)?;
    println!(
        "  h={first_height}: U_initial = {} (sum of i_k)",
        ledger.balance(StateCategory::InitialProtocolPool)
    );
    ledger.initial_pool_withdrawal(0, large, fee)?;
    step(
        ledger,
        "INITIAL_POOL_WITHDRAWAL #0",
        format!(
            "v = {large}, f = {fee}; window {} / {}",
            ledger.initial_valve().rolling_outflow(),
            INITIAL_VALVE_LIMIT
        ),
    )?;
    let rejected_height = first_height + 1;
    advance(ledger, rejected_height)?;
    match ledger.initial_pool_withdrawal(1, small, fee) {
        Err(LedgerError::InitialValveExceeded { rolling, requested }) => println!(
            "  h={rejected_height}: #1 (v = {small}) REJECTED: {rolling} + {requested} > L_I"
        ),
        other => return Err(format!("the valve admitted #1: {other:?}").into()),
    }
    let reopened_height = first_height + INITIAL_VALVE_WINDOW;
    advance(ledger, reopened_height - 1)?;
    ensure(
        ledger.initial_pool_withdrawal(1, small, fee).is_err(),
        "the valve reopened early",
    )?;
    advance(ledger, reopened_height)?;
    ledger.initial_pool_withdrawal(1, small, fee)?;
    step(
        ledger,
        "INITIAL_POOL_WITHDRAWAL #1",
        format!(
            "h={reopened_height}: block {first_height} left the window; window {}",
            ledger.initial_valve().rolling_outflow()
        ),
    )?;
    Ok(ValveRun {
        first_height,
        rejected_height,
        reopened_height,
    })
}

/// Checks that `R_I` empties at `N_I` and returns `R_M` after `H_M` exact decay steps.
fn issuance_projection() -> PocResult<u64> {
    ensure(
        initial_release_cumulative(INITIAL_RELEASE_BLOCKS) == INITIAL_ALLOCATION,
        "R_I does not empty at N_I",
    )?;
    let mut state = u128::from(MINER_ALLOCATION.get()) * Q64;
    for _ in 0..MINER_HALF_LIFE_BLOCKS {
        state = miner_decay_step(state);
    }
    Ok((state >> 64) as u64)
}

fn print_release(release: &PrimaryRelease) {
    println!(
        "  block k={}: PRIMARY_RELEASE  i_k = {} atoms (R_I -> U_initial), m_k = {} atoms (R_M -> P_pending)",
        release.block,
        group(release.initial.get()),
        group(release.miner.get())
    );
}

// ---------------------------------------------------------------------------
// Mock inputs
// ---------------------------------------------------------------------------

fn tag(name: &str) -> DomainSeparatedHash {
    DomainSeparatedHash::new("POC/MOCK", &[name.as_bytes()])
}

fn mock_context(height: u64, attempt_nonce: u64, generator_id: u32) -> FreshWorkContext {
    FreshWorkContext {
        chain_id: 0x504c_4155, // "PLAU"
        genesis_id: tag("genesis"),
        protocol_id: 2,
        crypto_suite_id: 1,
        program_id: tag("fresh-work-program"),
        air_id: tag("int8-tile-air"),
        generator_id,
        parent_canonical_id: tag(&format!("block-{}", height - 1)),
        stable_anchor_id: tag("anchor-0"),
        height,
        miner_policy_digest: tag("miner-policy"),
        payout_policy_digest: tag("payout-policy"),
        attempt_nonce,
        body_core_root: tag(&format!("body-core-{height}")),
        parent_derived_difficulty_context: tag("difficulty-0"),
        time_bucket: height * ledger::BLOCK_INTERVAL_SECONDS,
    }
}

/// The fresh share plus five mature shares from other miners. Owner 2 holds
/// two ShareIDs: its slots are simply the sum over them.
fn mock_cohort(fresh: DomainSeparatedHash) -> Vec<ShareID> {
    let mut shares = vec![ShareID {
        id: fresh,
        weight: 1_000_003,
        owner: OwnerId(1),
    }];
    for (i, (weight, owner)) in [
        (2_400_017u64, 2u64),
        (700_001, 2),
        (1_600_009, 3),
        (300_007, 4),
        (999_983, 5),
    ]
    .into_iter()
    .enumerate()
    {
        shares.push(ShareID {
            id: tag(&format!("mature-share-{i}")),
            weight,
            owner: OwnerId(owner),
        });
    }
    shares
}

/// Deterministic scaled integer operands with |x|, |y| < 2^23.
fn mock_scientific_operands() -> (Vec<f64>, Vec<f64>) {
    let operands = |mul: u64| -> Vec<f64> {
        (0..TILE_DIM as u64)
            .map(|i| ((i.wrapping_mul(mul) >> 7) % (1 << 24)) as f64 - (1 << 23) as f64)
            .collect()
    };
    (operands(2_654_435_761), operands(40_503))
}

// ---------------------------------------------------------------------------
// Output
// ---------------------------------------------------------------------------

fn plau(n: u64) -> PocResult<Atoms> {
    Atoms::from_plau(n).ok_or_else(|| "PLAU amount overflows".into())
}

fn ensure(condition: bool, message: &str) -> PocResult<()> {
    if condition {
        Ok(())
    } else {
        Err(message.into())
    }
}

fn section(letter: &str, title: &str) {
    println!("({letter}) {title}");
}

/// Reports one operation and re-checks the supply after it.
fn step(ledger: &Ledger, op: &str, detail: String) -> PocResult<()> {
    ensure(
        ledger.total() == u128::from(TOTAL_SUPPLY.get()),
        "supply changed",
    )?;
    println!("  {op:<32} {detail}");
    Ok(())
}

fn group(n: u64) -> String {
    let digits = n.to_string();
    let mut out = String::with_capacity(digits.len() + digits.len() / 3);
    for (i, c) in digits.chars().enumerate() {
        if i > 0 && (digits.len() - i).is_multiple_of(3) {
            out.push(',');
        }
        out.push(c);
    }
    out
}

fn print_categories(ledger: &Ledger) {
    let rule = "  +---------------------+-----------+---------------------------+";
    println!("{rule}");
    println!(
        "  | {:<19} | {:<9} | {:>25} |",
        "Category", "Symbol", "Balance (atoms)"
    );
    println!("{rule}");
    for category in StateCategory::ALL {
        println!(
            "  | {:<19} | {:<9} | {:>25} |",
            format!("{category:?}"),
            category.symbol(),
            group(ledger.balance(category).get())
        );
    }
    println!("{rule}");
    let total = ledger.total() as u64;
    let verdict = if u128::from(total) == u128::from(TOTAL_SUPPLY.get()) {
        "== M"
    } else {
        "!= M"
    };
    println!(
        "  | {:<19} | {:<9} | {:>25} |",
        "SUM",
        verdict,
        group(total)
    );
    println!("{rule}\n");
}

fn print_allocation(shares: &[ShareID], allocation: &Allocation) {
    let rule = "  +----+--------------------+-------+-----------+-------+";
    println!("{rule}");
    println!("  | #  | ShareID            | Owner | Weight    | Slots |");
    println!("{rule}");
    for (i, (share, slots)) in shares.iter().zip(&allocation.per_share).enumerate() {
        println!(
            "  | {i:<2} | {}.. | {:<5} | {:>9} | {slots:>5} |",
            share.id.short_hex(8),
            share.owner.0,
            group(share.weight)
        );
    }
    println!("{rule}");
    let order: Vec<String> = allocation.slots.iter().map(|s| s.to_string()).collect();
    println!("  lease order (slot -> share #): {}\n", order.join(" "));
}

fn print_summary(
    ledger: &Ledger,
    ids: &FreshWorkIds,
    allocation: &Allocation,
    matured_lots: usize,
    epoch_dust: Atoms,
    valve: &ValveRun,
    miner_at_half_life: u64,
) -> PocResult<()> {
    const WIDTH: usize = 78;
    let border = format!("+{}+", "=".repeat(WIDTH));
    let rule = format!("+{}+", "-".repeat(WIDTH));
    let line = |key: &str, value: String| println!("| {key:<20}: {value:<w$}|", w = WIDTH - 23);
    let distinct = allocation.per_share.iter().filter(|&&a| a > 0).count();
    let emission = ledger.emission();
    let half = MINER_ALLOCATION.get() / 2;

    println!("{border}");
    println!("|{:^WIDTH$}|", "PLAUTHIUM BLOCKS EXECUTED SUCCESSFULLY");
    println!("{border}");
    line(
        "Blocks",
        format!(
            "1..3 with Fresh Work; state advanced to h={}",
            ledger.height()
        ),
    );
    line(
        "Generators",
        format!(
            "h=1,2,3 -> profiles 0,1,2 (ids {}..{}), no fallback",
            GENERATOR_ID_BASE,
            GENERATOR_ID_BASE + 2
        ),
    );
    line(
        "Block 1 BlockID",
        format!("{}..", ids.block_id.short_hex(16)),
    );
    line(
        "Work unit",
        format!(
            "{TILE_DIM}x{TILE_DIM} INT8 -> INT32, {} MACs",
            group(CLASSICAL_MACS)
        ),
    );
    line(
        "Freivalds",
        format!(
            "ACCEPT, r_F = {DEFAULT_FREIVALDS_ROUNDS}, {} mults in F_(2^61-1)",
            group(FREIVALDS_FIELD_MULS)
        ),
    );
    line(
        "D'Hondt leases",
        format!(
            "{}/{LEASE_SLOTS} slots -> {distinct} discrete ShareIDs",
            allocation.assigned()
        ),
    );
    line(
        "Fee lots matured",
        format!("{matured_lots} (queue fee + Base Fee), R_l -> R_a"),
    );
    line(
        "Dust this epoch",
        format!(
            "{} atoms (total segregated {})",
            epoch_dust.get(),
            ledger.segregated_dust().get()
        ),
    );
    line(
        "Initial release",
        format!(
            "{} atoms after k = {}",
            group(emission.initial_released().get()),
            emission.block()
        ),
    );
    line(
        "Miner release",
        format!(
            "{} atoms; a = {MINER_DECAY_MULTIPLIER}",
            group(emission.miner_released().get())
        ),
    );
    line(
        "R_I at N_I",
        format!(
            "0 (all of I released over {} blocks)",
            group(INITIAL_RELEASE_BLOCKS)
        ),
    );
    line(
        "R_M at H_M",
        format!(
            "{} = R/2 - {} atoms",
            group(miner_at_half_life),
            half - miner_at_half_life
        ),
    );
    line(
        "InitialValve",
        format!(
            "h={} 29,990 ok; h={} 10 rejected; h={} ok",
            valve.first_height, valve.rejected_height, valve.reopened_height
        ),
    );
    println!("{rule}");
    for category in StateCategory::ALL {
        line(
            category.symbol(),
            format!(
                "{:<20}{:>25}",
                format!("{category:?}"),
                group(ledger.balance(category).get())
            ),
        );
    }
    println!("{rule}");
    let total = ledger.total();
    ensure(
        total == u128::from(TOTAL_SUPPLY.get()),
        "supply invariant violated",
    )?;
    line(
        "SUM (== M)",
        format!("{:<20}{:>25}  OK", "", group(total as u64)),
    );
    println!("{border}");
    Ok(())
}
