        share_target: Target(u128::MAX / 8),
        miner_key: sample_key(15),
        signature: sample_signature(16),
    }
}

fn sample_job() -> JobTransaction {
    JobTransaction {
        client_key: sample_key(20),
        queue_fee: 100_000_000,
        base_fee: 1_000_000_000,
        v_exec: 8_000_000_000,
