fn sample_withdrawal(outputs: usize) -> InitialPoolWithdrawal {
    let slh_key: Vec<u8> = (0..SLH_DSA_PUBLIC_KEY_LEN).map(|i| 70 + i as u8).collect();
    let slh_sig: Vec<u8> = (0..SLH_DSA_SIGNATURE_LEN)
        .map(|i| (i % 251) as u8)
        .collect();
    InitialPoolWithdrawal {
        expected_nonce: 3,
        outputs: (0..outputs)
            .map(|i| WithdrawalOutput {
                recipient: sample_digest(80 + i as u8),
