        FeeTransition::FwReward {
            epoch: 2,
            amount: 500,
            delta: [500, 0, 0, 0, 0, 0, 0, -500, 0, 0],
        },
        FeeTransition::EpochBooked {
            epoch: 2,
            budget: 1000,
            booked: 999,
            dust: 1,
            release_budget: 2_000,
            release_booked: 1_998,
            release_carry: 2,
            lots: 3,
            shares: 4,
            per_owner: vec![OwnerReward {
                owner: sample_digest(44),
                atoms: 2_997,
