            delta: [0, 0, 0, 0, 0, -999, 0, 999, 0, 0],
        },
        FeeTransition::ResultSettle {
            job_id: 123,
            v_exec: 80,
            v_da: 5,
            v_ref: 5,
            delta: [90, 0, -90, 0, 0, 0, 0, 0, 0, 0],
