    let full_withdrawal = sample_withdrawal(MAX_WITHDRAWAL_OUTPUTS);
    assert_eq!(
        codec::encoded_len(&full_withdrawal).unwrap(),
        ENCODED_WITHDRAWAL_MAX_LEN as u64
    );
    assert_eq!(full_withdrawal.checked_amount(), Some(136_000_000_000));
    assert_eq!(full_withdrawal.checked_gross(), Some(136_100_000_000));

    // The hex form `/api/submit_withdrawal` takes: the canonical encoding, round-tripped;
    // trailing bytes and oversized input are refused.
    let hex = full_withdrawal.to_hex().unwrap();
    assert_eq!(hex.len(), 2 * ENCODED_WITHDRAWAL_MAX_LEN);
    assert_eq!(
        InitialPoolWithdrawal::from_hex(&format!(" {hex}\n")).unwrap(),
        full_withdrawal
    );
    assert!(InitialPoolWithdrawal::from_hex(&format!("{hex}00")).is_err());
    let trailing = format!("{}00", withdrawal.to_hex().unwrap());
    assert!(InitialPoolWithdrawal::from_hex(&trailing).is_err());
    assert!(InitialPoolWithdrawal::from_hex("zz").is_err());

    let body = BlockBody {
        jobs: vec![job.clone()],
        shares: vec![share],
        withdrawals: vec![withdrawal.clone()],
        leases: vec![lease],
        receipts: vec![receipt],
        fee_transitions: transitions,
        ledger_digest: sample_digest(50),
    };
    let block = Block { header, body };

    for msg in [
        WireMessage::Handshake {
            protocol_id: 1,
            chain_id: 0x504C_4154,
            genesis_id: sample_digest(61),
            node_nonce: 99,
            best_height: 42,
            best_block_id: sample_digest(60),
        },
        WireMessage::GossipBlock(Box::new(block.clone())),
        WireMessage::GossipJob(job),
        WireMessage::GossipShare(Box::new(sample_share())),
        WireMessage::GossipWithdrawal(Box::new(withdrawal)),
        WireMessage::SyncRequest { from_height: 10 },
        WireMessage::SyncResponse {
            blocks: vec![block],
        },
    ] {
        let encoded = codec::encode(&msg).unwrap();
        let decoded: WireMessage = codec::decode(&encoded).unwrap();
        assert_eq!(decoded, msg);

        // A trailing byte must be rejected.
        let mut with_trailing = encoded.clone();
        with_trailing.push(0xff);
        assert!(codec::decode::<WireMessage>(&with_trailing).is_err());
        // So must a truncated frame.
        assert!(codec::decode::<WireMessage>(&encoded[..encoded.len() - 1]).is_err());
    }
}

/// The signed bytes are the canonical encoding without the trailing signature, so
/// the signature can never cover itself and every other field is covered.
#[test]
fn unsigned_encoding_is_the_encoding_without_the_signature() {
    let header = sample_header();
    let full = codec::encode(&header).unwrap();
    assert_eq!(
        header.unsigned_encoding().unwrap(),
        full[..full.len() - SIGNATURE_LEN]
    );
    assert_eq!(
        full[full.len() - SIGNATURE_LEN..],
        header.signature.as_bytes()[..]
    );

    let job = sample_job();
    let full = codec::encode(&job).unwrap();
    assert_eq!(
        job.unsigned_encoding().unwrap(),
        full[..full.len() - SIGNATURE_LEN]
    );

    let share = sample_share();
    let full = codec::encode(&share).unwrap();
    assert_eq!(
        share.unsigned_encoding().unwrap(),
        full[..full.len() - SIGNATURE_LEN]
    );

    // A withdrawal's two signatures trail its encoding.
    let withdrawal = sample_withdrawal(1);
    let full = codec::encode(&withdrawal).unwrap();
    assert_eq!(
        withdrawal.unsigned_encoding().unwrap(),
        full[..full.len() - SIGNATURE_LEN - SLH_DSA_SIGNATURE_LEN]
    );

    // Re-signing changes the encoding but not the signed bytes.
    let mut resigned = share.clone();
    resigned.signature = sample_signature(99);
    assert_eq!(
        resigned.unsigned_encoding().unwrap(),
        share.unsigned_encoding().unwrap()
    );
    assert_ne!(
        codec::encode(&resigned).unwrap(),
        codec::encode(&share).unwrap()
    );
}

/// `GossipShare` and `GossipWithdrawal` are variants 5 and 6: appending them kept the
/// discriminants 0..=4.
#[test]
fn gossip_share_and_withdrawal_are_appended_as_variants_5_and_6() {
    let share = sample_share();
    let encoded = codec::encode(&WireMessage::GossipShare(Box::new(share.clone()))).unwrap();
    assert_eq!(encoded[..4], 5u32.to_le_bytes());
    assert_eq!(encoded[4..], codec::encode(&share).unwrap()[..]);
    assert_eq!(encoded.len(), 4 + 8_059);
    assert_eq!(
        codec::decode::<WireMessage>(&encoded).unwrap(),
        WireMessage::GossipShare(Box::new(share))
    );
    assert_eq!(
        codec::encode(&WireMessage::SyncRequest { from_height: 1 }).unwrap()[..4],
        3u32.to_le_bytes()
    );
    let withdrawal = sample_withdrawal(1);
    let encoded =
        codec::encode(&WireMessage::GossipWithdrawal(Box::new(withdrawal.clone()))).unwrap();
    assert_eq!(encoded[..4], 6u32.to_le_bytes());
    assert_eq!(encoded[4..], codec::encode(&withdrawal).unwrap()[..]);
}

#[test]
fn keys_and_signatures_have_fixed_widths() {
    let key = sample_key(7);
    let bytes = codec::encode(&key).unwrap();
    assert_eq!(bytes.len(), PUBLIC_KEY_LEN, "no length prefix");
    assert_eq!(codec::decode::<PublicKey>(&bytes).unwrap(), key);
    assert!(codec::decode::<PublicKey>(&bytes[1..]).is_err());

    let sig = sample_signature(9);
    assert_eq!(codec::encode(&sig).unwrap().len(), SIGNATURE_LEN);
    let withdrawal = sample_withdrawal(0);
    assert_eq!(
        codec::encode(&withdrawal.slh_dsa_key).unwrap().len(),
        SLH_DSA_PUBLIC_KEY_LEN
    );
    assert_eq!(
        codec::encode(&withdrawal.slh_dsa_signature).unwrap().len(),
        SLH_DSA_SIGNATURE_LEN
    );
    assert!(SlhDsaPublicKey::from_slice(&[0u8; SLH_DSA_PUBLIC_KEY_LEN + 1]).is_err());

    // JSON uses hex; any other length is rejected.
    let json = serde_json::to_string(&key).unwrap();
    assert_eq!(json.len(), 2 * PUBLIC_KEY_LEN + 2);
    assert_eq!(serde_json::from_str::<PublicKey>(&json).unwrap(), key);
    assert!(serde_json::from_str::<PublicKey>("\"abcd\"").is_err());
    assert!(PublicKey::from_slice(&[0u8; PUBLIC_KEY_LEN - 1]).is_err());
    assert!(Signature::from_slice(&[0u8; SIGNATURE_LEN + 1]).is_err());
    assert_eq!(Signature::from_hex(&sig.to_hex()).unwrap(), sig);
}

#[test]
fn oversized_payload_is_rejected_by_codec_limit() {
    let huge = vec![0u8; MAX_FRAME_BYTES + 1024];
    assert!(codec::encode(&huge).is_err());
    assert!(codec::decode::<Vec<u8>>(&huge).is_err());
    // A length prefix that claims more than the limit fails before allocating.
    let mut lying = codec::encode(&vec![0u8; 4]).unwrap();
    lying[..8].copy_from_slice(&u64::MAX.to_le_bytes());
    assert!(codec::decode::<Vec<u8>>(&lying).is_err());
}

#[test]
fn difficulty_mode_round_trip() {
    for mode in [
        DifficultyMode::Fixed,
        DifficultyMode::Windowed { window: 32 },
    ] {
        let bytes = codec::encode(&mode).unwrap();
        assert_eq!(codec::decode::<DifficultyMode>(&bytes).unwrap(), mode);
        let json = serde_json::to_string(&mode).unwrap();
        assert_eq!(serde_json::from_str::<DifficultyMode>(&json).unwrap(), mode);
    }
}

#[test]
fn borrowed_sync_response_matches_the_normative_wire_encoding() {
    let block = Block {
        header: sample_header(),
        body: BlockBody {
            jobs: vec![sample_job()],
            shares: vec![sample_share()],
            withdrawals: vec![],
            leases: vec![],
            receipts: vec![],
            fee_transitions: vec![],
            ledger_digest: Digest::ZERO,
        },
    };
    let full = WireMessage::SyncResponse {
        blocks: vec![block.clone()],
    };
    let borrowed = (4u32, vec![&block]);
    let bytes = codec::encode(&borrowed).unwrap();
    assert_eq!(bytes, codec::encode(&full).unwrap());
    assert_eq!(bytes.len() as u64, codec::encoded_len(&borrowed).unwrap());
    assert_eq!(codec::decode::<WireMessage>(&bytes).unwrap(), full);
}
